return json_decode(<<<'CAMPUSDATA'
[{"id":"mrh301","code":"MRH 301","unit":"trad","title":"Approfondissement du droit du travail individuel et collectif","summary":"Le contrat de travail de sa formation à sa rupture, puis la représentation du personnel, la négociation et les conflits collectifs en Côte d'Ivoire.","lessons":[{"id":"mrh301-1","n":1,"t":"Sources et principes du droit du travail","min":25,"html":"<p>Le droit du travail régit les relations entre employeurs et salariés du secteur privé. En Côte d'Ivoire, il repose sur un ensemble de sources hiérarchisées.</p>\n<h3>Les sources</h3>\n<ul><li><strong>La Constitution</strong> : elle garantit notamment la liberté syndicale et le droit de grève.</li>\n<li><strong>Les conventions internationales</strong> : conventions de l'Organisation internationale du travail (OIT) ratifiées par la Côte d'Ivoire.</li>\n<li><strong>Le Code du travail</strong> : loi n° 2015-532 du 20 juillet 2015, qui a remplacé le Code de 1995, complétée par des décrets d'application.</li>\n<li><strong>La Convention collective interprofessionnelle</strong> du 19 juillet 1977 et les accords de branche ou d'entreprise.</li>\n<li><strong>Les usages</strong> et le <strong>règlement intérieur</strong> de l'entreprise.</li>\n<li><strong>Le contrat de travail</strong>, source individuelle.</li>\n<li><strong>La jurisprudence</strong> : décisions des tribunaux du travail, cours d'appel et Cour suprême.</li></ul>\n<h3>Le principe de faveur</h3>\n<p>Lorsque plusieurs normes s'appliquent à la même situation, on retient en principe celle qui est la plus favorable au salarié. Une clause du contrat moins favorable que la convention collective est donc sans effet sur ce point.</p>\n<h3>L'ordre public social</h3>\n<p>Les règles du Code du travail sont d'ordre public : on ne peut y déroger que dans un sens plus favorable au salarié. Par exemple, un contrat ne peut pas fixer un salaire inférieur au SMIG.</p>\n<h3>Les acteurs institutionnels</h3>\n<ul><li><strong>Le ministère chargé du Travail</strong> définit la politique du travail.</li>\n<li><strong>L'inspection du travail</strong> contrôle l'application de la loi, conseille et concilie.</li>\n<li><strong>Le tribunal du travail</strong> tranche les litiges individuels.</li>\n<li><strong>La CNPS</strong> gère la sécurité sociale des salariés du privé.</li></ul>\n<div class=\"callout\"><b>Méthode</b>Face à une question de droit du travail, cherchez d'abord la règle dans le Code, puis vérifiez si la convention collective ou le contrat prévoit mieux pour le salarié.</div>","quiz":[{"q":"Quel texte constitue le Code du travail ivoirien en vigueur ?","o":["Loi n° 95-15 du 12 janvier 1995","Loi n° 2015-532 du 20 juillet 2015","Décret du 19 juillet 1977"],"a":1,"e":"Le Code de 2015 a remplacé celui de 1995."},{"q":"La Convention collective interprofessionnelle ivoirienne date de…","o":["1977","1995","2015"],"a":0,"e":"Elle a été signée le 19 juillet 1977."},{"q":"Le principe de faveur signifie que…","o":["L'employeur choisit la règle applicable","La règle la plus favorable au salarié s'applique","La loi s'applique toujours avant le contrat"],"a":1,"e":"En cas de concurrence de normes, on retient la plus favorable au salarié."},{"q":"Une clause du contrat moins favorable que la convention collective est…","o":["Sans effet sur ce point","Prioritaire","Valable si le salarié a signé"],"a":0,"e":"La convention collective s'impose au contrat moins favorable."},{"q":"Quelle organisation internationale adopte les conventions sur le travail ?","o":["L'OMC","L'OIT","L'OHADA"],"a":1,"e":"L'Organisation internationale du travail."},{"q":"Le Code du travail est dit d'ordre public social car…","o":["On peut y déroger librement","On ne peut y déroger que dans un sens plus favorable au salarié","Il ne s'applique qu'au secteur public"],"a":1,"e":"Les dérogations ne sont admises qu'en faveur du salarié."},{"q":"Un contrat peut-il fixer un salaire inférieur au SMIG ?","o":["Oui, si le salarié accepte","Non","Oui, pendant la période d'essai"],"a":1,"e":"Le SMIG est un minimum d'ordre public."},{"q":"Qui contrôle l'application de la législation du travail dans les entreprises ?","o":["L'inspection du travail","La CNPS","Le commissaire aux comptes"],"a":0,"e":"C'est la mission première de l'inspection du travail."},{"q":"Quelle juridiction tranche les litiges individuels du travail ?","o":["Le tribunal de commerce","Le tribunal du travail","La Cour des comptes"],"a":1,"e":"Le tribunal du travail est compétent."},{"q":"Quel organisme gère la sécurité sociale des salariés du privé ?","o":["La CNPS","La DGI","Le FDFP"],"a":0,"e":"Caisse nationale de prévoyance sociale."},{"q":"Le règlement intérieur est une source…","o":["Internationale","Propre à l'entreprise","Constitutionnelle"],"a":1,"e":"Il est élaboré par l'employeur pour son entreprise."},{"q":"La liberté syndicale est garantie notamment par…","o":["La Constitution","Le règlement intérieur","Le contrat de travail"],"a":0,"e":"La Constitution consacre la liberté syndicale."},{"q":"La jurisprudence, c'est…","o":["L'ensemble des décisions des juridictions","Un décret","Un accord d'entreprise"],"a":0,"e":"Les décisions de justice précisent l'interprétation des textes."},{"q":"Le contrat de travail est une source…","o":["Collective","Individuelle","Internationale"],"a":1,"e":"Il lie un employeur et un salarié."},{"q":"Quelle est la première étape de méthode face à une question de droit du travail ?","o":["Consulter le contrat seulement","Chercher la règle dans le Code","Demander à un collègue"],"a":1,"e":"On part de la loi, puis on vérifie les sources plus favorables."},{"q":"Un accord d'entreprise peut-il prévoir des congés plus longs que la loi ?","o":["Oui","Non","Seulement pour les cadres"],"a":0,"e":"Une dérogation plus favorable est toujours permise."},{"q":"Les usages d'entreprise sont…","o":["Des pratiques constantes et générales","Des lois votées","Des circulaires ministérielles"],"a":0,"e":"Un usage est une pratique générale, constante et fixe."},{"q":"Le droit du travail étudié ici s'applique principalement…","o":["Aux fonctionnaires","Aux salariés du secteur privé","Aux travailleurs indépendants"],"a":1,"e":"Les fonctionnaires relèvent du statut général de la fonction publique."},{"q":"Quelle institution concilie aussi les parties avant un procès ?","o":["L'inspection du travail","La CNPS","La chambre de commerce"],"a":0,"e":"L'inspecteur du travail joue un rôle de conciliation."},{"q":"Les décrets d'application servent à…","o":["Préciser les modalités d'application de la loi","Remplacer la Constitution","Annuler les conventions collectives"],"a":0,"e":"Ils détaillent la mise en œuvre du Code."}]},{"id":"mrh301-2","n":2,"t":"Le contrat de travail : définition et critères","min":25,"html":"<p>Le contrat de travail est la convention par laquelle une personne s'engage à mettre son activité professionnelle, moyennant rémunération, sous la direction et l'autorité d'une autre personne.</p>\n<h3>Trois critères cumulatifs</h3>\n<ol><li><strong>Une prestation de travail</strong> : manuelle, intellectuelle ou artistique.</li>\n<li><strong>Une rémunération</strong> : en argent, éventuellement complétée d'avantages en nature.</li>\n<li><strong>Un lien de subordination</strong> : l'employeur donne des ordres, contrôle l'exécution et sanctionne les manquements. C'est le critère décisif.</li></ol>\n<h3>Distinguer des contrats voisins</h3>\n<div class=\"tbl\"><table><thead><tr><th>Contrat</th><th>Différence avec le contrat de travail</th></tr></thead><tbody>\n<tr><td>Prestation de services</td><td>Le prestataire est indépendant, sans subordination</td></tr>\n<tr><td>Mandat social</td><td>Le dirigeant représente la société, il n'est pas subordonné</td></tr>\n<tr><td>Stage</td><td>Objectif pédagogique, convention tripartite avec l'école</td></tr>\n<tr><td>Bénévolat</td><td>Aucune rémunération</td></tr></tbody></table></div>\n<h3>La requalification</h3>\n<p>Le juge ne s'arrête pas au nom donné au contrat. S'il constate les trois critères, il requalifie la relation en contrat de travail, avec toutes ses conséquences : salaire minimum, cotisations sociales, protection contre le licenciement.</p>\n<h3>Conditions de validité</h3>\n<ul><li>Le consentement libre et éclairé des parties.</li><li>La capacité à contracter (âge minimum légal d'admission à l'emploi).</li><li>Un objet licite.</li></ul>\n<h3>La forme</h3>\n<p>Le CDI peut en principe être conclu par écrit ou verbalement, mais l'écrit est vivement recommandé pour la preuve. Certains contrats, comme le CDD, doivent être écrits. Le travailleur étranger doit disposer d'un contrat visé par l'autorité compétente.</p>\n<div class=\"callout\"><b>À retenir</b>La subordination juridique est le critère qui fait basculer une relation dans le droit du travail.</div>","quiz":[{"q":"Combien de critères cumulatifs définissent le contrat de travail ?","o":["Deux","Trois","Quatre"],"a":1,"e":"Prestation, rémunération, subordination."},{"q":"Quel est le critère décisif du contrat de travail ?","o":["La rémunération","Le lien de subordination","La durée"],"a":1,"e":"C'est lui qui distingue le salarié de l'indépendant."},{"q":"Le lien de subordination implique que l'employeur peut…","o":["Donner des ordres, contrôler et sanctionner","Seulement payer","Choisir les vacances du salarié à sa place en toute liberté"],"a":0,"e":"Ce sont les trois pouvoirs qui caractérisent la subordination."},{"q":"Un bénévole n'est pas salarié car il manque…","o":["La prestation","La rémunération","Le lieu de travail"],"a":1,"e":"Sans rémunération, pas de contrat de travail."},{"q":"Le prestataire de services se distingue du salarié par…","o":["L'absence de subordination","L'absence de travail","Le paiement en espèces"],"a":0,"e":"Il organise librement son activité."},{"q":"Le juge peut requalifier un contrat de prestation en contrat de travail si…","o":["Les trois critères sont réunis","Le contrat est oral","Le prestataire le demande seulement"],"a":0,"e":"Le juge regarde la réalité de la relation."},{"q":"Le nom donné au contrat par les parties…","o":["Lie toujours le juge","Ne lie pas le juge","Est interdit"],"a":1,"e":"Seule la réalité de la relation compte."},{"q":"Une conséquence de la requalification est…","o":["La perte de tout droit","L'application du salaire minimum et des cotisations sociales","La dissolution de l'entreprise"],"a":1,"e":"La relation relève désormais du droit du travail."},{"q":"Le stage se distingue par…","o":["Son objectif pédagogique et sa convention avec l'école","L'absence de tuteur","Sa durée illimitée"],"a":0,"e":"La convention de stage est tripartite."},{"q":"Le mandataire social (dirigeant) est en principe…","o":["Subordonné","Non subordonné","Toujours salarié"],"a":1,"e":"Il représente la société."},{"q":"Une condition de validité du contrat est…","o":["Le consentement libre et éclairé","La présence d'un avocat","Un apport en capital"],"a":0,"e":"Sans consentement valable, le contrat est nul."},{"q":"La rémunération peut comprendre…","o":["Uniquement de l'argent","De l'argent et des avantages en nature","Uniquement des avantages en nature"],"a":1,"e":"Logement ou véhicule peuvent compléter le salaire."},{"q":"Le CDI peut-il être conclu verbalement ?","o":["Oui, mais l'écrit est recommandé","Non, jamais","Seulement pour les cadres"],"a":0,"e":"L'écrit facilite la preuve."},{"q":"Quel contrat doit obligatoirement être écrit ?","o":["Le CDD","Le CDI de droit commun","Aucun"],"a":0,"e":"Le CDD doit préciser son terme ou son objet par écrit."},{"q":"La prestation de travail peut être…","o":["Uniquement manuelle","Manuelle, intellectuelle ou artistique","Uniquement intellectuelle"],"a":1,"e":"Toute forme d'activité professionnelle."},{"q":"Un objet licite signifie que…","o":["Le travail demandé est permis par la loi","Le salaire est élevé","Le contrat est long"],"a":0,"e":"On ne peut pas contracter pour une activité illégale."},{"q":"Le contrat du travailleur étranger doit être…","o":["Visé par l'autorité compétente","Rédigé en anglais","Oral"],"a":0,"e":"Un visa administratif est exigé."},{"q":"Pourquoi recommander l'écrit pour un CDI ?","o":["Pour la preuve des engagements","Parce que la loi l'impose toujours","Pour payer moins d'impôts"],"a":0,"e":"L'écrit sécurise les deux parties."},{"q":"Un chauffeur « indépendant » soumis à des horaires imposés et sanctionné par une société risque…","o":["Une requalification en salarié","Une amende personnelle","Rien"],"a":0,"e":"Les indices de subordination sont présents."},{"q":"Le pouvoir de sanction de l'employeur est une manifestation…","o":["Du lien de subordination","De la rémunération","Du mandat social"],"a":0,"e":"Sanctionner fait partie des pouvoirs de l'employeur."}]},{"id":"mrh301-3","n":3,"t":"CDI, CDD et autres formes de contrat","min":25,"html":"<h3>Le CDI, contrat de droit commun</h3>\n<p>Le contrat à durée indéterminée est la forme normale de la relation de travail. Il ne prévoit pas de terme et peut être rompu par démission ou licenciement, sous réserve des règles de préavis et de motif.</p>\n<h3>Le CDD, contrat d'exception</h3>\n<ul><li>Il doit être <strong>écrit</strong> et préciser son terme (date) ou son objet (remplacement d'un salarié absent, surcroît temporaire d'activité, travail saisonnier…).</li>\n<li>Sa durée totale est plafonnée par la loi (deux ans dans le droit ivoirien) et le nombre de renouvellements est limité.</li>\n<li>S'il se poursuit au-delà de son terme, ou si les règles ne sont pas respectées, il est <strong>requalifié en CDI</strong>.</li>\n<li>Il ne peut pas être rompu avant son terme, sauf faute lourde, force majeure ou accord des parties.</li></ul>\n<h3>Autres formes</h3>\n<div class=\"tbl\"><table><thead><tr><th>Forme</th><th>Caractéristique</th></tr></thead><tbody>\n<tr><td>Travail temporaire (intérim)</td><td>Relation triangulaire : entreprise de travail temporaire, entreprise utilisatrice, salarié</td></tr>\n<tr><td>Travail à temps partiel</td><td>Durée inférieure à la durée légale, droits proportionnels</td></tr>\n<tr><td>Travail journalier</td><td>Engagement à la journée, payé à la fin de la journée ou de la semaine</td></tr>\n<tr><td>Contrat d'apprentissage</td><td>Formation pratique en entreprise et théorique en centre</td></tr>\n<tr><td>Stage de qualification ou d'insertion</td><td>Acquisition d'une expérience pour un jeune diplômé</td></tr></tbody></table></div>\n<h3>Le choix du contrat</h3>\n<p>Le CDD ne doit pas servir à pourvoir durablement un emploi lié à l'activité normale et permanente de l'entreprise. Le gestionnaire RH vérifie donc le motif, la durée, les renouvellements et la date de fin de chaque CDD dans un tableau de suivi.</p>\n<div class=\"callout\"><b>Bonne pratique RH</b>Programmez une alerte un mois avant la fin de chaque CDD pour décider à temps : fin de contrat, renouvellement ou embauche en CDI.</div>","quiz":[{"q":"Quelle est la forme normale de la relation de travail ?","o":["Le CDD","Le CDI","L'intérim"],"a":1,"e":"Le CDI est le contrat de droit commun."},{"q":"Le CDD doit obligatoirement être…","o":["Écrit","Oral","Notarié"],"a":0,"e":"L'écrit précise terme ou objet."},{"q":"Quelle est la durée maximale du CDD en droit ivoirien ?","o":["Six mois","Deux ans","Cinq ans"],"a":1,"e":"Au-delà, la relation devient un CDI."},{"q":"Que se passe-t-il si un CDD se poursuit après son terme ?","o":["Il devient un CDI","Il est nul","Il devient un stage"],"a":0,"e":"C'est la requalification."},{"q":"Un motif valable de CDD est…","o":["Le remplacement d'un salarié absent","Pourvoir un poste permanent pour toujours","Éviter le préavis"],"a":0,"e":"Le CDD répond à un besoin temporaire."},{"q":"Un CDD peut être rompu avant son terme en cas de…","o":["Faute lourde","Simple convenance de l'employeur","Baisse d'humeur"],"a":0,"e":"Aussi en cas de force majeure ou d'accord des parties."},{"q":"L'intérim met en relation…","o":["Deux parties","Trois parties","Quatre parties"],"a":1,"e":"Entreprise de travail temporaire, utilisatrice et salarié."},{"q":"Qui est l'employeur juridique de l'intérimaire ?","o":["L'entreprise utilisatrice","L'entreprise de travail temporaire","Le ministère"],"a":1,"e":"L'ETT le recrute et le rémunère."},{"q":"Le temps partiel correspond à une durée…","o":["Supérieure à la durée légale","Inférieure à la durée légale","Égale à 48 heures"],"a":1,"e":"Les droits sont proportionnels au temps travaillé."},{"q":"Le travailleur journalier est engagé…","o":["À l'année","À la journée","Au mois"],"a":1,"e":"Il est payé à la fin de la journée ou de la semaine."},{"q":"Le contrat d'apprentissage combine…","o":["Formation pratique et théorique","Deux emplois","Salaire et dividendes"],"a":0,"e":"Entreprise et centre de formation."},{"q":"Peut-on utiliser un CDD pour un emploi permanent de l'entreprise ?","o":["Oui, sans limite","Non, ce n'est pas son objet","Oui, s'il est renouvelé dix fois"],"a":1,"e":"Le CDD répond à un besoin temporaire."},{"q":"Le nombre de renouvellements d'un CDD est…","o":["Illimité","Limité par la loi","Fixé librement par l'employeur"],"a":1,"e":"La loi encadre les renouvellements."},{"q":"Le CDI peut être rompu par…","o":["Démission ou licenciement","Seulement la mort","Seulement l'accord de l'inspecteur"],"a":0,"e":"Sous réserve du préavis et d'un motif légitime pour le licenciement."},{"q":"Quel outil aide à suivre les CDD ?","o":["Un tableau de suivi avec dates de fin","Le registre des visites","L'organigramme"],"a":0,"e":"Il évite les requalifications involontaires."},{"q":"Quand programmer l'alerte de fin de CDD ?","o":["Le jour même","Environ un mois avant","Un an après"],"a":1,"e":"Cela laisse le temps de décider."},{"q":"Un CDD saisonnier est lié à…","o":["Des travaux qui se répètent chaque année à la même période","Une promotion","Un congé maladie"],"a":0,"e":"Exemple : récolte, campagne commerciale."},{"q":"Le stage de qualification vise surtout…","o":["Les jeunes diplômés en insertion","Les retraités","Les dirigeants"],"a":0,"e":"Il permet d'acquérir une première expérience."},{"q":"La requalification en CDI protège surtout…","o":["Le salarié","L'entreprise de travail temporaire","Le fisc"],"a":0,"e":"Le salarié obtient la stabilité du CDI."},{"q":"Un CDD doit préciser…","o":["Son terme ou son objet","Le nom du conjoint","La religion du salarié"],"a":0,"e":"C'est une mention indispensable."}]},{"id":"mrh301-4","n":4,"t":"L'embauche et la période d'essai","min":20,"html":"<h3>Les formalités d'embauche</h3>\n<ol><li>Vérifier l'identité et, pour un étranger, les documents requis.</li>\n<li>Faire passer la visite médicale d'embauche.</li>\n<li>Rédiger et signer le contrat (ou la lettre d'engagement).</li>\n<li>Déclarer le salarié à la CNPS et l'inscrire sur le registre d'employeur.</li>\n<li>Ouvrir le dossier du personnel et paramétrer la paie.</li></ol>\n<h3>La non-discrimination</h3>\n<p>Le recrutement ne peut pas être fondé sur l'origine, le sexe, la religion, l'opinion, l'appartenance syndicale, l'état de santé ou le handicap. Les questions posées en entretien doivent se rapporter aux compétences requises.</p>\n<h3>La période d'essai</h3>\n<p>Elle permet à l'employeur d'évaluer les compétences du salarié, et au salarié de vérifier que le poste lui convient.</p>\n<ul><li>Elle doit être <strong>prévue par écrit</strong>.</li>\n<li>Sa durée dépend de la catégorie professionnelle ; à titre indicatif, les textes ivoiriens prévoient environ 8 jours pour les travailleurs payés à l'heure ou à la journée, 1 mois pour les employés, 2 mois pour les agents de maîtrise et techniciens, 3 mois pour les cadres.</li>\n<li>Elle peut être <strong>renouvelée une fois</strong>, dans les conditions prévues.</li>\n<li>Pendant l'essai, chaque partie peut rompre le contrat sans préavis ni indemnité, sauf dispositions contraires, mais sans abus.</li></ul>\n<h3>L'intégration</h3>\n<p>Un parcours d'intégration réussi comporte un accueil le premier jour, un livret d'accueil, la présentation de l'équipe, un tuteur et des points d'étape pendant l'essai. Il réduit les départs précoces.</p>\n<div class=\"callout\"><b>Point de vigilance</b>Rompre l'essai pour un motif étranger aux compétences (grossesse, activité syndicale) constitue un abus.</div>","quiz":[{"q":"La visite médicale d'embauche sert à…","o":["Vérifier l'aptitude au poste","Fixer le salaire","Choisir le service"],"a":0,"e":"Elle est réalisée par le médecin du travail."},{"q":"À quel organisme déclare-t-on un nouveau salarié ?","o":["La CNPS","L'OIT","La BCEAO"],"a":0,"e":"La déclaration ouvre les droits sociaux."},{"q":"Un critère interdit de recrutement est…","o":["Les compétences","La religion","L'expérience"],"a":1,"e":"C'est une discrimination."},{"q":"Les questions d'entretien doivent porter sur…","o":["La vie privée","Les compétences requises pour le poste","Les opinions politiques"],"a":1,"e":"Elles doivent être en lien avec l'emploi."},{"q":"La période d'essai doit être…","o":["Prévue par écrit","Toujours de 6 mois","Supposée"],"a":0,"e":"Elle ne se présume pas."},{"q":"Durée d'essai indicative pour un cadre ?","o":["8 jours","1 mois","3 mois"],"a":2,"e":"Les cadres ont l'essai le plus long."},{"q":"Durée d'essai indicative pour un employé ?","o":["1 mois","6 mois","1 an"],"a":0,"e":"Selon la catégorie professionnelle."},{"q":"Combien de fois l'essai peut-il être renouvelé ?","o":["Jamais","Une fois","Autant que souhaité"],"a":1,"e":"Un seul renouvellement est admis."},{"q":"Pendant l'essai, la rupture se fait en principe…","o":["Sans préavis ni indemnité","Avec 3 mois de préavis","Uniquement devant le juge"],"a":0,"e":"Sauf disposition contraire, et sans abus."},{"q":"Rompre l'essai parce que la salariée est enceinte est…","o":["Légitime","Abusif","Obligatoire"],"a":1,"e":"Le motif est étranger aux compétences."},{"q":"La période d'essai sert aussi au salarié à…","o":["Vérifier que le poste lui convient","Négocier des dividendes","Choisir son employeur suivant"],"a":0,"e":"Elle bénéficie aux deux parties."},{"q":"Un tuteur d'intégration a pour rôle de…","o":["Accompagner le nouvel arrivant","Calculer la paie","Contrôler la CNPS"],"a":0,"e":"Il facilite la prise de poste."},{"q":"Le livret d'accueil contient notamment…","o":["Les informations pratiques sur l'entreprise","Les salaires de tous","Le bilan comptable"],"a":0,"e":"Horaires, contacts, règles, organisation."},{"q":"Un bon parcours d'intégration réduit…","o":["Les départs précoces","Le chiffre d'affaires","Les congés"],"a":0,"e":"Les nouveaux restent plus volontiers."},{"q":"Durée d'essai indicative pour un agent de maîtrise ?","o":["8 jours","2 mois","6 mois"],"a":1,"e":"Catégorie intermédiaire."},{"q":"Où enregistre-t-on l'embauche dans l'entreprise ?","o":["Sur le registre d'employeur","Sur le livre des ventes","Dans le bilan"],"a":0,"e":"Le registre retrace les mouvements du personnel."},{"q":"Quelle étape précède le paramétrage de la paie ?","o":["La signature du contrat","Le départ en retraite","Le licenciement"],"a":0,"e":"Le contrat fixe les éléments de rémunération."},{"q":"L'appartenance syndicale peut-elle justifier un refus d'embauche ?","o":["Oui","Non","Seulement dans les PME"],"a":1,"e":"C'est une discrimination interdite."},{"q":"Des points d'étape pendant l'essai permettent…","o":["D'évaluer et d'ajuster la prise de poste","De réduire le salaire","D'annuler la CNPS"],"a":0,"e":"Ils rendent l'évaluation objective."},{"q":"Le handicap peut-il être un motif d'exclusion d'un candidat ?","o":["Oui","Non, c'est discriminatoire","Seulement pour les cadres"],"a":1,"e":"Seule l'aptitude au poste, avec aménagements, peut être évaluée."}]},{"id":"mrh301-5","n":5,"t":"Exécution du contrat et pouvoir disciplinaire","min":25,"html":"<h3>Obligations de l'employeur</h3>\n<ul><li>Fournir le travail convenu et les moyens de l'exécuter.</li><li>Payer le salaire à échéance régulière et remettre un bulletin de paie.</li><li>Assurer la santé et la sécurité au travail.</li><li>Respecter la dignité et la vie privée du salarié.</li></ul>\n<h3>Obligations du salarié</h3>\n<ul><li>Exécuter personnellement le travail, avec soin.</li><li>Respecter les horaires, consignes et le règlement intérieur.</li><li>Être loyal : pas de concurrence déloyale, discrétion sur les informations confidentielles.</li></ul>\n<h3>Le pouvoir disciplinaire</h3>\n<p>L'employeur peut sanctionner une faute. L'échelle des sanctions figure dans le règlement intérieur :</p>\n<div class=\"tbl\"><table><thead><tr><th>Sanction</th><th>Gravité</th></tr></thead><tbody>\n<tr><td>Avertissement écrit</td><td>Faible</td></tr><tr><td>Blâme</td><td>Faible à moyenne</td></tr>\n<tr><td>Mise à pied</td><td>Moyenne : suspension sans salaire pour une durée limitée</td></tr>\n<tr><td>Licenciement</td><td>Maximale</td></tr></tbody></table></div>\n<h3>Les garanties du salarié</h3>\n<ul><li>La sanction doit être <strong>proportionnée</strong> à la faute.</li><li>Le salarié doit pouvoir <strong>s'expliquer</strong> avant la décision.</li><li>Une même faute ne peut être sanctionnée <strong>deux fois</strong>.</li><li>Les <strong>amendes</strong> et sanctions pécuniaires sont interdites.</li><li>La sanction doit être notifiée par écrit et motivée.</li></ul>\n<h3>Les degrés de faute</h3>\n<p>La <strong>faute légère</strong> justifie un avertissement ; la <strong>faute sérieuse</strong> peut justifier un licenciement avec préavis ; la <strong>faute lourde</strong> (vol, violence, abandon de poste prolongé) rend impossible le maintien du salarié et prive de préavis et d'indemnité de licenciement.</p>","quiz":[{"q":"Une obligation de l'employeur est de…","o":["Assurer la sécurité au travail","Choisir le logement du salarié","Contrôler ses comptes bancaires"],"a":0,"e":"C'est une obligation essentielle."},{"q":"Le salarié doit exécuter le travail…","o":["Personnellement","Par un remplaçant de son choix","Uniquement à distance"],"a":0,"e":"Le contrat est conclu en considération de la personne."},{"q":"L'obligation de loyauté interdit notamment…","o":["La concurrence déloyale","Les congés","La syndicalisation"],"a":0,"e":"Le salarié ne doit pas nuire à son employeur."},{"q":"Où figure l'échelle des sanctions ?","o":["Dans le règlement intérieur","Dans le bilan","Dans le registre CNPS"],"a":0,"e":"Elle doit être connue des salariés."},{"q":"La sanction la plus légère est généralement…","o":["L'avertissement","La mise à pied","Le licenciement"],"a":0,"e":"C'est le premier degré."},{"q":"La mise à pied disciplinaire est…","o":["Une suspension sans salaire limitée dans le temps","Une promotion","Un congé payé"],"a":0,"e":"Sanction de gravité moyenne."},{"q":"Les amendes infligées au salarié sont…","o":["Autorisées","Interdites","Obligatoires"],"a":1,"e":"Les sanctions pécuniaires sont prohibées."},{"q":"Peut-on sanctionner deux fois la même faute ?","o":["Oui","Non","Oui si le salarié est cadre"],"a":1,"e":"Règle du non-cumul."},{"q":"Avant de sanctionner, l'employeur doit…","o":["Permettre au salarié de s'expliquer","Prévenir la police","Consulter la CNPS"],"a":0,"e":"C'est une garantie des droits de la défense."},{"q":"La sanction doit être…","o":["Proportionnée à la faute","Toujours maximale","Secrète"],"a":0,"e":"Le juge contrôle la proportionnalité."},{"q":"La faute lourde prive le salarié…","o":["Du préavis et de l'indemnité de licenciement","Des congés déjà pris","De son nom"],"a":0,"e":"C'est sa conséquence principale."},{"q":"Un exemple de faute lourde est…","o":["Un retard isolé","Le vol dans l'entreprise","Une erreur de saisie"],"a":1,"e":"Elle rend impossible le maintien du salarié."},{"q":"Une faute sérieuse peut justifier…","o":["Un licenciement avec préavis","Une amende","Une réduction de salaire"],"a":0,"e":"Elle ne prive pas du préavis."},{"q":"La remise d'un bulletin de paie est une obligation…","o":["De l'employeur","Du salarié","De l'inspecteur"],"a":0,"e":"Elle accompagne chaque paiement."},{"q":"La discrétion sur les informations confidentielles relève de…","o":["L'obligation de loyauté","L'obligation de sécurité","Le droit de grève"],"a":0,"e":"Le salarié protège les secrets de l'entreprise."},{"q":"La notification d'une sanction doit être…","o":["Écrite et motivée","Orale seulement","Facultative"],"a":0,"e":"Le salarié doit connaître les griefs."},{"q":"Qui contrôle en dernier ressort la proportionnalité d'une sanction contestée ?","o":["Le juge","Le collègue","Le fournisseur"],"a":0,"e":"Le tribunal du travail peut annuler une sanction disproportionnée."},{"q":"Respecter la dignité du salarié est une obligation…","o":["De l'employeur","Facultative","Réservée aux cadres"],"a":0,"e":"Elle interdit notamment le harcèlement."},{"q":"Le blâme est une sanction de gravité…","o":["Faible à moyenne","Maximale","Nulle"],"a":0,"e":"Il reste inscrit au dossier."},{"q":"Le pouvoir disciplinaire découle…","o":["Du lien de subordination","Du capital social","Du règlement fiscal"],"a":0,"e":"Il fait partie des pouvoirs de l'employeur."}]},{"id":"mrh301-6","n":6,"t":"Durée du travail, repos et congés","min":25,"html":"<h3>La durée légale</h3>\n<p>Dans les entreprises non agricoles, la durée légale est de <strong>40 heures par semaine</strong>. Les heures effectuées au-delà sont des heures supplémentaires, soumises à autorisation et plafonnées.</p>\n<h3>Les heures supplémentaires</h3>\n<p>Elles donnent lieu à une majoration fixée par voie réglementaire. À titre indicatif, les taux pratiqués en Côte d'Ivoire sont :</p>\n<div class=\"tbl\"><table><thead><tr><th>Heures</th><th>Majoration indicative</th></tr></thead><tbody>\n<tr><td>41e à 46e heure</td><td>15 %</td></tr><tr><td>Au-delà de la 46e</td><td>50 %</td></tr>\n<tr><td>Heures de nuit</td><td>75 %</td></tr><tr><td>Dimanche et jours fériés (jour)</td><td>75 %</td></tr>\n<tr><td>Dimanche et jours fériés (nuit)</td><td>100 %</td></tr></tbody></table></div>\n<p class=\"note-sample\">Vérifiez toujours les taux dans le décret en vigueur.</p>\n<h3>Le repos</h3>\n<ul><li>Repos hebdomadaire d'au moins <strong>24 heures consécutives</strong>, en principe le dimanche.</li><li>Jours fériés : liste fixée par les textes ; le 1<sup>er</sup> mai est chômé et payé.</li></ul>\n<h3>Les congés payés</h3>\n<p>Le salarié acquiert <strong>2,2 jours ouvrables par mois</strong> de service effectif, soit environ 26 jours ouvrables par an, majorés selon l'ancienneté et, pour les mères, selon le nombre d'enfants à charge. Pendant le congé, il perçoit une allocation de congé calculée sur sa rémunération moyenne.</p>\n<h3>Les congés spéciaux</h3>\n<ul><li><strong>Congé de maternité</strong> : 14 semaines, dont une partie avant et une partie après l'accouchement.</li><li><strong>Permissions exceptionnelles</strong> pour événements familiaux (mariage, naissance, décès), dans les limites prévues par les textes.</li></ul>","quiz":[{"q":"Durée légale hebdomadaire dans les entreprises non agricoles ?","o":["35 heures","40 heures","48 heures"],"a":1,"e":"C'est la référence pour les heures supplémentaires."},{"q":"La 42e heure de la semaine est…","o":["Une heure normale","Une heure supplémentaire","Interdite"],"a":1,"e":"Toute heure au-delà de 40 est supplémentaire."},{"q":"Majoration indicative de la 41e à la 46e heure ?","o":["15 %","50 %","100 %"],"a":0,"e":"Premier palier de majoration."},{"q":"Majoration indicative au-delà de la 46e heure ?","o":["15 %","50 %","75 %"],"a":1,"e":"Second palier."},{"q":"Majoration indicative d'une heure de nuit un jour férié ?","o":["50 %","75 %","100 %"],"a":2,"e":"C'est le taux le plus élevé."},{"q":"Durée minimale du repos hebdomadaire ?","o":["12 heures","24 heures consécutives","48 heures"],"a":1,"e":"En principe le dimanche."},{"q":"Le repos hebdomadaire est en principe pris…","o":["Le lundi","Le dimanche","Au choix du salarié chaque semaine"],"a":1,"e":"Sauf dérogations prévues."},{"q":"Combien de jours ouvrables de congé acquiert-on par mois ?","o":["1,5","2,2","3"],"a":1,"e":"Soit environ 26 jours par an."},{"q":"Congés annuels de base pour 12 mois de service ?","o":["Environ 26 jours ouvrables","10 jours","45 jours"],"a":0,"e":"12 × 2,2 = 26,4."},{"q":"Les congés peuvent être majorés selon…","o":["L'ancienneté","La taille du bureau","La couleur du contrat"],"a":0,"e":"Et, pour les mères, le nombre d'enfants."},{"q":"Pendant ses congés, le salarié perçoit…","o":["Rien","Une allocation de congé","La moitié de son salaire obligatoirement"],"a":1,"e":"Calculée sur la rémunération moyenne."},{"q":"Durée du congé de maternité ?","o":["8 semaines","14 semaines","6 mois"],"a":1,"e":"Une partie avant, une partie après l'accouchement."},{"q":"Le 1er mai est…","o":["Chômé et payé","Travaillé","Chômé non payé"],"a":0,"e":"Fête du travail."},{"q":"Les heures supplémentaires sont…","o":["Illimitées","Soumises à autorisation et plafonnées","Interdites"],"a":1,"e":"Elles sont encadrées."},{"q":"Où vérifier les taux de majoration exacts ?","o":["Dans le décret en vigueur","Sur un forum","Dans le bilan"],"a":0,"e":"Les taux sont fixés par voie réglementaire."},{"q":"Un salarié travaille 45 heures. Combien d'heures supplémentaires ?","o":["3","5","45"],"a":1,"e":"45 − 40 = 5."},{"q":"Un salarié travaille 48 heures. Combien d'heures à 50 % (indicatif) ?","o":["2","8","6"],"a":0,"e":"Les heures 47 et 48 dépassent la 46e."},{"q":"Les permissions exceptionnelles couvrent…","o":["Des événements familiaux","Les vacances","Les formations longues"],"a":0,"e":"Mariage, naissance, décès…"},{"q":"Le calcul des congés se fonde sur…","o":["Le service effectif","L'âge du salarié uniquement","Le chiffre d'affaires"],"a":0,"e":"On compte les mois de travail effectif."},{"q":"Qui fixe la liste des jours fériés ?","o":["Les textes officiels","Chaque salarié","Le fournisseur"],"a":0,"e":"Elle est déterminée par l'État."}]},{"id":"mrh301-7","n":7,"t":"Suspension et modification du contrat","min":20,"html":"<h3>La suspension</h3>\n<p>Le contrat est suspendu lorsque le salarié cesse temporairement de travailler sans que le contrat soit rompu. Il reprend ensuite normalement.</p>\n<ul><li>Maladie non professionnelle, dans la limite de durée prévue par les textes.</li><li>Accident du travail ou maladie professionnelle.</li><li>Congé de maternité.</li><li>Mise à pied disciplinaire.</li><li>Grève.</li><li>Chômage technique, dans les conditions légales.</li><li>Détention préventive, dans certaines limites.</li></ul>\n<p>Pendant la suspension, le salarié ne travaille pas et n'est pas toujours payé par l'employeur ; selon le cas, il perçoit des indemnités (CNPS, maintien partiel du salaire).</p>\n<h3>Protection du salarié</h3>\n<p>L'employeur ne peut en principe pas licencier un salarié en raison de sa maladie pendant la période de protection, ni une salariée en congé de maternité.</p>\n<h3>La modification du contrat</h3>\n<div class=\"tbl\"><table><thead><tr><th>Type</th><th>Exemple</th><th>Accord du salarié ?</th></tr></thead><tbody>\n<tr><td>Modification d'un élément essentiel</td><td>Salaire, qualification, lieu de travail éloigné</td><td>Oui, obligatoire</td></tr>\n<tr><td>Changement des conditions de travail</td><td>Horaires dans la même journée, bureau voisin</td><td>Non, pouvoir de direction</td></tr></tbody></table></div>\n<p>Si le salarié refuse une modification d'un élément essentiel, l'employeur doit soit renoncer, soit engager un licenciement fondé sur un motif légitime (par exemple économique).</p>\n<h3>Le transfert d'entreprise</h3>\n<p>En cas de vente, fusion ou transformation de l'entreprise, les contrats en cours se poursuivent avec le nouvel employeur.</p>","quiz":[{"q":"La suspension du contrat signifie que…","o":["Le contrat est rompu","Le travail cesse temporairement sans rupture","Le salarié change d'employeur"],"a":1,"e":"Le contrat reprend ensuite."},{"q":"Une cause de suspension est…","o":["La maladie","La démission","La retraite"],"a":0,"e":"La maladie suspend le contrat."},{"q":"Le congé de maternité entraîne…","o":["Une suspension du contrat","Une rupture","Une modification du salaire"],"a":0,"e":"La salariée est protégée."},{"q":"La grève entraîne…","o":["La suspension du contrat","La rupture automatique","Une promotion"],"a":0,"e":"Le salaire n'est pas dû pour le temps de grève."},{"q":"Peut-on licencier une salariée en raison de son congé de maternité ?","o":["Oui","Non","Oui après 1 mois"],"a":1,"e":"Elle bénéficie d'une protection."},{"q":"Un changement de salaire est…","o":["Une modification d'un élément essentiel","Un simple changement de conditions","Libre pour l'employeur"],"a":0,"e":"Il exige l'accord du salarié."},{"q":"Un changement de bureau dans le même bâtiment est…","o":["Une modification essentielle","Un changement des conditions de travail","Un licenciement"],"a":1,"e":"Il relève du pouvoir de direction."},{"q":"Pour modifier la qualification d'un salarié, il faut…","o":["Son accord","Une note de service","L'accord de la CNPS"],"a":0,"e":"C'est un élément essentiel."},{"q":"Si le salarié refuse une modification essentielle, l'employeur peut…","o":["Renoncer ou licencier pour motif légitime","Réduire son salaire quand même","Le sanctionner automatiquement"],"a":0,"e":"Le refus n'est pas une faute en soi."},{"q":"Le chômage technique est…","o":["Une cause de suspension","Une démission","Une sanction"],"a":0,"e":"Dans les conditions fixées par la loi."},{"q":"En cas de vente de l'entreprise, les contrats…","o":["Se poursuivent avec le nouvel employeur","Sont rompus","Deviennent des CDD"],"a":0,"e":"Principe de continuité."},{"q":"Pendant un arrêt pour accident du travail, le salarié peut percevoir…","o":["Des indemnités de la CNPS","Des dividendes","Rien du tout, toujours"],"a":0,"e":"La branche risques professionnels le prend en charge."},{"q":"Modifier les horaires dans la même journée relève en principe…","o":["Du pouvoir de direction","D'un accord obligatoire","D'une décision du juge"],"a":0,"e":"C'est un changement des conditions de travail."},{"q":"La mise à pied disciplinaire suspend…","o":["Le contrat et le salaire","Uniquement les congés","Rien"],"a":0,"e":"Le salarié ne travaille pas et n'est pas payé."},{"q":"La détention préventive peut entraîner…","o":["Une suspension dans certaines limites","Un licenciement automatique","Une promotion"],"a":0,"e":"Les textes encadrent cette situation."},{"q":"Une mutation dans une ville éloignée non prévue au contrat est…","o":["Une modification essentielle","Un simple changement","Interdite dans tous les cas"],"a":0,"e":"Elle exige l'accord du salarié."},{"q":"Après une suspension, le contrat…","o":["Reprend normalement","Doit être réécrit","Devient un CDD"],"a":0,"e":"Le salarié retrouve son poste."},{"q":"La fusion de deux entreprises…","o":["Maintient les contrats en cours","Rompt tous les contrats","Réduit les salaires"],"a":0,"e":"Les contrats sont transférés."},{"q":"Le refus d'un simple changement des conditions de travail peut constituer…","o":["Une faute","Un droit absolu","Une démission"],"a":0,"e":"Il relève du pouvoir de direction."},{"q":"La maladie non professionnelle suspend le contrat…","o":["Dans la limite de durée prévue par les textes","Pour toujours","Jamais"],"a":0,"e":"Au-delà, la situation peut évoluer."}]},{"id":"mrh301-8","n":8,"t":"La rupture du contrat de travail","min":30,"html":"<h3>Les modes de rupture</h3>\n<ul><li><strong>Démission</strong> : volonté claire et non équivoque du salarié, avec respect du préavis.</li>\n<li><strong>Licenciement pour motif personnel</strong> : insuffisance professionnelle, faute.</li>\n<li><strong>Licenciement pour motif économique</strong> : difficultés économiques, restructuration ; procédure spécifique avec information de l'inspection du travail et critères d'ordre des licenciements.</li>\n<li><strong>Rupture d'un commun accord</strong>.</li><li><strong>Retraite</strong>, <strong>décès</strong>, <strong>force majeure</strong>.</li></ul>\n<h3>Le motif légitime</h3>\n<p>Le licenciement doit reposer sur un motif réel et légitime. À défaut, il est abusif et ouvre droit à des dommages-intérêts fixés par le juge.</p>\n<h3>Le préavis</h3>\n<p>Sauf faute lourde, la partie qui rompt un CDI doit respecter un préavis dont la durée varie selon la catégorie et l'ancienneté. Pendant le préavis de licenciement, le salarié dispose d'heures libres pour chercher un emploi. Le préavis non exécuté à l'initiative de l'employeur donne lieu à une indemnité compensatrice.</p>\n<h3>L'indemnité de licenciement</h3>\n<p>Elle est due au salarié licencié ayant l'ancienneté minimale requise (un an), sauf faute lourde. Elle se calcule en pourcentage du salaire mensuel moyen des 12 derniers mois, par année d'ancienneté, avec des taux croissants par tranches (de l'ordre de 30 %, 35 % puis 40 %).</p>\n<h3>Les documents de fin de contrat</h3>\n<ul><li>Le <strong>certificat de travail</strong> : dates d'entrée et de sortie, emplois occupés.</li><li>Le <strong>solde de tout compte</strong> : salaire, congés non pris, indemnités.</li><li>L'attestation destinée à la CNPS.</li></ul>\n<h3>Exercice</h3>\n<p>Un salarié a 8 ans d'ancienneté et un salaire mensuel moyen de 400 000 FCFA. Avec des taux indicatifs de 30 % pour les 5 premières années et 35 % de la 6e à la 10e, calculez l'indemnité.</p>\n<details class=\"callout\"><summary><strong>Afficher la correction</strong></summary><p style=\"margin-top:.6rem\">5 × 30 % × 400 000 = 600 000 ; 3 × 35 % × 400 000 = 420 000 ; total = <strong>1 020 000 FCFA</strong>.</p></details>","quiz":[{"q":"La démission doit exprimer une volonté…","o":["Claire et non équivoque","Implicite","Collective"],"a":0,"e":"Elle ne se présume pas."},{"q":"Un licenciement sans motif légitime est…","o":["Abusif","Économique","Valable"],"a":0,"e":"Il ouvre droit à des dommages-intérêts."},{"q":"L'insuffisance professionnelle est un motif…","o":["Personnel","Économique","Collectif"],"a":0,"e":"Il tient à la personne du salarié."},{"q":"Le licenciement économique implique notamment…","o":["L'information de l'inspection du travail","L'accord du salarié","Une amende"],"a":0,"e":"C'est une procédure spécifique."},{"q":"Quel fait prive du préavis ?","o":["La faute lourde","La faute légère","L'ancienneté"],"a":0,"e":"Le maintien du salarié est impossible."},{"q":"La durée du préavis dépend…","o":["De la catégorie et de l'ancienneté","De l'âge du dirigeant","Du chiffre d'affaires"],"a":0,"e":"Elle est fixée par les textes et la convention."},{"q":"Pendant le préavis de licenciement, le salarié dispose…","o":["D'heures libres pour chercher un emploi","D'une prime de départ doublée","D'aucun droit"],"a":0,"e":"C'est un droit prévu par les textes."},{"q":"Si l'employeur dispense le salarié de préavis, il doit…","o":["Verser une indemnité compensatrice","Ne rien verser","Payer une amende à l'État"],"a":0,"e":"Le salarié ne doit pas être pénalisé."},{"q":"Ancienneté minimale pour l'indemnité de licenciement ?","o":["1 mois","1 an","5 ans"],"a":1,"e":"En dessous, pas d'indemnité légale."},{"q":"L'indemnité de licenciement se calcule sur…","o":["Le salaire moyen des 12 derniers mois","Le premier salaire","Le SMIG"],"a":0,"e":"Par année d'ancienneté."},{"q":"Les taux de l'indemnité sont…","o":["Croissants avec l'ancienneté","Fixes","Décroissants"],"a":0,"e":"Par tranches successives."},{"q":"Ancienneté 8 ans, salaire 400 000, taux 30 % puis 35 %. Indemnité ?","o":["960 000","1 020 000","1 120 000"],"a":1,"e":"600 000 + 420 000."},{"q":"Le certificat de travail indique…","o":["Les dates et emplois occupés","Le motif du licenciement","Le salaire de tous"],"a":0,"e":"Il ne doit pas contenir de mention défavorable."},{"q":"Le solde de tout compte comprend…","o":["Salaire, congés non pris, indemnités","Uniquement le salaire","Les dividendes"],"a":0,"e":"C'est le règlement final."},{"q":"La rupture d'un commun accord suppose…","o":["La volonté des deux parties","Une faute","Une décision du juge"],"a":0,"e":"Elle est négociée."},{"q":"Le décès du salarié entraîne…","o":["La rupture du contrat","Une suspension","Un transfert au conjoint"],"a":0,"e":"Les sommes dues reviennent aux ayants droit."},{"q":"Qui fixe les dommages-intérêts pour licenciement abusif ?","o":["Le juge","L'employeur","La CNPS"],"a":0,"e":"Selon le préjudice subi."},{"q":"Les critères d'ordre des licenciements concernent…","o":["Le licenciement économique","La démission","L'essai"],"a":0,"e":"Ils déterminent qui est licencié en premier."},{"q":"La force majeure est un événement…","o":["Imprévisible et irrésistible","Prévu au contrat","Choisi par l'employeur"],"a":0,"e":"Elle peut rompre le contrat."},{"q":"Le salarié démissionnaire doit en principe…","o":["Respecter le préavis","Payer une indemnité de licenciement","Obtenir l'accord du juge"],"a":0,"e":"Sauf dispense de l'employeur."}]},{"id":"mrh301-9","n":9,"t":"Représentation du personnel et syndicats","min":25,"html":"<h3>Les délégués du personnel</h3>\n<p>Ils sont élus par les salariés dans les établissements qui emploient <strong>plus de 10 salariés</strong>. Leur nombre augmente avec l'effectif.</p>\n<ul><li>Présenter à l'employeur les réclamations individuelles et collectives (salaires, conditions de travail, application de la loi).</li><li>Saisir l'inspection du travail des plaintes relatives à l'application de la loi.</li><li>Veiller à l'application des règles d'hygiène et de sécurité.</li><li>Donner leur avis dans certains cas (licenciement économique, règlement intérieur).</li></ul>\n<p>Ils disposent d'un <strong>crédit d'heures</strong> rémunéré et d'un local. L'employeur les reçoit au moins une fois par mois.</p>\n<h3>La protection des représentants</h3>\n<p>Le licenciement d'un délégué du personnel ou d'un délégué syndical nécessite l'<strong>autorisation préalable de l'inspecteur du travail</strong>. Sans elle, le licenciement est nul.</p>\n<h3>Les syndicats</h3>\n<ul><li>La liberté syndicale permet à tout salarié d'adhérer ou non au syndicat de son choix.</li><li>Le syndicat se constitue par le dépôt de ses statuts et de la liste de ses dirigeants auprès de l'autorité compétente.</li><li>Il défend les intérêts professionnels, négocie les accords collectifs et peut agir en justice.</li><li>La section syndicale d'entreprise est représentée par un délégué syndical.</li></ul>\n<h3>Le comité d'hygiène et de sécurité</h3>\n<p>Dans les entreprises qui atteignent le seuil prévu, un comité de santé et sécurité au travail analyse les risques, enquête sur les accidents et propose des mesures de prévention.</p>\n<div class=\"callout\"><b>Rôle du RH</b>Organiser les élections, tenir le calendrier des réunions mensuelles, rédiger les procès-verbaux et suivre les réponses aux réclamations.</div>","quiz":[{"q":"À partir de quel effectif élit-on des délégués du personnel ?","o":["Plus de 10 salariés","Plus de 50 salariés","Plus de 300 salariés"],"a":0,"e":"Le seuil est fixé par la loi."},{"q":"Qui élit les délégués du personnel ?","o":["Les salariés","L'employeur","L'inspecteur du travail"],"a":0,"e":"Ils sont élus."},{"q":"Une mission des délégués est de…","o":["Présenter les réclamations des salariés","Fixer les salaires seuls","Diriger l'entreprise"],"a":0,"e":"C'est leur mission principale."},{"q":"À quelle fréquence minimale l'employeur reçoit-il les délégués ?","o":["Une fois par mois","Une fois par an","Jamais"],"a":0,"e":"Réunion mensuelle."},{"q":"Le crédit d'heures des délégués est…","o":["Rémunéré","Non payé","Déduit des congés"],"a":0,"e":"C'est du temps de travail."},{"q":"Licencier un délégué du personnel nécessite…","o":["L'autorisation de l'inspecteur du travail","L'accord du syndicat","Un simple courrier"],"a":0,"e":"Protection des représentants."},{"q":"Un licenciement de délégué sans autorisation est…","o":["Nul","Valable","Suspendu"],"a":0,"e":"Il est sans effet."},{"q":"La liberté syndicale permet…","o":["D'adhérer ou non au syndicat de son choix","D'obliger tous à adhérer","D'interdire les syndicats"],"a":0,"e":"Liberté positive et négative."},{"q":"Un syndicat se constitue par…","o":["Le dépôt des statuts et de la liste des dirigeants","Une décision de l'employeur","Un vote du conseil d'administration"],"a":0,"e":"Auprès de l'autorité compétente."},{"q":"Qui représente la section syndicale dans l'entreprise ?","o":["Le délégué syndical","Le DRH","Le comptable"],"a":0,"e":"Il est désigné par le syndicat."},{"q":"Les délégués peuvent saisir…","o":["L'inspection du travail","La Cour des comptes","La banque centrale"],"a":0,"e":"Pour les plaintes sur l'application de la loi."},{"q":"Le comité de santé et sécurité au travail…","o":["Analyse les risques et enquête sur les accidents","Fixe les dividendes","Recrute les cadres"],"a":0,"e":"Il propose des mesures de prévention."},{"q":"Un syndicat peut…","o":["Agir en justice","Lever l'impôt","Licencier"],"a":0,"e":"Pour défendre les intérêts professionnels."},{"q":"Le nombre de délégués dépend…","o":["De l'effectif","Du chiffre d'affaires","De l'ancienneté de l'entreprise"],"a":0,"e":"Il croît avec l'effectif."},{"q":"Qui organise généralement les élections dans l'entreprise ?","o":["L'employeur (service RH)","Le syndicat seul","Le médecin du travail"],"a":0,"e":"Dans le respect des règles légales."},{"q":"Les délégués donnent leur avis notamment sur…","o":["Le licenciement économique","Le choix des fournisseurs","Les prix de vente"],"a":0,"e":"Ils sont consultés dans certains cas."},{"q":"Les délégués disposent d'un local…","o":["Oui","Non","Seulement en grève"],"a":0,"e":"Pour exercer leur mandat."},{"q":"Un document à rédiger après chaque réunion avec les délégués est…","o":["Le procès-verbal","Le bilan","La facture"],"a":0,"e":"Il trace les réclamations et réponses."},{"q":"La protection des représentants vise à…","o":["Éviter les représailles","Augmenter leur salaire","Supprimer leurs heures"],"a":0,"e":"Ils doivent pouvoir exercer librement."},{"q":"Les délégués veillent aussi à…","o":["L'hygiène et la sécurité","La comptabilité","Le marketing"],"a":0,"e":"Parmi leurs missions."}]},{"id":"mrh301-10","n":10,"t":"Négociation collective, conflits et contentieux","min":30,"html":"<h3>La négociation collective</h3>\n<p>La convention collective est un accord écrit conclu entre, d'une part, un ou plusieurs syndicats de travailleurs et, d'autre part, un ou plusieurs employeurs ou organisations d'employeurs. Elle fixe les conditions de travail et les garanties sociales : classifications, salaires minima catégoriels, primes, congés, préavis.</p>\n<ul><li>Elle peut être <strong>interprofessionnelle</strong>, de <strong>branche</strong> ou d'<strong>entreprise</strong>.</li><li>Elle peut être <strong>étendue</strong> par arrêté ministériel à toutes les entreprises du champ couvert.</li></ul>\n<h3>Les conflits collectifs</h3>\n<p>Un conflit est collectif lorsqu'il oppose l'employeur à un groupe de salariés sur un intérêt collectif. La procédure comprend :</p>\n<ol><li>Une tentative de règlement dans l'entreprise.</li><li>La <strong>conciliation</strong> devant l'inspection du travail.</li><li>À défaut, la <strong>médiation</strong> ou l'<strong>arbitrage</strong>.</li></ol>\n<p>La <strong>grève</strong> est une cessation concertée du travail pour appuyer des revendications professionnelles. Elle doit être précédée d'un <strong>préavis</strong> et de l'épuisement des procédures de règlement. Pendant la grève, le contrat est suspendu et le salaire n'est pas dû. Le <strong>lock-out</strong> (fermeture par l'employeur) est strictement encadré.</p>\n<h3>Les litiges individuels</h3>\n<ol><li><strong>Tentative de conciliation</strong> devant l'inspecteur du travail.</li><li>En cas d'échec, procès-verbal de non-conciliation, puis saisine du <strong>tribunal du travail</strong>.</li><li>Appel devant la <strong>cour d'appel</strong>, puis pourvoi devant la <strong>Cour suprême</strong> (chambre judiciaire).</li></ol>\n<p>La procédure devant le tribunal du travail est en principe gratuite pour le salarié. Les actions en paiement de salaire sont soumises à un délai de prescription : le RH doit donc conserver les bulletins et les preuves de paiement.</p>","quiz":[{"q":"Qui signe une convention collective côté salariés ?","o":["Un ou plusieurs syndicats","Chaque salarié","L'inspecteur du travail"],"a":0,"e":"Ce sont les organisations syndicales."},{"q":"Une convention collective fixe notamment…","o":["Les salaires minima catégoriels","Le prix des produits","Les impôts"],"a":0,"e":"Et les classifications, primes, congés."},{"q":"Une convention de branche couvre…","o":["Un secteur d'activité","Une seule entreprise","Tous les pays"],"a":0,"e":"Par exemple le commerce ou le BTP."},{"q":"L'extension d'une convention se fait par…","o":["Arrêté ministériel","Décision de l'employeur","Vote des salariés"],"a":0,"e":"Elle s'impose alors à tout le champ couvert."},{"q":"Un conflit collectif porte sur…","o":["Un intérêt collectif","Un litige entre deux collègues","Une facture fournisseur"],"a":0,"e":"Il oppose l'employeur à un groupe."},{"q":"Première étape de règlement d'un conflit collectif ?","o":["La tentative de règlement dans l'entreprise","La grève","Le procès"],"a":0,"e":"On commence par le dialogue interne."},{"q":"Qui conduit la conciliation d'un conflit collectif ?","o":["L'inspection du travail","La CNPS","La police"],"a":0,"e":"C'est son rôle."},{"q":"À défaut de conciliation, on peut recourir à…","o":["La médiation ou l'arbitrage","Une amende","La démission collective"],"a":0,"e":"Procédures de règlement."},{"q":"La grève est…","o":["Une cessation concertée du travail","Un ralentissement individuel","Un congé payé"],"a":0,"e":"Pour appuyer des revendications professionnelles."},{"q":"La grève doit être précédée…","o":["D'un préavis","D'un licenciement","D'une fête"],"a":0,"e":"Et de l'épuisement des procédures."},{"q":"Pendant la grève, le salaire…","o":["N'est pas dû","Est doublé","Est versé par la CNPS"],"a":0,"e":"Le contrat est suspendu."},{"q":"Le lock-out désigne…","o":["La fermeture de l'entreprise par l'employeur","Une grève de salariés","Un accord salarial"],"a":0,"e":"Il est strictement encadré."},{"q":"Première étape d'un litige individuel ?","o":["Tentative de conciliation devant l'inspecteur","Appel","Cour suprême"],"a":0,"e":"Préalable obligatoire."},{"q":"Après un échec de conciliation, on saisit…","o":["Le tribunal du travail","La Cour des comptes","Le Parlement"],"a":0,"e":"Sur la base du procès-verbal de non-conciliation."},{"q":"L'appel d'un jugement du tribunal du travail est porté devant…","o":["La cour d'appel","L'inspection du travail","La CNPS"],"a":0,"e":"Deuxième degré de juridiction."},{"q":"La juridiction suprême est…","o":["La Cour suprême","Le tribunal du travail","L'inspection"],"a":0,"e":"Elle contrôle l'application du droit."},{"q":"La procédure devant le tribunal du travail est en principe…","o":["Gratuite pour le salarié","Très coûteuse","Interdite aux cadres"],"a":0,"e":"Pour faciliter l'accès à la justice."},{"q":"Pourquoi conserver les bulletins de paie ?","o":["Pour prouver les paiements en cas de litige","Pour la décoration","Pour les vendre"],"a":0,"e":"Les actions en paiement sont soumises à prescription."},{"q":"Une convention d'entreprise est signée…","o":["Au niveau d'une entreprise","Au niveau national uniquement","Par l'État seul"],"a":0,"e":"Elle peut améliorer la convention de branche."},{"q":"Les classifications professionnelles se trouvent…","o":["Dans la convention collective","Dans le bilan","Dans le registre des visites"],"a":0,"e":"Elles déterminent les catégories et salaires minima."}]}]},{"id":"mrh302","code":"MRH 302","unit":"prat","title":"Gestion de la paie et déclarations fiscales","summary":"Construire un bulletin de paie ivoirien du brut au net, calculer les cotisations CNPS et l'ITS, puis produire les déclarations mensuelles et annuelles.","lessons":[{"id":"mrh302-1","n":1,"t":"Le cadre de la paie et le bulletin","min":20,"html":"<p>La paie transforme les éléments du contrat et les événements du mois en un montant net à verser. Elle engage la responsabilité de l'employeur vis-à-vis du salarié, de la CNPS et de l'administration fiscale.</p>\n<h3>Vocabulaire de base</h3>\n<div class=\"tbl\"><table><thead><tr><th>Terme</th><th>Définition</th></tr></thead><tbody>\n<tr><td>Salaire brut</td><td>Total des éléments de rémunération avant retenues</td></tr>\n<tr><td>Brut imposable</td><td>Part du brut soumise à l'impôt</td></tr>\n<tr><td>Cotisations salariales</td><td>Retenues sur le salaire au profit de la CNPS</td></tr>\n<tr><td>Cotisations patronales</td><td>Charges payées en plus par l'employeur</td></tr>\n<tr><td>Net à payer</td><td>Somme effectivement versée au salarié</td></tr>\n<tr><td>Coût employeur</td><td>Brut + charges patronales</td></tr></tbody></table></div>\n<h3>Le SMIG</h3>\n<p>Aucun salaire ne peut être inférieur au salaire minimum interprofessionnel garanti. En Côte d'Ivoire, il a été porté à <strong>75 000 FCFA par mois</strong> à compter de janvier 2023. Les conventions collectives fixent en outre des minima par catégorie.</p>\n<h3>Les mentions du bulletin</h3>\n<ul><li>Identification de l'employeur (raison sociale, adresse, n° CNPS, n° compte contribuable).</li><li>Identification du salarié (nom, matricule, n° CNPS, emploi, catégorie, date d'embauche).</li><li>Période de paie, heures travaillées.</li><li>Éléments de rémunération, cotisations, impôts, net à payer.</li><li>Congés acquis et pris.</li></ul>\n<h3>Périodicité</h3>\n<p>Le salaire est payé à intervalles réguliers : au plus tous les mois pour les employés mensualisés. Le bulletin est remis à chaque paie et conservé par l'employeur.</p>","quiz":[{"q":"Le salaire brut est…","o":["Le total avant retenues","Le montant versé","Le coût employeur"],"a":0,"e":"Les retenues viennent ensuite."},{"q":"Le net à payer est…","o":["La somme versée au salarié","Le brut plus les charges","L'impôt"],"a":0,"e":"C'est ce que le salarié reçoit."},{"q":"Le coût employeur est égal à…","o":["Brut + charges patronales","Net − impôt","Brut − cotisations"],"a":0,"e":"C'est le coût total du salarié."},{"q":"Montant du SMIG mensuel ivoirien depuis janvier 2023 ?","o":["60 000 FCFA","75 000 FCFA","100 000 FCFA"],"a":1,"e":"Revalorisé en 2023."},{"q":"Un salaire peut-il être inférieur au SMIG ?","o":["Non","Oui avec accord","Oui en CDD"],"a":0,"e":"C'est un minimum d'ordre public."},{"q":"Les minima par catégorie sont fixés par…","o":["La convention collective","Le salarié","La banque"],"a":0,"e":"Grille des salaires catégoriels."},{"q":"Les cotisations patronales…","o":["S'ajoutent au coût employeur","Réduisent le net","Sont payées par le salarié"],"a":0,"e":"Elles ne sont pas retenues sur le salaire."},{"q":"Les cotisations salariales…","o":["Sont retenues sur le salaire","Sont payées par l'État","N'existent pas"],"a":0,"e":"Elles réduisent le net."},{"q":"Quelle mention identifie l'employeur sur le bulletin ?","o":["Le numéro CNPS employeur","Le groupe sanguin","Le nom du banquier"],"a":0,"e":"Avec la raison sociale et le compte contribuable."},{"q":"Le matricule sert à…","o":["Identifier le salarié de façon unique","Calculer l'impôt","Fixer les congés"],"a":0,"e":"C'est son identifiant interne."},{"q":"Le bulletin mentionne aussi…","o":["Les congés acquis et pris","Le chiffre d'affaires","Les salaires des collègues"],"a":0,"e":"Information utile au salarié."},{"q":"Périodicité maximale du paiement pour un mensuel ?","o":["Tous les mois","Tous les trimestres","Tous les ans"],"a":0,"e":"Le salaire est payé régulièrement."},{"q":"Le brut imposable est…","o":["La part du brut soumise à l'impôt","Toujours égal au net","Le coût employeur"],"a":0,"e":"Certains éléments en sont exclus."},{"q":"Qui conserve un double du bulletin ?","o":["L'employeur","Le fournisseur","Personne"],"a":0,"e":"Pour justifier les paiements."},{"q":"La paie engage la responsabilité de l'employeur vis-à-vis…","o":["Du salarié, de la CNPS et du fisc","Des clients seulement","Des actionnaires seulement"],"a":0,"e":"Trois interlocuteurs."},{"q":"La catégorie professionnelle figure sur le bulletin car…","o":["Elle détermine le minimum conventionnel","Elle est décorative","Elle fixe le taux de TVA"],"a":0,"e":"Elle conditionne le salaire minimum."},{"q":"Les heures travaillées sur la période figurent-elles sur le bulletin ?","o":["Oui","Non","Seulement pour les cadres"],"a":0,"e":"Elles justifient le calcul."},{"q":"Le numéro CNPS du salarié permet…","o":["De rattacher ses cotisations à ses droits","De payer la TVA","D'ouvrir un compte bancaire"],"a":0,"e":"Ses droits à retraite en dépendent."},{"q":"Si le brut est 300 000 et les charges patronales 60 000, le coût employeur est…","o":["240 000","300 000","360 000"],"a":2,"e":"300 000 + 60 000."},{"q":"Le bulletin est remis…","o":["À chaque paie","Une fois par an","Sur demande uniquement"],"a":0,"e":"C'est une obligation."}]},{"id":"mrh302-2","n":2,"t":"Salaire de base, sursalaire et primes","min":25,"html":"<h3>Le salaire de base</h3>\n<p>Il correspond au salaire minimum de la catégorie de l'emploi occupé, fixé par la convention collective. Il est calculé pour la durée légale de travail (173,33 heures par mois pour 40 heures par semaine).</p>\n<h3>Le sursalaire</h3>\n<p>C'est la part de salaire négociée au-dessus du minimum catégoriel. Salaire de base + sursalaire = salaire contractuel.</p>\n<h3>La prime d'ancienneté</h3>\n<p>Prévue par la convention collective, elle s'acquiert après une ancienneté minimale. À titre indicatif : <strong>2 % du salaire de base après 2 ans</strong>, puis <strong>1 % de plus par année</strong>, dans la limite de 25 %.</p>\n<div class=\"callout\"><b>Exemple</b>Salaire de base 200 000 FCFA, 6 ans d'ancienneté. Taux = 2 % + 4 × 1 % = 6 %. Prime = 12 000 FCFA.</div>\n<h3>Les autres primes</h3>\n<ul><li><strong>Primes liées au poste</strong> : responsabilité, salissure, panier, astreinte.</li><li><strong>Primes liées aux résultats</strong> : rendement, objectifs, bonus.</li><li><strong>Gratification</strong> ou 13e mois, si prévu par le contrat, la convention ou l'usage.</li></ul>\n<h3>Salaire horaire et journalier</h3>\n<p>Salaire horaire = salaire mensuel / 173,33. Il sert à valoriser les heures supplémentaires et les absences.</p>\n<h3>Égalité de rémunération</h3>\n<p>À travail égal, salaire égal : la rémunération ne peut pas varier selon le sexe, l'origine ou l'âge pour un même travail et une même qualification.</p>","quiz":[{"q":"Le salaire de base correspond…","o":["Au minimum de la catégorie","Au net","Au coût employeur"],"a":0,"e":"Fixé par la convention collective."},{"q":"Nombre d'heures mensuelles pour 40 h par semaine ?","o":["160","173,33","200"],"a":1,"e":"40 × 52 / 12."},{"q":"Le sursalaire est…","o":["La part négociée au-dessus du minimum","Une heure supplémentaire","Une cotisation"],"a":0,"e":"Base + sursalaire = salaire contractuel."},{"q":"Prime d'ancienneté indicative après 2 ans ?","o":["1 %","2 %","5 %"],"a":1,"e":"Puis +1 % par an."},{"q":"Plafond indicatif de la prime d'ancienneté ?","o":["10 %","25 %","50 %"],"a":1,"e":"Selon la convention collective."},{"q":"Base 200 000, 6 ans d'ancienneté : taux indicatif ?","o":["4 %","6 %","8 %"],"a":1,"e":"2 % + 4 × 1 %."},{"q":"Base 200 000, taux 6 % : prime ?","o":["6 000","12 000","20 000"],"a":1,"e":"200 000 × 6 %."},{"q":"Base 150 000, 10 ans d'ancienneté : prime indicative ?","o":["15 000","12 000","10 000"],"a":0,"e":"Taux 10 % (2 % + 8 %), soit 15 000."},{"q":"Salaire horaire = …","o":["Salaire mensuel / 173,33","Salaire mensuel / 30","Salaire annuel / 12"],"a":0,"e":"Base de calcul des heures."},{"q":"Salaire mensuel 346 660 FCFA : salaire horaire ?","o":["1 000","2 000","3 466"],"a":1,"e":"346 660 / 173,33 ≈ 2 000."},{"q":"Une prime de panier est liée…","o":["Au poste ou aux horaires","Aux résultats","À l'ancienneté"],"a":0,"e":"Elle compense un repas pris sur le lieu de travail."},{"q":"Une prime d'objectifs est liée…","o":["Aux résultats","À la salissure","À l'ancienneté"],"a":0,"e":"Elle dépend de la performance."},{"q":"Le 13e mois est dû…","o":["S'il est prévu par contrat, convention ou usage","Toujours","Jamais"],"a":0,"e":"Il n'est pas légal par défaut."},{"q":"« À travail égal, salaire égal » interdit…","o":["Les écarts fondés sur le sexe pour un même travail","Les primes","Les augmentations"],"a":0,"e":"Principe d'égalité."},{"q":"La prime d'ancienneté se calcule en général sur…","o":["Le salaire de base","Le net","Le chiffre d'affaires"],"a":0,"e":"Pas sur le sursalaire."},{"q":"Une prime d'astreinte rémunère…","o":["La disponibilité hors horaires","Les congés","L'ancienneté"],"a":0,"e":"Le salarié peut être appelé."},{"q":"Salaire contractuel = …","o":["Base + sursalaire","Base − primes","Net + impôt"],"a":0,"e":"Définition."},{"q":"Où trouver les taux de la prime d'ancienneté ?","o":["Dans la convention collective","Dans le Code pénal","Dans le bilan"],"a":0,"e":"Source conventionnelle."},{"q":"Une gratification exceptionnelle devient un usage si elle est…","o":["Générale, constante et fixe","Versée une fois","Secrète"],"a":0,"e":"Critères de l'usage."},{"q":"La prime de salissure compense…","o":["Des travaux salissants","Un retard","Un congé"],"a":0,"e":"Liée aux conditions du poste."}]},{"id":"mrh302-3","n":3,"t":"Heures supplémentaires et absences","min":25,"html":"<h3>Valoriser les heures supplémentaires</h3>\n<p>Heure supplémentaire = salaire horaire × (1 + taux de majoration). Taux indicatifs : 15 % de la 41e à la 46e heure, 50 % au-delà, 75 % la nuit ou le dimanche, 100 % la nuit du dimanche ou d'un jour férié.</p>\n<div class=\"callout\"><b>Exemple</b>Salaire horaire 1 500 FCFA. 4 heures à 15 % : 4 × 1 500 × 1,15 = 6 900 FCFA. 2 heures à 50 % : 2 × 1 500 × 1,5 = 4 500 FCFA. Total : 11 400 FCFA.</div>\n<h3>Les absences</h3>\n<div class=\"tbl\"><table><thead><tr><th>Absence</th><th>Traitement en paie</th></tr></thead><tbody>\n<tr><td>Absence injustifiée</td><td>Retenue proportionnelle, pas de sanction pécuniaire supplémentaire</td></tr>\n<tr><td>Maladie</td><td>Maintien de salaire selon l'ancienneté et la convention</td></tr>\n<tr><td>Accident du travail</td><td>Jour de l'accident payé par l'employeur, puis indemnités CNPS</td></tr>\n<tr><td>Maternité</td><td>Indemnités journalières prises en charge par la CNPS et l'employeur selon les règles en vigueur</td></tr>\n<tr><td>Permission exceptionnelle</td><td>Payée dans la limite prévue</td></tr>\n<tr><td>Congés payés</td><td>Remplacés par l'allocation de congé</td></tr></tbody></table></div>\n<h3>Calculer une retenue d'absence</h3>\n<p>Deux méthodes courantes : <strong>horaire</strong> (heures d'absence × salaire horaire) ou <strong>journalière</strong> (salaire / jours ouvrables du mois × jours d'absence). L'entreprise en choisit une et l'applique à tous.</p>\n<div class=\"callout\"><b>Exemple</b>Salaire 260 000 FCFA, 26 jours ouvrables, 2 jours d'absence injustifiée : retenue = 260 000 / 26 × 2 = 20 000 FCFA.</div>\n<h3>Les justificatifs</h3>\n<p>Le gestionnaire paie collecte chaque mois les relevés d'heures validés par les managers, les certificats médicaux et les déclarations d'accident. Sans justificatif, pas de saisie.</p>","quiz":[{"q":"Formule d'une heure supplémentaire ?","o":["Salaire horaire × (1 + taux)","Salaire mensuel × taux","Salaire horaire − taux"],"a":0,"e":"On majore le taux horaire."},{"q":"Salaire horaire 1 500, 4 h à 15 % : montant ?","o":["6 000","6 900","9 000"],"a":1,"e":"4 × 1 500 × 1,15."},{"q":"Salaire horaire 1 500, 2 h à 50 % : montant ?","o":["3 000","4 500","2 250"],"a":1,"e":"2 × 1 500 × 1,5."},{"q":"Salaire horaire 2 000, 1 h à 75 % : montant ?","o":["3 500","2 750","1 500"],"a":0,"e":"2 000 × 1,75."},{"q":"Salaire horaire 1 000, 3 h à 100 % : montant ?","o":["3 000","6 000","4 500"],"a":1,"e":"3 × 1 000 × 2."},{"q":"Une absence injustifiée entraîne…","o":["Une retenue proportionnelle","Une amende en plus","Une double retenue"],"a":0,"e":"Les sanctions pécuniaires sont interdites."},{"q":"Le jour de l'accident du travail est payé par…","o":["L'employeur","La CNPS","Le salarié"],"a":0,"e":"Ensuite, relais CNPS."},{"q":"Pendant les congés payés, le salarié perçoit…","o":["L'allocation de congé","Rien","Une indemnité CNPS"],"a":0,"e":"Elle remplace le salaire."},{"q":"Salaire 260 000, 26 jours, 2 jours d'absence : retenue ?","o":["10 000","20 000","26 000"],"a":1,"e":"260 000 / 26 × 2."},{"q":"Salaire 300 000, 25 jours ouvrables, 1 jour d'absence : retenue ?","o":["12 000","10 000","15 000"],"a":0,"e":"300 000 / 25."},{"q":"Méthode horaire de retenue = …","o":["Heures d'absence × salaire horaire","Jours × SMIG","Salaire × 10 %"],"a":0,"e":"Définition."},{"q":"L'entreprise doit appliquer sa méthode de retenue…","o":["De façon homogène à tous","Au cas par cas","Seulement aux cadres"],"a":0,"e":"Égalité de traitement."},{"q":"Le maintien de salaire en cas de maladie dépend…","o":["De l'ancienneté et de la convention","Du hasard","Du chiffre d'affaires"],"a":0,"e":"Durée variable."},{"q":"Qui valide les relevés d'heures supplémentaires ?","o":["Le manager","Le salarié seul","La CNPS"],"a":0,"e":"Avant transmission à la paie."},{"q":"Un arrêt maladie se justifie par…","o":["Un certificat médical","Un SMS","Rien"],"a":0,"e":"Pièce obligatoire."},{"q":"Sans justificatif, le gestionnaire paie…","o":["Ne saisit pas l'élément","Saisit quand même","Double le montant"],"a":0,"e":"Règle de contrôle."},{"q":"Une permission exceptionnelle pour mariage est…","o":["Payée dans la limite prévue","Toujours retenue","Interdite"],"a":0,"e":"Selon les textes."},{"q":"Les indemnités de maternité sont prises en charge…","o":["Par la CNPS et l'employeur selon les règles","Par le mari","Par la banque"],"a":0,"e":"Régime de protection sociale."},{"q":"Salaire horaire 1 200, 6 h à 15 % : montant ?","o":["8 280","7 200","10 800"],"a":0,"e":"6 × 1 200 × 1,15 = 8 280."},{"q":"Les heures supplémentaires doivent être…","o":["Justifiées et autorisées","Estimées","Payées en espèces uniquement"],"a":0,"e":"Relevés validés."}]},{"id":"mrh302-4","n":4,"t":"Avantages en nature et indemnités","min":20,"html":"<h3>Les avantages en nature</h3>\n<p>Ce sont des biens ou services fournis gratuitement ou à prix réduit par l'employeur : logement, véhicule de fonction utilisé à titre privé, domesticité, électricité, eau, téléphone. Ils font partie de la rémunération et sont en principe <strong>imposables</strong> et soumis à cotisations.</p>\n<p>Leur valeur est déterminée soit de façon réelle, soit selon des <strong>forfaits</strong> fixés par l'administration fiscale. La paie ajoute la valeur de l'avantage au brut imposable, sans la verser en argent.</p>\n<div class=\"callout\"><b>Principe comptable de la paie</b>L'avantage en nature augmente le brut et l'impôt, mais il est « déduit » à nouveau en bas de bulletin puisqu'il n'est pas payé en espèces.</div>\n<h3>Les indemnités et remboursements de frais</h3>\n<ul><li><strong>Indemnité de transport</strong> : exonérée d'impôt et de cotisations dans la limite du plafond fixé par les textes.</li><li><strong>Remboursement de frais professionnels</strong> (missions, déplacements) sur justificatifs : non imposable car ce n'est pas un salaire.</li><li><strong>Indemnités de représentation</strong> ou de logement versées en argent : imposables, sauf exception prévue par les textes.</li></ul>\n<h3>Les indemnités de rupture</h3>\n<p>L'indemnité de licenciement légale ou conventionnelle bénéficie d'un régime fiscal particulier dans certaines limites ; l'indemnité compensatrice de congés payés et l'indemnité compensatrice de préavis sont des éléments de salaire imposables.</p>\n<h3>Tableau de synthèse</h3>\n<div class=\"tbl\"><table><thead><tr><th>Élément</th><th>Imposable ?</th></tr></thead><tbody>\n<tr><td>Logement fourni</td><td>Oui (avantage en nature)</td></tr>\n<tr><td>Transport dans le plafond</td><td>Non</td></tr>\n<tr><td>Frais de mission justifiés</td><td>Non</td></tr>\n<tr><td>Indemnité compensatrice de congés</td><td>Oui</td></tr></tbody></table></div>","quiz":[{"q":"Un avantage en nature est…","o":["Un bien ou service fourni par l'employeur","Un remboursement de frais","Une amende"],"a":0,"e":"Il fait partie de la rémunération."},{"q":"Un logement fourni gratuitement est…","o":["Un avantage en nature imposable","Un frais professionnel","Exonéré dans tous les cas"],"a":0,"e":"Il s'ajoute au brut imposable."},{"q":"La valeur d'un avantage en nature peut être évaluée…","o":["Au réel ou au forfait","Librement par le salarié","Jamais"],"a":0,"e":"Selon les règles fiscales."},{"q":"L'avantage en nature est-il versé en espèces ?","o":["Non","Oui","Seulement en décembre"],"a":0,"e":"Il est déduit en bas de bulletin."},{"q":"L'indemnité de transport est exonérée…","o":["Dans la limite du plafond légal","Sans limite","Jamais"],"a":0,"e":"Au-delà, l'excédent est imposable."},{"q":"Un remboursement de frais de mission justifié est…","o":["Non imposable","Imposable","Interdit"],"a":0,"e":"Ce n'est pas un salaire."},{"q":"Pourquoi exiger des justificatifs de frais ?","o":["Pour prouver qu'il ne s'agit pas d'un salaire déguisé","Pour les archiver sans raison","Pour augmenter l'impôt"],"a":0,"e":"Sinon, requalification en salaire."},{"q":"L'indemnité compensatrice de congés payés est…","o":["Imposable","Exonérée","Une amende"],"a":0,"e":"C'est un élément de salaire."},{"q":"L'indemnité compensatrice de préavis est…","o":["Imposable","Exonérée","Versée par la CNPS"],"a":0,"e":"Elle remplace le salaire du préavis."},{"q":"Un véhicule de fonction utilisé à titre privé est…","o":["Un avantage en nature","Un frais professionnel","Un prêt"],"a":0,"e":"L'usage privé est un avantage."},{"q":"L'électricité payée par l'employeur au domicile du salarié est…","o":["Un avantage en nature","Une cotisation","Un dividende"],"a":0,"e":"Imposable selon les règles."},{"q":"L'indemnité de licenciement bénéficie…","o":["D'un régime fiscal particulier dans certaines limites","D'aucun traitement particulier","D'une double imposition"],"a":0,"e":"Régime spécifique."},{"q":"L'avantage en nature augmente…","o":["Le brut imposable","Le net versé en espèces","La TVA"],"a":0,"e":"Puis il est neutralisé en bas de bulletin."},{"q":"Une indemnité de logement versée en argent est en principe…","o":["Imposable","Toujours exonérée","Interdite"],"a":0,"e":"Sauf exception prévue."},{"q":"Un salarié reçoit une indemnité de transport supérieure au plafond. L'excédent est…","o":["Imposable","Exonéré","Remboursable à l'État"],"a":0,"e":"Seule la part dans le plafond est exonérée."},{"q":"Les frais de mission remboursés au forfait sans justificatif risquent…","o":["D'être requalifiés en salaire","D'être remboursés deux fois","D'être supprimés par la loi"],"a":0,"e":"En cas de contrôle."},{"q":"Le téléphone fourni pour un usage privé est…","o":["Un avantage en nature","Un frais de mission","Une prime d'ancienneté"],"a":0,"e":"Usage privé = avantage."},{"q":"Qui fixe les forfaits d'évaluation des avantages ?","o":["L'administration fiscale","Le salarié","Le syndicat"],"a":0,"e":"Barèmes officiels."},{"q":"Un avantage en nature est-il soumis aux cotisations sociales ?","o":["En principe oui","Jamais","Seulement pour les cadres"],"a":0,"e":"Il fait partie de la rémunération."},{"q":"Une domesticité payée par l'employeur est…","o":["Un avantage en nature","Un frais professionnel","Une indemnité de rupture"],"a":0,"e":"Service fourni au salarié."}]},{"id":"mrh302-5","n":5,"t":"Les cotisations sociales CNPS","min":30,"html":"<p>La Caisse nationale de prévoyance sociale (CNPS) gère la protection sociale des travailleurs du secteur privé. Les cotisations sont calculées sur le salaire brut, dans la limite de plafonds pour certaines branches.</p>\n<h3>Les branches et taux indicatifs</h3>\n<div class=\"tbl\"><table><thead><tr><th>Branche</th><th>Part patronale</th><th>Part salariale</th></tr></thead><tbody>\n<tr><td>Retraite</td><td>7,7 %</td><td>6,3 %</td></tr>\n<tr><td>Prestations familiales</td><td>5 %</td><td>—</td></tr>\n<tr><td>Assurance maternité</td><td>0,75 %</td><td>—</td></tr>\n<tr><td>Accidents du travail</td><td>2 % à 5 % selon le risque</td><td>—</td></tr></tbody></table></div>\n<p class=\"note-sample\">Taux et plafonds à vérifier chaque année sur le site de la CNPS.</p>\n<h3>Les plafonds</h3>\n<p>Les branches prestations familiales, maternité et accidents du travail sont calculées sur un salaire plafonné (70 000 FCFA par mois selon les règles en vigueur au moment de la rédaction). La retraite est calculée sur un plafond beaucoup plus élevé.</p>\n<div class=\"callout\"><b>Exemple</b>Brut 400 000 FCFA, taux AT 2 %. Retraite salariale : 400 000 × 6,3 % = 25 200. Retraite patronale : 400 000 × 7,7 % = 30 800. Prestations familiales : 70 000 × 5 % = 3 500. Maternité : 70 000 × 0,75 % = 525. AT : 70 000 × 2 % = 1 400.</div>\n<h3>La Couverture maladie universelle</h3>\n<p>Une cotisation CMU mensuelle forfaitaire par personne est prélevée pour le salarié et ses ayants droit, et reversée par l'employeur.</p>\n<h3>Les prestations</h3>\n<ul><li>Pension de retraite, de réversion ou d'invalidité.</li><li>Allocations familiales et prénatales.</li><li>Indemnités journalières de maternité.</li><li>Prise en charge des accidents du travail et maladies professionnelles.</li></ul>","quiz":[{"q":"Que gère la CNPS ?","o":["La protection sociale des salariés du privé","Les impôts","Les douanes"],"a":0,"e":"Caisse nationale de prévoyance sociale."},{"q":"Taux indicatif retraite part salariale ?","o":["6,3 %","7,7 %","14 %"],"a":0,"e":"La part patronale est de 7,7 %."},{"q":"Taux indicatif retraite part patronale ?","o":["6,3 %","7,7 %","5 %"],"a":1,"e":"Total retraite 14 %."},{"q":"Taux total retraite indicatif ?","o":["12 %","14 %","20 %"],"a":1,"e":"7,7 + 6,3."},{"q":"Qui paie les prestations familiales ?","o":["L'employeur seul","Le salarié seul","Les deux"],"a":0,"e":"Pas de part salariale."},{"q":"Le taux accidents du travail dépend…","o":["Du risque de l'activité","De l'âge du salarié","De la ville"],"a":0,"e":"De 2 % à 5 %."},{"q":"Brut 400 000 : retraite salariale ?","o":["25 200","30 800","28 000"],"a":0,"e":"400 000 × 6,3 %."},{"q":"Brut 400 000 : retraite patronale ?","o":["25 200","30 800","56 000"],"a":1,"e":"400 000 × 7,7 %."},{"q":"Plafond indicatif des prestations familiales ?","o":["70 000 FCFA","400 000 FCFA","Aucun"],"a":0,"e":"Selon les règles au moment de la rédaction."},{"q":"Brut 400 000, plafond 70 000, taux 5 % : prestations familiales ?","o":["20 000","3 500","5 000"],"a":1,"e":"On applique le taux au plafond."},{"q":"Assurance maternité indicative ?","o":["0,75 %","5 %","7,7 %"],"a":0,"e":"Part patronale."},{"q":"Brut 50 000 (sous le plafond), maternité 0,75 % ?","o":["375","525","500"],"a":0,"e":"50 000 × 0,75 %."},{"q":"Brut 400 000, plafond 70 000, AT 2 % ?","o":["8 000","1 400","2 000"],"a":1,"e":"70 000 × 2 %."},{"q":"La cotisation CMU est…","o":["Forfaitaire par personne","Proportionnelle au chiffre d'affaires","Facultative"],"a":0,"e":"Montant fixe mensuel."},{"q":"Qui reverse la CMU du salarié ?","o":["L'employeur","Le salarié directement toujours","La banque"],"a":0,"e":"Il la prélève et la reverse."},{"q":"Une prestation de la CNPS est…","o":["La pension de retraite","Le remboursement de la TVA","Le 13e mois"],"a":0,"e":"Branche retraite."},{"q":"Les allocations familiales relèvent de la branche…","o":["Prestations familiales","Retraite","AT"],"a":0,"e":"Financée par l'employeur."},{"q":"Où vérifier les taux à jour ?","o":["Sur le site de la CNPS","Sur un réseau social","Dans un vieux manuel"],"a":0,"e":"Source officielle."},{"q":"Les cotisations patronales réduisent-elles le net du salarié ?","o":["Non","Oui","Seulement la retraite"],"a":0,"e":"Elles s'ajoutent au coût employeur."},{"q":"Brut 200 000 : total retraite (salarié + employeur) ?","o":["28 000","12 600","15 400"],"a":0,"e":"200 000 × 14 %."}]},{"id":"mrh302-6","n":6,"t":"L'impôt sur les traitements et salaires (ITS)","min":30,"html":"<p>Depuis la réforme entrée en vigueur au 1<sup>er</sup> janvier 2024, les anciens impôts sur salaire (impôt sur les salaires, contribution nationale, impôt général sur le revenu) ont été regroupés en un <strong>impôt unique : l'ITS</strong>, retenu à la source par l'employeur.</p>\n<h3>L'assiette</h3>\n<p>L'ITS est calculé sur le <strong>revenu brut imposable</strong> du mois : salaire, primes, avantages en nature, après déduction des éléments exonérés (indemnité de transport dans le plafond, remboursements de frais).</p>\n<h3>Un barème progressif</h3>\n<p>Le revenu mensuel imposable est découpé en tranches, chacune taxée à un taux croissant. La première tranche, qui correspond au niveau du SMIG, est exonérée. Le barème exact est publié dans le Code général des impôts et les lois de finances.</p>\n<div class=\"callout\"><b>Principe du calcul par tranches</b>On n'applique pas le taux le plus élevé à tout le revenu : chaque tranche est taxée à son propre taux, puis on additionne.</div>\n<h3>La réduction pour charges de famille</h3>\n<p>Le montant brut de l'impôt est ensuite diminué d'une réduction qui dépend du nombre de parts (situation matrimoniale, enfants à charge). Plus le salarié a de charges de famille, plus la réduction est élevée.</p>\n<h3>Les étapes de calcul</h3>\n<ol><li>Déterminer le revenu brut imposable du mois.</li><li>Appliquer le barème progressif tranche par tranche.</li><li>Déduire la réduction pour charges de famille.</li><li>Retenir l'ITS sur le bulletin et le reverser à la DGI.</li></ol>\n<h3>Exercice sur un barème fictif</h3>\n<p>Barème d'entraînement : 0 % jusqu'à 75 000 ; 16 % de 75 001 à 240 000 ; 21 % au-delà. Revenu imposable : 300 000 FCFA. Calculez l'impôt avant réduction.</p>\n<details class=\"callout\"><summary><strong>Afficher la correction</strong></summary><p style=\"margin-top:.6rem\">Tranche 2 : (240 000 − 75 000) × 16 % = 26 400. Tranche 3 : (300 000 − 240 000) × 21 % = 12 600. Total = <strong>39 000 FCFA</strong>.</p></details>","quiz":[{"q":"Depuis quand l'ITS est-il un impôt unique sur les salaires ?","o":["1er janvier 2024","1er janvier 2015","1er janvier 1977"],"a":0,"e":"Réforme de la fiscalité des salaires."},{"q":"L'ITS a remplacé notamment…","o":["L'IS, la CN et l'IGR","La TVA","Les cotisations CNPS"],"a":0,"e":"Trois anciens impôts."},{"q":"Qui retient l'ITS ?","o":["L'employeur, à la source","Le salarié, en fin d'année","La banque"],"a":0,"e":"Retenue sur le bulletin."},{"q":"À qui l'ITS est-il reversé ?","o":["À la DGI","À la CNPS","Au FDFP"],"a":0,"e":"Direction générale des impôts."},{"q":"L'assiette de l'ITS est…","o":["Le revenu brut imposable","Le net à payer","Le coût employeur"],"a":0,"e":"Après exclusion des éléments exonérés."},{"q":"Un barème progressif signifie que…","o":["Chaque tranche a son propre taux croissant","Un seul taux s'applique","Les bas salaires paient plus"],"a":0,"e":"Calcul par tranches."},{"q":"La première tranche du barème est…","o":["Exonérée","Taxée au taux maximum","Doublée"],"a":0,"e":"Elle correspond au niveau du SMIG."},{"q":"La réduction pour charges de famille dépend…","o":["Du nombre de parts","Du chiffre d'affaires","De l'ancienneté"],"a":0,"e":"Situation familiale."},{"q":"Plus de charges de famille entraîne…","o":["Une réduction plus élevée","Un impôt plus élevé","Aucun effet"],"a":0,"e":"L'impôt diminue."},{"q":"Barème fictif : revenu 300 000. Tranche 16 % ?","o":["26 400","48 000","12 600"],"a":0,"e":"(240 000 − 75 000) × 16 %."},{"q":"Barème fictif : revenu 300 000. Tranche 21 % ?","o":["12 600","63 000","21 000"],"a":0,"e":"(300 000 − 240 000) × 21 %."},{"q":"Barème fictif : impôt total avant réduction pour 300 000 ?","o":["39 000","63 000","48 000"],"a":0,"e":"26 400 + 12 600."},{"q":"Barème fictif : revenu 75 000. Impôt ?","o":["0","12 000","16 000"],"a":0,"e":"Tranche exonérée."},{"q":"Barème fictif : revenu 175 000. Impôt ?","o":["16 000","28 000","36 750"],"a":0,"e":"(175 000 − 75 000) × 16 %."},{"q":"Où trouver le barème officiel ?","o":["Code général des impôts et lois de finances","Convention collective","Site de la CNPS"],"a":0,"e":"Sources fiscales."},{"q":"Quelle étape vient après l'application du barème ?","o":["La réduction pour charges de famille","Le calcul du brut","L'embauche"],"a":0,"e":"On réduit l'impôt brut."},{"q":"L'indemnité de transport dans le plafond entre-t-elle dans l'assiette ?","o":["Non","Oui","À moitié"],"a":0,"e":"Elle est exonérée."},{"q":"Les avantages en nature entrent-ils dans l'assiette ?","o":["Oui","Non","Seulement le logement"],"a":0,"e":"Ils sont imposables."},{"q":"Appliquer le taux le plus élevé à tout le revenu est…","o":["Une erreur","La bonne méthode","Obligatoire"],"a":0,"e":"On calcule tranche par tranche."},{"q":"L'ITS apparaît sur…","o":["Le bulletin de paie","Le bilan des clients","La facture"],"a":0,"e":"Comme retenue."}]},{"id":"mrh302-7","n":7,"t":"Les charges fiscales patronales","min":20,"html":"<p>En plus des cotisations CNPS, l'employeur supporte des impôts et taxes assis sur la masse salariale.</p>\n<h3>Les principales charges</h3>\n<div class=\"tbl\"><table><thead><tr><th>Charge</th><th>Bénéficiaire</th><th>Taux indicatif</th></tr></thead><tbody>\n<tr><td>Contribution employeur (impôt sur salaires à la charge de l'employeur)</td><td>DGI</td><td>Taux différent pour le personnel local et le personnel expatrié</td></tr>\n<tr><td>Taxe d'apprentissage</td><td>FDFP</td><td>0,4 %</td></tr>\n<tr><td>Taxe additionnelle à la formation professionnelle continue</td><td>FDFP</td><td>1,2 %</td></tr></tbody></table></div>\n<p class=\"note-sample\">Taux à vérifier dans le Code général des impôts de l'année.</p>\n<h3>Le FDFP</h3>\n<p>Le Fonds de développement de la formation professionnelle collecte les taxes de formation et finance en retour des plans de formation des entreprises et des actions d'apprentissage. L'entreprise qui présente un plan de formation peut obtenir un financement.</p>\n<h3>Calculer le coût employeur complet</h3>\n<div class=\"callout\"><b>Exemple (taux indicatifs)</b>Brut 400 000 FCFA. Charges CNPS patronales (retraite, PF, maternité, AT) : 30 800 + 3 500 + 525 + 1 400 = 36 225. Taxe d'apprentissage : 1 600. Formation continue : 4 800. Ces montants s'ajoutent, avec la contribution employeur, au brut pour donner le coût total.</div>\n<h3>Pourquoi le suivre ?</h3>\n<p>Le coût employeur sert à établir le budget de masse salariale, comparer des scénarios d'embauche et chiffrer une demande d'augmentation.</p>","quiz":[{"q":"La taxe d'apprentissage est versée au…","o":["FDFP","CNPS","Trésor américain"],"a":0,"e":"Fonds de développement de la formation professionnelle."},{"q":"Taux indicatif de la taxe d'apprentissage ?","o":["0,4 %","1,2 %","5 %"],"a":0,"e":"Sur la masse salariale."},{"q":"Taux indicatif de la taxe additionnelle formation continue ?","o":["0,4 %","1,2 %","7,7 %"],"a":1,"e":"Également collectée par le FDFP."},{"q":"Brut 400 000 : taxe d'apprentissage à 0,4 % ?","o":["1 600","4 000","400"],"a":0,"e":"400 000 × 0,4 %."},{"q":"Brut 400 000 : formation continue à 1,2 % ?","o":["4 800","1 200","12 000"],"a":0,"e":"400 000 × 1,2 %."},{"q":"La contribution employeur est versée à…","o":["La DGI","La CNPS","Le syndicat"],"a":0,"e":"Impôt sur salaires à la charge de l'employeur."},{"q":"La contribution employeur distingue…","o":["Personnel local et expatrié","Hommes et femmes","CDI et CDD"],"a":0,"e":"Taux différents."},{"q":"Le FDFP finance en retour…","o":["Des plans de formation","Les retraites","Les dividendes"],"a":0,"e":"Sur présentation d'un plan."},{"q":"Les charges fiscales patronales réduisent-elles le net du salarié ?","o":["Non","Oui","Parfois"],"a":0,"e":"Elles sont à la charge de l'employeur."},{"q":"Le coût employeur sert à…","o":["Établir le budget de masse salariale","Calculer la TVA","Fixer les prix de vente uniquement"],"a":0,"e":"Outil de pilotage."},{"q":"Brut 400 000 : charges CNPS patronales de l'exemple ?","o":["36 225","30 800","25 200"],"a":0,"e":"30 800 + 3 500 + 525 + 1 400."},{"q":"Où vérifier les taux fiscaux ?","o":["Code général des impôts de l'année","Convention collective","Contrat de travail"],"a":0,"e":"Source fiscale."},{"q":"Qui supporte la taxe d'apprentissage ?","o":["L'employeur","Le salarié","L'apprenti"],"a":0,"e":"Charge patronale."},{"q":"Une entreprise veut embaucher. Quel montant compare-t-elle au budget ?","o":["Le coût employeur","Le net","L'ITS"],"a":0,"e":"Coût complet du poste."},{"q":"Brut 250 000 : formation continue à 1,2 % ?","o":["3 000","1 000","2 500"],"a":0,"e":"250 000 × 1,2 %."},{"q":"Brut 250 000 : taxe d'apprentissage à 0,4 % ?","o":["1 000","2 500","400"],"a":0,"e":"250 000 × 0,4 %."},{"q":"Les taxes de formation sont assises sur…","o":["La masse salariale","Le chiffre d'affaires","Le résultat net"],"a":0,"e":"Les salaires versés."},{"q":"Chiffrer une augmentation de 10 000 FCFA brut coûte à l'employeur…","o":["Plus de 10 000 FCFA","Exactement 10 000 FCFA","Moins de 10 000 FCFA"],"a":0,"e":"On ajoute les charges patronales."},{"q":"Le FDFP est un organisme lié à…","o":["La formation professionnelle","La retraite","La santé"],"a":0,"e":"Son nom l'indique."},{"q":"La contribution employeur est un impôt ou une cotisation sociale ?","o":["Un impôt","Une cotisation sociale","Une taxe municipale"],"a":0,"e":"Versé à la DGI."}]},{"id":"mrh302-8","n":8,"t":"Du brut au net : bulletin complet","min":30,"html":"<p>Cette leçon assemble tout le cours en un bulletin complet. Suivez toujours le même ordre.</p>\n<h3>Ordre de calcul</h3>\n<ol><li>Salaire de base + sursalaire.</li><li>+ prime d'ancienneté et autres primes.</li><li>+ heures supplémentaires.</li><li>− retenues d'absence.</li><li>+ avantages en nature = <strong>brut imposable</strong>.</li><li>− cotisations salariales CNPS (retraite, CMU).</li><li>− ITS.</li><li>+ éléments non imposables (transport dans le plafond, remboursements de frais).</li><li>− avantages en nature (non versés en espèces).</li><li>− acomptes et avances = <strong>net à payer</strong>.</li></ol>\n<h3>Cas pratique</h3>\n<p>Salaire de base 250 000 ; ancienneté 4 ans (prime indicative 4 %) ; 3 heures supplémentaires à 15 % ; indemnité de transport 25 000 (exonérée) ; pas d'avantage en nature ; ITS communiqué par le logiciel : 20 000 ; acompte : 30 000.</p>\n<details class=\"callout\"><summary><strong>Afficher la correction</strong></summary>\n<p style=\"margin-top:.6rem\">Prime d'ancienneté : 250 000 × 4 % = 10 000.<br>Salaire horaire : 250 000 / 173,33 ≈ 1 442 ; 3 h × 1 442 × 1,15 ≈ 4 975.<br>Brut imposable : 250 000 + 10 000 + 4 975 = 264 975.<br>Retraite salariale : 264 975 × 6,3 % ≈ 16 693.<br>Net imposable après CNPS et ITS : 264 975 − 16 693 − 20 000 = 228 282.<br>+ transport 25 000 − acompte 30 000 = <strong>223 282 FCFA</strong>.</p></details>\n<h3>Les contrôles de cohérence</h3>\n<ul><li>Le net est-il inférieur au brut + éléments non imposables ?</li><li>Les taux et plafonds appliqués sont-ils ceux de l'année ?</li><li>L'écart avec le mois précédent s'explique-t-il ?</li></ul>","quiz":[{"q":"Premier élément du calcul de la paie ?","o":["Salaire de base + sursalaire","ITS","Acompte"],"a":0,"e":"On part du salaire contractuel."},{"q":"Les avantages en nature entrent dans…","o":["Le brut imposable","Le net en espèces","Rien"],"a":0,"e":"Puis ils sont déduits en bas de bulletin."},{"q":"Les cotisations salariales sont déduites…","o":["Après le brut imposable","Avant le salaire de base","Jamais"],"a":0,"e":"Étape 6."},{"q":"L'indemnité de transport exonérée est ajoutée…","o":["Après les retenues","Au brut imposable","Jamais"],"a":0,"e":"Elle n'est pas imposable."},{"q":"L'acompte est…","o":["Déduit du net","Ajouté au brut","Versé à la CNPS"],"a":0,"e":"Il a déjà été payé."},{"q":"Base 250 000, prime d'ancienneté 4 % ?","o":["10 000","4 000","25 000"],"a":0,"e":"250 000 × 4 %."},{"q":"Salaire horaire pour 250 000 ?","o":["≈ 1 442","≈ 2 500","≈ 1 000"],"a":0,"e":"250 000 / 173,33."},{"q":"Brut imposable du cas pratique ?","o":["≈ 264 975","250 000","289 975"],"a":0,"e":"250 000 + 10 000 + 4 975."},{"q":"Retraite salariale du cas pratique ?","o":["≈ 16 693","≈ 20 403","≈ 25 000"],"a":0,"e":"6,3 % du brut imposable."},{"q":"Net à payer du cas pratique ?","o":["≈ 223 282","≈ 264 975","≈ 198 282"],"a":0,"e":"Après transport et acompte."},{"q":"L'ITS est déduit…","o":["Après les cotisations salariales","Avant le salaire de base","Du coût employeur"],"a":0,"e":"Étape 7."},{"q":"Un net supérieur au brut + non imposables indique…","o":["Une erreur","Un bonus légal","Rien d'anormal"],"a":0,"e":"Contrôle de cohérence."},{"q":"Les retenues d'absence interviennent…","o":["Avant le brut imposable","Après le net","Jamais"],"a":0,"e":"Étape 4."},{"q":"Pourquoi vérifier l'écart avec le mois précédent ?","o":["Pour détecter les erreurs","Pour décorer","Pour réduire l'impôt"],"a":0,"e":"Un écart inexpliqué est suspect."},{"q":"Les remboursements de frais sont…","o":["Ajoutés comme non imposables","Soumis à l'ITS","Soumis à la CNPS"],"a":0,"e":"Ils ne sont pas du salaire."},{"q":"Si l'avantage en nature vaut 50 000, on…","o":["L'ajoute au brut puis le déduit du net","L'ajoute au net en espèces","L'ignore"],"a":0,"e":"Neutralisation."},{"q":"Heures supplémentaires dans le brut imposable ?","o":["Oui","Non","Seulement au-delà de 46 h"],"a":0,"e":"Elles sont imposables."},{"q":"Les taux utilisés doivent être…","o":["Ceux de l'année en cours","Ceux de 1995","Choisis librement"],"a":0,"e":"Contrôle de mise à jour."},{"q":"La CMU salariale est…","o":["Une retenue sur le bulletin","Une prime","Un avantage en nature"],"a":0,"e":"Forfait mensuel."},{"q":"Le net à payer correspond à…","o":["La somme virée au salarié","Le coût employeur","Le brut"],"a":0,"e":"Montant final."}]},{"id":"mrh302-9","n":9,"t":"Les déclarations mensuelles","min":25,"html":"<p>Après la paie, l'employeur doit déclarer et reverser les cotisations et impôts retenus. Les retards entraînent des majorations et pénalités.</p>\n<h3>Auprès de la CNPS</h3>\n<ul><li>Déclaration des salaires et des cotisations sociales, par salarié.</li><li>Périodicité : <strong>mensuelle</strong> pour les employeurs d'au moins 20 salariés, <strong>trimestrielle</strong> pour les plus petits (règle à vérifier).</li><li>Paiement dans le délai réglementaire, de préférence par télédéclaration (e-CNPS).</li></ul>\n<h3>Auprès de la DGI</h3>\n<ul><li>Déclaration et paiement de l'ITS retenu et de la contribution employeur.</li><li>Déclaration des taxes de formation (collectées pour le FDFP).</li><li>Télédéclaration et paiement sur la plateforme e-impôts.</li></ul>\n<h3>Le calendrier type</h3>\n<div class=\"tbl\"><table><thead><tr><th>Quand</th><th>Tâche</th></tr></thead><tbody>\n<tr><td>Fin du mois M</td><td>Paie du mois M, virements</td></tr>\n<tr><td>Début du mois M+1</td><td>Préparation des états récapitulatifs</td></tr>\n<tr><td>Avant l'échéance DGI de M+1</td><td>Déclaration et paiement ITS et taxes</td></tr>\n<tr><td>Avant l'échéance CNPS</td><td>Déclaration et paiement des cotisations</td></tr></tbody></table></div>\n<h3>Les rapprochements</h3>\n<p>Avant chaque déclaration, le gestionnaire rapproche le journal de paie (totaux par rubrique) des montants déclarés. Tout écart est expliqué avant l'envoi.</p>\n<div class=\"callout\"><b>Pénalités</b>Un retard de déclaration ou de paiement entraîne des majorations. Tenez un calendrier des échéances et programmez des rappels.</div>","quiz":[{"q":"Pourquoi déclarer à temps ?","o":["Pour éviter les majorations et pénalités","Pour obtenir un cadeau","C'est facultatif"],"a":0,"e":"Les retards coûtent cher."},{"q":"Périodicité CNPS indicative pour 20 salariés et plus ?","o":["Mensuelle","Annuelle","Hebdomadaire"],"a":0,"e":"Les petits employeurs déclarent par trimestre."},{"q":"Périodicité CNPS indicative pour moins de 20 salariés ?","o":["Trimestrielle","Mensuelle","Semestrielle"],"a":0,"e":"Règle à vérifier."},{"q":"La plateforme de télédéclaration fiscale est…","o":["e-impôts","e-CNPS","e-FDFP"],"a":0,"e":"Pour la DGI."},{"q":"L'ITS retenu est déclaré à…","o":["La DGI","La CNPS","La mairie"],"a":0,"e":"Impôt."},{"q":"Les cotisations sociales sont déclarées à…","o":["La CNPS","La DGI","Le FDFP"],"a":0,"e":"Protection sociale."},{"q":"Les taxes de formation sont déclarées via…","o":["La DGI pour le FDFP","La CNPS","La banque"],"a":0,"e":"Collectées pour le FDFP."},{"q":"Le journal de paie contient…","o":["Les totaux par rubrique","Les factures clients","Le bilan"],"a":0,"e":"Base des rapprochements."},{"q":"Que faire avant d'envoyer une déclaration ?","o":["Rapprocher le journal de paie et les montants déclarés","Rien","L'imprimer en couleur"],"a":0,"e":"Contrôle indispensable."},{"q":"Un écart entre journal de paie et déclaration doit être…","o":["Expliqué avant l'envoi","Ignoré","Arrondi"],"a":0,"e":"Règle de contrôle."},{"q":"Quand prépare-t-on les états récapitulatifs ?","o":["Début du mois suivant","Fin d'année seulement","Jamais"],"a":0,"e":"Calendrier type."},{"q":"Un outil pour ne pas oublier les échéances ?","o":["Un calendrier avec rappels","La mémoire seule","Un post-it perdu"],"a":0,"e":"Organisation."},{"q":"La contribution employeur est déclarée à…","o":["La DGI","La CNPS","Le syndicat"],"a":0,"e":"Impôt sur salaires employeur."},{"q":"La déclaration CNPS se fait…","o":["Par salarié","Globalement sans détail","Une fois dans la carrière"],"a":0,"e":"Pour rattacher les droits individuels."},{"q":"Un retard de paiement des cotisations entraîne…","o":["Des majorations","Une réduction","Rien"],"a":0,"e":"Pénalités de retard."},{"q":"La paie du mois M est versée…","o":["Fin du mois M","Fin du mois M+3","Au début de l'année"],"a":0,"e":"Calendrier type."},{"q":"La télédéclaration CNPS s'appelle…","o":["e-CNPS","e-impôts","e-paie"],"a":0,"e":"Service en ligne de la CNPS."},{"q":"Les déclarations sont une obligation…","o":["De l'employeur","Du salarié","Du syndicat"],"a":0,"e":"Il retient et reverse."},{"q":"Le rapprochement porte sur…","o":["Les totaux par rubrique","Les noms uniquement","Les adresses"],"a":0,"e":"Montants."},{"q":"Les règles de périodicité doivent être…","o":["Vérifiées auprès des organismes","Inventées","Copiées d'un autre pays"],"a":0,"e":"Sources officielles."}]},{"id":"mrh302-10","n":10,"t":"Clôture annuelle, contrôles et archivage","min":25,"html":"<h3>Les déclarations annuelles</h3>\n<ul><li><strong>DISA</strong> (déclaration individuelle des salaires annuels) auprès de la CNPS : elle récapitule, salarié par salarié, les salaires et cotisations de l'année et alimente les droits à retraite.</li>\n<li><strong>État 301</strong> auprès de la DGI : déclaration annuelle récapitulative des salaires et des impôts retenus.</li></ul>\n<h3>Les travaux de fin d'année</h3>\n<ol><li>Vérifier que la somme des 12 mois correspond aux déclarations mensuelles.</li><li>Régulariser les écarts éventuels.</li><li>Mettre à jour les taux, plafonds et barèmes pour l'année suivante.</li><li>Calculer les provisions pour congés payés pour la comptabilité.</li></ol>\n<h3>Le contrôle interne de la paie</h3>\n<ul><li><strong>Séparation des tâches</strong> : celui qui saisit n'est pas celui qui valide et paie.</li><li><strong>Contrôle des entrées et sorties</strong> : pas de « salarié fantôme ».</li><li><strong>Contrôle des modifications</strong> de salaire : toute hausse est justifiée par un document signé.</li><li><strong>Accès restreint</strong> au logiciel de paie.</li></ul>\n<h3>L'archivage</h3>\n<p>Le double des bulletins, les journaux de paie et les déclarations doivent être conservés pendant les durées légales, afin de pouvoir répondre à un contrôle de la CNPS, de la DGI ou à un litige. Un archivage numérique sécurisé est recommandé.</p>\n<h3>Le contrôle par les organismes</h3>\n<p>La CNPS et la DGI peuvent contrôler l'entreprise. Un dossier de paie bien tenu (contrats, variables justifiées, déclarations rapprochées) limite les redressements.</p>","quiz":[{"q":"Que signifie DISA ?","o":["Déclaration individuelle des salaires annuels","Dossier interne des salaires ajustés","Déclaration d'impôt sur les avantages"],"a":0,"e":"Déclaration annuelle CNPS."},{"q":"La DISA est adressée à…","o":["La CNPS","La DGI","Le FDFP"],"a":0,"e":"Elle alimente les droits à retraite."},{"q":"L'État 301 est adressé à…","o":["La DGI","La CNPS","L'inspection du travail"],"a":0,"e":"Déclaration fiscale annuelle."},{"q":"Première vérification de fin d'année ?","o":["Somme des 12 mois = déclarations mensuelles","Changer de logiciel","Supprimer les archives"],"a":0,"e":"Cohérence annuelle."},{"q":"En fin d'année, on met à jour…","o":["Taux, plafonds et barèmes","Les noms des clients","Le logo"],"a":0,"e":"Pour l'année suivante."},{"q":"Les provisions pour congés payés servent…","o":["À la comptabilité","À la CNPS","Au salarié directement"],"a":0,"e":"Charges à payer."},{"q":"La séparation des tâches signifie que…","o":["Celui qui saisit ne valide pas et ne paie pas","Une seule personne fait tout","Le salarié calcule sa paie"],"a":0,"e":"Limite les fraudes."},{"q":"Un « salarié fantôme » est…","o":["Une personne payée qui n'existe pas ou ne travaille pas","Un intérimaire","Un stagiaire"],"a":0,"e":"Fraude classique."},{"q":"Toute hausse de salaire doit être justifiée par…","o":["Un document signé","Un appel téléphonique","Rien"],"a":0,"e":"Traçabilité."},{"q":"L'accès au logiciel de paie doit être…","o":["Restreint","Ouvert à tous","Public"],"a":0,"e":"Données confidentielles."},{"q":"Pourquoi archiver les bulletins ?","o":["Pour répondre aux contrôles et litiges","Pour les vendre","Par habitude seulement"],"a":0,"e":"Preuve."},{"q":"Qui peut contrôler la paie d'une entreprise ?","o":["La CNPS et la DGI","Les clients","Les concurrents"],"a":0,"e":"Organismes de contrôle."},{"q":"Un dossier de paie bien tenu limite…","o":["Les redressements","Les salaires","Les congés"],"a":0,"e":"En cas de contrôle."},{"q":"L'archivage recommandé est…","o":["Numérique et sécurisé","Sur une clé perdue","Dans un tiroir ouvert"],"a":0,"e":"Sécurité et durabilité."},{"q":"Les écarts détectés en fin d'année doivent être…","o":["Régularisés","Cachés","Reportés à dans 10 ans"],"a":0,"e":"Correction."},{"q":"La DISA récapitule les salaires…","o":["Salarié par salarié","Globalement seulement","Par client"],"a":0,"e":"Déclaration individuelle."},{"q":"Le contrôle des entrées et sorties vérifie…","o":["Que seuls les salariés présents sont payés","Les ventes","Les stocks"],"a":0,"e":"Contrôle interne."},{"q":"Combien de temps conserver les documents de paie ?","o":["Pendant les durées légales","Une semaine","Jusqu'à la fin du mois"],"a":0,"e":"Selon les textes."},{"q":"Un contrat de travail classé au dossier sert à…","o":["Justifier le salaire payé","Décorer le bureau","Calculer la TVA"],"a":0,"e":"Pièce justificative."},{"q":"La DISA a un impact sur…","o":["Les droits à retraite du salarié","Le prix de vente","Le capital social"],"a":0,"e":"Elle enregistre ses cotisations."}]}]},{"id":"mrh303","code":"MRH 303","unit":"trad","title":"Stratégie RH et gestion des carrières","summary":"Aligner les ressources humaines sur la stratégie : GPEC, référentiels de compétences, évaluation, formation, carrières, talents et fidélisation.","lessons":[{"id":"mrh303-1","n":1,"t":"La fonction RH et ses rôles stratégiques","min":20,"html":"<p>La fonction RH a longtemps été administrative (paie, contrats). Elle est devenue un partenaire de la direction, chargé de fournir à l'entreprise les compétences dont elle a besoin pour réussir.</p>\n<h3>Le modèle de Dave Ulrich</h3>\n<p>Ulrich (1997) décrit quatre rôles complémentaires du DRH, selon deux axes : court terme / long terme et processus / personnes.</p>\n<div class=\"tbl\"><table><thead><tr><th>Rôle</th><th>Focalisation</th><th>Exemple</th></tr></thead><tbody>\n<tr><td>Partenaire stratégique</td><td>Long terme, processus</td><td>Traduire le plan stratégique en plan RH</td></tr>\n<tr><td>Agent du changement</td><td>Long terme, personnes</td><td>Accompagner une réorganisation</td></tr>\n<tr><td>Expert administratif</td><td>Court terme, processus</td><td>Fiabiliser la paie, digitaliser les processus</td></tr>\n<tr><td>Champion des salariés</td><td>Court terme, personnes</td><td>Écoute, climat social, engagement</td></tr></tbody></table></div>\n<h3>Les missions de la fonction RH</h3>\n<ul><li>Attirer : recrutement, marque employeur.</li><li>Développer : formation, carrières.</li><li>Rémunérer : politique salariale.</li><li>Fidéliser : engagement, qualité de vie au travail.</li><li>Administrer : paie, contrats, obligations légales.</li><li>Dialoguer : relations sociales.</li></ul>\n<h3>Le DRH au comité de direction</h3>\n<p>Un DRH stratégique participe aux décisions : ouverture d'un site, lancement d'un produit, digitalisation. Il en chiffre l'impact humain (effectifs, compétences, coût, risques sociaux).</p>\n<div class=\"callout\"><b>À retenir</b>La stratégie RH n'existe pas seule : elle découle de la stratégie de l'entreprise.</div>","quiz":[{"q":"Qui a proposé le modèle des quatre rôles du DRH ?","o":["Dave Ulrich","Henri Fayol","Abraham Maslow"],"a":0,"e":"Modèle publié en 1997."},{"q":"Le rôle de partenaire stratégique vise…","o":["Le long terme et les processus","Le court terme et les personnes","Uniquement la paie"],"a":0,"e":"Traduire la stratégie en plan RH."},{"q":"Accompagner une réorganisation relève du rôle…","o":["D'agent du changement","D'expert administratif","De champion des salariés"],"a":0,"e":"Long terme, personnes."},{"q":"Fiabiliser la paie relève du rôle…","o":["D'expert administratif","De partenaire stratégique","D'agent du changement"],"a":0,"e":"Court terme, processus."},{"q":"Le champion des salariés s'occupe…","o":["De l'écoute et de l'engagement","Des dividendes","Des achats"],"a":0,"e":"Court terme, personnes."},{"q":"Historiquement, la fonction RH était surtout…","o":["Administrative","Commerciale","Financière"],"a":0,"e":"Paie et contrats."},{"q":"« Attirer » renvoie à…","o":["Recrutement et marque employeur","Paie","Contentieux"],"a":0,"e":"Mission d'attraction."},{"q":"« Développer » renvoie à…","o":["Formation et carrières","Licenciement","Comptabilité"],"a":0,"e":"Faire progresser les compétences."},{"q":"La stratégie RH découle…","o":["De la stratégie de l'entreprise","Des envies du DRH","Des concurrents seuls"],"a":0,"e":"Alignement stratégique."},{"q":"Un DRH au comité de direction chiffre…","o":["L'impact humain des décisions","Le prix des matières premières","Les taux de change"],"a":0,"e":"Effectifs, compétences, coût, risques."},{"q":"Combien de rôles comporte le modèle d'Ulrich ?","o":["Deux","Quatre","Six"],"a":1,"e":"Quatre rôles."},{"q":"Les deux axes du modèle sont…","o":["Court/long terme et processus/personnes","Prix/qualité","Local/international"],"a":0,"e":"Ils forment une matrice."},{"q":"Digitaliser les processus RH relève plutôt…","o":["De l'expert administratif","Du champion des salariés","Du négociateur syndical"],"a":0,"e":"Efficacité des processus."},{"q":"La qualité de vie au travail relève de la mission…","o":["Fidéliser","Administrer","Attirer"],"a":0,"e":"Elle favorise la rétention."},{"q":"Les relations sociales relèvent de la mission…","o":["Dialoguer","Rémunérer","Développer"],"a":0,"e":"Dialogue avec les représentants."},{"q":"La politique salariale relève de la mission…","o":["Rémunérer","Attirer","Dialoguer"],"a":0,"e":"Rétribution."},{"q":"Pourquoi le DRH participe-t-il aux décisions stratégiques ?","o":["Pour en mesurer l'impact humain","Pour signer les factures","Pour vendre les produits"],"a":0,"e":"Rôle de partenaire."},{"q":"L'ouverture d'un nouveau site pose au DRH la question…","o":["Des effectifs et compétences nécessaires","Du prix du terrain","De la couleur des murs"],"a":0,"e":"Planification RH."},{"q":"Le modèle d'Ulrich date de…","o":["1997","1950","2020"],"a":0,"e":"Human Resource Champions."},{"q":"Traduire le plan stratégique en plan RH est le rôle…","o":["De partenaire stratégique","D'expert administratif","De champion des salariés"],"a":0,"e":"Alignement."}]},{"id":"mrh303-2","n":2,"t":"Du diagnostic stratégique à la stratégie RH","min":25,"html":"<h3>Le diagnostic externe</h3>\n<p>L'outil <strong>PESTEL</strong> analyse l'environnement : Politique, Économique, Social, Technologique, Écologique, Légal. Côté RH : réforme du Code du travail, pénurie de profils numériques, évolution démographique, télétravail.</p>\n<h3>Le diagnostic interne</h3>\n<p>On analyse la pyramide des âges, la structure des qualifications, le turnover, l'absentéisme, la masse salariale, le climat social.</p>\n<h3>La matrice SWOT appliquée aux RH</h3>\n<div class=\"tbl\"><table><thead><tr><th></th><th>Positif</th><th>Négatif</th></tr></thead><tbody>\n<tr><td>Interne</td><td>Forces : équipe expérimentée, faible turnover</td><td>Faiblesses : peu de compétences digitales, vieillissement</td></tr>\n<tr><td>Externe</td><td>Opportunités : jeunes diplômés disponibles, financement FDFP</td><td>Menaces : concurrence pour les talents, nouvelles obligations légales</td></tr></tbody></table></div>\n<h3>La pyramide des âges</h3>\n<p>Elle représente l'effectif par tranche d'âge et par sexe. Une pyramide en « champignon » (beaucoup de seniors) annonce des départs à la retraite et des pertes de savoir-faire ; une pyramide en « poire » indique un effectif jeune, à former et fidéliser.</p>\n<h3>Formuler la stratégie RH</h3>\n<p>On en déduit 3 à 5 axes prioritaires, chacun avec des actions, des responsables, un budget et des indicateurs. Exemple : « Développer les compétences numériques : 80 % des managers formés d'ici 18 mois. »</p>","quiz":[{"q":"PESTEL analyse…","o":["L'environnement externe","Les stocks","Le bilan"],"a":0,"e":"Six dimensions externes."},{"q":"Le « L » de PESTEL signifie…","o":["Légal","Local","Logistique"],"a":0,"e":"Cadre juridique."},{"q":"La pyramide des âges fait partie du diagnostic…","o":["Interne","Externe","Commercial"],"a":0,"e":"Donnée de l'entreprise."},{"q":"Dans un SWOT, une faible compétence digitale est…","o":["Une faiblesse","Une opportunité","Une menace"],"a":0,"e":"Interne et négative."},{"q":"Des jeunes diplômés disponibles sur le marché sont…","o":["Une opportunité","Une force","Une faiblesse"],"a":0,"e":"Externe et positive."},{"q":"La concurrence pour les talents est…","o":["Une menace","Une force","Une opportunité"],"a":0,"e":"Externe et négative."},{"q":"Un faible turnover est…","o":["Une force","Une menace","Une opportunité"],"a":0,"e":"Interne et positif."},{"q":"Une pyramide en « champignon » indique…","o":["Beaucoup de seniors","Beaucoup de jeunes","Un effectif stable"],"a":0,"e":"Départs à la retraite à prévoir."},{"q":"Risque principal d'une pyramide en champignon ?","o":["Perte de savoir-faire","Excès de jeunes","Baisse des salaires"],"a":0,"e":"Départs massifs."},{"q":"Une pyramide en « poire » indique…","o":["Un effectif jeune","Un effectif vieillissant","Un effectif sans femmes"],"a":0,"e":"Base large."},{"q":"Combien d'axes prioritaires viser dans une stratégie RH ?","o":["3 à 5","20 à 30","Un seul toujours"],"a":0,"e":"Pour rester lisible."},{"q":"Chaque axe stratégique comporte…","o":["Actions, responsables, budget, indicateurs","Seulement un slogan","Une liste de noms"],"a":0,"e":"Pour être pilotable."},{"q":"Le « T » de PESTEL renvoie à…","o":["Technologique","Territorial","Temporel"],"a":0,"e":"Innovations, digitalisation."},{"q":"Une réforme du Code du travail relève du facteur…","o":["Légal","Écologique","Technologique"],"a":0,"e":"Cadre juridique."},{"q":"Le financement FDFP disponible est…","o":["Une opportunité","Une faiblesse","Une menace"],"a":0,"e":"Externe et positif."},{"q":"Le vieillissement de l'effectif est…","o":["Une faiblesse interne","Une opportunité","Une force"],"a":0,"e":"Risque interne."},{"q":"La masse salariale fait partie du diagnostic…","o":["Interne","Externe","Politique"],"a":0,"e":"Donnée interne."},{"q":"SWOT croise…","o":["Interne/externe et positif/négatif","Prix/volume","Hommes/femmes"],"a":0,"e":"Matrice à quatre cases."},{"q":"« 80 % des managers formés d'ici 18 mois » est…","o":["Un objectif mesurable","Un slogan vague","Une menace"],"a":0,"e":"Il a un indicateur et un délai."},{"q":"La pyramide des âges est construite par…","o":["Tranche d'âge et sexe","Service et salaire","Ville et client"],"a":0,"e":"Représentation classique."}]},{"id":"mrh303-3","n":3,"t":"La GPEC : démarche et outils","min":25,"html":"<p>La gestion prévisionnelle des emplois et des compétences (GPEC) consiste à anticiper les besoins en emplois et compétences pour réduire les écarts entre ressources et besoins futurs.</p>\n<h3>Les quatre étapes</h3>\n<ol><li><strong>Analyser l'existant</strong> : effectifs, emplois, compétences, âges, mobilités.</li>\n<li><strong>Anticiper les besoins</strong> à 3 à 5 ans à partir de la stratégie : nouveaux métiers, métiers en déclin, volumes.</li>\n<li><strong>Mesurer les écarts</strong> quantitatifs (nombre) et qualitatifs (compétences).</li>\n<li><strong>Bâtir le plan d'action</strong> : recrutement, formation, mobilité, reconversion, sous-traitance.</li></ol>\n<h3>Les métiers</h3>\n<ul><li><strong>Métiers sensibles</strong> : menacés par l'évolution (automatisation).</li><li><strong>Métiers émergents</strong> : nouveaux besoins (data, cybersécurité).</li><li><strong>Métiers en tension</strong> : difficiles à recruter.</li><li><strong>Métiers stratégiques</strong> : cœur de la valeur de l'entreprise.</li></ul>\n<h3>Écarts quantitatifs : exemple</h3>\n<div class=\"callout\"><b>Cas</b>Aujourd'hui : 40 comptables. Départs prévus à 3 ans : 8 retraites, 4 démissions estimées. Besoin à 3 ans : 35 comptables. Ressources prévisibles = 40 − 12 = 28. Écart = 35 − 28 = <strong>7 à recruter ou former</strong>.</div>\n<h3>Les leviers de réduction des écarts</h3>\n<div class=\"tbl\"><table><thead><tr><th>Écart</th><th>Levier</th></tr></thead><tbody>\n<tr><td>Manque de personnes</td><td>Recrutement, mobilité interne</td></tr>\n<tr><td>Manque de compétences</td><td>Formation, tutorat</td></tr>\n<tr><td>Excédent de personnes</td><td>Reconversion, mobilité, départs volontaires</td></tr></tbody></table></div>","quiz":[{"q":"Que signifie GPEC ?","o":["Gestion prévisionnelle des emplois et des compétences","Gestion de la paie et des charges","Groupe de pilotage des effectifs"],"a":0,"e":"Définition."},{"q":"Première étape de la GPEC ?","o":["Analyser l'existant","Recruter","Licencier"],"a":0,"e":"On part de la situation actuelle."},{"q":"Horizon habituel d'anticipation ?","o":["3 à 5 ans","1 semaine","30 ans"],"a":0,"e":"Moyen terme."},{"q":"Un écart qualitatif porte sur…","o":["Les compétences","Le nombre de personnes","Le budget"],"a":0,"e":"Nature des savoir-faire."},{"q":"Un écart quantitatif porte sur…","o":["Le nombre de personnes","Les compétences","Les valeurs"],"a":0,"e":"Volume."},{"q":"Un métier menacé par l'automatisation est…","o":["Sensible","Émergent","Stratégique"],"a":0,"e":"Il risque de disparaître."},{"q":"La cybersécurité est un exemple de métier…","o":["Émergent","Sensible","En déclin"],"a":0,"e":"Nouveau besoin."},{"q":"Un métier difficile à recruter est…","o":["En tension","Sensible","Excédentaire"],"a":0,"e":"Pénurie de candidats."},{"q":"Cas : 40 comptables, 12 départs, besoin 35. Ressources prévisibles ?","o":["28","35","52"],"a":0,"e":"40 − 12."},{"q":"Cas : écart à combler ?","o":["7","12","5"],"a":0,"e":"35 − 28."},{"q":"Manque de compétences : levier principal ?","o":["La formation","Le licenciement","La sous-traitance du DRH"],"a":0,"e":"Développer les compétences."},{"q":"Excédent de personnes : levier possible ?","o":["La reconversion","Le recrutement massif","L'augmentation générale"],"a":0,"e":"Réaffecter les compétences."},{"q":"Manque de personnes : levier ?","o":["Recrutement ou mobilité interne","Réduction d'horaires","Aucun"],"a":0,"e":"Combler le volume."},{"q":"La GPEC part de…","o":["La stratégie de l'entreprise","Des souhaits individuels uniquement","Du hasard"],"a":0,"e":"Besoins futurs dérivés de la stratégie."},{"q":"Un métier cœur de valeur est…","o":["Stratégique","Sensible","Secondaire"],"a":0,"e":"À protéger en priorité."},{"q":"La troisième étape de la GPEC est…","o":["Mesurer les écarts","Analyser l'existant","Bâtir le plan"],"a":0,"e":"Ordre des étapes."},{"q":"La dernière étape est…","o":["Bâtir le plan d'action","Mesurer les écarts","Analyser l'existant"],"a":0,"e":"Traduire en actions."},{"q":"60 techniciens, 10 départs, besoin 55 : écart ?","o":["5","10","15"],"a":0,"e":"55 − 50."},{"q":"20 commerciaux, 2 départs, besoin 18 : écart ?","o":["0","2","4"],"a":0,"e":"18 − 18."},{"q":"Le tutorat répond à un écart…","o":["Qualitatif","Quantitatif","Financier"],"a":0,"e":"Transmission de compétences."}]},{"id":"mrh303-4","n":4,"t":"Référentiels d'emplois et de compétences","min":20,"html":"<h3>Emploi, poste, métier</h3>\n<ul><li><strong>Poste</strong> : situation de travail individuelle et précise (« comptable fournisseurs, site de Yopougon »).</li><li><strong>Emploi</strong> : ensemble de postes proches (« comptable »).</li><li><strong>Métier</strong> : famille d'emplois partageant un cœur de compétences (« finance »).</li></ul>\n<h3>La notion de compétence</h3>\n<p>Une compétence est la capacité à mobiliser des ressources pour agir efficacement dans une situation de travail. On distingue :</p>\n<div class=\"tbl\"><table><thead><tr><th>Type</th><th>Exemple</th></tr></thead><tbody>\n<tr><td>Savoirs (connaissances)</td><td>Connaître le plan comptable</td></tr>\n<tr><td>Savoir-faire (pratiques)</td><td>Réaliser un rapprochement bancaire</td></tr>\n<tr><td>Savoir-être (comportements)</td><td>Rigueur, sens du service</td></tr></tbody></table></div>\n<h3>La fiche de poste</h3>\n<p>Elle comprend : intitulé, rattachement hiérarchique, finalité, missions et activités, compétences requises, conditions d'exercice, indicateurs de performance.</p>\n<h3>Le référentiel de compétences</h3>\n<p>Il liste, pour chaque emploi, les compétences attendues avec un niveau de maîtrise (par exemple de 1 à 4 : notions, pratique accompagnée, autonomie, expertise). Il sert à recruter, évaluer, former et construire les parcours.</p>\n<h3>La cartographie</h3>\n<p>En croisant les compétences requises et les compétences détenues par chaque salarié, on obtient une cartographie qui montre les points forts et les manques.</p>","quiz":[{"q":"Le poste est…","o":["Une situation de travail individuelle et précise","Une famille de métiers","Un salaire"],"a":0,"e":"Niveau le plus fin."},{"q":"L'emploi regroupe…","o":["Des postes proches","Des entreprises","Des salaires"],"a":0,"e":"Niveau intermédiaire."},{"q":"Le métier est…","o":["Une famille d'emplois","Un poste précis","Un contrat"],"a":0,"e":"Cœur de compétences commun."},{"q":"Connaître le plan comptable est un…","o":["Savoir","Savoir-faire","Savoir-être"],"a":0,"e":"Connaissance."},{"q":"Réaliser un rapprochement bancaire est un…","o":["Savoir-faire","Savoir","Savoir-être"],"a":0,"e":"Pratique."},{"q":"La rigueur est un…","o":["Savoir-être","Savoir","Savoir-faire"],"a":0,"e":"Comportement."},{"q":"Une compétence est…","o":["La capacité à mobiliser des ressources pour agir","Un diplôme","Une ancienneté"],"a":0,"e":"Définition."},{"q":"La fiche de poste indique…","o":["Les missions et compétences requises","Le salaire de tous","Le bilan"],"a":0,"e":"Contenu type."},{"q":"Le rattachement hiérarchique figure sur…","o":["La fiche de poste","Le bulletin CNPS","Le registre du commerce"],"a":0,"e":"Élément de la fiche."},{"q":"Niveau 4 d'une échelle notions/pratique/autonomie/expertise ?","o":["Expertise","Notions","Autonomie"],"a":0,"e":"Le plus élevé."},{"q":"Le référentiel de compétences sert à…","o":["Recruter, évaluer, former","Calculer la TVA","Vendre"],"a":0,"e":"Outil transversal."},{"q":"La cartographie des compétences croise…","o":["Compétences requises et détenues","Salaires et impôts","Clients et fournisseurs"],"a":0,"e":"Elle révèle les écarts."},{"q":"« Comptable fournisseurs, site de Yopougon » est…","o":["Un poste","Un métier","Une famille"],"a":0,"e":"Situation précise."},{"q":"« Finance » est…","o":["Un métier ou famille","Un poste","Un savoir-être"],"a":0,"e":"Niveau large."},{"q":"Les indicateurs de performance sur la fiche de poste servent…","o":["À évaluer le titulaire","À décorer","À payer la CNPS"],"a":0,"e":"Mesure des résultats."},{"q":"Le sens du service est un…","o":["Savoir-être","Savoir","Savoir-faire"],"a":0,"e":"Comportement."},{"q":"Utiliser Excel pour un tableau croisé est un…","o":["Savoir-faire","Savoir-être","Métier"],"a":0,"e":"Pratique outillée."},{"q":"La finalité du poste décrit…","o":["Sa raison d'être","Son salaire","Son lieu"],"a":0,"e":"Pourquoi le poste existe."},{"q":"La cartographie révèle…","o":["Points forts et manques","Chiffre d'affaires","Stocks"],"a":0,"e":"Diagnostic compétences."},{"q":"Le niveau « pratique accompagnée » précède…","o":["L'autonomie","Les notions","Le recrutement"],"a":0,"e":"Progression."}]},{"id":"mrh303-5","n":5,"t":"L'entretien annuel d'évaluation","min":25,"html":"<p>L'entretien annuel est un échange formalisé entre le manager et le collaborateur. Il fait le bilan de l'année écoulée et fixe les objectifs de l'année suivante.</p>\n<h3>Objectifs</h3>\n<ul><li>Évaluer les résultats et les compétences.</li><li>Fixer de nouveaux objectifs.</li><li>Identifier les besoins de formation.</li><li>Recueillir les souhaits d'évolution.</li></ul>\n<h3>Déroulé type</h3>\n<ol><li><strong>Préparation</strong> : les deux parties remplissent le support une à deux semaines avant.</li><li><strong>Accueil</strong> : rappel du cadre et de la durée.</li><li><strong>Bilan</strong> des objectifs : atteints, partiellement atteints, non atteints, avec les faits.</li><li><strong>Évaluation des compétences</strong> selon le référentiel.</li><li><strong>Objectifs</strong> de l'année à venir, SMART.</li><li><strong>Développement</strong> : formation, projet professionnel.</li><li><strong>Conclusion</strong> : commentaires et signatures.</li></ol>\n<h3>Les erreurs d'évaluation</h3>\n<div class=\"tbl\"><table><thead><tr><th>Erreur</th><th>Description</th></tr></thead><tbody>\n<tr><td>Effet de récence</td><td>Ne retenir que les derniers mois</td></tr>\n<tr><td>Effet de halo</td><td>Une qualité ou un défaut colore tout le jugement</td></tr>\n<tr><td>Tendance centrale</td><td>Noter tout le monde « moyen »</td></tr>\n<tr><td>Indulgence ou sévérité</td><td>Noter systématiquement trop haut ou trop bas</td></tr></tbody></table></div>\n<h3>Entretien annuel et entretien professionnel</h3>\n<p>L'entretien d'évaluation porte sur la performance ; l'entretien professionnel porte sur les perspectives d'évolution et de formation. Beaucoup d'entreprises les tiennent le même jour, en deux parties distinctes.</p>","quiz":[{"q":"L'entretien annuel réunit…","o":["Le manager et le collaborateur","Le DRH et le syndicat","Le salarié et la CNPS"],"a":0,"e":"Échange formalisé."},{"q":"Un objectif de l'entretien annuel est…","o":["Fixer les objectifs de l'année suivante","Calculer la paie","Licencier"],"a":0,"e":"Parmi d'autres."},{"q":"Quand préparer l'entretien ?","o":["Une à deux semaines avant","Pendant","Jamais"],"a":0,"e":"Préparation des deux parties."},{"q":"Le bilan des objectifs s'appuie sur…","o":["Des faits","Des impressions","Des rumeurs"],"a":0,"e":"Objectivité."},{"q":"Ne retenir que les derniers mois est…","o":["L'effet de récence","L'effet de halo","La tendance centrale"],"a":0,"e":"Biais temporel."},{"q":"Noter tout le monde « moyen » est…","o":["La tendance centrale","L'indulgence","L'effet de halo"],"a":0,"e":"Évitement de la décision."},{"q":"Une qualité qui colore tout le jugement est…","o":["L'effet de halo","L'effet de récence","La sévérité"],"a":0,"e":"Biais de généralisation."},{"q":"Noter systématiquement trop haut est…","o":["L'indulgence","La sévérité","La tendance centrale"],"a":0,"e":"Biais de clémence."},{"q":"Les objectifs fixés doivent être…","o":["SMART","Vagues","Secrets"],"a":0,"e":"Mesurables et datés."},{"q":"L'entretien professionnel porte sur…","o":["Les perspectives d'évolution et de formation","La performance de l'année","Le salaire uniquement"],"a":0,"e":"Distinct de l'évaluation."},{"q":"La conclusion de l'entretien comprend…","o":["Commentaires et signatures","Un licenciement","Un calcul d'ITS"],"a":0,"e":"Formalisation."},{"q":"Les besoins de formation identifiés alimentent…","o":["Le plan de formation","Le bilan comptable","Le registre CNPS"],"a":0,"e":"Lien direct."},{"q":"L'évaluation des compétences s'appuie sur…","o":["Le référentiel","L'humeur du manager","Le chiffre d'affaires global"],"a":0,"e":"Grille commune."},{"q":"Pour limiter l'effet de récence, le manager…","o":["Note des faits tout au long de l'année","Attend le dernier jour","Demande aux collègues"],"a":0,"e":"Suivi continu."},{"q":"L'accueil de l'entretien sert à…","o":["Rappeler le cadre et la durée","Annoncer une sanction","Calculer une prime"],"a":0,"e":"Mise en confiance."},{"q":"Un objectif « partiellement atteint » doit être…","o":["Expliqué avec des faits","Ignoré","Noté zéro"],"a":0,"e":"Analyse objective."},{"q":"Les souhaits d'évolution sont recueillis pour…","o":["Construire les parcours de carrière","Réduire le salaire","Remplir un formulaire inutile"],"a":0,"e":"Gestion des carrières."},{"q":"Évaluation et entretien professionnel peuvent être tenus…","o":["Le même jour en deux parties","Jamais","Par téléphone uniquement"],"a":0,"e":"Pratique courante."},{"q":"Qui signe le support d'entretien ?","o":["Le manager et le collaborateur","Le client","L'inspecteur"],"a":0,"e":"Engagement mutuel."},{"q":"La sévérité consiste à…","o":["Noter systématiquement trop bas","Noter trop haut","Ne pas noter"],"a":0,"e":"Biais inverse de l'indulgence."}]},{"id":"mrh303-6","n":6,"t":"Le plan de formation","min":25,"html":"<p>Le plan de formation (ou plan de développement des compétences) regroupe les actions de formation retenues par l'entreprise pour une période, généralement l'année.</p>\n<h3>Les étapes</h3>\n<ol><li><strong>Recueillir les besoins</strong> : entretiens annuels, managers, projets de l'entreprise, obligations réglementaires (sécurité).</li><li><strong>Analyser et prioriser</strong> selon la stratégie et le budget.</li><li><strong>Construire le plan</strong> : actions, publics, durées, prestataires, coûts, calendrier.</li><li><strong>Faire valider</strong> par la direction et informer les représentants du personnel.</li><li><strong>Mettre en œuvre</strong> : convocations, logistique, suivi des présences.</li><li><strong>Évaluer</strong> les actions.</li></ol>\n<h3>Les types de besoins</h3>\n<ul><li><strong>Individuels</strong> : un salarié qui prend de nouvelles responsabilités.</li><li><strong>Collectifs</strong> : un nouveau logiciel pour tout un service.</li><li><strong>Stratégiques</strong> : un nouveau marché ou une nouvelle norme.</li></ul>\n<h3>Les modalités</h3>\n<p>Formation présentielle, à distance (e-learning), mixte (blended), en situation de travail, tutorat, séminaire, formation certifiante.</p>\n<h3>Le financement par le FDFP</h3>\n<p>L'entreprise qui cotise au FDFP peut soumettre son plan de formation pour obtenir un financement, dans les conditions fixées par le fonds. Le dossier présente les actions, les coûts et les bénéficiaires.</p>\n<h3>Le budget</h3>\n<div class=\"callout\"><b>Exemple</b>Formation Excel pour 12 personnes : 2 jours × 150 000 FCFA par jour de formateur = 300 000 ; salle et pauses : 60 000 ; supports : 24 000. Coût total : 384 000 FCFA, soit 32 000 FCFA par participant.</div>","quiz":[{"q":"Le plan de formation couvre généralement…","o":["Une année","Une journée","Dix ans"],"a":0,"e":"Période annuelle."},{"q":"Première étape du plan ?","o":["Recueillir les besoins","Évaluer","Payer le prestataire"],"a":0,"e":"Point de départ."},{"q":"Une source de besoins est…","o":["L'entretien annuel","Le bilan comptable","Le registre des visites"],"a":0,"e":"Besoins individuels exprimés."},{"q":"Former tout un service à un nouveau logiciel est un besoin…","o":["Collectif","Individuel","Personnel privé"],"a":0,"e":"Concerne un groupe."},{"q":"Un salarié promu manager a un besoin…","o":["Individuel","Collectif","Stratégique global"],"a":0,"e":"Situation personnelle."},{"q":"Une nouvelle norme qualité crée un besoin…","o":["Stratégique","Individuel","Inexistant"],"a":0,"e":"Lié à l'orientation de l'entreprise."},{"q":"Le blended learning est…","o":["Un mélange présentiel et distanciel","Une formation uniquement en salle","Un test"],"a":0,"e":"Formation mixte."},{"q":"Qui valide le plan ?","o":["La direction","Le prestataire","Le client"],"a":0,"e":"Décision budgétaire."},{"q":"Qui est informé du plan ?","o":["Les représentants du personnel","Les concurrents","Les fournisseurs"],"a":0,"e":"Dialogue social."},{"q":"Quel organisme peut financer le plan ?","o":["Le FDFP","La CNPS","La DGI"],"a":0,"e":"Fonds de formation."},{"q":"Exemple : 2 jours × 150 000 = ?","o":["300 000","150 000","450 000"],"a":0,"e":"Coût formateur."},{"q":"Coût total de l'exemple ?","o":["384 000","300 000","360 000"],"a":0,"e":"300 000 + 60 000 + 24 000."},{"q":"Coût par participant (12 personnes) ?","o":["32 000","25 000","38 400"],"a":0,"e":"384 000 / 12."},{"q":"Dernière étape du plan ?","o":["Évaluer","Recueillir les besoins","Valider"],"a":0,"e":"Mesurer l'efficacité."},{"q":"La formation en situation de travail se déroule…","o":["Au poste","Dans un hôtel","À l'étranger obligatoirement"],"a":0,"e":"Apprentissage sur le terrain."},{"q":"Les critères de priorisation sont…","o":["La stratégie et le budget","L'ordre alphabétique","La couleur"],"a":0,"e":"Arbitrage."},{"q":"Le suivi des présences intervient lors de…","o":["La mise en œuvre","L'évaluation","Le recueil des besoins"],"a":0,"e":"Logistique."},{"q":"Le dossier FDFP présente…","o":["Actions, coûts et bénéficiaires","Le bilan fiscal","Les ventes"],"a":0,"e":"Contenu du dossier."},{"q":"Une formation obligatoire de sécurité relève de besoins…","o":["Réglementaires","Facultatifs","Commerciaux"],"a":0,"e":"Imposés par la loi."},{"q":"Le e-learning est une modalité…","o":["À distance","Présentielle","Interdite"],"a":0,"e":"Formation en ligne."}]},{"id":"mrh303-7","n":7,"t":"Évaluer la formation","min":20,"html":"<h3>Le modèle de Kirkpatrick</h3>\n<p>Donald Kirkpatrick propose d'évaluer une formation à quatre niveaux, du plus simple au plus exigeant.</p>\n<div class=\"tbl\"><table><thead><tr><th>Niveau</th><th>Question</th><th>Outil</th></tr></thead><tbody>\n<tr><td>1 Réaction</td><td>Les participants sont-ils satisfaits ?</td><td>Questionnaire « à chaud »</td></tr>\n<tr><td>2 Apprentissage</td><td>Ont-ils acquis les connaissances ?</td><td>Test, quiz, mise en situation</td></tr>\n<tr><td>3 Comportement</td><td>Appliquent-ils au poste ?</td><td>Observation, entretien « à froid » à 3 mois</td></tr>\n<tr><td>4 Résultats</td><td>L'entreprise en tire-t-elle un bénéfice ?</td><td>Indicateurs : erreurs, productivité, accidents</td></tr></tbody></table></div>\n<h3>Évaluation à chaud et à froid</h3>\n<p>L'évaluation <strong>à chaud</strong> a lieu à la fin de la session. L'évaluation <strong>à froid</strong> intervient quelques semaines ou mois après, pour vérifier le transfert au poste.</p>\n<h3>Le retour sur investissement</h3>\n<p>ROI = (gains − coût de la formation) / coût × 100. Il est difficile à calculer mais utile pour les formations à fort enjeu.</p>\n<div class=\"callout\"><b>Exemple</b>Coût : 2 000 000 FCFA. Gains estimés (baisse des erreurs de facturation) : 3 000 000 FCFA. ROI = (3 000 000 − 2 000 000) / 2 000 000 × 100 = <strong>50 %</strong>.</div>\n<h3>Les conditions du transfert</h3>\n<p>Le transfert au poste dépend du soutien du manager, de l'occasion d'appliquer rapidement, et de la pertinence du contenu par rapport au travail réel.</p>","quiz":[{"q":"Combien de niveaux compte le modèle de Kirkpatrick ?","o":["Trois","Quatre","Cinq"],"a":1,"e":"Réaction, apprentissage, comportement, résultats."},{"q":"Le niveau 1 mesure…","o":["La satisfaction","Les résultats financiers","Le comportement"],"a":0,"e":"Réaction."},{"q":"Le niveau 2 mesure…","o":["Les acquis","La satisfaction","Le ROI"],"a":0,"e":"Apprentissage."},{"q":"Le niveau 3 mesure…","o":["L'application au poste","La satisfaction","Le coût"],"a":0,"e":"Comportement."},{"q":"Le niveau 4 mesure…","o":["Les résultats pour l'entreprise","La satisfaction","Les connaissances"],"a":0,"e":"Impact organisationnel."},{"q":"Outil du niveau 1 ?","o":["Questionnaire à chaud","Indicateurs de productivité","Observation à 3 mois"],"a":0,"e":"Fin de session."},{"q":"Outil du niveau 2 ?","o":["Test ou quiz","Bilan comptable","Enquête clients"],"a":0,"e":"Vérifier les connaissances."},{"q":"L'évaluation à froid a lieu…","o":["Quelques semaines ou mois après","Pendant la formation","Avant la formation"],"a":0,"e":"Transfert au poste."},{"q":"Formule du ROI ?","o":["(gains − coût) / coût × 100","coût / gains","gains × coût"],"a":0,"e":"Rendement."},{"q":"Coût 2 M, gains 3 M : ROI ?","o":["50 %","150 %","33 %"],"a":0,"e":"(3 − 2) / 2."},{"q":"Coût 1 M, gains 1,5 M : ROI ?","o":["50 %","150 %","25 %"],"a":0,"e":"(1,5 − 1) / 1."},{"q":"Coût 1 M, gains 1 M : ROI ?","o":["0 %","100 %","50 %"],"a":0,"e":"Aucun gain net."},{"q":"Le transfert au poste dépend notamment…","o":["Du soutien du manager","De la couleur de la salle","Du prix du déjeuner"],"a":0,"e":"Facteur clé."},{"q":"Une baisse des accidents après une formation sécurité relève du niveau…","o":["4","1","2"],"a":0,"e":"Résultats."},{"q":"Un participant satisfait a-t-il forcément appris ?","o":["Non","Oui","Toujours"],"a":0,"e":"Niveaux 1 et 2 sont distincts."},{"q":"Qui a proposé les quatre niveaux ?","o":["Donald Kirkpatrick","Dave Ulrich","Frederick Taylor"],"a":0,"e":"Modèle classique."},{"q":"L'observation au poste sert le niveau…","o":["3","1","4"],"a":0,"e":"Comportement."},{"q":"Pour quelles formations calculer le ROI en priorité ?","o":["Les formations à fort enjeu","Toutes, même minimes","Aucune"],"a":0,"e":"Calcul coûteux."},{"q":"Appliquer rapidement après la formation…","o":["Favorise le transfert","Nuit à la mémorisation","N'a aucun effet"],"a":0,"e":"Occasion de pratique."},{"q":"Le niveau le plus exigeant à mesurer est…","o":["Le niveau 4","Le niveau 1","Le niveau 2"],"a":0,"e":"Résultats organisationnels."}]},{"id":"mrh303-8","n":8,"t":"Carrières, mobilité et promotion","min":25,"html":"<h3>La gestion des carrières</h3>\n<p>Elle organise l'évolution des salariés dans l'entreprise en conciliant les besoins de l'organisation et les aspirations individuelles.</p>\n<h3>Les formes de mobilité</h3>\n<div class=\"tbl\"><table><thead><tr><th>Mobilité</th><th>Définition</th><th>Exemple</th></tr></thead><tbody>\n<tr><td>Verticale</td><td>Changement de niveau hiérarchique</td><td>Technicien → chef d'équipe</td></tr>\n<tr><td>Horizontale (fonctionnelle)</td><td>Changement de métier au même niveau</td><td>Comptable → contrôleur de gestion junior</td></tr>\n<tr><td>Géographique</td><td>Changement de lieu</td><td>Abidjan → San-Pédro</td></tr>\n<tr><td>Internationale</td><td>Affectation dans une filiale étrangère</td><td>Abidjan → Dakar</td></tr></tbody></table></div>\n<h3>Les outils</h3>\n<ul><li><strong>Bourse de l'emploi interne</strong> : publication des postes vacants aux salariés.</li><li><strong>Aires de mobilité</strong> : emplois accessibles depuis un emploi donné, avec une formation courte.</li><li><strong>Bilan de compétences</strong> pour clarifier un projet professionnel.</li><li><strong>Comité carrières</strong> : revue annuelle des parcours.</li></ul>\n<h3>La promotion</h3>\n<p>Une politique de promotion transparente précise les critères : résultats, compétences, potentiel, ancienneté minimale dans le poste. La promotion s'accompagne d'un avenant au contrat et d'une période d'adaptation.</p>\n<h3>Le principe de Peter</h3>\n<p>Laurence Peter observe que chacun tend à être promu jusqu'à atteindre son niveau d'incompétence. D'où l'importance d'évaluer le potentiel pour le nouveau poste, et pas seulement la performance dans l'ancien.</p>\n<h3>Les carrières en Y</h3>\n<p>Elles offrent deux voies de progression : managériale et d'expertise. Un excellent technicien peut progresser sans devenir manager.</p>","quiz":[{"q":"La gestion des carrières concilie…","o":["Besoins de l'organisation et aspirations individuelles","Prix et coûts","Clients et fournisseurs"],"a":0,"e":"Double objectif."},{"q":"Technicien devenant chef d'équipe : mobilité…","o":["Verticale","Horizontale","Géographique"],"a":0,"e":"Changement de niveau."},{"q":"Comptable devenant contrôleur de gestion junior : mobilité…","o":["Horizontale","Verticale","Internationale"],"a":0,"e":"Changement de métier."},{"q":"Abidjan vers San-Pédro : mobilité…","o":["Géographique","Verticale","Fonctionnelle"],"a":0,"e":"Changement de lieu."},{"q":"Abidjan vers Dakar dans une filiale : mobilité…","o":["Internationale","Horizontale","Verticale"],"a":0,"e":"Autre pays."},{"q":"La bourse de l'emploi interne publie…","o":["Les postes vacants aux salariés","Les cours de la bourse","Les salaires"],"a":0,"e":"Mobilité interne."},{"q":"Une aire de mobilité regroupe…","o":["Les emplois accessibles avec une formation courte","Les bureaux libres","Les clients"],"a":0,"e":"Passerelles."},{"q":"Le bilan de compétences aide à…","o":["Clarifier un projet professionnel","Calculer la paie","Réduire les effectifs"],"a":0,"e":"Orientation."},{"q":"Le comité carrières réalise…","o":["Une revue annuelle des parcours","La paie","L'audit fiscal"],"a":0,"e":"Instance de décision."},{"q":"Un critère de promotion est…","o":["Le potentiel","La couleur préférée","L'âge seul"],"a":0,"e":"Avec résultats et compétences."},{"q":"La promotion s'accompagne…","o":["D'un avenant au contrat","D'une démission","D'un licenciement"],"a":0,"e":"Modification du contrat."},{"q":"Le principe de Peter dit que chacun tend à être promu…","o":["Jusqu'à son niveau d'incompétence","Jusqu'à la direction générale","Jamais"],"a":0,"e":"Observation de Laurence Peter."},{"q":"Pour éviter le principe de Peter, on évalue…","o":["Le potentiel pour le nouveau poste","Seulement l'ancienneté","Seulement la sympathie"],"a":0,"e":"Pas uniquement la performance passée."},{"q":"La carrière en Y offre…","o":["Une voie managériale et une voie d'expertise","Une seule voie","Aucune promotion"],"a":0,"e":"Deux filières."},{"q":"Un excellent technicien peut progresser sans devenir manager grâce à…","o":["La carrière en Y","Le principe de Peter","La mutation"],"a":0,"e":"Filière expertise."},{"q":"La transparence des critères de promotion favorise…","o":["Le sentiment d'équité","Les conflits","Le turnover"],"a":0,"e":"Justice perçue."},{"q":"Une période d'adaptation après promotion sert à…","o":["Accompagner la prise de poste","Réduire le salaire","Retarder l'avenant"],"a":0,"e":"Sécuriser la transition."},{"q":"La mobilité géographique nécessite souvent…","o":["L'accord du salarié si non prévue au contrat","Rien","Un licenciement"],"a":0,"e":"Élément essentiel."},{"q":"Les aspirations individuelles sont recueillies notamment lors…","o":["De l'entretien professionnel","De la paie","Du bilan comptable"],"a":0,"e":"Souhaits d'évolution."},{"q":"La mobilité interne réduit…","o":["Les coûts et délais de recrutement externe","Les compétences","La motivation"],"a":0,"e":"Avantage principal."}]},{"id":"mrh303-9","n":9,"t":"Talents et plans de succession","min":20,"html":"<h3>La gestion des talents</h3>\n<p>Elle vise à identifier, développer et retenir les collaborateurs à fort potentiel ou détenteurs de compétences rares.</p>\n<h3>La matrice 9-box</h3>\n<p>Elle croise la <strong>performance</strong> actuelle (faible, moyenne, forte) et le <strong>potentiel</strong> d'évolution (faible, moyen, fort) : neuf cases.</p>\n<div class=\"tbl\"><table><thead><tr><th>Case</th><th>Profil</th><th>Action</th></tr></thead><tbody>\n<tr><td>Forte performance, fort potentiel</td><td>Talent clé</td><td>Parcours accéléré, mentorat, rétention</td></tr>\n<tr><td>Forte performance, faible potentiel</td><td>Expert solide</td><td>Reconnaissance, maintien dans le poste</td></tr>\n<tr><td>Faible performance, fort potentiel</td><td>Énigme</td><td>Comprendre le blocage, changer de poste</td></tr>\n<tr><td>Faible performance, faible potentiel</td><td>À risque</td><td>Plan d'amélioration ou réorientation</td></tr></tbody></table></div>\n<h3>Le plan de succession</h3>\n<p>Pour chaque poste clé, on identifie les successeurs possibles et leur délai de préparation : « prêt maintenant », « prêt dans 1 à 2 ans », « prêt dans 3 ans et plus ». Il évite qu'un départ imprévu paralyse l'activité.</p>\n<h3>Les postes clés</h3>\n<p>Un poste est clé s'il a un fort impact sur les résultats, s'il est difficile à pourvoir ou si son titulaire détient un savoir unique.</p>\n<h3>La confidentialité</h3>\n<p>Les revues de talents sont confidentielles. On communique au salarié les actions de développement, sans lui promettre un poste.</p>","quiz":[{"q":"La gestion des talents vise à…","o":["Identifier, développer et retenir","Licencier","Réduire les salaires"],"a":0,"e":"Trois verbes clés."},{"q":"La matrice 9-box croise…","o":["Performance et potentiel","Âge et salaire","Service et ancienneté"],"a":0,"e":"Deux axes."},{"q":"Combien de cases dans la 9-box ?","o":["Six","Neuf","Douze"],"a":1,"e":"3 × 3."},{"q":"Forte performance et fort potentiel : profil ?","o":["Talent clé","À risque","Énigme"],"a":0,"e":"Case idéale."},{"q":"Forte performance et faible potentiel : profil ?","o":["Expert solide","Talent clé","Énigme"],"a":0,"e":"Performant dans son poste."},{"q":"Faible performance et fort potentiel : profil ?","o":["Énigme","Expert","Talent clé"],"a":0,"e":"Potentiel inexploité."},{"q":"Action pour un talent clé ?","o":["Parcours accéléré et rétention","Plan d'amélioration","Aucune"],"a":0,"e":"Investir."},{"q":"Action pour une « énigme » ?","o":["Comprendre le blocage","Promouvoir immédiatement","Ignorer"],"a":0,"e":"Diagnostic."},{"q":"Action pour un profil à risque ?","o":["Plan d'amélioration ou réorientation","Promotion","Bonus"],"a":0,"e":"Remédiation."},{"q":"Le plan de succession concerne…","o":["Les postes clés","Tous les stagiaires","Les fournisseurs"],"a":0,"e":"Continuité."},{"q":"« Prêt maintenant » indique…","o":["Un successeur immédiat","Un successeur dans 5 ans","Aucun successeur"],"a":0,"e":"Délai de préparation."},{"q":"Le plan de succession évite…","o":["La paralysie après un départ imprévu","Les promotions","Les formations"],"a":0,"e":"Continuité d'activité."},{"q":"Un poste est clé s'il…","o":["A un fort impact sur les résultats","Est proche de la sortie","Est récent"],"a":0,"e":"Critère principal."},{"q":"Un poste difficile à pourvoir peut être…","o":["Clé","Secondaire toujours","Supprimé"],"a":0,"e":"Autre critère."},{"q":"Les revues de talents sont…","o":["Confidentielles","Publiques","Affichées"],"a":0,"e":"Discrétion."},{"q":"Doit-on promettre un poste au successeur identifié ?","o":["Non","Oui","Toujours par écrit"],"a":0,"e":"On communique les actions de développement."},{"q":"Le mentorat est une action pour…","o":["Les talents clés","Les fournisseurs","Les clients"],"a":0,"e":"Développement."},{"q":"Un savoir unique détenu par un titulaire rend son poste…","o":["Clé","Inutile","Temporaire"],"a":0,"e":"Risque de perte."},{"q":"L'expert solide mérite…","o":["Reconnaissance et maintien","Licenciement","Rétrogradation"],"a":0,"e":"Il est performant."},{"q":"Le potentiel mesure…","o":["La capacité d'évolution future","Le salaire actuel","L'ancienneté"],"a":0,"e":"Projection."}]},{"id":"mrh303-10","n":10,"t":"Marque employeur et fidélisation","min":20,"html":"<h3>La marque employeur</h3>\n<p>C'est l'image de l'entreprise en tant qu'employeur, auprès des candidats et des salariés. Elle repose sur une promesse (la proposition de valeur employeur) : ce que l'entreprise offre en échange du travail.</p>\n<ul><li>Rémunération et avantages.</li><li>Perspectives de carrière et de formation.</li><li>Culture, valeurs, ambiance.</li><li>Sens du travail et impact.</li><li>Équilibre vie professionnelle / vie personnelle.</li></ul>\n<h3>Les canaux</h3>\n<p>Site carrière, réseaux professionnels, relations écoles, forums emploi, témoignages de salariés, avis en ligne.</p>\n<h3>La fidélisation</h3>\n<p>Un départ coûte cher : recrutement, intégration, perte de productivité. Les leviers de fidélisation :</p>\n<div class=\"tbl\"><table><thead><tr><th>Levier</th><th>Exemple</th></tr></thead><tbody>\n<tr><td>Reconnaissance</td><td>Feedback régulier, valorisation des réussites</td></tr>\n<tr><td>Développement</td><td>Formation, mobilité interne</td></tr>\n<tr><td>Rémunération</td><td>Équité interne, compétitivité externe</td></tr>\n<tr><td>Management</td><td>Manager de proximité disponible</td></tr>\n<tr><td>Conditions de travail</td><td>Horaires, sécurité, outils</td></tr></tbody></table></div>\n<h3>Mesurer</h3>\n<p>Taux de turnover, taux de départ des talents, ancienneté moyenne, résultats des enquêtes d'engagement, motifs recueillis lors des <strong>entretiens de départ</strong>.</p>\n<h3>Théorie de Herzberg</h3>\n<p>Herzberg distingue les <strong>facteurs d'hygiène</strong> (salaire, conditions) dont l'absence crée l'insatisfaction, et les <strong>facteurs de motivation</strong> (reconnaissance, responsabilité, intérêt du travail) qui créent la satisfaction.</p>","quiz":[{"q":"La marque employeur est…","o":["L'image de l'entreprise en tant qu'employeur","Le logo des produits","Le prix de vente"],"a":0,"e":"Auprès des candidats et salariés."},{"q":"La proposition de valeur employeur décrit…","o":["Ce que l'entreprise offre en échange du travail","Les prix","Les bénéfices"],"a":0,"e":"Promesse."},{"q":"Un canal de marque employeur est…","o":["Le site carrière","Le bilan","La déclaration fiscale"],"a":0,"e":"Communication vers les candidats."},{"q":"Pourquoi un départ coûte-t-il cher ?","o":["Recrutement, intégration, perte de productivité","Il ne coûte rien","Seulement à cause des cadeaux"],"a":0,"e":"Coûts cachés."},{"q":"Un feedback régulier est un levier de…","o":["Reconnaissance","Rémunération","Sécurité"],"a":0,"e":"Valoriser."},{"q":"La mobilité interne est un levier de…","o":["Développement","Sanction","Rémunération"],"a":0,"e":"Évolution."},{"q":"L'équité interne concerne…","o":["La rémunération","Les horaires","Les stocks"],"a":0,"e":"Justice salariale."},{"q":"Un manager de proximité disponible est un levier…","o":["Managérial","Fiscal","Commercial"],"a":0,"e":"Relation au quotidien."},{"q":"Les entretiens de départ servent à…","o":["Recueillir les motifs de départ","Retenir le salaire","Calculer l'ITS"],"a":0,"e":"Comprendre et corriger."},{"q":"Selon Herzberg, le salaire est un facteur…","o":["D'hygiène","De motivation","Neutre"],"a":0,"e":"Son absence crée l'insatisfaction."},{"q":"Selon Herzberg, la reconnaissance est un facteur…","o":["De motivation","D'hygiène","Neutre"],"a":0,"e":"Elle crée la satisfaction."},{"q":"Les facteurs d'hygiène mal gérés créent…","o":["L'insatisfaction","La motivation","L'engagement"],"a":0,"e":"Principe de Herzberg."},{"q":"L'intérêt du travail est un facteur…","o":["De motivation","D'hygiène","Fiscal"],"a":0,"e":"Satisfaction intrinsèque."},{"q":"Un indicateur de fidélisation est…","o":["Le taux de turnover","Le chiffre d'affaires","La TVA"],"a":0,"e":"Mesure des départs."},{"q":"Les témoignages de salariés renforcent…","o":["La marque employeur","Les stocks","Les impôts"],"a":0,"e":"Authenticité."},{"q":"L'équilibre vie pro / vie perso fait partie…","o":["De la proposition de valeur employeur","Du bilan","Des déclarations CNPS"],"a":0,"e":"Élément de l'offre."},{"q":"Les conditions de travail sont, chez Herzberg, des facteurs…","o":["D'hygiène","De motivation","Sans effet"],"a":0,"e":"Environnement."},{"q":"La compétitivité externe compare les salaires…","o":["Au marché","Entre collègues","Aux impôts"],"a":0,"e":"Attractivité."},{"q":"Une enquête d'engagement mesure…","o":["L'implication des salariés","Les ventes","La trésorerie"],"a":0,"e":"Indicateur de climat."},{"q":"Le taux de départ des talents mesure…","o":["La perte des profils clés","Les embauches","Les promotions"],"a":0,"e":"Indicateur ciblé."}]}]},{"id":"mrh304","code":"MRH 304","unit":"trad","title":"Gestion du processus RH","summary":"Le cycle de vie du collaborateur vu comme une suite de processus : recruter, intégrer, administrer, rémunérer, gérer les départs, piloter et améliorer.","lessons":[{"id":"mrh304-1","n":1,"t":"L'approche processus appliquée aux RH","min":20,"html":"<p>Un processus est un ensemble d'activités qui transforment des éléments d'entrée en éléments de sortie, pour un client interne ou externe.</p>\n<h3>Les composantes d'un processus</h3>\n<ul><li><strong>Entrées</strong> : une demande de recrutement, des variables de paie.</li><li><strong>Activités</strong> : étapes successives.</li><li><strong>Sorties</strong> : un salarié recruté, un bulletin de paie.</li><li><strong>Ressources</strong> : personnes, outils, budget.</li><li><strong>Pilote (process owner)</strong> : responsable de la performance du processus.</li><li><strong>Indicateurs</strong> : délai, coût, qualité.</li></ul>\n<h3>L'outil SIPOC</h3>\n<p>SIPOC résume un processus en cinq colonnes : <strong>S</strong>uppliers (fournisseurs), <strong>I</strong>nputs (entrées), <strong>P</strong>rocess (étapes), <strong>O</strong>utputs (sorties), <strong>C</strong>ustomers (clients).</p>\n<div class=\"callout\"><b>Exemple : processus paie</b>Fournisseurs : managers, salariés · Entrées : relevés d'heures, absences · Processus : saisir, calculer, contrôler, valider, payer · Sorties : bulletins, virements · Clients : salariés, CNPS, DGI.</div>\n<h3>Les trois familles de processus</h3>\n<div class=\"tbl\"><table><thead><tr><th>Famille</th><th>Exemples RH</th></tr></thead><tbody>\n<tr><td>Processus de pilotage</td><td>Stratégie RH, budget de masse salariale</td></tr>\n<tr><td>Processus opérationnels</td><td>Recrutement, formation, paie</td></tr>\n<tr><td>Processus support</td><td>SIRH, archivage, juridique</td></tr></tbody></table></div>\n<h3>La cartographie des processus RH</h3>\n<p>Elle représente l'ensemble des processus et leurs liens. Elle sert à clarifier les responsabilités, repérer les doublons et préparer une digitalisation.</p>","quiz":[{"q":"Un processus transforme…","o":["Des entrées en sorties","Des salaires en impôts","Des clients en fournisseurs"],"a":0,"e":"Définition."},{"q":"Le pilote d'un processus est…","o":["Le responsable de sa performance","Le client final","Le fournisseur"],"a":0,"e":"Process owner."},{"q":"Une entrée du processus paie est…","o":["Les relevés d'heures","Le bulletin","Le virement"],"a":0,"e":"Donnée d'entrée."},{"q":"Une sortie du processus paie est…","o":["Le bulletin de paie","Le relevé d'heures","La demande d'absence"],"a":0,"e":"Résultat."},{"q":"Que signifie le « S » de SIPOC ?","o":["Suppliers (fournisseurs)","Salaires","Services"],"a":0,"e":"Premier élément."},{"q":"Que signifie le « C » de SIPOC ?","o":["Customers (clients)","Contrôle","Coûts"],"a":0,"e":"Destinataires."},{"q":"Combien de colonnes compte SIPOC ?","o":["Cinq","Trois","Sept"],"a":0,"e":"S, I, P, O, C."},{"q":"La paie est un processus…","o":["Opérationnel","De pilotage","Inexistant"],"a":0,"e":"Réalisation courante."},{"q":"La stratégie RH est un processus…","o":["De pilotage","Support","Opérationnel"],"a":0,"e":"Orientation."},{"q":"Le SIRH relève des processus…","o":["Support","De pilotage","Commerciaux"],"a":0,"e":"Outil au service des autres."},{"q":"Trois types d'indicateurs de processus ?","o":["Délai, coût, qualité","Nom, prénom, âge","Rouge, vert, bleu"],"a":0,"e":"Performance."},{"q":"La cartographie des processus sert à…","o":["Clarifier les responsabilités","Calculer l'ITS","Recruter plus vite automatiquement"],"a":0,"e":"Vision d'ensemble."},{"q":"Qui sont les clients du processus paie ?","o":["Salariés, CNPS, DGI","Fournisseurs de matières","Concurrents"],"a":0,"e":"Destinataires des sorties."},{"q":"Les managers sont, pour la paie, des…","o":["Fournisseurs","Clients uniquement","Pilotes"],"a":0,"e":"Ils transmettent les variables."},{"q":"Une ressource d'un processus peut être…","o":["Un logiciel","Une sortie","Un client"],"a":0,"e":"Moyen mis en œuvre."},{"q":"Repérer des doublons est un bénéfice de…","o":["La cartographie","La paie","L'embauche"],"a":0,"e":"Analyse globale."},{"q":"Le budget de masse salariale relève du…","o":["Pilotage","Support","Opérationnel"],"a":0,"e":"Orientation et contrôle."},{"q":"L'archivage relève d'un processus…","o":["Support","De pilotage","Commercial"],"a":0,"e":"Au service des autres."},{"q":"Le « P » de SIPOC désigne…","o":["Les étapes du processus","Le prix","Le personnel"],"a":0,"e":"Process."},{"q":"Une demande de recrutement est une…","o":["Entrée","Sortie","Ressource"],"a":0,"e":"Déclencheur du processus."}]},{"id":"mrh304-2","n":2,"t":"Recruter : définir le besoin et sourcer","min":25,"html":"<h3>Définir le besoin</h3>\n<ol><li><strong>Justifier</strong> le poste : remplacement, création, surcroît d'activité. Faut-il recruter ou réorganiser ?</li><li><strong>Faire valider</strong> la demande (budget, direction).</li><li><strong>Rédiger la fiche de poste</strong> et le <strong>profil recherché</strong> : diplômes, expérience, compétences, savoir-être.</li><li>Distinguer les critères <strong>indispensables</strong> des critères <strong>souhaitables</strong>.</li></ol>\n<h3>Sourcer les candidats</h3>\n<div class=\"tbl\"><table><thead><tr><th>Source</th><th>Avantage</th><th>Limite</th></tr></thead><tbody>\n<tr><td>Mobilité interne</td><td>Rapide, motivante, candidat connu</td><td>Crée un autre poste vacant</td></tr>\n<tr><td>Cooptation</td><td>Candidats recommandés, bonne intégration</td><td>Risque d'entre-soi</td></tr>\n<tr><td>Annonces en ligne, réseaux professionnels</td><td>Large audience</td><td>Beaucoup de candidatures à trier</td></tr>\n<tr><td>Écoles et universités</td><td>Jeunes profils, stages de pré-embauche</td><td>Peu d'expérience</td></tr>\n<tr><td>Cabinets de recrutement</td><td>Expertise, profils rares</td><td>Coût élevé</td></tr>\n<tr><td>Agence emploi jeunes, forums</td><td>Proximité, coût faible</td><td>Volume variable</td></tr></tbody></table></div>\n<h3>Rédiger une annonce</h3>\n<p>Une bonne annonce présente l'entreprise, le poste et ses missions, le profil, les conditions (lieu, contrat) et le mode de candidature. Elle doit être non discriminatoire.</p>\n<h3>Indicateurs</h3>\n<p>Délai de recrutement (de la demande à l'arrivée), coût par recrutement, nombre de candidatures par annonce, taux de réussite en période d'essai.</p>","quiz":[{"q":"Première question avant de recruter ?","o":["Faut-il recruter ou réorganiser ?","Quel salaire proposer ?","Quelle couleur pour l'annonce ?"],"a":0,"e":"Justifier le besoin."},{"q":"Qui valide la demande de recrutement ?","o":["La direction selon le budget","Le candidat","Le cabinet"],"a":0,"e":"Validation budgétaire."},{"q":"Le profil recherché décrit…","o":["Diplômes, expérience, compétences","Le prix du poste","Les clients"],"a":0,"e":"Portrait du candidat idéal."},{"q":"Pourquoi distinguer indispensable et souhaitable ?","o":["Pour ne pas exclure de bons candidats","Pour compliquer","Pour discriminer"],"a":0,"e":"Priorisation."},{"q":"Avantage de la mobilité interne ?","o":["Rapide et motivante","Toujours moins de compétences","Plus coûteuse"],"a":0,"e":"Candidat connu."},{"q":"Limite de la mobilité interne ?","o":["Elle crée un autre poste vacant","Elle est illégale","Elle coûte très cher"],"a":0,"e":"Effet domino."},{"q":"La cooptation consiste à…","o":["Recruter sur recommandation de salariés","Passer par un cabinet","Publier en ligne"],"a":0,"e":"Réseau interne."},{"q":"Risque de la cooptation ?","o":["L'entre-soi","Le coût élevé","L'illégalité"],"a":0,"e":"Manque de diversité."},{"q":"Avantage d'un cabinet de recrutement ?","o":["Expertise pour profils rares","Gratuité","Rapidité garantie"],"a":0,"e":"Spécialisation."},{"q":"Limite d'un cabinet ?","o":["Coût élevé","Aucune expertise","Aucun candidat"],"a":0,"e":"Honoraires."},{"q":"Les relations écoles permettent…","o":["D'attirer de jeunes profils","De recruter des retraités","D'éviter l'annonce"],"a":0,"e":"Stages de pré-embauche."},{"q":"Une annonce doit être…","o":["Non discriminatoire","Vague","Secrète"],"a":0,"e":"Obligation légale."},{"q":"Une annonce présente notamment…","o":["Les missions du poste","Les salaires des collègues","Le bilan de l'entreprise"],"a":0,"e":"Contenu type."},{"q":"Délai de recrutement : de…","o":["La demande à l'arrivée","L'annonce à l'entretien","L'essai à la retraite"],"a":0,"e":"Définition courante."},{"q":"Coût par recrutement =","o":["Coûts totaux / nombre de recrutements","Salaire × 12","Nombre de CV"],"a":0,"e":"Indicateur."},{"q":"Les annonces en ligne offrent…","o":["Une large audience","Des candidats déjà formés au poste","Zéro tri"],"a":0,"e":"Portée."},{"q":"Limite des annonces en ligne ?","o":["Beaucoup de candidatures à trier","Aucune candidature","Illégales"],"a":0,"e":"Volume."},{"q":"Un indicateur de qualité du recrutement ?","o":["Taux de réussite en période d'essai","Nombre d'annonces","Couleur du logo"],"a":0,"e":"Le recruté convient-il ?"},{"q":"Un remplacement suite à démission justifie…","o":["Un besoin de recrutement","Un licenciement","Rien"],"a":0,"e":"Motif de besoin."},{"q":"Les forums emploi ont un coût…","o":["Faible","Très élevé","Illimité"],"a":0,"e":"Accessibles."}]},{"id":"mrh304-3","n":3,"t":"Recruter : sélectionner les candidats","min":25,"html":"<h3>Le tri des candidatures</h3>\n<p>On compare chaque CV aux critères indispensables. Une grille de présélection garantit que tous les dossiers sont traités de la même façon.</p>\n<h3>Les outils de sélection</h3>\n<div class=\"tbl\"><table><thead><tr><th>Outil</th><th>Ce qu'il évalue</th></tr></thead><tbody>\n<tr><td>Entretien téléphonique</td><td>Motivation, disponibilité, prétentions</td></tr>\n<tr><td>Entretien structuré</td><td>Compétences, expériences, comportements</td></tr>\n<tr><td>Test technique</td><td>Savoir-faire (Excel, comptabilité, rédaction)</td></tr>\n<tr><td>Mise en situation</td><td>Comportement en contexte réel</td></tr>\n<tr><td>Test de personnalité</td><td>Préférences comportementales (à interpréter avec prudence)</td></tr>\n<tr><td>Prise de références</td><td>Confirmation par d'anciens employeurs, avec l'accord du candidat</td></tr></tbody></table></div>\n<h3>L'entretien structuré</h3>\n<p>Tous les candidats reçoivent les mêmes questions, évaluées avec la même grille. Les questions comportementales portent sur des situations vécues : « Décrivez une situation où… ». La méthode <strong>STAR</strong> aide à analyser la réponse : Situation, Tâche, Action, Résultat.</p>\n<h3>La décision</h3>\n<p>Le recruteur et le manager comparent les candidats sur la grille, décident, puis font une proposition écrite. Les candidats non retenus reçoivent une réponse : c'est aussi une question de marque employeur.</p>\n<h3>Les questions interdites</h3>\n<p>Projets de grossesse, religion, opinions politiques, appartenance syndicale, état de santé sans rapport avec l'aptitude, origine.</p>","quiz":[{"q":"Une grille de présélection garantit…","o":["Un traitement égal des dossiers","Un recrutement plus cher","Moins de candidats"],"a":0,"e":"Équité."},{"q":"L'entretien téléphonique évalue surtout…","o":["Motivation et disponibilité","Les compétences Excel en détail","La personnalité profonde"],"a":0,"e":"Premier filtre."},{"q":"Un test technique évalue…","o":["Le savoir-faire","L'âge","Le salaire souhaité seulement"],"a":0,"e":"Compétence pratique."},{"q":"La mise en situation évalue…","o":["Le comportement en contexte réel","Le diplôme","L'adresse"],"a":0,"e":"Simulation."},{"q":"Un test de personnalité doit être interprété…","o":["Avec prudence","Comme vérité absolue","Par le candidat seul"],"a":0,"e":"Préférences, pas aptitudes."},{"q":"La prise de références se fait…","o":["Avec l'accord du candidat","En secret","Auprès de sa famille"],"a":0,"e":"Respect de la vie privée."},{"q":"Dans l'entretien structuré, les candidats reçoivent…","o":["Les mêmes questions","Des questions différentes","Aucune question"],"a":0,"e":"Comparabilité."},{"q":"Une question comportementale commence par…","o":["« Décrivez une situation où… »","« Êtes-vous marié ? »","« Quel est votre signe ? »"],"a":0,"e":"Faits vécus."},{"q":"Que signifie le « S » de STAR ?","o":["Situation","Salaire","Service"],"a":0,"e":"Contexte."},{"q":"Que signifie le « A » de STAR ?","o":["Action","Âge","Avis"],"a":0,"e":"Ce que le candidat a fait."},{"q":"Que signifie le « R » de STAR ?","o":["Résultat","Référence","Religion"],"a":0,"e":"Issue obtenue."},{"q":"Qui décide du recrutement ?","o":["Le recruteur et le manager","Le candidat","Le cabinet seul toujours"],"a":0,"e":"Décision conjointe."},{"q":"La proposition au candidat retenu doit être…","o":["Écrite","Orale seulement","Secrète"],"a":0,"e":"Trace."},{"q":"Répondre aux candidats non retenus relève…","o":["De la marque employeur","D'une obligation fiscale","De la CNPS"],"a":0,"e":"Image de l'entreprise."},{"q":"« Avez-vous un projet de grossesse ? » est…","o":["Interdit","Autorisé","Obligatoire"],"a":0,"e":"Discrimination."},{"q":"Demander la religion d'un candidat est…","o":["Interdit","Utile","Obligatoire"],"a":0,"e":"Sans lien avec le poste."},{"q":"Demander l'appartenance syndicale est…","o":["Interdit","Recommandé","Neutre"],"a":0,"e":"Liberté syndicale."},{"q":"On compare d'abord le CV aux…","o":["Critères indispensables","Photos","Loisirs"],"a":0,"e":"Tri initial."},{"q":"Les prétentions salariales sont souvent abordées…","o":["Lors de l'entretien téléphonique","Jamais","Après l'embauche"],"a":0,"e":"Premier filtre."},{"q":"La méthode STAR aide à…","o":["Analyser une réponse comportementale","Calculer la paie","Rédiger l'annonce"],"a":0,"e":"Structure d'analyse."}]},{"id":"mrh304-4","n":4,"t":"Intégrer les nouveaux collaborateurs","min":20,"html":"<p>L'intégration (onboarding) commence dès la signature du contrat et se prolonge pendant les premiers mois. Une intégration réussie réduit les départs précoces et accélère la productivité.</p>\n<h3>Les quatre temps</h3>\n<div class=\"tbl\"><table><thead><tr><th>Temps</th><th>Actions</th></tr></thead><tbody>\n<tr><td>Avant l'arrivée (pre-boarding)</td><td>Message de bienvenue, documents administratifs, préparation du poste (matériel, accès)</td></tr>\n<tr><td>Le premier jour</td><td>Accueil par le manager, visite, présentation de l'équipe, remise du livret d'accueil</td></tr>\n<tr><td>Le premier mois</td><td>Formations au poste, rencontres avec les services clés, tuteur</td></tr>\n<tr><td>Jusqu'à la fin de l'essai</td><td>Points d'étape réguliers (J+30, J+60, J+90), bilan de fin d'essai</td></tr></tbody></table></div>\n<h3>Le livret d'accueil</h3>\n<p>Il présente l'entreprise (histoire, organigramme, valeurs), les informations pratiques (horaires, accès, restauration), les règles (règlement intérieur, sécurité), les contacts utiles.</p>\n<h3>Le tuteur</h3>\n<p>Salarié expérimenté, il transmet les savoir-faire et les codes non écrits. Il doit être volontaire, disponible et reconnu pour ce rôle.</p>\n<h3>Mesurer l'intégration</h3>\n<p>Taux de départ pendant l'essai, taux de confirmation, questionnaire d'étonnement à 1 mois (« Qu'est-ce qui vous a surpris ? ») et satisfaction des nouveaux arrivants.</p>\n<div class=\"callout\"><b>Le rapport d'étonnement</b>Demander au nouvel arrivant ce qui l'a étonné est une source précieuse d'amélioration pour l'entreprise.</div>","quiz":[{"q":"Quand commence l'intégration ?","o":["Dès la signature du contrat","Après l'essai","Au bout d'un an"],"a":0,"e":"Pre-boarding."},{"q":"Une intégration réussie réduit…","o":["Les départs précoces","La productivité","Les salaires"],"a":0,"e":"Rétention."},{"q":"Préparer le matériel avant l'arrivée relève du…","o":["Pre-boarding","Premier mois","Bilan d'essai"],"a":0,"e":"Avant l'arrivée."},{"q":"Qui accueille idéalement le nouvel arrivant le premier jour ?","o":["Le manager","Le fournisseur","Personne"],"a":0,"e":"Symbole fort."},{"q":"Le livret d'accueil est remis…","o":["Le premier jour","À la fin de l'essai","Jamais"],"a":0,"e":"Premier jour."},{"q":"Le livret d'accueil contient…","o":["Organigramme et informations pratiques","Les salaires de tous","Le bilan fiscal"],"a":0,"e":"Contenu type."},{"q":"Le tuteur transmet…","o":["Savoir-faire et codes non écrits","Le salaire","Les impôts"],"a":0,"e":"Compagnonnage."},{"q":"Un bon tuteur est…","o":["Volontaire et disponible","Désigné de force","Nouveau dans l'entreprise"],"a":0,"e":"Conditions."},{"q":"Points d'étape recommandés ?","o":["J+30, J+60, J+90","Uniquement J+365","Aucun"],"a":0,"e":"Suivi régulier."},{"q":"Le rapport d'étonnement demande…","o":["Ce qui a surpris le nouvel arrivant","Son salaire","Son âge"],"a":0,"e":"Regard neuf."},{"q":"Un indicateur d'intégration est…","o":["Le taux de départ pendant l'essai","Le chiffre d'affaires","La TVA"],"a":0,"e":"Mesure."},{"q":"Rencontrer les services clés se fait durant…","o":["Le premier mois","Le pre-boarding","Après un an"],"a":0,"e":"Découverte."},{"q":"Le bilan de fin d'essai conclut…","o":["La période d'intégration","L'annonce","Le recrutement"],"a":0,"e":"Décision de confirmation."},{"q":"Onboarding signifie…","o":["Intégration","Licenciement","Formation continue"],"a":0,"e":"Terme anglais."},{"q":"Le rapport d'étonnement est utile à…","o":["L'amélioration de l'entreprise","Le calcul de la paie","La CNPS"],"a":0,"e":"Source d'idées."},{"q":"Le règlement intérieur est présenté…","o":["Lors de l'accueil","Jamais","Lors du départ"],"a":0,"e":"Règles à connaître."},{"q":"Préparer les accès informatiques avant l'arrivée évite…","o":["Un premier jour sans outil","Les congés","La paie"],"a":0,"e":"Accueil professionnel."},{"q":"Le tuteur doit être…","o":["Reconnu pour ce rôle","Anonyme","Pénalisé"],"a":0,"e":"Valorisation."},{"q":"Le taux de confirmation mesure…","o":["Les essais concluants","Les démissions de cadres","Les ventes"],"a":0,"e":"Réussite de l'intégration."},{"q":"Un message de bienvenue avant l'arrivée relève…","o":["Du pre-boarding","Du bilan","Du départ"],"a":0,"e":"Anticipation."}]},{"id":"mrh304-5","n":5,"t":"Administrer le personnel","min":25,"html":"<p>L'administration du personnel regroupe les tâches qui garantissent la conformité légale et la tenue des informations sur chaque salarié.</p>\n<h3>Le dossier individuel</h3>\n<ul><li>Pièces d'identité, état civil, situation familiale (pour la paie et l'ITS).</li><li>Contrat, avenants, fiches de poste.</li><li>Diplômes, certificats de travail antérieurs.</li><li>Déclaration CNPS, visites médicales.</li><li>Évaluations, formations, sanctions éventuelles.</li></ul>\n<h3>Les registres et documents obligatoires</h3>\n<div class=\"tbl\"><table><thead><tr><th>Document</th><th>Contenu</th></tr></thead><tbody>\n<tr><td>Registre d'employeur</td><td>Mouvements du personnel, renseignements sur chaque salarié</td></tr>\n<tr><td>Règlement intérieur</td><td>Discipline, hygiène, sécurité</td></tr>\n<tr><td>Affichages obligatoires</td><td>Horaires, coordonnées de l'inspection du travail, règlement intérieur</td></tr>\n<tr><td>Bulletins de paie (double)</td><td>Rémunérations versées</td></tr></tbody></table></div>\n<h3>Les documents délivrés aux salariés</h3>\n<p>Attestation de travail, certificat de travail, attestation de salaire, relevés pour la CNPS, documents de fin de contrat.</p>\n<h3>Les mouvements</h3>\n<p>Chaque entrée, sortie, promotion, mutation ou changement de situation familiale déclenche une mise à jour du dossier, du SIRH et de la paie.</p>\n<h3>Confidentialité et accès</h3>\n<p>Les dossiers sont conservés dans un lieu sécurisé ou un SIRH à accès restreint. Seules les personnes habilitées y accèdent ; le salarié peut consulter les informations le concernant.</p>","quiz":[{"q":"La situation familiale figure au dossier car elle sert…","o":["Au calcul de l'ITS","Au marketing","Aux ventes"],"a":0,"e":"Charges de famille."},{"q":"Le contrat et ses avenants sont conservés…","o":["Dans le dossier individuel","Dans le bilan","Chez le client"],"a":0,"e":"Pièces essentielles."},{"q":"Le registre d'employeur retrace…","o":["Les mouvements du personnel","Les achats","Les ventes"],"a":0,"e":"Entrées, sorties."},{"q":"Le règlement intérieur porte sur…","o":["Discipline, hygiène, sécurité","Les salaires individuels","Le chiffre d'affaires"],"a":0,"e":"Contenu."},{"q":"Un affichage obligatoire est…","o":["Les coordonnées de l'inspection du travail","Le salaire du DG","Le bilan"],"a":0,"e":"Information des salariés."},{"q":"Qui peut accéder au dossier individuel ?","o":["Les personnes habilitées et le salarié pour ses données","Tout le monde","Les clients"],"a":0,"e":"Confidentialité."},{"q":"L'attestation de travail est délivrée…","o":["Aux salariés en poste qui la demandent","Aux fournisseurs","Jamais"],"a":0,"e":"Document courant."},{"q":"Une promotion entraîne la mise à jour…","o":["Du dossier, du SIRH et de la paie","Du bilan uniquement","De rien"],"a":0,"e":"Cohérence."},{"q":"Les visites médicales sont archivées…","o":["Dans le dossier individuel (aptitude)","Au registre du commerce","Nulle part"],"a":0,"e":"Suivi de l'aptitude."},{"q":"Les dossiers doivent être conservés…","o":["Dans un lieu sécurisé","Sur un bureau ouvert","Chez soi"],"a":0,"e":"Protection."},{"q":"Un changement de situation familiale impacte…","o":["La paie","Les ventes","Les stocks"],"a":0,"e":"ITS, prestations."},{"q":"Les sanctions disciplinaires figurent…","o":["Au dossier individuel","Sur le panneau d'affichage","Dans l'annonce"],"a":0,"e":"Traçabilité."},{"q":"Le double des bulletins de paie est…","o":["Conservé par l'employeur","Détruit","Remis au client"],"a":0,"e":"Obligation."},{"q":"L'attestation de salaire sert notamment…","o":["Aux démarches du salarié (banque, CNPS)","Au marketing","À l'audit fiscal de l'entreprise uniquement"],"a":0,"e":"Justificatif."},{"q":"Le certificat de travail est remis…","o":["À la fin du contrat","À l'embauche","Chaque mois"],"a":0,"e":"Document de sortie."},{"q":"Un SIRH à accès restreint protège…","o":["La confidentialité","Le chiffre d'affaires","La TVA"],"a":0,"e":"Sécurité."},{"q":"Les diplômes sont vérifiés…","o":["À l'embauche","Jamais","À la retraite"],"a":0,"e":"Vérification."},{"q":"Chaque mouvement du personnel déclenche…","o":["Une mise à jour","Une sanction","Une annonce"],"a":0,"e":"Suivi."},{"q":"Le salarié peut-il consulter ses informations ?","o":["Oui","Non","Seulement avec un avocat"],"a":0,"e":"Droit d'accès."},{"q":"Les horaires collectifs doivent être…","o":["Affichés","Cachés","Envoyés à la CNPS"],"a":0,"e":"Affichage obligatoire."}]},{"id":"mrh304-6","n":6,"t":"Gérer les temps et les absences","min":20,"html":"<h3>Pourquoi gérer les temps ?</h3>\n<p>La gestion des temps garantit le respect de la durée légale, le paiement exact des heures et le suivi de l'absentéisme.</p>\n<h3>Les outils</h3>\n<ul><li>Feuilles de présence ou pointeuse (badge, biométrie).</li><li>Planning des équipes et des roulements.</li><li>Module « temps et absences » du SIRH avec workflow de validation.</li></ul>\n<h3>Les types d'absences</h3>\n<div class=\"tbl\"><table><thead><tr><th>Absence</th><th>Justificatif</th></tr></thead><tbody>\n<tr><td>Congés payés</td><td>Demande validée par le manager</td></tr>\n<tr><td>Maladie</td><td>Certificat médical</td></tr>\n<tr><td>Accident du travail</td><td>Déclaration d'accident, certificat</td></tr>\n<tr><td>Permission exceptionnelle</td><td>Acte d'état civil (mariage, naissance, décès)</td></tr>\n<tr><td>Absence injustifiée</td><td>Aucun : retenue et éventuelle procédure disciplinaire</td></tr></tbody></table></div>\n<h3>Le taux d'absentéisme</h3>\n<p>Taux = heures d'absence / heures théoriques de travail × 100. On exclut en général les congés payés et on analyse par motif, service et durée.</p>\n<div class=\"callout\"><b>Exemple</b>Service de 20 personnes, 173 heures théoriques chacune par mois = 3 460 heures. Absences : 138 heures. Taux = 138 / 3 460 × 100 ≈ <strong>4 %</strong>.</div>\n<h3>Le planning des congés</h3>\n<p>Il est établi à l'avance pour assurer la continuité du service. Les demandes sont validées selon des règles connues (ancienneté, charges de famille, rotation).</p>","quiz":[{"q":"La gestion des temps garantit notamment…","o":["Le respect de la durée légale","La hausse des prix","La baisse des impôts"],"a":0,"e":"Conformité."},{"q":"Un outil de gestion des temps est…","o":["La pointeuse","Le bilan","La facture"],"a":0,"e":"Enregistrement des présences."},{"q":"Le justificatif d'une absence maladie est…","o":["Un certificat médical","Un SMS","Rien"],"a":0,"e":"Pièce obligatoire."},{"q":"Le justificatif d'une permission pour mariage est…","o":["Un acte d'état civil","Une facture","Un CV"],"a":0,"e":"Preuve de l'événement."},{"q":"Une absence injustifiée entraîne…","o":["Retenue et éventuelle procédure disciplinaire","Une prime","Rien"],"a":0,"e":"Conséquences."},{"q":"Formule du taux d'absentéisme ?","o":["Heures d'absence / heures théoriques × 100","Absences × salaire","Jours / 365"],"a":0,"e":"Définition."},{"q":"Exemple : 138 h d'absence sur 3 460 h ?","o":["≈ 4 %","≈ 10 %","≈ 1 %"],"a":0,"e":"138 / 3 460."},{"q":"20 personnes × 173 h = ?","o":["3 460 h","2 000 h","1 730 h"],"a":0,"e":"Heures théoriques."},{"q":"Les congés payés sont en général…","o":["Exclus du taux d'absentéisme","Inclus","Doublés"],"a":0,"e":"Absence prévue et légale."},{"q":"On analyse l'absentéisme par…","o":["Motif, service et durée","Couleur","Client"],"a":0,"e":"Axes d'analyse."},{"q":"Le workflow de validation d'une absence implique…","o":["Le manager","Le fournisseur","Le client"],"a":0,"e":"Validation hiérarchique."},{"q":"Le planning des congés assure…","o":["La continuité du service","La baisse des salaires","Les ventes"],"a":0,"e":"Organisation."},{"q":"Les règles de priorité des congés doivent être…","o":["Connues de tous","Secrètes","Changées chaque jour"],"a":0,"e":"Équité."},{"q":"La déclaration d'accident justifie…","o":["Un accident du travail","Un congé payé","Un retard"],"a":0,"e":"Pièce spécifique."},{"q":"10 personnes × 170 h ; 85 h d'absence : taux ?","o":["5 %","8,5 %","0,5 %"],"a":0,"e":"85 / 1 700."},{"q":"Un badge biométrique sert à…","o":["Enregistrer les présences","Payer la CNPS","Vendre"],"a":0,"e":"Pointage."},{"q":"Un taux d'absentéisme élevé peut signaler…","o":["Un problème de conditions de travail","Une hausse des ventes","Rien"],"a":0,"e":"Signal d'alerte."},{"q":"Les roulements d'équipes figurent sur…","o":["Le planning","Le bilan","Le contrat de vente"],"a":0,"e":"Organisation du travail."},{"q":"Un critère de priorité des congés peut être…","o":["Les charges de famille","La taille","Le signe astrologique"],"a":0,"e":"Règle usuelle."},{"q":"Le module temps du SIRH alimente…","o":["La paie","Le marketing","La comptabilité fournisseurs"],"a":0,"e":"Variables de paie."}]},{"id":"mrh304-7","n":7,"t":"Gérer la rémunération","min":25,"html":"<h3>Les composantes de la rémunération globale</h3>\n<ul><li><strong>Fixe</strong> : salaire de base, sursalaire.</li><li><strong>Variable individuel</strong> : primes d'objectifs, commissions.</li><li><strong>Variable collectif</strong> : intéressement, participation, prime d'équipe.</li><li><strong>Périphériques</strong> : avantages en nature, assurance santé complémentaire, prévoyance.</li></ul>\n<h3>Les trois équités</h3>\n<div class=\"tbl\"><table><thead><tr><th>Équité</th><th>Question</th></tr></thead><tbody>\n<tr><td>Interne</td><td>Les postes de même niveau sont-ils payés de façon cohérente ?</td></tr>\n<tr><td>Externe</td><td>Nos salaires sont-ils compétitifs par rapport au marché ?</td></tr>\n<tr><td>Individuelle</td><td>La performance de chacun est-elle reconnue ?</td></tr></tbody></table></div>\n<h3>La grille de salaires</h3>\n<p>Elle définit, par niveau de poste, une fourchette : minimum, point médian, maximum. Le <strong>ratio comparatif</strong> (compa-ratio) = salaire du salarié / point médian. À 1, le salarié est au milieu de la fourchette.</p>\n<div class=\"callout\"><b>Exemple</b>Point médian 500 000 FCFA, salaire 450 000 : compa-ratio = 0,9 (sous le médian).</div>\n<h3>La revue salariale annuelle</h3>\n<ol><li>Fixer l'enveloppe globale (en % de la masse salariale).</li><li>Répartir entre augmentations générales et individuelles.</li><li>Proposer par manager selon performance et position dans la fourchette.</li><li>Valider, notifier, mettre à jour la paie.</li></ol>\n<h3>L'effet de l'augmentation sur la masse salariale</h3>\n<p>Une augmentation au 1<sup>er</sup> juillet ne pèse que 6 mois sur l'année en cours (effet masse) mais 12 mois l'année suivante (effet report).</p>","quiz":[{"q":"Le salaire de base fait partie de la rémunération…","o":["Fixe","Variable collective","Périphérique"],"a":0,"e":"Composante fixe."},{"q":"Une commission est une rémunération…","o":["Variable individuelle","Fixe","Périphérique"],"a":0,"e":"Liée à la performance individuelle."},{"q":"L'intéressement est une rémunération…","o":["Variable collective","Fixe","Individuelle"],"a":0,"e":"Liée aux résultats collectifs."},{"q":"Une assurance santé complémentaire est un élément…","o":["Périphérique","Fixe","Variable individuel"],"a":0,"e":"Avantage social."},{"q":"L'équité interne compare…","o":["Les postes de même niveau dans l'entreprise","L'entreprise au marché","Les clients"],"a":0,"e":"Cohérence interne."},{"q":"L'équité externe compare…","o":["Les salaires au marché","Les salariés entre eux","Les impôts"],"a":0,"e":"Compétitivité."},{"q":"L'équité individuelle reconnaît…","o":["La performance de chacun","L'âge","Le diplôme seul"],"a":0,"e":"Mérite."},{"q":"Une fourchette de salaire comprend…","o":["Minimum, point médian, maximum","Seulement un montant","Le net et l'ITS"],"a":0,"e":"Structure."},{"q":"Compa-ratio =","o":["Salaire / point médian","Point médian / salaire","Salaire − médian"],"a":0,"e":"Définition."},{"q":"Salaire 450 000, médian 500 000 : compa-ratio ?","o":["0,9","1,1","0,5"],"a":0,"e":"450 / 500."},{"q":"Salaire 550 000, médian 500 000 : compa-ratio ?","o":["1,1","0,9","1,5"],"a":0,"e":"550 / 500."},{"q":"Compa-ratio de 1 signifie…","o":["Au point médian","Au minimum","Au maximum"],"a":0,"e":"Milieu de fourchette."},{"q":"Première étape de la revue salariale ?","o":["Fixer l'enveloppe globale","Notifier les salariés","Mettre à jour la paie"],"a":0,"e":"Cadre budgétaire."},{"q":"L'enveloppe se répartit entre…","o":["Augmentations générales et individuelles","Impôts et cotisations","Clients et fournisseurs"],"a":0,"e":"Deux types."},{"q":"Augmentation au 1er juillet : combien de mois pèse-t-elle cette année ?","o":["6","12","3"],"a":0,"e":"Effet masse."},{"q":"L'effet report correspond…","o":["À l'impact sur l'année suivante","À une baisse de salaire","Au retard de paie"],"a":0,"e":"12 mois l'année suivante."},{"q":"Après validation d'une augmentation, on…","o":["Notifie et met à jour la paie","L'oublie","Attend 2 ans"],"a":0,"e":"Mise en œuvre."},{"q":"Un salarié à compa-ratio 0,8 performant peut…","o":["Recevoir une augmentation plus forte","Être rétrogradé","Rien"],"a":0,"e":"Rattrapage dans la fourchette."},{"q":"La prévoyance est un élément…","o":["Périphérique","Fixe","Variable individuel"],"a":0,"e":"Protection sociale complémentaire."},{"q":"Une prime d'équipe est…","o":["Variable collective","Fixe","Périphérique"],"a":0,"e":"Résultat de groupe."}]},{"id":"mrh304-8","n":8,"t":"Gérer les départs","min":20,"html":"<h3>Les types de départs</h3>\n<ul><li>Démission, fin de CDD, licenciement, rupture d'un commun accord, retraite, décès.</li><li>Départs <strong>volontaires</strong> (à l'initiative du salarié) et <strong>involontaires</strong> (à l'initiative de l'employeur ou liés à un événement).</li></ul>\n<h3>La check-list de sortie (offboarding)</h3>\n<ol><li>Vérifier le motif et la procédure applicable (préavis, entretien préalable).</li><li>Calculer le solde de tout compte : salaire, congés non pris, indemnités.</li><li>Récupérer le matériel (ordinateur, badge, téléphone, véhicule).</li><li>Fermer les accès informatiques le dernier jour.</li><li>Organiser la passation des dossiers.</li><li>Remettre les documents : certificat de travail, reçu pour solde de tout compte, attestation CNPS.</li><li>Mener l'entretien de départ.</li><li>Mettre à jour le registre, le SIRH et les déclarations.</li></ol>\n<h3>L'entretien de départ</h3>\n<p>Il recueille les motifs réels du départ, l'avis sur le management, la rémunération, les conditions de travail. Les réponses sont analysées globalement pour améliorer la fidélisation.</p>\n<h3>Le départ à la retraite</h3>\n<p>Il s'anticipe : transmission des savoirs, recrutement ou formation d'un successeur, constitution du dossier de pension auprès de la CNPS.</p>\n<h3>Les anciens salariés</h3>\n<p>Un départ bien géré préserve la réputation de l'entreprise. Certains anciens salariés reviennent ou recommandent des candidats.</p>","quiz":[{"q":"Une démission est un départ…","o":["Volontaire","Involontaire","Automatique"],"a":0,"e":"Initiative du salarié."},{"q":"Un licenciement est un départ…","o":["Involontaire","Volontaire","Temporaire"],"a":0,"e":"Initiative de l'employeur."},{"q":"Offboarding signifie…","o":["Gestion du départ","Intégration","Recrutement"],"a":0,"e":"Processus de sortie."},{"q":"Le solde de tout compte comprend…","o":["Salaire, congés non pris, indemnités","Seulement le salaire","Les dividendes"],"a":0,"e":"Règlement final."},{"q":"Quand fermer les accès informatiques ?","o":["Le dernier jour","Un an après","Jamais"],"a":0,"e":"Sécurité."},{"q":"La passation des dossiers sert à…","o":["Assurer la continuité","Retarder le départ","Calculer l'ITS"],"a":0,"e":"Transmission."},{"q":"Le certificat de travail est remis…","o":["Au départ","À l'embauche","Chaque mois"],"a":0,"e":"Document de sortie."},{"q":"L'entretien de départ recueille…","o":["Les motifs réels du départ","Le salaire du successeur","Les ventes"],"a":0,"e":"Amélioration."},{"q":"Les réponses aux entretiens de départ sont analysées…","o":["Globalement","Individuellement pour sanctionner","Jamais"],"a":0,"e":"Tendances."},{"q":"Un départ à la retraite s'anticipe par…","o":["La transmission des savoirs","Le licenciement","Rien"],"a":0,"e":"Continuité."},{"q":"Le dossier de pension est constitué auprès de…","o":["La CNPS","La DGI","Le FDFP"],"a":0,"e":"Retraite."},{"q":"Récupérer le badge et l'ordinateur fait partie…","o":["De la check-list de sortie","Du recrutement","De l'intégration"],"a":0,"e":"Restitution."},{"q":"Après le départ, on met à jour…","o":["Registre, SIRH et déclarations","Le logo","Les prix"],"a":0,"e":"Cohérence."},{"q":"Un départ bien géré préserve…","o":["La réputation de l'entreprise","Les stocks","Le capital"],"a":0,"e":"Marque employeur."},{"q":"Les anciens salariés peuvent…","o":["Recommander des candidats","Accéder au SIRH","Recevoir le salaire"],"a":0,"e":"Réseau d'alumni."},{"q":"La fin de CDD est un départ…","o":["Lié au terme du contrat","Une démission","Un licenciement pour faute"],"a":0,"e":"Échéance."},{"q":"Avant tout départ, on vérifie…","o":["Le motif et la procédure applicable","La météo","Le chiffre d'affaires"],"a":0,"e":"Conformité."},{"q":"Le reçu pour solde de tout compte est…","o":["Remis au salarié","Envoyé au client","Inutile"],"a":0,"e":"Document de sortie."},{"q":"La rupture d'un commun accord est…","o":["Négociée entre les parties","Imposée par l'employeur","Imposée par le juge"],"a":0,"e":"Accord."},{"q":"L'attestation CNPS de fin de contrat sert…","o":["Aux droits sociaux du salarié","Aux ventes","À la TVA"],"a":0,"e":"Justificatif."}]},{"id":"mrh304-9","n":9,"t":"Le tableau de bord RH","min":25,"html":"<p>Le tableau de bord RH rassemble les indicateurs clés qui permettent de piloter les ressources humaines et d'alerter la direction.</p>\n<h3>Les indicateurs essentiels</h3>\n<div class=\"tbl\"><table><thead><tr><th>Domaine</th><th>Indicateur</th><th>Formule</th></tr></thead><tbody>\n<tr><td>Effectifs</td><td>Effectif moyen</td><td>(effectif début + effectif fin) / 2</td></tr>\n<tr><td>Mouvements</td><td>Turnover</td><td>((entrées + sorties) / 2) / effectif moyen × 100</td></tr>\n<tr><td>Absences</td><td>Absentéisme</td><td>heures d'absence / heures théoriques × 100</td></tr>\n<tr><td>Rémunération</td><td>Salaire moyen</td><td>masse salariale / effectif moyen</td></tr>\n<tr><td>Formation</td><td>Taux d'accès</td><td>salariés formés / effectif × 100</td></tr>\n<tr><td>Sécurité</td><td>Taux de fréquence des accidents</td><td>nombre d'accidents avec arrêt × 1 000 000 / heures travaillées</td></tr></tbody></table></div>\n<h3>Construire un indicateur</h3>\n<p>Chaque indicateur a une fiche : définition, formule, source de données, fréquence, responsable, cible et seuil d'alerte.</p>\n<h3>Présenter</h3>\n<ul><li>8 à 12 indicateurs au maximum pour la direction.</li><li>Comparaison à la période précédente et à la cible.</li><li>Code couleur : vert (conforme), orange (vigilance), rouge (alerte).</li><li>Un commentaire qui explique les écarts et propose une action.</li></ul>\n<div class=\"callout\"><b>Exemple</b>Effectif début 180, fin 200 : effectif moyen 190. Entrées 30, sorties 10 : turnover = ((30 + 10) / 2) / 190 × 100 ≈ 10,5 %.</div>","quiz":[{"q":"Effectif début 180, fin 200 : effectif moyen ?","o":["190","200","380"],"a":0,"e":"(180 + 200) / 2."},{"q":"Turnover de l'exemple ?","o":["≈ 10,5 %","≈ 20 %","≈ 5 %"],"a":0,"e":"20 / 190."},{"q":"Salaire moyen =","o":["Masse salariale / effectif moyen","Effectif / masse salariale","Masse × effectif"],"a":0,"e":"Formule."},{"q":"Masse salariale 60 M, effectif moyen 200 : salaire moyen ?","o":["300 000","3 000 000","30 000"],"a":0,"e":"60 000 000 / 200."},{"q":"Taux d'accès à la formation =","o":["Salariés formés / effectif × 100","Heures / effectif","Budget / effectif"],"a":0,"e":"Formule."},{"q":"50 formés sur 200 : taux d'accès ?","o":["25 %","50 %","4 %"],"a":0,"e":"50 / 200."},{"q":"Le taux de fréquence des accidents utilise…","o":["Accidents avec arrêt × 1 000 000 / heures travaillées","Accidents / effectif","Accidents × 100"],"a":0,"e":"Formule standard."},{"q":"2 accidents, 400 000 heures : taux de fréquence ?","o":["5","0,5","50"],"a":0,"e":"2 × 1 000 000 / 400 000."},{"q":"Nombre d'indicateurs recommandé pour la direction ?","o":["8 à 12","50","1"],"a":0,"e":"Lisibilité."},{"q":"Une fiche indicateur précise…","o":["Définition, formule, source, seuil","Seulement le titre","Le prix"],"a":0,"e":"Contenu."},{"q":"Code couleur rouge signifie…","o":["Alerte","Conforme","Vigilance"],"a":0,"e":"Seuil franchi."},{"q":"Code couleur orange signifie…","o":["Vigilance","Alerte","Conforme"],"a":0,"e":"Surveillance."},{"q":"Un indicateur doit être comparé…","o":["À la période précédente et à la cible","À rien","Aux concurrents uniquement"],"a":0,"e":"Analyse d'évolution."},{"q":"Le commentaire d'un tableau de bord doit…","o":["Expliquer les écarts et proposer une action","Répéter les chiffres","Être absent"],"a":0,"e":"Valeur ajoutée."},{"q":"Effectif début 100, fin 120 : effectif moyen ?","o":["110","120","220"],"a":0,"e":"(100 + 120) / 2."},{"q":"Entrées 10, sorties 12, effectif moyen 110 : turnover ?","o":["10 %","20 %","11 %"],"a":0,"e":"11 / 110."},{"q":"Le seuil d'alerte sert à…","o":["Déclencher une réaction","Décorer","Calculer l'ITS"],"a":0,"e":"Pilotage."},{"q":"La source de données d'un indicateur peut être…","o":["Le SIRH","Un réseau social","Un concurrent"],"a":0,"e":"Origine fiable."},{"q":"La fréquence d'un indicateur indique…","o":["À quel rythme il est mis à jour","Son importance","Sa couleur"],"a":0,"e":"Mensuel, trimestriel…"},{"q":"Le tableau de bord sert à…","o":["Piloter et alerter","Remplacer la paie","Recruter"],"a":0,"e":"Outil de décision."}]},{"id":"mrh304-10","n":10,"t":"Améliorer et digitaliser les processus RH","min":20,"html":"<h3>La roue de Deming (PDCA)</h3>\n<ol><li><strong>Plan</strong> : analyser le problème et planifier l'amélioration.</li><li><strong>Do</strong> : tester la solution à petite échelle.</li><li><strong>Check</strong> : mesurer les résultats.</li><li><strong>Act</strong> : généraliser si c'est efficace, sinon ajuster, puis recommencer.</li></ol>\n<h3>Repérer les dysfonctionnements</h3>\n<ul><li>Étapes inutiles ou en double (double saisie des absences).</li><li>Délais d'attente (validations bloquées).</li><li>Erreurs répétées (erreurs de paie).</li><li>Absence de responsable clair.</li></ul>\n<h3>L'outil des 5 pourquoi</h3>\n<p>On pose cinq fois la question « pourquoi ? » pour remonter à la cause racine. Exemple : erreurs de paie → variables reçues en retard → managers ne connaissent pas l'échéance → aucun calendrier diffusé → procédure non formalisée.</p>\n<h3>La digitalisation</h3>\n<div class=\"tbl\"><table><thead><tr><th>Processus</th><th>Outil numérique</th></tr></thead><tbody>\n<tr><td>Recrutement</td><td>Logiciel de suivi des candidatures (ATS)</td></tr>\n<tr><td>Absences</td><td>Portail libre-service avec workflow</td></tr>\n<tr><td>Paie</td><td>Logiciel de paie connecté au SIRH</td></tr>\n<tr><td>Formation</td><td>Plateforme e-learning (LMS)</td></tr>\n<tr><td>Documents</td><td>Signature électronique, coffre-fort numérique</td></tr></tbody></table></div>\n<p>On ne digitalise pas un processus défaillant : on le simplifie d'abord, sinon on automatise les erreurs.</p>\n<h3>L'audit RH</h3>\n<p>L'audit vérifie la conformité (respect de la loi), l'efficacité (atteinte des objectifs) et l'efficience (coût) des processus RH, et formule des recommandations.</p>","quiz":[{"q":"PDCA signifie…","o":["Plan, Do, Check, Act","Paie, Déclaration, Contrôle, Archive","Prix, Délai, Coût, Avis"],"a":0,"e":"Roue de Deming."},{"q":"L'étape « Do » consiste à…","o":["Tester à petite échelle","Mesurer","Généraliser"],"a":0,"e":"Expérimentation."},{"q":"L'étape « Check » consiste à…","o":["Mesurer les résultats","Planifier","Agir"],"a":0,"e":"Vérification."},{"q":"L'étape « Act » consiste à…","o":["Généraliser ou ajuster","Planifier","Tester"],"a":0,"e":"Standardisation."},{"q":"La double saisie est…","o":["Une étape inutile","Une bonne pratique","Obligatoire"],"a":0,"e":"Gaspillage."},{"q":"La méthode des 5 pourquoi cherche…","o":["La cause racine","Un coupable","Un budget"],"a":0,"e":"Analyse causale."},{"q":"Combien de fois pose-t-on « pourquoi » ?","o":["Cinq","Deux","Dix"],"a":0,"e":"Par convention."},{"q":"Un ATS est un logiciel de…","o":["Suivi des candidatures","Paie","Comptabilité"],"a":0,"e":"Applicant Tracking System."},{"q":"Un LMS est une plateforme de…","o":["Formation en ligne","Recrutement","Paie"],"a":0,"e":"Learning Management System."},{"q":"Un portail libre-service permet au salarié de…","o":["Poser ses absences en ligne","Modifier son salaire","Valider sa propre paie"],"a":0,"e":"Autonomie encadrée."},{"q":"Faut-il digitaliser un processus défaillant tel quel ?","o":["Non, il faut d'abord le simplifier","Oui, immédiatement","Oui, et le doubler"],"a":0,"e":"Sinon on automatise les erreurs."},{"q":"La signature électronique sert à…","o":["Signer des documents à distance","Calculer l'ITS","Recruter"],"a":0,"e":"Dématérialisation."},{"q":"L'audit RH vérifie la conformité, c'est-à-dire…","o":["Le respect de la loi","Le chiffre d'affaires","La couleur des bureaux"],"a":0,"e":"Légalité."},{"q":"L'efficience mesure…","o":["Le rapport résultat / coût","Le respect de la loi","L'ancienneté"],"a":0,"e":"Coût."},{"q":"L'efficacité mesure…","o":["L'atteinte des objectifs","Le coût","Le nombre de pages"],"a":0,"e":"Résultats."},{"q":"Des validations bloquées créent…","o":["Des délais d'attente","Des économies","Des embauches"],"a":0,"e":"Dysfonctionnement."},{"q":"Qui a donné son nom à la roue PDCA ?","o":["Deming","Herzberg","Ulrich"],"a":0,"e":"W. Edwards Deming."},{"q":"Dans l'exemple, la cause racine des erreurs de paie est…","o":["Une procédure non formalisée","Le salarié","La CNPS"],"a":0,"e":"Fin de la chaîne des pourquoi."},{"q":"Après « Act », on…","o":["Recommence le cycle","Arrête définitivement","Supprime le processus"],"a":0,"e":"Amélioration continue."},{"q":"Un coffre-fort numérique sert à…","o":["Stocker les documents RH en sécurité","Payer les salaires","Recruter"],"a":0,"e":"Archivage sécurisé."}]}]},{"id":"mrh305","code":"MRH 305","unit":"trad","title":"Maîtrise des relations sociales en entreprise","summary":"Acteurs et instances du dialogue social, négociation, climat social, prévention et gestion des conflits, santé-sécurité et RSE.","lessons":[{"id":"mrh305-1","n":1,"t":"Les fondements des relations sociales","min":20,"html":"<p>Les relations sociales désignent l'ensemble des échanges entre la direction, les salariés et leurs représentants sur les conditions de travail, d'emploi et de rémunération.</p>\n<h3>Les acteurs</h3>\n<div class=\"tbl\"><table><thead><tr><th>Côté</th><th>Acteurs</th></tr></thead><tbody>\n<tr><td>Employeur</td><td>Direction générale, DRH, managers, organisations patronales</td></tr>\n<tr><td>Salariés</td><td>Délégués du personnel, délégués syndicaux, syndicats, salariés eux-mêmes</td></tr>\n<tr><td>État</td><td>Ministère du Travail, inspection du travail, juridictions</td></tr></tbody></table></div>\n<h3>Les formes du dialogue social</h3>\n<ul><li><strong>Information</strong> : la direction communique une décision ou une donnée.</li><li><strong>Consultation</strong> : la direction recueille l'avis des représentants avant de décider.</li><li><strong>Négociation</strong> : les parties cherchent un accord qui les engage.</li><li><strong>Concertation</strong> : échange informel pour préparer une décision.</li></ul>\n<h3>Les enjeux</h3>\n<p>Un dialogue social de qualité favorise la paix sociale, l'adhésion aux changements, la performance et la prévention des conflits. Il repose sur la confiance, la transparence et le respect des engagements.</p>\n<h3>Le tripartisme</h3>\n<p>Au niveau national, les grandes questions (SMIG, conventions, réformes) sont discutées entre l'État, les employeurs et les travailleurs. C'est un principe promu par l'OIT.</p>","quiz":[{"q":"Les relations sociales concernent les échanges entre…","o":["Direction, salariés et représentants","Clients et fournisseurs","Actionnaires seuls"],"a":0,"e":"Définition."},{"q":"Un acteur côté employeur est…","o":["Le DRH","Le délégué syndical","L'inspecteur"],"a":0,"e":"Représentant de la direction."},{"q":"Un acteur côté salariés est…","o":["Le délégué du personnel","Le DG","Le comptable"],"a":0,"e":"Représentant élu."},{"q":"L'inspection du travail relève de…","o":["L'État","L'employeur","Les syndicats"],"a":0,"e":"Administration."},{"q":"Informer signifie…","o":["Communiquer une décision ou une donnée","Recueillir un avis","Signer un accord"],"a":0,"e":"Forme la plus simple."},{"q":"Consulter signifie…","o":["Recueillir l'avis avant de décider","Imposer","Négocier un accord signé"],"a":0,"e":"Avis préalable."},{"q":"Négocier signifie…","o":["Rechercher un accord qui engage","Informer","Sanctionner"],"a":0,"e":"Engagement mutuel."},{"q":"La concertation est…","o":["Un échange informel pour préparer une décision","Un procès","Une grève"],"a":0,"e":"Préparation."},{"q":"Un bon dialogue social favorise…","o":["La paix sociale","Les conflits","Le turnover"],"a":0,"e":"Enjeu principal."},{"q":"Le dialogue social repose sur…","o":["La confiance et la transparence","Le secret","La menace"],"a":0,"e":"Conditions."},{"q":"Le tripartisme réunit…","o":["État, employeurs, travailleurs","Clients, fournisseurs, banques","DG, DRH, DAF"],"a":0,"e":"Trois parties."},{"q":"Quel organisme international promeut le tripartisme ?","o":["L'OIT","Le FMI","L'OMS"],"a":0,"e":"Organisation internationale du travail."},{"q":"Le SMIG est discuté au niveau…","o":["National tripartite","D'une seule entreprise","D'un service"],"a":0,"e":"Question nationale."},{"q":"Les organisations patronales représentent…","o":["Les employeurs","Les salariés","L'État"],"a":0,"e":"Côté employeur."},{"q":"Le respect des engagements pris est…","o":["Une condition de la confiance","Facultatif","Contraire au dialogue"],"a":0,"e":"Crédibilité."},{"q":"Un dialogue social de qualité favorise l'adhésion…","o":["Aux changements","Aux concurrents","Aux impôts"],"a":0,"e":"Accompagnement."},{"q":"Les managers participent-ils aux relations sociales ?","o":["Oui, au quotidien","Non jamais","Seulement en grève"],"a":0,"e":"Relais de proximité."},{"q":"Laquelle de ces formes engage juridiquement les parties ?","o":["La négociation aboutie","L'information","La concertation"],"a":0,"e":"Accord signé."},{"q":"Les juridictions du travail relèvent de…","o":["L'État","L'employeur","Les syndicats"],"a":0,"e":"Justice."},{"q":"Le dialogue social porte notamment sur…","o":["Les conditions de travail et la rémunération","Les prix de vente","Le design des produits"],"a":0,"e":"Objet."}]},{"id":"mrh305-2","n":2,"t":"Faire vivre les instances représentatives","min":20,"html":"<h3>Le calendrier</h3>\n<p>Les délégués du personnel sont reçus au moins une fois par mois. Le DRH établit un calendrier annuel des réunions et le diffuse.</p>\n<h3>Avant la réunion</h3>\n<ul><li>Recevoir les questions écrites des délégués quelques jours avant.</li><li>Préparer les réponses avec les services concernés (paie, sécurité, logistique).</li><li>Rédiger et envoyer l'ordre du jour.</li></ul>\n<h3>Pendant la réunion</h3>\n<ul><li>Rappeler l'ordre du jour et le temps disponible.</li><li>Traiter chaque point, distinguer réponses immédiates et engagements à suivre.</li><li>Garder un ton respectueux, écouter, reformuler.</li></ul>\n<h3>Après la réunion</h3>\n<ul><li>Rédiger le <strong>procès-verbal</strong> ou compte rendu : questions, réponses, engagements, responsables, délais.</li><li>Le faire valider et le conserver dans un registre.</li><li>Suivre les engagements dans un tableau.</li></ul>\n<div class=\"tbl\"><table><thead><tr><th>Réclamation</th><th>Réponse</th><th>Responsable</th><th>Échéance</th></tr></thead><tbody>\n<tr><td>Climatisation en panne à l'atelier</td><td>Réparation commandée</td><td>Services généraux</td><td>15 du mois</td></tr>\n<tr><td>Retard de paiement des heures sup.</td><td>Régularisation sur la paie suivante</td><td>Paie</td><td>Fin du mois</td></tr></tbody></table></div>\n<h3>Les moyens des représentants</h3>\n<p>Crédit d'heures, local, panneau d'affichage, liberté de circulation dans l'entreprise pour l'exercice du mandat. Entraver ces droits constitue un délit d'entrave.</p>","quiz":[{"q":"Fréquence minimale de réception des délégués ?","o":["Une fois par mois","Une fois par an","Toutes les semaines obligatoirement"],"a":0,"e":"Réunion mensuelle."},{"q":"Qui établit le calendrier annuel des réunions ?","o":["Le DRH","Le client","La CNPS"],"a":0,"e":"Organisation."},{"q":"Les questions des délégués sont transmises…","o":["Par écrit avant la réunion","Après la réunion","Jamais"],"a":0,"e":"Préparation."},{"q":"Pour préparer les réponses, le DRH consulte…","o":["Les services concernés","Les concurrents","Personne"],"a":0,"e":"Réponses fondées."},{"q":"L'ordre du jour est envoyé…","o":["Avant la réunion","Après","Jamais"],"a":0,"e":"Information préalable."},{"q":"Pendant la réunion, on distingue…","o":["Réponses immédiates et engagements à suivre","Amis et ennemis","Hommes et femmes"],"a":0,"e":"Clarté."},{"q":"Reformuler sert à…","o":["Vérifier la compréhension","Couper la parole","Gagner du temps"],"a":0,"e":"Écoute active."},{"q":"Le procès-verbal contient…","o":["Questions, réponses, engagements, délais","Uniquement la date","Les salaires"],"a":0,"e":"Contenu."},{"q":"Le PV est conservé…","o":["Dans un registre","À la poubelle","Chez un délégué uniquement"],"a":0,"e":"Traçabilité."},{"q":"Un tableau de suivi des engagements indique…","o":["Responsable et échéance","Le prix des produits","Les impôts"],"a":0,"e":"Pilotage."},{"q":"Un moyen des représentants est…","o":["Le crédit d'heures","Un véhicule de fonction obligatoire","Une prime automatique"],"a":0,"e":"Temps de mandat."},{"q":"Les représentants disposent d'un panneau…","o":["D'affichage","Solaire","Publicitaire"],"a":0,"e":"Communication."},{"q":"Empêcher un délégué d'exercer son mandat constitue…","o":["Un délit d'entrave","Une bonne gestion","Un usage"],"a":0,"e":"Infraction."},{"q":"La liberté de circulation des délégués sert…","o":["À l'exercice du mandat","À quitter le travail","À vendre"],"a":0,"e":"Contact avec les salariés."},{"q":"Suivre les engagements renforce…","o":["La crédibilité de la direction","Les conflits","Le turnover"],"a":0,"e":"Confiance."},{"q":"Le ton de la réunion doit être…","o":["Respectueux","Agressif","Indifférent"],"a":0,"e":"Qualité du dialogue."},{"q":"Qui valide le PV ?","o":["Les participants","Le client","La banque"],"a":0,"e":"Accord sur le contenu."},{"q":"Réparer une climatisation en panne relève…","o":["Des services généraux","De la paie","Du marketing"],"a":0,"e":"Exemple du tableau."},{"q":"Rappeler le temps disponible en début de réunion sert à…","o":["Cadrer les échanges","Abréger sans raison","Éviter les questions"],"a":0,"e":"Organisation."},{"q":"Le local des représentants est…","o":["Un moyen prévu par la loi","Un privilège facultatif","Interdit"],"a":0,"e":"Moyen légal."}]},{"id":"mrh305-3","n":3,"t":"Préparer et conduire une négociation","min":25,"html":"<h3>Positions et intérêts</h3>\n<p>La <strong>position</strong> est ce que l'on demande (« 10 % d'augmentation »). L'<strong>intérêt</strong> est la raison profonde (« faire face à la hausse du coût de la vie »). La négociation raisonnée, développée à Harvard par Fisher et Ury, recommande de négocier sur les intérêts plutôt que sur les positions.</p>\n<h3>Les quatre principes de la négociation raisonnée</h3>\n<ol><li>Traiter séparément les personnes et le problème.</li><li>Se concentrer sur les intérêts, pas sur les positions.</li><li>Imaginer plusieurs options avant de décider.</li><li>Utiliser des critères objectifs (inflation, grille du marché).</li></ol>\n<h3>La MESORE</h3>\n<p>La meilleure solution de rechange (en anglais BATNA) est ce que l'on fera si la négociation échoue. Plus elle est bonne, plus on est en position de force.</p>\n<h3>Préparer</h3>\n<div class=\"tbl\"><table><thead><tr><th>Élément</th><th>Question</th></tr></thead><tbody>\n<tr><td>Objectif idéal</td><td>Que visons-nous ?</td></tr>\n<tr><td>Point de rupture</td><td>En dessous de quoi refusons-nous ?</td></tr>\n<tr><td>Marges de manœuvre</td><td>Que pouvons-nous céder ?</td></tr>\n<tr><td>Contreparties</td><td>Que demander en échange ?</td></tr>\n<tr><td>Arguments et chiffres</td><td>Quelles données objectives ?</td></tr></tbody></table></div>\n<h3>Conduire</h3>\n<p>Ouvrir en rappelant l'objectif commun, écouter les demandes, questionner pour découvrir les intérêts, proposer des options, échanger des concessions contre des contreparties, formaliser l'accord par écrit.</p>\n<div class=\"callout\"><b>Règle d'or</b>Ne jamais faire une concession sans contrepartie.</div>","quiz":[{"q":"La position est…","o":["Ce que l'on demande","La raison profonde","Le point de rupture"],"a":0,"e":"Demande exprimée."},{"q":"L'intérêt est…","o":["La raison profonde de la demande","Le taux d'intérêt","La position"],"a":0,"e":"Motivation."},{"q":"La négociation raisonnée a été développée par…","o":["Fisher et Ury","Taylor et Fayol","Maslow et Herzberg"],"a":0,"e":"Harvard Negotiation Project."},{"q":"Premier principe : séparer…","o":["Les personnes du problème","Hommes et femmes","Cadres et ouvriers"],"a":0,"e":"Éviter les attaques personnelles."},{"q":"On négocie de préférence sur…","o":["Les intérêts","Les positions","Les émotions"],"a":0,"e":"Principe clé."},{"q":"Imaginer plusieurs options sert à…","o":["Élargir les solutions possibles","Retarder","Compliquer"],"a":0,"e":"Créativité."},{"q":"Un critère objectif peut être…","o":["L'inflation","L'humeur du DG","La météo"],"a":0,"e":"Référence neutre."},{"q":"La MESORE est…","o":["La meilleure solution de rechange","Le salaire moyen","Un accord signé"],"a":0,"e":"Alternative en cas d'échec."},{"q":"Le terme anglais de la MESORE est…","o":["BATNA","SMART","SWOT"],"a":0,"e":"Best Alternative To a Negotiated Agreement."},{"q":"Une bonne MESORE donne…","o":["Une position de force","Une faiblesse","Aucun effet"],"a":0,"e":"On peut refuser un mauvais accord."},{"q":"Le point de rupture est…","o":["Le seuil en dessous duquel on refuse","L'objectif idéal","La première offre"],"a":0,"e":"Limite."},{"q":"Les marges de manœuvre sont…","o":["Ce que l'on peut céder","Les bénéfices","Les salaires"],"a":0,"e":"Flexibilité."},{"q":"Règle d'or de la négociation ?","o":["Pas de concession sans contrepartie","Céder vite","Ne jamais écouter"],"a":0,"e":"Équilibre."},{"q":"On ouvre la négociation en rappelant…","o":["L'objectif commun","Les menaces","Les erreurs passées"],"a":0,"e":"Climat constructif."},{"q":"Questionner sert à…","o":["Découvrir les intérêts","Piéger l'autre","Gagner du temps"],"a":0,"e":"Compréhension."},{"q":"L'accord est formalisé…","o":["Par écrit","Oralement","Jamais"],"a":0,"e":"Sécurité juridique."},{"q":"« 10 % d'augmentation » est…","o":["Une position","Un intérêt","Une MESORE"],"a":0,"e":"Demande chiffrée."},{"q":"« Faire face au coût de la vie » est…","o":["Un intérêt","Une position","Un point de rupture"],"a":0,"e":"Raison profonde."},{"q":"Les données objectives servent à…","o":["Argumenter","Menacer","Décorer"],"a":0,"e":"Crédibilité."},{"q":"Une contrepartie est…","o":["Ce que l'on demande en échange d'une concession","Une sanction","Une taxe"],"a":0,"e":"Échange."}]},{"id":"mrh305-4","n":4,"t":"Diagnostiquer le climat social","min":20,"html":"<p>Le climat social est la perception collective que les salariés ont de leur environnement de travail : relations, conditions, confiance envers la direction.</p>\n<h3>Les indicateurs objectifs</h3>\n<ul><li>Taux d'absentéisme, notamment les absences courtes et répétées.</li><li>Turnover et démissions.</li><li>Nombre de réclamations des délégués et de litiges.</li><li>Accidents du travail.</li><li>Jours de grève, arrêts de travail.</li><li>Participation aux événements internes.</li></ul>\n<h3>Les indicateurs subjectifs</h3>\n<ul><li>Baromètre social (questionnaire anonyme).</li><li>Entretiens individuels et de départ.</li><li>Rumeurs, tensions visibles, messages sur les panneaux.</li></ul>\n<h3>Le baromètre social</h3>\n<p>Il est administré à intervalle régulier (souvent annuel), avec les mêmes questions pour comparer dans le temps. Thèmes : management, rémunération, conditions de travail, reconnaissance, perspectives, confiance.</p>\n<div class=\"callout\"><b>Condition de réussite</b>Communiquer les résultats aux salariés et annoncer un plan d'action. Un baromètre sans suite dégrade la confiance.</div>\n<h3>Les signaux faibles</h3>\n<p>Ce sont des indices discrets qui annoncent une dégradation : baisse de participation, repli des équipes, multiplication des absences courtes. Le manager de proximité est le mieux placé pour les repérer.</p>","quiz":[{"q":"Le climat social est…","o":["Une perception collective","Une température","Un bilan financier"],"a":0,"e":"Définition."},{"q":"Un indicateur objectif est…","o":["Le taux d'absentéisme","La rumeur","L'impression du DG"],"a":0,"e":"Mesurable."},{"q":"Un indicateur subjectif est…","o":["Le baromètre social","Le nombre de grèves","Le turnover"],"a":0,"e":"Perception."},{"q":"Des absences courtes et répétées peuvent signaler…","o":["Une dégradation du climat","Une hausse des ventes","Rien"],"a":0,"e":"Signal."},{"q":"Le baromètre social est…","o":["Anonyme","Nominatif","Public"],"a":0,"e":"Liberté d'expression."},{"q":"Pourquoi garder les mêmes questions ?","o":["Pour comparer dans le temps","Par paresse","Pour tromper"],"a":0,"e":"Suivi."},{"q":"Fréquence habituelle du baromètre ?","o":["Annuelle","Quotidienne","Décennale"],"a":0,"e":"Souvent chaque année."},{"q":"Condition de réussite du baromètre ?","o":["Communiquer les résultats et un plan d'action","Garder les résultats secrets","Sanctionner les répondants"],"a":0,"e":"Crédibilité."},{"q":"Un baromètre sans suite…","o":["Dégrade la confiance","Améliore le climat","N'a aucun effet"],"a":0,"e":"Déception."},{"q":"Un signal faible est…","o":["Un indice discret de dégradation","Une grève","Un licenciement"],"a":0,"e":"Anticipation."},{"q":"Qui repère le mieux les signaux faibles ?","o":["Le manager de proximité","Le client","Le fournisseur"],"a":0,"e":"Présence quotidienne."},{"q":"Un thème du baromètre est…","o":["La reconnaissance","Le prix des produits","La TVA"],"a":0,"e":"Perception au travail."},{"q":"Les jours de grève sont un indicateur…","o":["Objectif","Subjectif","Inutile"],"a":0,"e":"Mesurable."},{"q":"La baisse de participation aux événements internes est…","o":["Un signal faible","Un signe de bonne santé","Sans intérêt"],"a":0,"e":"Désengagement."},{"q":"Les entretiens de départ informent sur…","o":["Le climat social","Les stocks","Les impôts"],"a":0,"e":"Motifs de départ."},{"q":"Le nombre de réclamations des délégués est un indicateur…","o":["Objectif","Financier","Commercial"],"a":0,"e":"Comptable."},{"q":"La confiance envers la direction fait partie…","o":["Du climat social","Du bilan","De la paie"],"a":0,"e":"Composante."},{"q":"Les accidents du travail peuvent refléter…","o":["Les conditions de travail","Le prix de l'action","Le marketing"],"a":0,"e":"Indicateur."},{"q":"Les rumeurs sont…","o":["Un indicateur subjectif à écouter","Toujours vraies","À ignorer toujours"],"a":0,"e":"Signal à analyser."},{"q":"Le repli des équipes est…","o":["Un signal faible","Une bonne nouvelle","Un indicateur financier"],"a":0,"e":"Isolement."}]},{"id":"mrh305-5","n":5,"t":"La communication sociale interne","min":20,"html":"<p>La communication interne accompagne le dialogue social : elle informe, explique les décisions et donne la parole aux salariés.</p>\n<h3>Les trois sens de la communication</h3>\n<div class=\"tbl\"><table><thead><tr><th>Sens</th><th>Exemples</th></tr></thead><tbody>\n<tr><td>Descendante</td><td>Note de service, réunion d'information, journal interne</td></tr>\n<tr><td>Ascendante</td><td>Boîte à idées, enquêtes, remontées des délégués</td></tr>\n<tr><td>Transversale</td><td>Réunions inter-services, réseau social interne</td></tr></tbody></table></div>\n<h3>Les supports</h3>\n<p>Affichage, intranet, messagerie, réunions d'équipe, groupes de discussion, journal interne, séminaires. Le choix dépend du public : un atelier sans ordinateurs sera mieux touché par l'affichage et la réunion d'équipe.</p>\n<h3>Communiquer un changement</h3>\n<ol><li>Informer d'abord les managers et les représentants du personnel.</li><li>Expliquer le pourquoi (contexte), le quoi (décision), le comment (mise en œuvre) et l'impact pour les salariés.</li><li>Prévoir un temps de questions.</li><li>Répéter le message par plusieurs canaux.</li></ol>\n<h3>Les erreurs à éviter</h3>\n<ul><li>Laisser les salariés apprendre une décision par la rumeur.</li><li>Promettre ce que l'on ne pourra pas tenir.</li><li>Communiquer uniquement par écrit une décision sensible.</li></ul>\n<div class=\"callout\"><b>Principe</b>Le silence de la direction est toujours interprété, souvent négativement.</div>","quiz":[{"q":"La communication descendante va…","o":["De la direction vers les salariés","Des salariés vers la direction","Entre services"],"a":0,"e":"Sens hiérarchique."},{"q":"Une boîte à idées est une communication…","o":["Ascendante","Descendante","Externe"],"a":0,"e":"Des salariés vers la direction."},{"q":"Une réunion inter-services est une communication…","o":["Transversale","Descendante","Ascendante"],"a":0,"e":"Entre pairs."},{"q":"Une note de service est une communication…","o":["Descendante","Ascendante","Transversale"],"a":0,"e":"Information de la direction."},{"q":"Pour un atelier sans ordinateurs, on privilégie…","o":["Affichage et réunion d'équipe","Intranet uniquement","E-mail uniquement"],"a":0,"e":"Adapter au public."},{"q":"Qui informer en premier d'un changement ?","o":["Managers et représentants","Les clients","La presse"],"a":0,"e":"Relais."},{"q":"Communiquer un changement, c'est expliquer…","o":["Pourquoi, quoi, comment, impact","Seulement la date","Seulement le coût"],"a":0,"e":"Structure."},{"q":"Pourquoi prévoir un temps de questions ?","o":["Pour lever les doutes","Pour perdre du temps","Pour sanctionner"],"a":0,"e":"Dialogue."},{"q":"Répéter par plusieurs canaux sert à…","o":["Toucher tout le monde","Ennuyer","Cacher"],"a":0,"e":"Couverture."},{"q":"Laisser une décision circuler par la rumeur est…","o":["Une erreur","Une bonne pratique","Neutre"],"a":0,"e":"Déformation."},{"q":"Promettre sans pouvoir tenir…","o":["Détruit la confiance","Motive durablement","Est recommandé"],"a":0,"e":"Crédibilité."},{"q":"Une décision sensible doit être communiquée…","o":["Aussi à l'oral","Uniquement par écrit","Jamais"],"a":0,"e":"Explication humaine."},{"q":"Le silence de la direction est…","o":["Interprété, souvent négativement","Sans effet","Toujours positif"],"a":0,"e":"Principe."},{"q":"Le journal interne est une communication…","o":["Descendante","Ascendante","Externe commerciale"],"a":0,"e":"Information générale."},{"q":"Les remontées des délégués sont une communication…","o":["Ascendante","Descendante","Transversale"],"a":0,"e":"Vers la direction."},{"q":"Un réseau social interne favorise la communication…","o":["Transversale","Uniquement descendante","Externe"],"a":0,"e":"Échanges entre salariés."},{"q":"La communication interne sert à…","o":["Informer, expliquer, donner la parole","Vendre","Recruter uniquement"],"a":0,"e":"Fonctions."},{"q":"Le « comment » d'un changement correspond à…","o":["La mise en œuvre","Le contexte","La décision"],"a":0,"e":"Modalités."},{"q":"Le « pourquoi » d'un changement correspond au…","o":["Contexte","Calendrier","Budget"],"a":0,"e":"Raisons."},{"q":"Les enquêtes auprès des salariés sont une communication…","o":["Ascendante","Descendante","Transversale"],"a":0,"e":"Recueil d'avis."}]},{"id":"mrh305-6","n":6,"t":"Prévenir les conflits","min":20,"html":"<h3>Les sources de conflit</h3>\n<div class=\"tbl\"><table><thead><tr><th>Source</th><th>Exemple</th></tr></thead><tbody>\n<tr><td>Intérêts divergents</td><td>Salaires, primes, horaires</td></tr>\n<tr><td>Injustice perçue</td><td>Promotion jugée arbitraire</td></tr>\n<tr><td>Communication défaillante</td><td>Décision apprise par la rumeur</td></tr>\n<tr><td>Conditions de travail</td><td>Chaleur, sécurité, charge de travail</td></tr>\n<tr><td>Changements mal accompagnés</td><td>Réorganisation brutale</td></tr>\n<tr><td>Relations personnelles</td><td>Tensions entre collègues ou avec un manager</td></tr></tbody></table></div>\n<h3>L'escalade du conflit</h3>\n<p>Un conflit évolue par étapes : tension latente, désaccord exprimé, blocage, affrontement ouvert. Plus on intervient tôt, plus la résolution est facile et peu coûteuse.</p>\n<h3>Les outils de prévention</h3>\n<ul><li>Règles claires et appliquées de façon égale (règlement intérieur, grilles).</li><li>Traitement rapide des réclamations.</li><li>Dialogue régulier avec les représentants.</li><li>Formation des managers à l'écoute et au feedback.</li><li>Veille sur les indicateurs de climat social.</li><li>Procédure interne de réclamation connue de tous.</li></ul>\n<h3>Le rôle du manager</h3>\n<p>Il désamorce les tensions au quotidien : il écoute, clarifie les faits, rappelle les règles, remonte les problèmes qu'il ne peut pas traiter seul.</p>\n<div class=\"callout\"><b>Règle</b>Une réclamation traitée rapidement, même par une réponse négative argumentée, vaut mieux qu'une réclamation ignorée.</div>","quiz":[{"q":"Une promotion jugée arbitraire relève…","o":["De l'injustice perçue","Des conditions de travail","Des intérêts financiers purs"],"a":0,"e":"Sentiment d'iniquité."},{"q":"Une réorganisation brutale est un exemple de…","o":["Changement mal accompagné","Bonne communication","Faible charge"],"a":0,"e":"Source de conflit."},{"q":"Première étape de l'escalade ?","o":["Tension latente","Affrontement ouvert","Blocage"],"a":0,"e":"Début invisible."},{"q":"Dernière étape de l'escalade ?","o":["Affrontement ouvert","Désaccord exprimé","Tension latente"],"a":0,"e":"Conflit déclaré."},{"q":"Quand intervenir sur un conflit ?","o":["Le plus tôt possible","Le plus tard possible","Jamais"],"a":0,"e":"Coût moindre."},{"q":"Des règles claires appliquées également préviennent…","o":["Le sentiment d'injustice","Les ventes","La paie"],"a":0,"e":"Équité."},{"q":"Former les managers à l'écoute sert à…","o":["Désamorcer les tensions","Augmenter les tensions","Réduire les salaires"],"a":0,"e":"Prévention."},{"q":"Une procédure interne de réclamation doit être…","o":["Connue de tous","Secrète","Réservée aux cadres"],"a":0,"e":"Accessibilité."},{"q":"Une réponse négative argumentée vaut mieux que…","o":["Une réclamation ignorée","Une réponse positive","Rien, c'est pareil"],"a":0,"e":"Respect."},{"q":"Le manager clarifie…","o":["Les faits","Les rumeurs uniquement","Le bilan"],"a":0,"e":"Objectivité."},{"q":"Ce que le manager ne peut traiter seul, il…","o":["Le remonte","L'ignore","Le cache"],"a":0,"e":"Escalade maîtrisée."},{"q":"La chaleur excessive dans un atelier relève…","o":["Des conditions de travail","De l'injustice","Des relations personnelles"],"a":0,"e":"Environnement."},{"q":"Une décision apprise par la rumeur relève…","o":["D'une communication défaillante","Des intérêts divergents","De la sécurité"],"a":0,"e":"Information."},{"q":"La veille sur les indicateurs de climat sert à…","o":["Anticiper","Punir","Recruter"],"a":0,"e":"Prévention."},{"q":"Traiter rapidement les réclamations…","o":["Prévient l'escalade","Crée des conflits","Est inutile"],"a":0,"e":"Réactivité."},{"q":"Les tensions entre collègues relèvent…","o":["Des relations personnelles","Des salaires","Des impôts"],"a":0,"e":"Interpersonnel."},{"q":"Le désaccord exprimé vient après…","o":["La tension latente","L'affrontement","Le blocage"],"a":0,"e":"Ordre de l'escalade."},{"q":"Un dialogue régulier avec les représentants est…","o":["Un outil de prévention","Une source de conflit","Facultatif et inutile"],"a":0,"e":"Canal permanent."},{"q":"Les salaires et primes relèvent de…","o":["Intérêts divergents","Relations personnelles","Communication"],"a":0,"e":"Enjeux économiques."},{"q":"Le coût d'un conflit augmente…","o":["Avec son escalade","Quand on agit tôt","Jamais"],"a":0,"e":"D'où l'intérêt d'agir vite."}]},{"id":"mrh305-7","n":7,"t":"Gérer un conflit individuel","min":20,"html":"<h3>Les styles de gestion des conflits</h3>\n<p>Le modèle de Thomas et Kilmann décrit cinq styles, selon l'importance accordée à ses propres intérêts et à ceux de l'autre.</p>\n<div class=\"tbl\"><table><thead><tr><th>Style</th><th>Description</th><th>Quand l'utiliser</th></tr></thead><tbody>\n<tr><td>Compétition</td><td>Imposer sa solution</td><td>Urgence, sécurité</td></tr>\n<tr><td>Collaboration</td><td>Chercher une solution gagnant-gagnant</td><td>Enjeu important, temps disponible</td></tr>\n<tr><td>Compromis</td><td>Chacun cède une partie</td><td>Solution rapide et acceptable</td></tr>\n<tr><td>Évitement</td><td>Reporter ou ignorer</td><td>Enjeu mineur, besoin de calmer</td></tr>\n<tr><td>Accommodation</td><td>Céder à l'autre</td><td>Préserver la relation, enjeu faible pour soi</td></tr></tbody></table></div>\n<h3>La médiation interne</h3>\n<p>Un tiers neutre (RH, manager d'un autre service) aide deux personnes à trouver elles-mêmes une solution.</p>\n<ol><li>Entretiens séparés pour écouter chaque partie.</li><li>Réunion commune : règles (respect, confidentialité), expression de chacun.</li><li>Recherche d'options.</li><li>Accord écrit et suivi.</li></ol>\n<h3>La méthode DESC pour exprimer un désaccord</h3>\n<p><strong>D</strong>écrire les faits, <strong>E</strong>xprimer son ressenti, <strong>S</strong>uggérer une solution, <strong>C</strong>onclure sur les conséquences positives.</p>\n<h3>Quand passer au disciplinaire ?</h3>\n<p>Si le conflit révèle une faute (insulte, violence, harcèlement), la médiation ne suffit pas : l'employeur doit agir et, le cas échéant, sanctionner.</p>","quiz":[{"q":"Le modèle des cinq styles est dû à…","o":["Thomas et Kilmann","Fisher et Ury","Hersey et Blanchard"],"a":0,"e":"Modèle classique."},{"q":"Imposer sa solution correspond au style…","o":["Compétition","Collaboration","Évitement"],"a":0,"e":"Affirmation forte."},{"q":"Solution gagnant-gagnant : style…","o":["Collaboration","Compromis","Accommodation"],"a":0,"e":"Intérêts des deux."},{"q":"Chacun cède une partie : style…","o":["Compromis","Compétition","Évitement"],"a":0,"e":"Partage."},{"q":"Reporter le problème : style…","o":["Évitement","Collaboration","Compétition"],"a":0,"e":"Retrait."},{"q":"Céder à l'autre : style…","o":["Accommodation","Compétition","Collaboration"],"a":0,"e":"Priorité à la relation."},{"q":"Quand utiliser la compétition ?","o":["En cas d'urgence ou de sécurité","Toujours","Jamais"],"a":0,"e":"Décision rapide."},{"q":"La collaboration demande…","o":["Du temps","Aucun effort","De la force"],"a":0,"e":"Recherche approfondie."},{"q":"Un médiateur est…","o":["Un tiers neutre","Un juge","Un avocat de l'une des parties"],"a":0,"e":"Impartialité."},{"q":"Première étape de la médiation ?","o":["Entretiens séparés","Accord écrit","Sanction"],"a":0,"e":"Écoute individuelle."},{"q":"Une règle de la réunion de médiation est…","o":["La confidentialité","L'interruption permanente","L'enregistrement public"],"a":0,"e":"Cadre de confiance."},{"q":"La médiation se termine par…","o":["Un accord écrit et un suivi","Un licenciement","Rien"],"a":0,"e":"Formalisation."},{"q":"Le « D » de DESC signifie…","o":["Décrire les faits","Décider","Dénoncer"],"a":0,"e":"Objectivité."},{"q":"Le « E » de DESC signifie…","o":["Exprimer son ressenti","Exiger","Évaluer"],"a":0,"e":"Émotion."},{"q":"Le « S » de DESC signifie…","o":["Suggérer une solution","Sanctionner","Supprimer"],"a":0,"e":"Proposition."},{"q":"Le « C » de DESC signifie…","o":["Conclure sur les conséquences positives","Condamner","Calculer"],"a":0,"e":"Motivation."},{"q":"En cas de harcèlement, la médiation…","o":["Ne suffit pas","Suffit toujours","Est obligatoire seule"],"a":0,"e":"Faute grave."},{"q":"Le médiateur aide les parties à…","o":["Trouver elles-mêmes une solution","Accepter sa décision","Se sanctionner"],"a":0,"e":"Autonomie."},{"q":"L'évitement convient à…","o":["Un enjeu mineur","Un enjeu vital","Une question de sécurité"],"a":0,"e":"Faible importance."},{"q":"Une insulte grave révèle…","o":["Une faute","Un simple malentendu toujours","Un droit"],"a":0,"e":"Disciplinaire."}]},{"id":"mrh305-8","n":8,"t":"Gérer un conflit collectif et la grève","min":25,"html":"<h3>Les phases d'un conflit collectif</h3>\n<ol><li><strong>Revendication</strong> : cahier de doléances remis par les représentants.</li><li><strong>Négociation</strong> interne.</li><li><strong>Préavis de grève</strong> en cas d'échec.</li><li><strong>Conciliation</strong> devant l'inspection du travail.</li><li><strong>Médiation</strong> ou <strong>arbitrage</strong> si nécessaire.</li><li><strong>Sortie de crise</strong> : protocole d'accord.</li></ol>\n<h3>Le plan d'action de la DRH</h3>\n<ul><li>Accuser réception et proposer une rencontre rapide.</li><li>Analyser chaque revendication : légitimité, coût, faisabilité.</li><li>Obtenir un mandat clair de la direction.</li><li>Informer tout le personnel de façon factuelle.</li><li>Organiser le service minimum si l'activité l'exige.</li><li>Tenir un journal des événements.</li></ul>\n<h3>Les règles pendant la grève</h3>\n<ul><li>Le contrat est suspendu, le salaire correspondant n'est pas dû.</li><li>Le gréviste ne peut pas être sanctionné pour avoir fait grève, sauf faute lourde.</li><li>Les non-grévistes doivent pouvoir travailler : l'occupation des locaux et l'entrave à la liberté du travail sont illicites.</li><li>L'employeur ne peut pas remplacer les grévistes par des embauches pour briser la grève.</li></ul>\n<h3>Le protocole de fin de conflit</h3>\n<p>Il précise les mesures accordées, le calendrier, le traitement des jours de grève (retenue, étalement, récupération) et l'engagement à reprendre le travail.</p>","quiz":[{"q":"Le cahier de doléances est remis…","o":["Par les représentants","Par le client","Par la CNPS"],"a":0,"e":"Revendications écrites."},{"q":"Après l'échec de la négociation interne vient…","o":["Le préavis de grève","La paie","Le recrutement"],"a":0,"e":"Étape suivante."},{"q":"La conciliation a lieu devant…","o":["L'inspection du travail","Le tribunal de commerce","La banque"],"a":0,"e":"Procédure légale."},{"q":"La sortie de crise est formalisée par…","o":["Un protocole d'accord","Un licenciement","Une annonce"],"a":0,"e":"Accord écrit."},{"q":"Première action de la DRH face à une revendication ?","o":["Accuser réception et proposer une rencontre","Ignorer","Sanctionner"],"a":0,"e":"Ouverture."},{"q":"Chaque revendication est analysée selon…","o":["Légitimité, coût, faisabilité","Couleur","Âge du délégué"],"a":0,"e":"Grille d'analyse."},{"q":"Pourquoi obtenir un mandat de la direction ?","o":["Pour savoir jusqu'où négocier","Pour éviter de négocier","Pour sanctionner"],"a":0,"e":"Marges."},{"q":"L'information du personnel doit être…","o":["Factuelle","Partisane","Absente"],"a":0,"e":"Neutralité."},{"q":"Un journal des événements sert à…","o":["Garder une trace","Décorer","Payer"],"a":0,"e":"Preuve."},{"q":"Pendant la grève, le salaire…","o":["N'est pas dû","Est doublé","Est versé par l'État"],"a":0,"e":"Suspension."},{"q":"Peut-on sanctionner un salarié pour avoir fait grève ?","o":["Non, sauf faute lourde","Oui toujours","Oui s'il est cadre"],"a":0,"e":"Droit de grève."},{"q":"L'occupation des locaux est…","o":["Illicite","Un droit","Obligatoire"],"a":0,"e":"Entrave."},{"q":"Les non-grévistes doivent pouvoir…","o":["Travailler","Être sanctionnés","Rester chez eux payés"],"a":0,"e":"Liberté du travail."},{"q":"Embaucher pour remplacer des grévistes est…","o":["Interdit","Recommandé","Obligatoire"],"a":0,"e":"Atteinte au droit de grève."},{"q":"Le protocole de fin de conflit traite…","o":["Des jours de grève","Des prix de vente","Du capital"],"a":0,"e":"Retenue, étalement…"},{"q":"Le service minimum s'organise…","o":["Si l'activité l'exige","Jamais","Toujours à 100 %"],"a":0,"e":"Continuité essentielle."},{"q":"L'arbitrage intervient…","o":["Après échec de la conciliation","Avant la revendication","Jamais"],"a":0,"e":"Dernier recours."},{"q":"La grève suspend…","o":["Le contrat de travail","Le règlement intérieur","L'entreprise"],"a":0,"e":"Effet juridique."},{"q":"Le protocole comprend l'engagement…","o":["À reprendre le travail","À démissionner","À vendre"],"a":0,"e":"Fin du conflit."},{"q":"Une revendication coûteuse mais légitime peut être…","o":["Étalée dans le temps","Ignorée","Sanctionnée"],"a":0,"e":"Option de négociation."}]},{"id":"mrh305-9","n":9,"t":"Santé, sécurité et risques psychosociaux","min":25,"html":"<h3>L'obligation de sécurité</h3>\n<p>L'employeur doit protéger la santé physique et mentale des salariés. Il évalue les risques, met en place des mesures de prévention et informe les salariés.</p>\n<h3>Les principes de prévention</h3>\n<ol><li>Éviter les risques.</li><li>Évaluer ceux qui ne peuvent être évités.</li><li>Combattre les risques à la source.</li><li>Adapter le travail à l'homme.</li><li>Privilégier la protection collective sur la protection individuelle.</li><li>Former et informer.</li></ol>\n<h3>Les acteurs</h3>\n<ul><li>Le <strong>comité de santé et sécurité au travail</strong> : analyse les risques, enquête après accident.</li><li>Le <strong>médecin du travail</strong> : visites, aptitude, conseils.</li><li>Les <strong>délégués du personnel</strong> : remontent les problèmes.</li><li>L'<strong>inspection du travail</strong> : contrôle.</li></ul>\n<h3>Les risques psychosociaux (RPS)</h3>\n<p>Ce sont les risques pour la santé mentale et physique liés à l'organisation du travail et aux relations : stress chronique, épuisement professionnel (burn-out), harcèlement moral ou sexuel, violences internes ou externes.</p>\n<div class=\"tbl\"><table><thead><tr><th>Facteur de RPS</th><th>Exemple</th></tr></thead><tbody>\n<tr><td>Intensité du travail</td><td>Objectifs irréalistes, heures excessives</td></tr>\n<tr><td>Manque d'autonomie</td><td>Aucune marge sur la façon de travailler</td></tr>\n<tr><td>Rapports sociaux dégradés</td><td>Isolement, conflits, manque de soutien</td></tr>\n<tr><td>Insécurité de la situation</td><td>Peur de perdre son emploi</td></tr></tbody></table></div>\n<h3>Le rôle des RH</h3>\n<p>Mettre en place une procédure de signalement du harcèlement, former les managers, suivre les indicateurs (absences, accidents), proposer un soutien (écoute, aménagement de poste).</p>","quiz":[{"q":"L'obligation de sécurité couvre la santé…","o":["Physique et mentale","Physique uniquement","Financière"],"a":0,"e":"Définition large."},{"q":"Premier principe de prévention ?","o":["Éviter les risques","Distribuer des gants","Sanctionner"],"a":0,"e":"Priorité."},{"q":"On privilégie la protection…","o":["Collective","Individuelle","Aucune"],"a":0,"e":"Principe."},{"q":"Adapter le travail à l'homme signifie…","o":["Concevoir les postes selon les capacités humaines","Choisir des salariés robustes","Allonger les horaires"],"a":0,"e":"Ergonomie."},{"q":"Qui enquête après un accident ?","o":["Le comité de santé et sécurité","Le comptable","Le client"],"a":0,"e":"Instance spécialisée."},{"q":"Le médecin du travail se prononce sur…","o":["L'aptitude","Le salaire","La promotion"],"a":0,"e":"Rôle médical."},{"q":"Les RPS sont liés…","o":["À l'organisation du travail et aux relations","Aux machines uniquement","Au climat météo"],"a":0,"e":"Définition."},{"q":"Le burn-out est…","o":["Un épuisement professionnel","Une promotion","Un congé"],"a":0,"e":"RPS."},{"q":"Des objectifs irréalistes relèvent du facteur…","o":["Intensité du travail","Autonomie","Insécurité"],"a":0,"e":"Surcharge."},{"q":"Aucune marge sur la façon de travailler relève…","o":["Du manque d'autonomie","De l'intensité","Des rapports sociaux"],"a":0,"e":"Facteur de RPS."},{"q":"L'isolement relève…","o":["Des rapports sociaux dégradés","De l'intensité","De l'autonomie"],"a":0,"e":"Manque de soutien."},{"q":"La peur de perdre son emploi relève…","o":["De l'insécurité de la situation","De l'intensité","De l'autonomie"],"a":0,"e":"Facteur."},{"q":"Le harcèlement moral est…","o":["Un risque psychosocial","Un style de management acceptable","Une sanction"],"a":0,"e":"RPS grave."},{"q":"Une procédure de signalement du harcèlement doit…","o":["Exister et être connue","Être secrète","Être facultative"],"a":0,"e":"Rôle RH."},{"q":"Un aménagement de poste est…","o":["Une mesure de soutien","Une sanction","Une promotion"],"a":0,"e":"Adaptation."},{"q":"Combattre les risques à la source signifie…","o":["Supprimer la cause du danger","Soigner après","Assurer"],"a":0,"e":"Principe."},{"q":"La formation et l'information sont…","o":["Des principes de prévention","Facultatives","Interdites"],"a":0,"e":"Principe."},{"q":"Qui contrôle le respect des règles de sécurité ?","o":["L'inspection du travail","La DGI","Le client"],"a":0,"e":"Contrôle."},{"q":"Les heures excessives sont un facteur…","o":["D'intensité du travail","D'autonomie","De sécurité d'emploi"],"a":0,"e":"Surcharge."},{"q":"Former les managers aux RPS aide à…","o":["Repérer et prévenir","Augmenter les objectifs","Isoler les salariés"],"a":0,"e":"Prévention."}]},{"id":"mrh305-10","n":10,"t":"RSE et dialogue social","min":20,"html":"<h3>La responsabilité sociétale des entreprises</h3>\n<p>La RSE est l'intégration volontaire par l'entreprise de préoccupations sociales, environnementales et de gouvernance dans ses activités et ses relations avec les parties prenantes.</p>\n<h3>La norme ISO 26000</h3>\n<p>Publiée en 2010, elle propose des lignes directrices (non certifiables) autour de sept questions centrales : gouvernance, droits de l'homme, relations et conditions de travail, environnement, loyauté des pratiques, questions relatives aux consommateurs, communautés et développement local.</p>\n<h3>Le volet social de la RSE</h3>\n<ul><li>Conditions de travail décentes, santé et sécurité.</li><li>Dialogue social et respect de la liberté syndicale.</li><li>Égalité professionnelle et non-discrimination.</li><li>Formation et employabilité.</li><li>Lutte contre le travail des enfants et le travail forcé dans la chaîne d'approvisionnement.</li></ul>\n<h3>Les parties prenantes</h3>\n<p>Salariés, représentants, clients, fournisseurs, communautés locales, État, actionnaires. Le dialogue social est une forme de dialogue avec une partie prenante essentielle : les salariés.</p>\n<h3>Mesurer</h3>\n<p>Le rapport RSE ou extra-financier présente des indicateurs : taux de femmes cadres, heures de formation, taux de fréquence des accidents, nombre d'accords signés.</p>\n<div class=\"callout\"><b>Enjeu en Côte d'Ivoire</b>Dans les filières d'exportation (cacao, hévéa), les acheteurs internationaux exigent de plus en plus la preuve de pratiques sociales responsables chez leurs fournisseurs.</div>","quiz":[{"q":"La RSE intègre des préoccupations…","o":["Sociales, environnementales et de gouvernance","Uniquement financières","Uniquement commerciales"],"a":0,"e":"Trois piliers."},{"q":"La RSE est en principe…","o":["Volontaire","Toujours imposée par la loi","Interdite"],"a":0,"e":"Démarche volontaire."},{"q":"La norme ISO 26000 date de…","o":["2010","1990","2020"],"a":0,"e":"Publication."},{"q":"ISO 26000 est-elle certifiable ?","o":["Non","Oui","Seulement en Afrique"],"a":0,"e":"Lignes directrices."},{"q":"Combien de questions centrales dans ISO 26000 ?","o":["Sept","Trois","Douze"],"a":0,"e":"Structure."},{"q":"Les relations et conditions de travail sont…","o":["Une question centrale d'ISO 26000","Hors RSE","Uniquement juridiques"],"a":0,"e":"Volet social."},{"q":"Un élément du volet social est…","o":["L'égalité professionnelle","Le prix de vente","La publicité"],"a":0,"e":"Non-discrimination."},{"q":"La lutte contre le travail des enfants concerne aussi…","o":["La chaîne d'approvisionnement","Uniquement les bureaux","Les actionnaires"],"a":0,"e":"Fournisseurs."},{"q":"Une partie prenante est…","o":["Un acteur concerné par l'activité de l'entreprise","Seulement l'actionnaire","Un concurrent uniquement"],"a":0,"e":"Définition."},{"q":"Les salariés sont…","o":["Une partie prenante essentielle","Hors des parties prenantes","Des fournisseurs"],"a":0,"e":"Dialogue social."},{"q":"Un indicateur social du rapport RSE est…","o":["Le taux de femmes cadres","Le chiffre d'affaires","Le cours de bourse"],"a":0,"e":"Indicateur extra-financier."},{"q":"Le rapport extra-financier présente…","o":["Des indicateurs non financiers","Seulement le bilan","Les prix"],"a":0,"e":"Performance RSE."},{"q":"Le nombre d'accords signés mesure…","o":["La vitalité du dialogue social","Les ventes","La trésorerie"],"a":0,"e":"Indicateur."},{"q":"Pourquoi la RSE compte dans les filières d'exportation ?","o":["Les acheteurs exigent des pratiques responsables","Elle réduit les impôts automatiquement","Elle est inutile"],"a":0,"e":"Exigence du marché."},{"q":"Les communautés locales sont…","o":["Une partie prenante","Sans rapport","Des concurrents"],"a":0,"e":"Territoire."},{"q":"La formation et l'employabilité relèvent…","o":["Du volet social","De l'environnement","De la gouvernance uniquement"],"a":0,"e":"Développement des salariés."},{"q":"La loyauté des pratiques est…","o":["Une question centrale d'ISO 26000","Un indicateur de paie","Une taxe"],"a":0,"e":"Éthique des affaires."},{"q":"La liberté syndicale fait partie…","o":["Du volet social de la RSE","Du marketing","De la comptabilité"],"a":0,"e":"Droits fondamentaux."},{"q":"Le taux de fréquence des accidents est un indicateur…","o":["Social","Financier","Commercial"],"a":0,"e":"Santé-sécurité."},{"q":"La gouvernance est…","o":["Une question centrale d'ISO 26000","Hors RSE","Une prime"],"a":0,"e":"Pilier."}]}]},{"id":"mrh306","code":"MRH 306","unit":"trad","title":"Sondage, collecte, traitement et interprétation de data RH","summary":"De la question à la décision : sources de données RH, échantillonnage, questionnaires, nettoyage, statistiques descriptives, indicateurs et restitution.","lessons":[{"id":"mrh306-1","n":1,"t":"Pourquoi la data RH ?","min":20,"html":"<p>La data RH (ou <em>people analytics</em>) consiste à collecter et analyser les données sur les salariés pour éclairer les décisions RH par des faits plutôt que par des intuitions.</p>\n<h3>Quatre niveaux d'analyse</h3>\n<div class=\"tbl\"><table><thead><tr><th>Niveau</th><th>Question</th><th>Exemple</th></tr></thead><tbody>\n<tr><td>Descriptif</td><td>Que s'est-il passé ?</td><td>Turnover de 12 % cette année</td></tr>\n<tr><td>Diagnostique</td><td>Pourquoi ?</td><td>Départs concentrés chez les commerciaux de moins de 2 ans</td></tr>\n<tr><td>Prédictif</td><td>Que va-t-il se passer ?</td><td>Probabilité de départ par profil</td></tr>\n<tr><td>Prescriptif</td><td>Que faut-il faire ?</td><td>Recommandation d'actions ciblées</td></tr></tbody></table></div>\n<h3>Les questions typiques</h3>\n<ul><li>Pourquoi nos jeunes talents partent-ils ?</li><li>Quel canal de recrutement donne les meilleurs profils ?</li><li>La formation améliore-t-elle la performance ?</li><li>Y a-t-il des écarts de salaire injustifiés entre hommes et femmes ?</li></ul>\n<h3>La démarche</h3>\n<ol><li>Formuler une question métier précise.</li><li>Identifier les données nécessaires.</li><li>Collecter et nettoyer.</li><li>Analyser.</li><li>Interpréter et restituer.</li><li>Décider et agir.</li></ol>\n<div class=\"callout\"><b>À retenir</b>On commence toujours par la question, jamais par les données disponibles.</div>","quiz":[{"q":"People analytics désigne…","o":["L'analyse des données sur les salariés","La publicité","La comptabilité"],"a":0,"e":"Data RH."},{"q":"Objectif principal de la data RH ?","o":["Décider sur des faits","Remplacer les managers","Surveiller les salariés"],"a":0,"e":"Éclairer les décisions."},{"q":"Le niveau descriptif répond à…","o":["Que s'est-il passé ?","Pourquoi ?","Que faire ?"],"a":0,"e":"Constat."},{"q":"Le niveau diagnostique répond à…","o":["Pourquoi ?","Que s'est-il passé ?","Que va-t-il se passer ?"],"a":0,"e":"Explication."},{"q":"Le niveau prédictif répond à…","o":["Que va-t-il se passer ?","Pourquoi ?","Que s'est-il passé ?"],"a":0,"e":"Anticipation."},{"q":"Le niveau prescriptif répond à…","o":["Que faut-il faire ?","Que s'est-il passé ?","Pourquoi ?"],"a":0,"e":"Recommandation."},{"q":"« Turnover de 12 % » est une analyse…","o":["Descriptive","Prédictive","Prescriptive"],"a":0,"e":"Constat chiffré."},{"q":"« Départs concentrés chez les commerciaux récents » est une analyse…","o":["Diagnostique","Descriptive","Prescriptive"],"a":0,"e":"Explication."},{"q":"« Probabilité de départ par profil » est une analyse…","o":["Prédictive","Descriptive","Diagnostique"],"a":0,"e":"Projection."},{"q":"Première étape de la démarche ?","o":["Formuler une question métier","Collecter toutes les données","Faire un graphique"],"a":0,"e":"Point de départ."},{"q":"Dernière étape de la démarche ?","o":["Décider et agir","Nettoyer","Collecter"],"a":0,"e":"Finalité."},{"q":"On commence par…","o":["La question","Les données disponibles","Le logiciel"],"a":0,"e":"Règle d'or."},{"q":"Comparer les salaires hommes/femmes relève de…","o":["L'équité salariale","Le marketing","La logistique"],"a":0,"e":"Question RH."},{"q":"Le niveau le plus avancé est…","o":["Prescriptif","Descriptif","Diagnostique"],"a":0,"e":"Recommandation d'actions."},{"q":"Le nettoyage des données intervient…","o":["Avant l'analyse","Après la décision","Jamais"],"a":0,"e":"Qualité."},{"q":"Mesurer l'effet de la formation sur la performance est…","o":["Une question de data RH","Une question fiscale","Hors sujet"],"a":0,"e":"Question typique."},{"q":"L'interprétation vient après…","o":["L'analyse","La décision","L'action"],"a":0,"e":"Ordre logique."},{"q":"Décider sur l'intuition seule risque…","o":["Des erreurs","D'être toujours juste","Rien"],"a":0,"e":"Biais."},{"q":"Identifier le meilleur canal de recrutement est…","o":["Une question data RH","Une question juridique","Une question de paie"],"a":0,"e":"Exemple."},{"q":"Combien de niveaux d'analyse ?","o":["Quatre","Deux","Six"],"a":0,"e":"Descriptif à prescriptif."}]},{"id":"mrh306-2","n":2,"t":"Sources et qualité des données RH","min":20,"html":"<h3>Les sources</h3>\n<div class=\"tbl\"><table><thead><tr><th>Source</th><th>Données</th></tr></thead><tbody>\n<tr><td>SIRH / fichier du personnel</td><td>Identité, poste, service, date d'entrée, contrat</td></tr>\n<tr><td>Logiciel de paie</td><td>Salaires, primes, heures, absences</td></tr>\n<tr><td>Gestion des temps</td><td>Présences, retards, heures supplémentaires</td></tr>\n<tr><td>Recrutement (ATS)</td><td>Candidatures, sources, délais</td></tr>\n<tr><td>Formation (LMS)</td><td>Inscriptions, heures, résultats</td></tr>\n<tr><td>Enquêtes</td><td>Satisfaction, engagement, opinions</td></tr>\n<tr><td>Entretiens annuels</td><td>Évaluations, objectifs, souhaits</td></tr></tbody></table></div>\n<h3>Données quantitatives et qualitatives</h3>\n<p>Les données <strong>quantitatives</strong> sont chiffrées (âge, salaire, heures). Les données <strong>qualitatives</strong> décrivent (service, motif de départ, commentaire libre). Parmi les qualitatives, on distingue les variables <strong>nominales</strong> (sans ordre : service) et <strong>ordinales</strong> (avec ordre : niveau de satisfaction).</p>\n<h3>Les critères de qualité</h3>\n<ul><li><strong>Exactitude</strong> : la donnée est juste.</li><li><strong>Complétude</strong> : pas de champs vides.</li><li><strong>Cohérence</strong> : même valeur dans tous les systèmes.</li><li><strong>Actualité</strong> : la donnée est à jour.</li><li><strong>Unicité</strong> : pas de doublons.</li></ul>\n<div class=\"callout\"><b>Exemple d'incohérence</b>Un salarié sorti en mars figure encore dans le SIRH en juin, mais plus dans la paie : l'effectif calculé sera faux.</div>\n<h3>Le référentiel unique</h3>\n<p>Un identifiant commun (matricule) dans tous les systèmes permet de croiser les données sans erreur.</p>","quiz":[{"q":"Les salaires proviennent principalement…","o":["Du logiciel de paie","De l'ATS","Du LMS"],"a":0,"e":"Source paie."},{"q":"Les sources de candidatures proviennent…","o":["De l'ATS","De la paie","Du LMS"],"a":0,"e":"Recrutement."},{"q":"Les heures de formation proviennent…","o":["Du LMS","De l'ATS","Du registre"],"a":0,"e":"Formation."},{"q":"L'âge est une donnée…","o":["Quantitative","Qualitative nominale","Qualitative ordinale"],"a":0,"e":"Chiffrée."},{"q":"Le service d'affectation est une variable…","o":["Qualitative nominale","Quantitative","Ordinale"],"a":0,"e":"Sans ordre."},{"q":"Le niveau de satisfaction (faible, moyen, fort) est une variable…","o":["Qualitative ordinale","Nominale","Quantitative continue"],"a":0,"e":"Avec ordre."},{"q":"Un motif de départ est une donnée…","o":["Qualitative","Quantitative","Financière"],"a":0,"e":"Description."},{"q":"L'exactitude signifie que la donnée est…","o":["Juste","Récente","Unique"],"a":0,"e":"Critère."},{"q":"La complétude signifie…","o":["Pas de champs vides","Pas de doublons","Donnée à jour"],"a":0,"e":"Critère."},{"q":"La cohérence signifie…","o":["Même valeur dans tous les systèmes","Donnée récente","Donnée unique"],"a":0,"e":"Critère."},{"q":"L'actualité signifie…","o":["Donnée à jour","Donnée juste","Donnée complète"],"a":0,"e":"Critère."},{"q":"L'unicité signifie…","o":["Pas de doublons","Pas de champs vides","Donnée récente"],"a":0,"e":"Critère."},{"q":"Un salarié sorti encore présent dans le SIRH est un problème…","o":["De cohérence et d'actualité","De complétude seulement","Sans importance"],"a":0,"e":"Exemple."},{"q":"L'identifiant commun recommandé est…","o":["Le matricule","Le prénom","L'adresse"],"a":0,"e":"Clé unique."},{"q":"Pourquoi un identifiant commun ?","o":["Pour croiser les données sans erreur","Pour décorer","Pour l'impôt"],"a":0,"e":"Jointures fiables."},{"q":"Les évaluations annuelles proviennent…","o":["Des entretiens annuels","De la paie","Du LMS"],"a":0,"e":"Source."},{"q":"Les retards proviennent…","o":["De la gestion des temps","De l'ATS","Des enquêtes"],"a":0,"e":"Source."},{"q":"Un commentaire libre d'enquête est…","o":["Qualitatif","Quantitatif","Ordinal"],"a":0,"e":"Texte."},{"q":"Le salaire est une donnée…","o":["Quantitative","Nominale","Ordinale"],"a":0,"e":"Chiffrée."},{"q":"Deux fiches pour la même personne violent…","o":["L'unicité","L'actualité","L'exactitude seulement"],"a":0,"e":"Doublon."}]},{"id":"mrh306-3","n":3,"t":"Concevoir une enquête","min":20,"html":"<h3>Les étapes</h3>\n<ol><li><strong>Définir l'objectif</strong> : que veut-on savoir et pour décider quoi ?</li><li><strong>Définir la population</strong> : tous les salariés, un service, les nouveaux arrivants ?</li><li><strong>Choisir entre recensement et sondage</strong>.</li><li><strong>Rédiger et tester</strong> le questionnaire.</li><li><strong>Administrer</strong> l'enquête.</li><li><strong>Traiter, analyser, restituer</strong>.</li></ol>\n<h3>Recensement ou sondage ?</h3>\n<p>Le <strong>recensement</strong> interroge toute la population : possible quand elle est petite (une PME de 80 salariés). Le <strong>sondage</strong> interroge un échantillon représentatif : utile pour une grande population ou quand le temps est limité.</p>\n<h3>Les types d'études</h3>\n<div class=\"tbl\"><table><thead><tr><th>Type</th><th>Méthode</th><th>Usage</th></tr></thead><tbody>\n<tr><td>Quantitative</td><td>Questionnaire fermé, nombreux répondants</td><td>Mesurer, comparer, chiffrer</td></tr>\n<tr><td>Qualitative</td><td>Entretiens, focus groups, peu de participants</td><td>Comprendre, explorer les causes</td></tr></tbody></table></div>\n<p>Les deux se complètent : une étude qualitative peut préparer les questions d'une enquête quantitative, ou expliquer ses résultats.</p>\n<h3>Le focus group</h3>\n<p>Réunion de 6 à 10 personnes animée autour d'un thème, pour recueillir des perceptions et des idées.</p>\n<h3>Le calendrier</h3>\n<p>Évitez les périodes chargées (clôture, congés). Prévoyez 2 à 3 semaines de collecte avec relances.</p>","quiz":[{"q":"Première étape d'une enquête ?","o":["Définir l'objectif","Rédiger les questions","Analyser"],"a":0,"e":"Pourquoi enquêter."},{"q":"La population d'une enquête est…","o":["L'ensemble des personnes concernées","Les répondants seulement","La ville"],"a":0,"e":"Définition."},{"q":"Le recensement interroge…","o":["Toute la population","Un échantillon","Personne"],"a":0,"e":"Exhaustivité."},{"q":"Le sondage interroge…","o":["Un échantillon représentatif","Toute la population","Seulement les cadres"],"a":0,"e":"Partie de la population."},{"q":"Pour une PME de 80 salariés, on privilégie…","o":["Le recensement","Un sondage de 5 personnes","Aucune enquête"],"a":0,"e":"Population petite."},{"q":"Une étude quantitative sert à…","o":["Mesurer et comparer","Explorer en profondeur","Remplacer la paie"],"a":0,"e":"Chiffrer."},{"q":"Une étude qualitative sert à…","o":["Comprendre les causes","Chiffrer précisément","Calculer l'ITS"],"a":0,"e":"Explorer."},{"q":"Un focus group réunit environ…","o":["6 à 10 personnes","100 personnes","1 personne"],"a":0,"e":"Petit groupe."},{"q":"Une étude qualitative peut…","o":["Préparer une enquête quantitative","Remplacer toute mesure","Être inutile"],"a":0,"e":"Complémentarité."},{"q":"Méthode typique de l'étude quantitative ?","o":["Questionnaire fermé","Entretien libre","Observation seule"],"a":0,"e":"Standardisé."},{"q":"Méthode typique de l'étude qualitative ?","o":["Entretiens ou focus groups","Questionnaire à 500 personnes","Bilan"],"a":0,"e":"Approfondi."},{"q":"Durée de collecte recommandée ?","o":["2 à 3 semaines avec relances","Une heure","Six mois"],"a":0,"e":"Calendrier."},{"q":"Période à éviter pour enquêter ?","o":["Les congés ou périodes chargées","Un mois normal","Aucune"],"a":0,"e":"Taux de réponse."},{"q":"Pourquoi tester le questionnaire ?","o":["Détecter les questions mal comprises","Perdre du temps","Augmenter les coûts"],"a":0,"e":"Pré-test."},{"q":"L'objectif doit préciser…","o":["Ce que l'on veut décider","Le logo","Le nombre de pages"],"a":0,"e":"Utilité."},{"q":"Les nouveaux arrivants peuvent constituer…","o":["Une population d'enquête","Un échantillon aléatoire de l'entreprise","Rien"],"a":0,"e":"Population ciblée."},{"q":"Le sondage est utile quand…","o":["La population est grande","La population compte 10 personnes","On a trop de temps"],"a":0,"e":"Économie."},{"q":"Un focus group est une méthode…","o":["Qualitative","Quantitative","Comptable"],"a":0,"e":"Discussion."},{"q":"Une étude qualitative peut aussi…","o":["Expliquer les résultats quantitatifs","Remplacer les chiffres","Calculer le turnover"],"a":0,"e":"Approfondissement."},{"q":"Les relances servent à…","o":["Augmenter le taux de réponse","Irriter","Changer les questions"],"a":0,"e":"Participation."}]},{"id":"mrh306-4","n":4,"t":"L'échantillonnage","min":25,"html":"<p>Un échantillon est représentatif s'il reproduit les caractéristiques de la population (sexe, âge, service, catégorie).</p>\n<h3>Les méthodes</h3>\n<div class=\"tbl\"><table><thead><tr><th>Méthode</th><th>Principe</th></tr></thead><tbody>\n<tr><td>Aléatoire simple</td><td>Chaque individu a la même chance d'être tiré (tirage au sort sur la liste des matricules)</td></tr>\n<tr><td>Systématique</td><td>On tire un individu tous les k de la liste (1 sur 10)</td></tr>\n<tr><td>Stratifié</td><td>On découpe la population en strates (services) puis on tire au hasard dans chaque strate</td></tr>\n<tr><td>Par quotas</td><td>On fixe la composition de l'échantillon (40 % de femmes, 20 % de cadres) et on choisit les répondants pour l'atteindre</td></tr>\n<tr><td>De convenance</td><td>On interroge les personnes disponibles (rapide mais biaisé)</td></tr></tbody></table></div>\n<h3>La taille de l'échantillon et la marge d'erreur</h3>\n<p>Plus l'échantillon est grand, plus la marge d'erreur est faible. Pour un échantillon aléatoire et une proportion proche de 50 %, la marge d'erreur à 95 % est d'environ <strong>1 / √n</strong>.</p>\n<div class=\"callout\"><b>Exemples</b>n = 100 : marge ≈ 10 points. n = 400 : marge ≈ 5 points. n = 1 000 : marge ≈ 3 points. Pour diviser la marge par 2, il faut multiplier l'échantillon par 4.</div>\n<h3>Les biais d'échantillonnage</h3>\n<ul><li><strong>Biais de sélection</strong> : certains groupes n'ont pas pu être tirés.</li><li><strong>Biais de non-réponse</strong> : ceux qui répondent diffèrent de ceux qui ne répondent pas (les plus mécontents, ou les plus impliqués).</li></ul>\n<h3>Le redressement</h3>\n<p>Si un groupe est sous-représenté parmi les répondants, on peut pondérer ses réponses pour retrouver la structure de la population.</p>","quiz":[{"q":"Un échantillon représentatif…","o":["Reproduit les caractéristiques de la population","Est toujours très grand","Ne contient que des volontaires"],"a":0,"e":"Définition."},{"q":"Tirage au sort sur la liste des matricules : méthode…","o":["Aléatoire simple","Par quotas","De convenance"],"a":0,"e":"Même chance pour tous."},{"q":"Tirer 1 personne sur 10 dans la liste : méthode…","o":["Systématique","Stratifiée","Par quotas"],"a":0,"e":"Pas fixe."},{"q":"Tirer au hasard dans chaque service : méthode…","o":["Stratifiée","Aléatoire simple","De convenance"],"a":0,"e":"Par strates."},{"q":"Fixer 40 % de femmes dans l'échantillon : méthode…","o":["Par quotas","Aléatoire simple","Systématique"],"a":0,"e":"Composition imposée."},{"q":"Interroger les personnes disponibles : méthode…","o":["De convenance","Stratifiée","Aléatoire"],"a":0,"e":"Rapide mais biaisé."},{"q":"La méthode la plus biaisée est…","o":["De convenance","Aléatoire simple","Stratifiée"],"a":0,"e":"Non représentative."},{"q":"Marge d'erreur approximative à 95 % ?","o":["1 / √n","n / 100","√n"],"a":0,"e":"Formule simplifiée."},{"q":"n = 100 : marge ≈ ?","o":["10 points","5 points","1 point"],"a":0,"e":"1 / 10."},{"q":"n = 400 : marge ≈ ?","o":["5 points","10 points","2 points"],"a":0,"e":"1 / 20."},{"q":"n = 1 000 : marge ≈ ?","o":["3 points","10 points","0,1 point"],"a":0,"e":"1 / 31,6."},{"q":"Pour diviser la marge par 2, on multiplie l'échantillon par…","o":["4","2","10"],"a":0,"e":"Racine carrée."},{"q":"n = 2 500 : marge ≈ ?","o":["2 points","5 points","25 points"],"a":0,"e":"1 / 50."},{"q":"Plus l'échantillon est grand, la marge…","o":["Diminue","Augmente","Ne change pas"],"a":0,"e":"Précision."},{"q":"Le biais de non-réponse vient de…","o":["Différences entre répondants et non-répondants","Trop de réponses","Le logiciel"],"a":0,"e":"Définition."},{"q":"Le biais de sélection vient de…","o":["Groupes exclus du tirage","Trop de questions","La couleur du questionnaire"],"a":0,"e":"Accès inégal."},{"q":"Le redressement consiste à…","o":["Pondérer les réponses","Supprimer des réponses","Inventer des réponses"],"a":0,"e":"Correction."},{"q":"Un groupe sous-représenté parmi les répondants peut être…","o":["Pondéré","Ignoré","Doublé au hasard"],"a":0,"e":"Redressement."},{"q":"La méthode stratifiée garantit…","o":["La présence de chaque strate","L'absence de biais totale","Un échantillon minuscule"],"a":0,"e":"Représentation."},{"q":"Qui répond souvent le plus spontanément ?","o":["Les plus mécontents ou les plus impliqués","Un groupe représentatif","Personne"],"a":0,"e":"Biais de non-réponse."}]},{"id":"mrh306-5","n":5,"t":"Rédiger un questionnaire","min":25,"html":"<h3>Les types de questions</h3>\n<div class=\"tbl\"><table><thead><tr><th>Type</th><th>Exemple</th><th>Avantage</th></tr></thead><tbody>\n<tr><td>Fermée dichotomique</td><td>Avez-vous suivi une formation cette année ? Oui / Non</td><td>Simple à traiter</td></tr>\n<tr><td>Fermée à choix multiples</td><td>Quels avantages utilisez-vous ? (plusieurs réponses)</td><td>Rapide</td></tr>\n<tr><td>Échelle de Likert</td><td>« Mon manager reconnaît mon travail » : de 1 (pas du tout d'accord) à 5 (tout à fait d'accord)</td><td>Mesure une intensité</td></tr>\n<tr><td>Question de classement</td><td>Classez ces 5 critères par importance</td><td>Priorisation</td></tr>\n<tr><td>Ouverte</td><td>Que faudrait-il améliorer en priorité ?</td><td>Idées, nuances</td></tr></tbody></table></div>\n<h3>Les règles de rédaction</h3>\n<ul><li>Une seule idée par question (pas de question « double »).</li><li>Vocabulaire simple, sans jargon.</li><li>Pas de question orientée (« Ne pensez-vous pas que… »).</li><li>Pas de double négation.</li><li>Des modalités de réponse exhaustives et exclusives.</li></ul>\n<div class=\"callout\"><b>Question double à éviter</b>« Êtes-vous satisfait de votre salaire et de vos horaires ? » : si la réponse est non, on ne sait pas sur quoi. Il faut deux questions.</div>\n<h3>La structure</h3>\n<ol><li>Introduction : objectif, durée, anonymat.</li><li>Questions simples et générales.</li><li>Questions plus précises ou sensibles.</li><li>Données signalétiques (service, ancienneté) à la fin.</li><li>Remerciements.</li></ol>\n<h3>La durée</h3>\n<p>Visez 10 à 15 minutes au maximum. Au-delà, les abandons augmentent et la qualité des réponses baisse.</p>","quiz":[{"q":"Une question Oui / Non est…","o":["Fermée dichotomique","Ouverte","Likert"],"a":0,"e":"Deux modalités."},{"q":"Une échelle de 1 à 5 d'accord est…","o":["Une échelle de Likert","Une question ouverte","Un classement"],"a":0,"e":"Mesure d'intensité."},{"q":"Avantage de la question ouverte ?","o":["Recueillir idées et nuances","Traitement très rapide","Aucun"],"a":0,"e":"Richesse."},{"q":"Classer 5 critères par importance est…","o":["Une question de classement","Une dichotomique","Une ouverte"],"a":0,"e":"Priorisation."},{"q":"Combien d'idées par question ?","o":["Une seule","Deux","Autant que possible"],"a":0,"e":"Règle."},{"q":"« Salaire et horaires » dans une même question est…","o":["Une question double","Une bonne pratique","Une Likert"],"a":0,"e":"À éviter."},{"q":"« Ne pensez-vous pas que… » est…","o":["Une question orientée","Neutre","Recommandée"],"a":0,"e":"Influence la réponse."},{"q":"Les modalités de réponse doivent être…","o":["Exhaustives et exclusives","Vagues","Répétées"],"a":0,"e":"Toutes les options, sans chevauchement."},{"q":"Où placer les données signalétiques ?","o":["À la fin","Au début","Au milieu"],"a":0,"e":"Moins intrusif."},{"q":"L'introduction précise…","o":["Objectif, durée, anonymat","Le salaire du DG","Les sanctions"],"a":0,"e":"Mise en confiance."},{"q":"Durée maximale recommandée ?","o":["10 à 15 minutes","1 heure","2 minutes toujours"],"a":0,"e":"Éviter les abandons."},{"q":"Un questionnaire trop long entraîne…","o":["Plus d'abandons","Plus de réponses","Aucun effet"],"a":0,"e":"Lassitude."},{"q":"Les questions sensibles viennent…","o":["Après les questions simples","En premier","Jamais"],"a":0,"e":"Progressivité."},{"q":"Éviter le jargon sert à…","o":["Être compris de tous","Paraître expert","Raccourcir"],"a":0,"e":"Clarté."},{"q":"La double négation…","o":["Est à éviter","Est recommandée","Est obligatoire"],"a":0,"e":"Confusion."},{"q":"« Quels avantages utilisez-vous ? (plusieurs réponses) » est…","o":["Fermée à choix multiples","Ouverte","Likert"],"a":0,"e":"Plusieurs cases."},{"q":"Une échelle de Likert mesure…","o":["Un degré d'accord","Un salaire","Une date"],"a":0,"e":"Intensité."},{"q":"On termine un questionnaire par…","o":["Des remerciements","Une menace","Une question sur le salaire du voisin"],"a":0,"e":"Politesse."},{"q":"Une question fermée est…","o":["Simple à traiter statistiquement","Impossible à coder","Toujours ouverte"],"a":0,"e":"Standardisée."},{"q":"Si « non » à une question double, on ne sait pas…","o":["Sur quel élément porte le non","Qui a répondu","La date"],"a":0,"e":"Ambiguïté."}]},{"id":"mrh306-6","n":6,"t":"Collecter les données","min":20,"html":"<h3>Les modes d'administration</h3>\n<div class=\"tbl\"><table><thead><tr><th>Mode</th><th>Avantages</th><th>Limites</th></tr></thead><tbody>\n<tr><td>En ligne (formulaire web)</td><td>Rapide, peu coûteux, traitement automatique</td><td>Exclut ceux sans accès numérique</td></tr>\n<tr><td>Papier</td><td>Accessible à tous</td><td>Saisie manuelle, risque d'erreurs</td></tr>\n<tr><td>Face à face</td><td>Bon taux de réponse, questions expliquées</td><td>Coûteux, influence de l'enquêteur</td></tr>\n<tr><td>Téléphone</td><td>Rapide pour des sites éloignés</td><td>Questionnaires courts seulement</td></tr></tbody></table></div>\n<p>Dans une entreprise avec des ateliers et des bureaux, on combine souvent le formulaire en ligne et le papier.</p>\n<h3>Le taux de réponse</h3>\n<p>Taux de réponse = questionnaires exploitables / questionnaires diffusés × 100. Pour l'améliorer : soutien affiché de la direction, garantie d'anonymat, temps dédié pendant les heures de travail, relances, promesse de restitution.</p>\n<div class=\"callout\"><b>Exemple</b>350 questionnaires diffusés, 245 exploitables : taux de réponse = 70 %.</div>\n<h3>L'anonymat et la protection des données</h3>\n<ul><li>Ne pas demander le nom ni le matricule.</li><li>Ne pas publier de résultats sur moins de 5 répondants.</li><li>Limiter les questions signalétiques trop précises (âge exact + service de 3 personnes = identification).</li><li>Respecter la loi ivoirienne n° 2013-450 sur les données personnelles : finalité claire, conservation limitée, sécurité.</li></ul>\n<h3>Le suivi de la collecte</h3>\n<p>Suivez le taux de réponse par service chaque jour et relancez les services en retard via les managers.</p>","quiz":[{"q":"Avantage de l'enquête en ligne ?","o":["Rapide et peu coûteuse","Accessible sans outil numérique","Saisie manuelle"],"a":0,"e":"Efficacité."},{"q":"Limite de l'enquête en ligne ?","o":["Exclut ceux sans accès numérique","Trop lente","Trop chère"],"a":0,"e":"Fracture numérique."},{"q":"Limite du questionnaire papier ?","o":["Saisie manuelle et erreurs","Inaccessible","Trop rapide"],"a":0,"e":"Traitement."},{"q":"Avantage du face à face ?","o":["Bon taux de réponse","Aucun coût","Anonymat total"],"a":0,"e":"Présence."},{"q":"Limite du face à face ?","o":["Influence de l'enquêteur","Taux de réponse faible","Aucune"],"a":0,"e":"Biais."},{"q":"Le téléphone convient à…","o":["Des questionnaires courts","Des questionnaires de 50 pages","Rien"],"a":0,"e":"Contrainte."},{"q":"Pour une entreprise avec ateliers et bureaux, on…","o":["Combine en ligne et papier","Utilise seulement l'e-mail","N'enquête pas"],"a":0,"e":"Accessibilité."},{"q":"Taux de réponse =","o":["Exploitables / diffusés × 100","Diffusés / exploitables","Réponses × 100"],"a":0,"e":"Formule."},{"q":"350 diffusés, 245 exploitables : taux ?","o":["70 %","245 %","35 %"],"a":0,"e":"245 / 350."},{"q":"200 diffusés, 150 exploitables : taux ?","o":["75 %","50 %","150 %"],"a":0,"e":"150 / 200."},{"q":"Un levier du taux de réponse est…","o":["La garantie d'anonymat","La menace","La complexité"],"a":0,"e":"Confiance."},{"q":"Accorder du temps pendant les heures de travail…","o":["Augmente les réponses","Diminue les réponses","N'a aucun effet"],"a":0,"e":"Facilitation."},{"q":"Faut-il demander le matricule dans une enquête anonyme ?","o":["Non","Oui","Seulement pour les cadres"],"a":0,"e":"Anonymat."},{"q":"Seuil minimal de répondants pour publier un résultat ?","o":["5","1","50"],"a":0,"e":"Protection."},{"q":"Âge exact + service de 3 personnes permet…","o":["L'identification","L'anonymat","La représentativité"],"a":0,"e":"Risque."},{"q":"La loi ivoirienne sur les données personnelles date de…","o":["2013","1995","2020"],"a":0,"e":"Loi n° 2013-450."},{"q":"Cette loi exige notamment…","o":["Une finalité claire","Une conservation illimitée","La publication des noms"],"a":0,"e":"Principe."},{"q":"Le suivi quotidien de la collecte se fait par…","o":["Taux de réponse par service","Salaire","Chiffre d'affaires"],"a":0,"e":"Pilotage."},{"q":"Qui relance les services en retard ?","o":["Les managers","Les clients","La CNPS"],"a":0,"e":"Relais."},{"q":"La promesse de restitution des résultats…","o":["Encourage la participation","Décourage","Est interdite"],"a":0,"e":"Motivation."}]},{"id":"mrh306-7","n":7,"t":"Nettoyer et organiser les données","min":20,"html":"<p>Avant d'analyser, il faut nettoyer : des données sales produisent des conclusions fausses.</p>\n<h3>Les problèmes fréquents</h3>\n<div class=\"tbl\"><table><thead><tr><th>Problème</th><th>Exemple</th><th>Traitement</th></tr></thead><tbody>\n<tr><td>Doublons</td><td>Le même répondant deux fois</td><td>Supprimer le doublon</td></tr>\n<tr><td>Valeurs manquantes</td><td>Question non renseignée</td><td>Exclure de l'analyse de cette question ou signaler</td></tr>\n<tr><td>Valeurs aberrantes</td><td>Âge = 250</td><td>Corriger si possible, sinon exclure</td></tr>\n<tr><td>Formats incohérents</td><td>« RH », « Ress. Humaines », « rh »</td><td>Harmoniser les libellés</td></tr>\n<tr><td>Dates en texte</td><td>« 12 mars 2020 » au lieu d'une date</td><td>Convertir au format date</td></tr></tbody></table></div>\n<h3>Le codage</h3>\n<p>On transforme les réponses en codes numériques pour les traiter : Oui = 1, Non = 0 ; Likert de 1 à 5. Les réponses ouvertes sont regroupées en <strong>thèmes</strong> (analyse de contenu) puis comptées.</p>\n<h3>Le tableau de données</h3>\n<ul><li>Une ligne = un répondant (ou un salarié).</li><li>Une colonne = une variable.</li><li>Une seule ligne d'en-tête, sans cellules fusionnées.</li><li>Un dictionnaire des variables : nom, question, codes possibles.</li></ul>\n<h3>Traçabilité</h3>\n<p>Conservez le fichier brut intact et travaillez sur une copie. Notez chaque opération de nettoyage pour pouvoir la refaire ou la justifier.</p>","quiz":[{"q":"Pourquoi nettoyer les données ?","o":["Des données sales donnent des conclusions fausses","Pour les rendre jolies","C'est inutile"],"a":0,"e":"Fiabilité."},{"q":"Le même répondant présent deux fois est…","o":["Un doublon","Une valeur manquante","Une valeur aberrante"],"a":0,"e":"Problème."},{"q":"Âge = 250 est…","o":["Une valeur aberrante","Un doublon","Un format"],"a":0,"e":"Impossible."},{"q":"« RH », « rh », « Ress. Humaines » posent un problème de…","o":["Format incohérent","Doublon","Valeur manquante"],"a":0,"e":"Libellés."},{"q":"Traitement des libellés incohérents ?","o":["Harmoniser","Supprimer la colonne","Ignorer"],"a":0,"e":"Uniformiser."},{"q":"Une question non renseignée est…","o":["Une valeur manquante","Une valeur aberrante","Un doublon"],"a":0,"e":"Vide."},{"q":"Codage : Oui = ?","o":["1","0","5"],"a":0,"e":"Convention."},{"q":"Codage : Non = ?","o":["0","1","2"],"a":0,"e":"Convention."},{"q":"Les réponses ouvertes sont regroupées en…","o":["Thèmes","Salaires","Dates"],"a":0,"e":"Analyse de contenu."},{"q":"Dans le tableau, une ligne correspond à…","o":["Un répondant","Une question","Un service"],"a":0,"e":"Individu."},{"q":"Une colonne correspond à…","o":["Une variable","Un répondant","Une date unique"],"a":0,"e":"Caractéristique."},{"q":"Les cellules fusionnées sont…","o":["À éviter","Recommandées","Obligatoires"],"a":0,"e":"Gênent le traitement."},{"q":"Le dictionnaire des variables contient…","o":["Nom, question, codes","Les salaires","Les noms des répondants"],"a":0,"e":"Documentation."},{"q":"Le fichier brut doit être…","o":["Conservé intact","Écrasé","Supprimé"],"a":0,"e":"Traçabilité."},{"q":"On travaille sur…","o":["Une copie","L'original","Un papier"],"a":0,"e":"Sécurité."},{"q":"Noter chaque opération de nettoyage permet…","o":["De la refaire ou la justifier","De perdre du temps","De cacher"],"a":0,"e":"Reproductibilité."},{"q":"Une date saisie en texte doit être…","o":["Convertie au format date","Laissée telle quelle","Supprimée"],"a":0,"e":"Calculs possibles."},{"q":"Une valeur aberrante non corrigeable est…","o":["Exclue","Gardée telle quelle","Doublée"],"a":0,"e":"Traitement."},{"q":"Une échelle de Likert est codée…","o":["De 1 à 5","En lettres","En couleurs"],"a":0,"e":"Numérique."},{"q":"Combien de lignes d'en-tête ?","o":["Une seule","Trois","Aucune"],"a":0,"e":"Structure propre."}]},{"id":"mrh306-8","n":8,"t":"Statistiques descriptives","min":30,"html":"<h3>Les indicateurs de tendance centrale</h3>\n<ul><li><strong>Moyenne</strong> : somme des valeurs / nombre de valeurs.</li><li><strong>Médiane</strong> : valeur qui partage la série ordonnée en deux moitiés.</li><li><strong>Mode</strong> : valeur la plus fréquente.</li></ul>\n<div class=\"callout\"><b>Exemple</b>Salaires (en milliers de FCFA) : 150, 160, 180, 200, 1 200. Moyenne = 1 890 / 5 = 378. Médiane = 180. La moyenne est tirée vers le haut par le salaire de 1 200 : la médiane représente mieux le salarié « typique ».</div>\n<h3>Les indicateurs de dispersion</h3>\n<ul><li><strong>Étendue</strong> : maximum − minimum.</li><li><strong>Écart-type</strong> : dispersion moyenne autour de la moyenne. Plus il est grand, plus les valeurs sont éparpillées.</li><li><strong>Quartiles</strong> : Q1 (25 % des valeurs en dessous), Q2 = médiane, Q3 (75 % en dessous). L'écart interquartile = Q3 − Q1.</li></ul>\n<h3>Les pourcentages</h3>\n<p>Pour une question fermée, on calcule la répartition des réponses. Pour une échelle de Likert, on présente souvent le <strong>taux de satisfaction</strong> = pourcentage de réponses 4 et 5.</p>\n<h3>Le tableau croisé</h3>\n<p>Il croise deux variables (satisfaction × service) pour comparer des groupes. Attention aux effectifs faibles dans certaines cases.</p>\n<h3>Les ratios d'écart</h3>\n<p>Écart salarial hommes-femmes = (salaire moyen des hommes − salaire moyen des femmes) / salaire moyen des hommes × 100.</p>","quiz":[{"q":"La moyenne se calcule…","o":["Somme / nombre de valeurs","Valeur du milieu","Valeur la plus fréquente"],"a":0,"e":"Définition."},{"q":"La médiane est…","o":["La valeur qui partage la série en deux","La somme","Le maximum"],"a":0,"e":"Milieu."},{"q":"Le mode est…","o":["La valeur la plus fréquente","La moyenne","L'étendue"],"a":0,"e":"Fréquence."},{"q":"Moyenne de 150, 160, 180, 200, 1 200 ?","o":["378","180","1 200"],"a":0,"e":"1 890 / 5."},{"q":"Médiane de 150, 160, 180, 200, 1 200 ?","o":["180","378","160"],"a":0,"e":"Valeur centrale."},{"q":"Quand une valeur extrême existe, on préfère…","o":["La médiane","La moyenne","Le maximum"],"a":0,"e":"Robustesse."},{"q":"Étendue de 150 à 1 200 ?","o":["1 050","1 350","180"],"a":0,"e":"1 200 − 150."},{"q":"Un écart-type élevé signifie…","o":["Des valeurs éparpillées","Des valeurs identiques","Une erreur"],"a":0,"e":"Dispersion."},{"q":"Q1 est la valeur sous laquelle se trouvent…","o":["25 % des valeurs","50 %","75 %"],"a":0,"e":"Premier quartile."},{"q":"Q2 est…","o":["La médiane","Le maximum","La moyenne"],"a":0,"e":"Deuxième quartile."},{"q":"Q3 est la valeur sous laquelle se trouvent…","o":["75 % des valeurs","25 %","100 %"],"a":0,"e":"Troisième quartile."},{"q":"Écart interquartile =","o":["Q3 − Q1","Q2 − Q1","Max − Min"],"a":0,"e":"Dispersion centrale."},{"q":"Taux de satisfaction sur Likert 1-5 =","o":["% de réponses 4 et 5","% de réponses 3","Moyenne × 10"],"a":0,"e":"Convention."},{"q":"Sur 200 réponses, 120 notes 4 ou 5 : taux de satisfaction ?","o":["60 %","40 %","120 %"],"a":0,"e":"120 / 200."},{"q":"Un tableau croisé compare…","o":["Deux variables","Une seule valeur","Des impôts"],"a":0,"e":"Croisement."},{"q":"Risque d'un tableau croisé ?","o":["Effectifs faibles dans certaines cases","Trop de précision","Aucun"],"a":0,"e":"Fiabilité."},{"q":"Moyenne de 2, 4, 6 ?","o":["4","6","12"],"a":0,"e":"12 / 3."},{"q":"Mode de 3, 3, 4, 5, 5, 5 ?","o":["5","3","4"],"a":0,"e":"Le plus fréquent."},{"q":"Hommes 500, femmes 450 : écart salarial ?","o":["10 %","5 %","50 %"],"a":0,"e":"(500 − 450) / 500."},{"q":"Médiane de 10, 20, 30, 40 ?","o":["25","20","30"],"a":0,"e":"(20 + 30) / 2."}]},{"id":"mrh306-9","n":9,"t":"Les indicateurs RH clés","min":25,"html":"<div class=\"tbl\"><table><thead><tr><th>Indicateur</th><th>Formule</th></tr></thead><tbody>\n<tr><td>Turnover</td><td>((entrées + sorties) / 2) / effectif moyen × 100</td></tr>\n<tr><td>Taux de départ volontaire</td><td>démissions / effectif moyen × 100</td></tr>\n<tr><td>Absentéisme</td><td>heures d'absence / heures théoriques × 100</td></tr>\n<tr><td>Ancienneté moyenne</td><td>somme des anciennetés / effectif</td></tr>\n<tr><td>Taux de féminisation</td><td>femmes / effectif × 100</td></tr>\n<tr><td>Coût moyen de recrutement</td><td>dépenses de recrutement / nombre de recrutements</td></tr>\n<tr><td>Taux de réussite des essais</td><td>essais confirmés / essais × 100</td></tr>\n<tr><td>Taux d'accès à la formation</td><td>salariés formés / effectif × 100</td></tr></tbody></table></div>\n<h3>L'eNPS</h3>\n<p>L'<em>employee Net Promoter Score</em> repose sur une question : « Recommanderiez-vous notre entreprise comme employeur à un proche ? », notée de 0 à 10.</p>\n<ul><li>9 et 10 : <strong>promoteurs</strong>.</li><li>7 et 8 : <strong>passifs</strong>.</li><li>0 à 6 : <strong>détracteurs</strong>.</li></ul>\n<p>eNPS = % de promoteurs − % de détracteurs. Il varie de −100 à +100.</p>\n<div class=\"callout\"><b>Exemple</b>200 répondants : 70 promoteurs (35 %), 80 passifs, 50 détracteurs (25 %). eNPS = 35 − 25 = <strong>+10</strong>.</div>\n<h3>Lire un indicateur</h3>\n<p>Un indicateur isolé ne dit rien : comparez-le dans le temps, entre services et à une référence (cible, secteur).</p>","quiz":[{"q":"Taux de départ volontaire =","o":["Démissions / effectif moyen × 100","Licenciements / effectif","Embauches / effectif"],"a":0,"e":"Départs choisis."},{"q":"15 démissions, effectif moyen 300 : taux ?","o":["5 %","15 %","20 %"],"a":0,"e":"15 / 300."},{"q":"Taux de féminisation =","o":["Femmes / effectif × 100","Hommes / femmes","Femmes cadres / cadres"],"a":0,"e":"Formule."},{"q":"120 femmes sur 400 : taux de féminisation ?","o":["30 %","12 %","40 %"],"a":0,"e":"120 / 400."},{"q":"Coût moyen de recrutement : 6 M pour 20 recrutements ?","o":["300 000","120 000","6 000 000"],"a":0,"e":"6 000 000 / 20."},{"q":"18 essais confirmés sur 20 : taux de réussite ?","o":["90 %","18 %","10 %"],"a":0,"e":"18 / 20."},{"q":"La question de l'eNPS porte sur…","o":["La recommandation de l'entreprise comme employeur","Le salaire","Le manager"],"a":0,"e":"Recommandation."},{"q":"Échelle de l'eNPS ?","o":["0 à 10","1 à 5","0 à 100"],"a":0,"e":"Notation."},{"q":"Un promoteur donne…","o":["9 ou 10","7 ou 8","0 à 6"],"a":0,"e":"Définition."},{"q":"Un passif donne…","o":["7 ou 8","9 ou 10","0 à 6"],"a":0,"e":"Définition."},{"q":"Un détracteur donne…","o":["0 à 6","7 ou 8","9 ou 10"],"a":0,"e":"Définition."},{"q":"eNPS =","o":["% promoteurs − % détracteurs","% passifs","Moyenne × 10"],"a":0,"e":"Formule."},{"q":"35 % promoteurs, 25 % détracteurs : eNPS ?","o":["+10","+60","−10"],"a":0,"e":"35 − 25."},{"q":"20 % promoteurs, 50 % détracteurs : eNPS ?","o":["−30","+30","+70"],"a":0,"e":"20 − 50."},{"q":"L'eNPS varie entre…","o":["−100 et +100","0 et 10","0 et 100"],"a":0,"e":"Bornes."},{"q":"Les passifs comptent-ils dans le calcul ?","o":["Non, seulement dans le total","Oui, ils s'ajoutent","Oui, ils se soustraient"],"a":0,"e":"Ils diluent les pourcentages."},{"q":"Un indicateur isolé…","o":["Ne dit rien sans comparaison","Suffit toujours","Est inutile"],"a":0,"e":"Contexte nécessaire."},{"q":"On compare un indicateur…","o":["Dans le temps, entre services, à une référence","À rien","Seulement aux concurrents"],"a":0,"e":"Axes de comparaison."},{"q":"Ancienneté moyenne : somme 1 200 ans pour 150 salariés ?","o":["8 ans","12 ans","15 ans"],"a":0,"e":"1 200 / 150."},{"q":"60 formés sur 240 : taux d'accès ?","o":["25 %","60 %","40 %"],"a":0,"e":"60 / 240."}]},{"id":"mrh306-10","n":10,"t":"Interpréter et restituer","min":25,"html":"<h3>Corrélation et causalité</h3>\n<p>Deux variables sont <strong>corrélées</strong> si elles varient ensemble. Cela ne prouve pas que l'une cause l'autre. Exemple : les services qui ont le plus de formation ont aussi le plus de départs ; la formation ne cause pas forcément les départs (peut-être ces services recrutent beaucoup de jeunes, plus mobiles). Il faut chercher les <strong>facteurs confondants</strong>.</p>\n<h3>Choisir le bon graphique</h3>\n<div class=\"tbl\"><table><thead><tr><th>Objectif</th><th>Graphique</th></tr></thead><tbody>\n<tr><td>Évolution dans le temps</td><td>Courbe</td></tr>\n<tr><td>Comparaison entre catégories</td><td>Barres</td></tr>\n<tr><td>Répartition d'un tout (peu de parts)</td><td>Barres empilées à 100 % (le camembert est à limiter)</td></tr>\n<tr><td>Relation entre deux variables</td><td>Nuage de points</td></tr>\n<tr><td>Pyramide des âges</td><td>Barres horizontales opposées</td></tr></tbody></table></div>\n<h3>Les règles d'un bon graphique</h3>\n<ul><li>Un titre qui dit le message (« Le turnover des commerciaux a doublé en 2 ans »).</li><li>Axes lisibles, unité indiquée, axe des barres commençant à zéro.</li><li>Pas d'effets 3D.</li><li>Mettre en valeur la donnée importante, griser le reste.</li></ul>\n<h3>Structurer la restitution</h3>\n<ol><li>Rappel de l'objectif et de la méthode (population, taux de réponse).</li><li>Trois à cinq messages clés.</li><li>Les chiffres qui les étayent.</li><li>Les limites (échantillon, biais).</li><li>Les recommandations et les prochaines étapes.</li></ol>\n<div class=\"callout\"><b>Restituer aux salariés</b>Partager les principaux résultats avec ceux qui ont répondu renforce la confiance et la participation future.</div>","quiz":[{"q":"Deux variables qui varient ensemble sont…","o":["Corrélées","Causales forcément","Indépendantes"],"a":0,"e":"Définition."},{"q":"Une corrélation prouve-t-elle une causalité ?","o":["Non","Oui","Toujours"],"a":0,"e":"Principe clé."},{"q":"Un facteur confondant est…","o":["Une variable cachée qui explique la corrélation","Une erreur de saisie","Un graphique"],"a":0,"e":"Définition."},{"q":"Pour une évolution dans le temps, on utilise…","o":["Une courbe","Un camembert","Un nuage de points"],"a":0,"e":"Temps continu."},{"q":"Pour comparer des catégories, on utilise…","o":["Des barres","Une courbe","Un tableau de 500 lignes"],"a":0,"e":"Comparaison."},{"q":"Pour une relation entre deux variables, on utilise…","o":["Un nuage de points","Un camembert","Une barre"],"a":0,"e":"Relation."},{"q":"La pyramide des âges se représente par…","o":["Des barres horizontales opposées","Une courbe","Un camembert"],"a":0,"e":"Convention."},{"q":"Le camembert est à…","o":["Limiter","Privilégier toujours","Utiliser en 3D"],"a":0,"e":"Lecture difficile."},{"q":"Un bon titre de graphique…","o":["Dit le message","Est vague","Est absent"],"a":0,"e":"Clarté."},{"q":"L'axe d'un graphique en barres doit commencer à…","o":["Zéro","La valeur minimale","N'importe où"],"a":0,"e":"Éviter les exagérations."},{"q":"Les effets 3D sont…","o":["À éviter","Recommandés","Obligatoires"],"a":0,"e":"Déforment."},{"q":"Mettre en valeur la donnée importante et…","o":["Griser le reste","Tout colorer","Tout supprimer"],"a":0,"e":"Focalisation."},{"q":"Combien de messages clés dans une restitution ?","o":["3 à 5","20","1 000"],"a":0,"e":"Mémorisable."},{"q":"La restitution rappelle d'abord…","o":["Objectif et méthode","Les recommandations","Les limites"],"a":0,"e":"Contexte."},{"q":"Pourquoi mentionner les limites ?","o":["Pour l'honnêteté de l'analyse","Pour se discréditer","C'est interdit"],"a":0,"e":"Rigueur."},{"q":"La restitution se termine par…","o":["Recommandations et prochaines étapes","Le taux de réponse","Les données brutes"],"a":0,"e":"Action."},{"q":"Partager les résultats avec les répondants…","o":["Renforce la confiance","Est inutile","Est interdit"],"a":0,"e":"Participation future."},{"q":"Plus de formation et plus de départs dans un service : conclusion correcte ?","o":["Chercher d'autres explications avant de conclure","La formation cause les départs","Supprimer la formation"],"a":0,"e":"Corrélation ≠ causalité."},{"q":"Le taux de réponse figure dans…","o":["La méthode","Les recommandations","Le titre"],"a":0,"e":"Qualité des données."},{"q":"L'unité doit figurer…","o":["Sur les axes","Nulle part","Dans les annexes seulement"],"a":0,"e":"Lisibilité."}]}]},{"id":"mrh307","code":"MRH 307","unit":"trad","title":"Management d'équipes et performance collective","summary":"Rôles et styles du manager, motivation, dynamique d'équipe, objectifs, délégation, feedback, réunions et management à distance.","lessons":[{"id":"mrh307-1","n":1,"t":"Les rôles du manager","min":20,"html":"<p>Le manager obtient des résultats avec et par une équipe. Il organise le travail, développe les personnes et fait le lien avec le reste de l'organisation.</p>\n<h3>Les fonctions selon Fayol</h3>\n<p>Henri Fayol (1916) décrit cinq fonctions administratives : <strong>prévoir, organiser, commander, coordonner, contrôler</strong>.</p>\n<h3>Les rôles selon Mintzberg</h3>\n<p>Henry Mintzberg (1973) a observé des dirigeants au travail et identifié dix rôles regroupés en trois familles.</p>\n<div class=\"tbl\"><table><thead><tr><th>Famille</th><th>Rôles</th></tr></thead><tbody>\n<tr><td>Interpersonnels</td><td>Symbole, leader, agent de liaison</td></tr>\n<tr><td>Informationnels</td><td>Observateur actif, diffuseur, porte-parole</td></tr>\n<tr><td>Décisionnels</td><td>Entrepreneur, régulateur (gestion des perturbations), répartiteur de ressources, négociateur</td></tr></tbody></table></div>\n<h3>Manager et leader</h3>\n<p>Le <strong>management</strong> organise, planifie et contrôle ; le <strong>leadership</strong> donne une direction, inspire et entraîne. Un bon manager combine les deux.</p>\n<h3>Le passage d'expert à manager</h3>\n<p>Un bon technicien promu manager doit changer de posture : passer de « faire » à « faire faire », accepter de déléguer et mesurer sa réussite à celle de son équipe.</p>","quiz":[{"q":"Qui a décrit les cinq fonctions « prévoir, organiser, commander, coordonner, contrôler » ?","o":["Henri Fayol","Henry Mintzberg","Abraham Maslow"],"a":0,"e":"1916."},{"q":"Combien de rôles décrit Mintzberg ?","o":["Dix","Cinq","Trois"],"a":0,"e":"En trois familles."},{"q":"Combien de familles de rôles chez Mintzberg ?","o":["Trois","Deux","Cinq"],"a":0,"e":"Interpersonnels, informationnels, décisionnels."},{"q":"Le rôle de leader est…","o":["Interpersonnel","Informationnel","Décisionnel"],"a":0,"e":"Famille."},{"q":"Le rôle de porte-parole est…","o":["Informationnel","Interpersonnel","Décisionnel"],"a":0,"e":"Communiquer vers l'extérieur."},{"q":"Le rôle de négociateur est…","o":["Décisionnel","Informationnel","Interpersonnel"],"a":0,"e":"Famille."},{"q":"Le répartiteur de ressources est un rôle…","o":["Décisionnel","Interpersonnel","Informationnel"],"a":0,"e":"Allocation."},{"q":"L'agent de liaison est un rôle…","o":["Interpersonnel","Décisionnel","Informationnel"],"a":0,"e":"Réseau."},{"q":"L'observateur actif est un rôle…","o":["Informationnel","Décisionnel","Interpersonnel"],"a":0,"e":"Collecte d'informations."},{"q":"Le régulateur gère…","o":["Les perturbations","Les salaires","Les ventes"],"a":0,"e":"Crises."},{"q":"Le management consiste surtout à…","o":["Organiser, planifier, contrôler","Inspirer uniquement","Vendre"],"a":0,"e":"Distinction."},{"q":"Le leadership consiste surtout à…","o":["Donner une direction et inspirer","Contrôler les heures","Calculer la paie"],"a":0,"e":"Distinction."},{"q":"Un bon manager…","o":["Combine management et leadership","Choisit l'un seulement","N'a besoin d'aucun"],"a":0,"e":"Complémentarité."},{"q":"Passer d'expert à manager, c'est passer de…","o":["Faire à faire faire","Faire faire à faire","Diriger à exécuter"],"a":0,"e":"Changement de posture."},{"q":"La réussite du manager se mesure à…","o":["Celle de son équipe","Son travail personnel seulement","Son ancienneté"],"a":0,"e":"Posture."},{"q":"Mintzberg a publié son étude en…","o":["1973","1916","2000"],"a":0,"e":"The Nature of Managerial Work."},{"q":"Le rôle de symbole consiste à…","o":["Représenter l'unité lors d'événements officiels","Calculer","Négocier"],"a":0,"e":"Rôle interpersonnel."},{"q":"Le diffuseur transmet l'information…","o":["À son équipe","Aux concurrents","À la presse uniquement"],"a":0,"e":"Rôle informationnel."},{"q":"L'entrepreneur lance…","o":["Des projets d'amélioration","Des grèves","Des impôts"],"a":0,"e":"Rôle décisionnel."},{"q":"Le manager obtient des résultats…","o":["Avec et par une équipe","Seul","Grâce aux clients seulement"],"a":0,"e":"Définition."}]},{"id":"mrh307-2","n":2,"t":"Les styles de leadership","min":20,"html":"<h3>Les travaux de Kurt Lewin</h3>\n<p>Dans les années 1930, Lewin compare trois styles de conduite de groupe.</p>\n<div class=\"tbl\"><table><thead><tr><th>Style</th><th>Caractéristiques</th><th>Effets observés</th></tr></thead><tbody>\n<tr><td>Autoritaire</td><td>Le leader décide seul et donne des ordres</td><td>Productivité élevée en sa présence, tensions, dépendance</td></tr>\n<tr><td>Démocratique</td><td>Le leader associe le groupe aux décisions</td><td>Bonne motivation, travail qui se poursuit en son absence</td></tr>\n<tr><td>Laisser-faire</td><td>Le leader intervient très peu</td><td>Désorganisation, faible productivité</td></tr></tbody></table></div>\n<h3>Les quatre systèmes de Likert</h3>\n<p>Rensis Likert distingue : autoritaire exploiteur, autoritaire paternaliste, consultatif et participatif. Il associe le système participatif aux meilleures performances durables.</p>\n<h3>Le leadership transformationnel</h3>\n<p>Le leader transformationnel partage une vision, stimule intellectuellement, considère chaque personne et donne l'exemple. Il s'oppose au leadership <strong>transactionnel</strong>, fondé sur l'échange récompense / performance.</p>\n<h3>Le leadership au service (servant leadership)</h3>\n<p>Le leader se met au service de l'équipe : il lève les obstacles, développe les personnes et sert la mission commune.</p>\n<div class=\"callout\"><b>À retenir</b>Aucun style n'est bon partout : le style efficace dépend de la situation, de l'équipe et de l'urgence.</div>","quiz":[{"q":"Qui a comparé les styles autoritaire, démocratique et laisser-faire ?","o":["Kurt Lewin","Fayol","Taylor"],"a":0,"e":"Années 1930."},{"q":"Dans le style autoritaire, le leader…","o":["Décide seul","Associe le groupe","N'intervient pas"],"a":0,"e":"Caractéristique."},{"q":"Effet du style autoritaire ?","o":["Dépendance et tensions","Autonomie totale","Désorganisation"],"a":0,"e":"Observation de Lewin."},{"q":"Dans le style démocratique, le leader…","o":["Associe le groupe aux décisions","Décide seul","Est absent"],"a":0,"e":"Participation."},{"q":"Effet du style démocratique ?","o":["Le travail se poursuit en l'absence du leader","Le travail s'arrête","Conflits permanents"],"a":0,"e":"Autonomie."},{"q":"Le laisser-faire produit…","o":["Désorganisation","Haute productivité","Discipline stricte"],"a":0,"e":"Observation."},{"q":"Combien de systèmes chez Rensis Likert ?","o":["Quatre","Trois","Cinq"],"a":0,"e":"Du plus autoritaire au participatif."},{"q":"Le système associé aux meilleures performances durables selon Likert ?","o":["Participatif","Autoritaire exploiteur","Paternaliste"],"a":0,"e":"Conclusion."},{"q":"Le leader transformationnel…","o":["Partage une vision","Échange uniquement récompense contre performance","N'intervient pas"],"a":0,"e":"Inspiration."},{"q":"Le leadership transactionnel repose sur…","o":["L'échange récompense / performance","La vision","Le service"],"a":0,"e":"Échange."},{"q":"Le leader au service…","o":["Lève les obstacles pour l'équipe","Commande seul","Ignore l'équipe"],"a":0,"e":"Servant leadership."},{"q":"Le style efficace dépend…","o":["De la situation","Toujours du même style","Du hasard"],"a":0,"e":"Contingence."},{"q":"Donner l'exemple est une caractéristique du leadership…","o":["Transformationnel","Laisser-faire","Exploiteur"],"a":0,"e":"Exemplarité."},{"q":"L'autoritaire paternaliste est un système de…","o":["Likert","Lewin","Mintzberg"],"a":0,"e":"Classification."},{"q":"En situation d'urgence, un style plus directif peut être…","o":["Adapté","Interdit","Toujours inefficace"],"a":0,"e":"Contingence."},{"q":"La stimulation intellectuelle relève du leadership…","o":["Transformationnel","Transactionnel","Laisser-faire"],"a":0,"e":"Composante."},{"q":"Considérer chaque personne individuellement relève du leadership…","o":["Transformationnel","Autoritaire","Laisser-faire"],"a":0,"e":"Considération individuelle."},{"q":"Le système consultatif demande l'avis…","o":["Avant de décider","Après avoir décidé","Jamais"],"a":0,"e":"Consultation."},{"q":"La productivité du groupe autoritaire est élevée surtout…","o":["En présence du leader","En son absence","Jamais"],"a":0,"e":"Dépendance."},{"q":"Développer les personnes est central dans…","o":["Le servant leadership","Le laisser-faire","L'autoritaire exploiteur"],"a":0,"e":"Service."}]},{"id":"mrh307-3","n":3,"t":"Le management situationnel","min":20,"html":"<p>Paul Hersey et Ken Blanchard proposent d'adapter le style du manager au niveau de <strong>développement</strong> du collaborateur sur une tâche donnée : sa <strong>compétence</strong> et son <strong>engagement</strong> (motivation, confiance).</p>\n<h3>Les quatre niveaux d'autonomie et les styles associés</h3>\n<div class=\"tbl\"><table><thead><tr><th>Niveau</th><th>Profil</th><th>Style</th><th>Comportement du manager</th></tr></thead><tbody>\n<tr><td>D1</td><td>Faible compétence, fort enthousiasme (débutant)</td><td>S1 Directif</td><td>Explique quoi, comment, quand ; contrôle de près</td></tr>\n<tr><td>D2</td><td>Compétence en progrès, motivation en baisse</td><td>S2 Persuasif (coaching)</td><td>Explique, encourage, écoute, décide encore</td></tr>\n<tr><td>D3</td><td>Compétence bonne, confiance variable</td><td>S3 Participatif</td><td>Écoute, soutient, décide avec le collaborateur</td></tr>\n<tr><td>D4</td><td>Compétent et engagé</td><td>S4 Délégatif</td><td>Confie la responsabilité, contrôle léger</td></tr></tbody></table></div>\n<h3>Les deux dimensions du comportement</h3>\n<p>Le <strong>comportement directif</strong> (organiser, fixer, contrôler) et le <strong>comportement de soutien</strong> (écouter, encourager, impliquer). S1 : directif fort, soutien faible. S2 : les deux forts. S3 : soutien fort, directif faible. S4 : les deux faibles.</p>\n<h3>Le niveau dépend de la tâche</h3>\n<p>Un même collaborateur peut être D4 sur la paie et D1 sur un nouveau logiciel. Le manager adapte donc son style tâche par tâche.</p>\n<div class=\"callout\"><b>Erreurs fréquentes</b>Déléguer à un débutant (abandon) ou diriger de près un expert (démotivation).</div>","quiz":[{"q":"Qui a proposé le management situationnel ?","o":["Hersey et Blanchard","Fisher et Ury","Thomas et Kilmann"],"a":0,"e":"Modèle classique."},{"q":"Le niveau de développement combine…","o":["Compétence et engagement","Âge et ancienneté","Salaire et diplôme"],"a":0,"e":"Deux dimensions."},{"q":"Profil D1 ?","o":["Faible compétence, fort enthousiasme","Compétent et engagé","Compétent mais peu confiant"],"a":0,"e":"Débutant."},{"q":"Style pour D1 ?","o":["Directif","Délégatif","Participatif"],"a":0,"e":"S1."},{"q":"Profil D2 ?","o":["Compétence en progrès, motivation en baisse","Expert","Débutant enthousiaste"],"a":0,"e":"Apprenant désillusionné."},{"q":"Style pour D2 ?","o":["Persuasif","Délégatif","Participatif"],"a":0,"e":"S2 coaching."},{"q":"Profil D3 ?","o":["Compétent, confiance variable","Débutant","Expert autonome"],"a":0,"e":"Définition."},{"q":"Style pour D3 ?","o":["Participatif","Directif","Persuasif"],"a":0,"e":"S3."},{"q":"Profil D4 ?","o":["Compétent et engagé","Débutant","Démotivé"],"a":0,"e":"Autonome."},{"q":"Style pour D4 ?","o":["Délégatif","Directif","Persuasif"],"a":0,"e":"S4."},{"q":"S1 combine…","o":["Directif fort, soutien faible","Les deux forts","Les deux faibles"],"a":0,"e":"Directif."},{"q":"S2 combine…","o":["Directif fort et soutien fort","Directif faible","Les deux faibles"],"a":0,"e":"Coaching."},{"q":"S3 combine…","o":["Soutien fort, directif faible","Directif fort","Les deux faibles"],"a":0,"e":"Participatif."},{"q":"S4 combine…","o":["Directif faible et soutien faible","Les deux forts","Directif fort"],"a":0,"e":"Délégation."},{"q":"Le comportement de soutien consiste à…","o":["Écouter et encourager","Contrôler de près","Fixer les délais"],"a":0,"e":"Dimension relationnelle."},{"q":"Le niveau de développement dépend…","o":["De la tâche","De la personne uniquement","De l'âge"],"a":0,"e":"Tâche par tâche."},{"q":"Déléguer à un débutant risque…","o":["L'abandon ou l'échec","La réussite garantie","Rien"],"a":0,"e":"Erreur."},{"q":"Diriger de près un expert risque…","o":["La démotivation","La motivation","L'augmentation de compétence"],"a":0,"e":"Erreur."},{"q":"Un collaborateur expert en paie découvre un logiciel : style sur le logiciel ?","o":["Directif","Délégatif","Aucun"],"a":0,"e":"Il est débutant sur cette tâche."},{"q":"Le style persuasif implique que le manager…","o":["Explique et décide encore","Décide avec le collaborateur","Laisse décider seul"],"a":0,"e":"S2."}]},{"id":"mrh307-4","n":4,"t":"Motiver son équipe","min":25,"html":"<h3>La pyramide de Maslow</h3>\n<p>Abraham Maslow (1943) hiérarchise cinq besoins : <strong>physiologiques</strong>, <strong>sécurité</strong>, <strong>appartenance</strong>, <strong>estime</strong>, <strong>accomplissement</strong>. Un besoin supérieur motive surtout quand les besoins de base sont satisfaits.</p>\n<div class=\"tbl\"><table><thead><tr><th>Besoin</th><th>Au travail</th></tr></thead><tbody>\n<tr><td>Physiologiques</td><td>Salaire suffisant, pauses, conditions correctes</td></tr>\n<tr><td>Sécurité</td><td>Contrat stable, sécurité au poste</td></tr>\n<tr><td>Appartenance</td><td>Esprit d'équipe, intégration</td></tr>\n<tr><td>Estime</td><td>Reconnaissance, titre, responsabilités</td></tr>\n<tr><td>Accomplissement</td><td>Projets stimulants, développement</td></tr></tbody></table></div>\n<h3>La théorie des attentes de Vroom</h3>\n<p>Victor Vroom : Motivation = <strong>Expectation × Instrumentalité × Valence</strong>.</p>\n<ul><li>Expectation : « Si je fais l'effort, j'atteindrai l'objectif. »</li><li>Instrumentalité : « Si j'atteins l'objectif, j'obtiendrai la récompense. »</li><li>Valence : « Cette récompense a de la valeur pour moi. »</li></ul>\n<p>Si l'un des trois facteurs est nul, la motivation est nulle.</p>\n<h3>Motivation intrinsèque et extrinsèque</h3>\n<p>Selon Deci et Ryan, la motivation <strong>intrinsèque</strong> vient de l'intérêt pour l'activité ; la motivation <strong>extrinsèque</strong> vient de récompenses ou de contraintes externes. La motivation intrinsèque est nourrie par trois besoins : <strong>autonomie</strong>, <strong>compétence</strong> et <strong>relations</strong>.</p>\n<h3>Les leviers du manager</h3>\n<p>Donner du sens, fixer des objectifs atteignables, reconnaître, laisser de l'autonomie, développer les compétences, créer un climat de confiance.</p>","quiz":[{"q":"Combien de niveaux compte la pyramide de Maslow ?","o":["Cinq","Trois","Sept"],"a":0,"e":"Hiérarchie des besoins."},{"q":"Le premier niveau de Maslow est…","o":["Physiologique","Accomplissement","Estime"],"a":0,"e":"Base."},{"q":"Le sommet de la pyramide est…","o":["L'accomplissement","La sécurité","L'appartenance"],"a":0,"e":"Réalisation de soi."},{"q":"Un contrat stable répond au besoin de…","o":["Sécurité","Estime","Accomplissement"],"a":0,"e":"Stabilité."},{"q":"L'esprit d'équipe répond au besoin…","o":["D'appartenance","Physiologique","De sécurité"],"a":0,"e":"Lien social."},{"q":"La reconnaissance répond au besoin…","o":["D'estime","Physiologique","De sécurité"],"a":0,"e":"Valorisation."},{"q":"Un projet stimulant répond au besoin…","o":["D'accomplissement","De sécurité","Physiologique"],"a":0,"e":"Développement."},{"q":"Maslow a publié sa théorie en…","o":["1943","1990","1916"],"a":0,"e":"Date."},{"q":"Formule de Vroom ?","o":["Expectation × Instrumentalité × Valence","E + I + V","E / I"],"a":0,"e":"Produit."},{"q":"L'expectation, c'est croire que…","o":["L'effort permet d'atteindre l'objectif","La récompense a de la valeur","Le salaire augmente"],"a":0,"e":"Premier facteur."},{"q":"L'instrumentalité, c'est croire que…","o":["L'objectif atteint mène à la récompense","L'effort mène à l'objectif","La récompense plaît"],"a":0,"e":"Deuxième facteur."},{"q":"La valence est…","o":["La valeur de la récompense pour la personne","La probabilité de réussite","Le salaire"],"a":0,"e":"Troisième facteur."},{"q":"Si la valence est nulle, la motivation est…","o":["Nulle","Maximale","Moyenne"],"a":0,"e":"Produit."},{"q":"La motivation intrinsèque vient…","o":["De l'intérêt pour l'activité","D'une prime","D'une sanction"],"a":0,"e":"Deci et Ryan."},{"q":"La motivation extrinsèque vient…","o":["De récompenses ou contraintes externes","De l'intérêt pour la tâche","Du plaisir"],"a":0,"e":"Définition."},{"q":"Les trois besoins de la motivation intrinsèque ?","o":["Autonomie, compétence, relations","Salaire, prime, congés","Sécurité, argent, statut"],"a":0,"e":"Théorie de l'autodétermination."},{"q":"Un objectif jugé impossible réduit…","o":["L'expectation","La valence","L'instrumentalité"],"a":0,"e":"Croyance en la réussite."},{"q":"Une prime promise mais jamais versée réduit…","o":["L'instrumentalité","L'expectation","La valence"],"a":0,"e":"Lien objectif-récompense."},{"q":"Un levier du manager est…","o":["Donner du sens","Menacer","Isoler"],"a":0,"e":"Motivation."},{"q":"Laisser de l'autonomie nourrit…","o":["La motivation intrinsèque","La peur","L'absentéisme"],"a":0,"e":"Besoin d'autonomie."}]},{"id":"mrh307-5","n":5,"t":"La dynamique d'équipe","min":20,"html":"<h3>Groupe et équipe</h3>\n<p>Un <strong>groupe</strong> est un ensemble de personnes ; une <strong>équipe</strong> partage un objectif commun, des règles et une interdépendance dans le travail.</p>\n<h3>Le modèle de Tuckman</h3>\n<div class=\"tbl\"><table><thead><tr><th>Phase</th><th>Ce qui se passe</th><th>Rôle du manager</th></tr></thead><tbody>\n<tr><td>Formation (forming)</td><td>Découverte, politesse, incertitude</td><td>Clarifier objectifs et rôles</td></tr>\n<tr><td>Tension (storming)</td><td>Conflits de rôles, rivalités</td><td>Arbitrer, écouter, poser les règles</td></tr>\n<tr><td>Normalisation (norming)</td><td>Règles communes, cohésion</td><td>Faciliter, renforcer la coopération</td></tr>\n<tr><td>Performance (performing)</td><td>Efficacité, autonomie</td><td>Déléguer, soutenir</td></tr>\n<tr><td>Dissolution (adjourning)</td><td>Fin du projet</td><td>Célébrer, capitaliser</td></tr></tbody></table></div>\n<h3>Les rôles de Belbin</h3>\n<p>Meredith Belbin identifie neuf rôles d'équipe, dont : le <strong>coordinateur</strong> (organise), le <strong>propulseur</strong> (pousse à l'action), le <strong>concepteur</strong> (idées nouvelles), le <strong>priseur</strong> (évalue avec objectivité), l'<strong>organisateur</strong> (transforme les idées en plans), le <strong>finisseur</strong> (soigne les détails), le <strong>soutien</strong> (harmonie), l'<strong>explorateur de ressources</strong> (contacts extérieurs), le <strong>spécialiste</strong> (expertise). Une équipe équilibrée réunit des rôles complémentaires.</p>\n<h3>La cohésion</h3>\n<p>Elle se construit par un objectif partagé, des réussites communes, la confiance et des rituels (réunion hebdomadaire, célébrations). Trop de cohésion peut produire la <strong>pensée de groupe</strong> : on évite de contredire pour préserver l'harmonie, au détriment de la qualité des décisions.</p>","quiz":[{"q":"Une équipe se distingue d'un groupe par…","o":["Un objectif commun et une interdépendance","Le nombre de personnes","Le lieu"],"a":0,"e":"Définition."},{"q":"Combien de phases dans le modèle de Tuckman (version complète) ?","o":["Cinq","Trois","Quatre"],"a":0,"e":"Avec la dissolution."},{"q":"Phase de découverte et de politesse ?","o":["Formation","Tension","Performance"],"a":0,"e":"Forming."},{"q":"Phase des conflits de rôles ?","o":["Tension","Normalisation","Dissolution"],"a":0,"e":"Storming."},{"q":"Phase des règles communes ?","o":["Normalisation","Formation","Tension"],"a":0,"e":"Norming."},{"q":"Phase d'efficacité et d'autonomie ?","o":["Performance","Tension","Formation"],"a":0,"e":"Performing."},{"q":"Rôle du manager en phase de formation ?","o":["Clarifier objectifs et rôles","Déléguer tout","Célébrer"],"a":0,"e":"Cadrage."},{"q":"Rôle du manager en phase de tension ?","o":["Arbitrer et poser les règles","Se retirer","Dissoudre"],"a":0,"e":"Régulation."},{"q":"Rôle du manager en phase de performance ?","o":["Déléguer et soutenir","Contrôler de près","Recruter"],"a":0,"e":"Autonomie."},{"q":"En fin de projet, le manager…","o":["Célèbre et capitalise","Sanctionne","Ignore"],"a":0,"e":"Dissolution."},{"q":"Combien de rôles d'équipe chez Belbin ?","o":["Neuf","Cinq","Douze"],"a":0,"e":"Modèle."},{"q":"Le concepteur apporte…","o":["Des idées nouvelles","Les détails finaux","Les contacts"],"a":0,"e":"Créativité."},{"q":"Le finisseur…","o":["Soigne les détails","Organise","Pousse à l'action"],"a":0,"e":"Qualité."},{"q":"Le propulseur…","o":["Pousse à l'action","Évalue","Apaise"],"a":0,"e":"Dynamisme."},{"q":"Le priseur…","o":["Évalue avec objectivité","Crée","Coordonne"],"a":0,"e":"Analyse."},{"q":"L'explorateur de ressources…","o":["Apporte des contacts extérieurs","Soigne les détails","Arbitre"],"a":0,"e":"Réseau."},{"q":"Une équipe équilibrée réunit…","o":["Des rôles complémentaires","Des profils identiques","Uniquement des experts"],"a":0,"e":"Diversité."},{"q":"La pensée de groupe est…","o":["Éviter de contredire pour préserver l'harmonie","Une bonne décision collective","Un conflit ouvert"],"a":0,"e":"Risque de trop de cohésion."},{"q":"La cohésion se construit par…","o":["Des réussites communes","L'isolement","La rivalité"],"a":0,"e":"Facteur."},{"q":"Un rituel d'équipe est par exemple…","o":["Une réunion hebdomadaire","Une sanction","Un licenciement"],"a":0,"e":"Habitude collective."}]},{"id":"mrh307-6","n":6,"t":"Fixer des objectifs et piloter la performance","min":25,"html":"<h3>Les objectifs SMART</h3>\n<p>Spécifique, Mesurable, Atteignable, Réaliste, Temporellement défini.</p>\n<div class=\"callout\"><b>Exemple</b>Vague : « Améliorer le service client ». SMART : « Répondre à 90 % des demandes clients en moins de 24 heures d'ici le 31 décembre. »</div>\n<h3>Les OKR</h3>\n<p>Les <em>Objectives and Key Results</em> associent un <strong>objectif</strong> qualitatif et inspirant à 2 à 5 <strong>résultats clés</strong> mesurables. Ils sont fixés par trimestre, partagés avec toute l'équipe, et volontairement ambitieux.</p>\n<h3>Les indicateurs de performance (KPI)</h3>\n<div class=\"tbl\"><table><thead><tr><th>Type</th><th>Exemple</th></tr></thead><tbody>\n<tr><td>Quantité</td><td>Nombre de dossiers traités</td></tr>\n<tr><td>Qualité</td><td>Taux d'erreurs, satisfaction client</td></tr>\n<tr><td>Délai</td><td>Temps moyen de traitement</td></tr>\n<tr><td>Coût</td><td>Coût par dossier</td></tr></tbody></table></div>\n<h3>La cascade des objectifs</h3>\n<p>Les objectifs de l'entreprise se déclinent en objectifs de service, puis d'équipe, puis individuels. Chacun voit ainsi sa contribution au résultat global.</p>\n<h3>Le suivi</h3>\n<p>Points réguliers (hebdomadaires ou mensuels), tableau de bord visuel, analyse des écarts et actions correctives. On célèbre les réussites et on analyse les échecs sans chercher de coupable.</p>\n<h3>Objectifs individuels et collectifs</h3>\n<p>Trop d'objectifs individuels peuvent créer de la compétition interne. Un équilibre avec des objectifs collectifs favorise l'entraide.</p>","quiz":[{"q":"Le « S » de SMART signifie…","o":["Spécifique","Simple","Stratégique"],"a":0,"e":"Précis."},{"q":"Le « T » de SMART signifie…","o":["Temporellement défini","Total","Technique"],"a":0,"e":"Échéance."},{"q":"« Améliorer le service client » est…","o":["Un objectif vague","SMART","Un KPI"],"a":0,"e":"Pas mesurable."},{"q":"OKR signifie…","o":["Objectives and Key Results","Organisation, Knowledge, Resources","Objectifs, Km, Revenus"],"a":0,"e":"Méthode."},{"q":"Combien de résultats clés par objectif OKR ?","o":["2 à 5","20","Un seul toujours"],"a":0,"e":"Recommandation."},{"q":"Périodicité habituelle des OKR ?","o":["Trimestrielle","Décennale","Quotidienne"],"a":0,"e":"Cycle court."},{"q":"Les OKR sont volontairement…","o":["Ambitieux","Faciles","Secrets"],"a":0,"e":"Dépassement."},{"q":"Le taux d'erreurs est un KPI de…","o":["Qualité","Quantité","Coût"],"a":0,"e":"Type."},{"q":"Le temps moyen de traitement est un KPI de…","o":["Délai","Qualité","Quantité"],"a":0,"e":"Type."},{"q":"Le nombre de dossiers traités est un KPI de…","o":["Quantité","Délai","Coût"],"a":0,"e":"Type."},{"q":"Le coût par dossier est un KPI de…","o":["Coût","Qualité","Délai"],"a":0,"e":"Type."},{"q":"La cascade des objectifs va…","o":["De l'entreprise vers l'individu","De l'individu vers l'entreprise","Du client vers le fournisseur"],"a":0,"e":"Déclinaison."},{"q":"La cascade permet à chacun de voir…","o":["Sa contribution au résultat global","Le salaire des autres","Les ventes des concurrents"],"a":0,"e":"Sens."},{"q":"Face à un échec, on…","o":["Analyse sans chercher de coupable","Sanctionne immédiatement","Cache"],"a":0,"e":"Culture d'apprentissage."},{"q":"Trop d'objectifs individuels peuvent créer…","o":["De la compétition interne","De l'entraide","De la cohésion"],"a":0,"e":"Risque."},{"q":"Les objectifs collectifs favorisent…","o":["L'entraide","La rivalité","L'isolement"],"a":0,"e":"Coopération."},{"q":"Un tableau de bord visuel sert au…","o":["Suivi","Recrutement","Licenciement"],"a":0,"e":"Pilotage."},{"q":"La satisfaction client est un KPI de…","o":["Qualité","Délai","Quantité"],"a":0,"e":"Type."},{"q":"« 90 % des demandes en moins de 24 h d'ici le 31 décembre » est…","o":["SMART","Vague","Un OKR sans mesure"],"a":0,"e":"Mesurable et daté."},{"q":"Le « M » de SMART signifie…","o":["Mesurable","Motivant","Minimal"],"a":0,"e":"Quantifiable."}]},{"id":"mrh307-7","n":7,"t":"Déléguer efficacement","min":20,"html":"<h3>Pourquoi déléguer ?</h3>\n<ul><li>Libérer du temps pour les tâches à forte valeur (pilotage, développement).</li><li>Développer les compétences et l'autonomie des collaborateurs.</li><li>Motiver en confiant des responsabilités.</li></ul>\n<h3>La matrice d'Eisenhower</h3>\n<div class=\"tbl\"><table><thead><tr><th></th><th>Urgent</th><th>Pas urgent</th></tr></thead><tbody>\n<tr><td>Important</td><td>Faire soi-même tout de suite</td><td>Planifier</td></tr>\n<tr><td>Pas important</td><td>Déléguer</td><td>Abandonner</td></tr></tbody></table></div>\n<h3>Ce qui ne se délègue pas</h3>\n<p>L'évaluation et la sanction de ses collaborateurs, les sujets confidentiels, les décisions stratégiques qui relèvent du manager.</p>\n<h3>Les étapes de la délégation</h3>\n<ol><li>Choisir la tâche et la bonne personne (compétence, disponibilité, motivation).</li><li>Expliquer l'objectif, le résultat attendu, les délais, les moyens et le niveau d'autonomie.</li><li>Vérifier la compréhension (faire reformuler).</li><li>Convenir des points de suivi.</li><li>Laisser faire, sans reprendre la main à la première difficulté.</li><li>Faire le bilan et reconnaître le travail.</li></ol>\n<h3>Déléguer n'est pas se décharger</h3>\n<p>Le manager reste <strong>responsable</strong> du résultat vis-à-vis de sa hiérarchie. Il délègue l'autorité nécessaire, pas sa responsabilité finale.</p>\n<div class=\"callout\"><b>Piège</b>La « délégation inversée » : le collaborateur remonte chaque problème au manager, qui finit par tout refaire. Demandez-lui de venir avec une proposition de solution.</div>","quiz":[{"q":"Un bénéfice de la délégation est…","o":["Développer les compétences des collaborateurs","Réduire les salaires","Éviter toute responsabilité"],"a":0,"e":"Développement."},{"q":"Dans la matrice d'Eisenhower, important et urgent :","o":["Faire soi-même tout de suite","Déléguer","Abandonner"],"a":0,"e":"Priorité."},{"q":"Important mais pas urgent :","o":["Planifier","Déléguer","Abandonner"],"a":0,"e":"Anticiper."},{"q":"Urgent mais pas important :","o":["Déléguer","Faire soi-même","Planifier"],"a":0,"e":"Délégation."},{"q":"Ni urgent ni important :","o":["Abandonner","Déléguer","Faire tout de suite"],"a":0,"e":"Élimination."},{"q":"Peut-on déléguer l'évaluation de ses collaborateurs ?","o":["Non","Oui","Toujours"],"a":0,"e":"Responsabilité managériale."},{"q":"Les sujets confidentiels se délèguent-ils ?","o":["Non","Oui","Toujours"],"a":0,"e":"Discrétion."},{"q":"Première étape de la délégation ?","o":["Choisir la tâche et la personne","Faire le bilan","Laisser faire"],"a":0,"e":"Point de départ."},{"q":"Pour vérifier la compréhension, on…","o":["Fait reformuler","Répète trois fois","Envoie un e-mail seulement"],"a":0,"e":"Contrôle."},{"q":"Après avoir délégué, le manager…","o":["Laisse faire et suit aux points convenus","Reprend la main à la première difficulté","Oublie"],"a":0,"e":"Confiance."},{"q":"À la fin, le manager…","o":["Fait le bilan et reconnaît le travail","Critique seulement","Ne dit rien"],"a":0,"e":"Reconnaissance."},{"q":"Qui reste responsable du résultat ?","o":["Le manager","Le collaborateur seul","Le client"],"a":0,"e":"Responsabilité finale."},{"q":"Le manager délègue…","o":["L'autorité nécessaire","Sa responsabilité finale","Son salaire"],"a":0,"e":"Principe."},{"q":"La délégation inversée, c'est quand…","o":["Le collaborateur remonte tout au manager","Le manager délègue trop","Le DG délègue au client"],"a":0,"e":"Piège."},{"q":"Remède à la délégation inversée ?","o":["Demander une proposition de solution","Tout refaire soi-même","Sanctionner"],"a":0,"e":"Responsabilisation."},{"q":"Il faut préciser le niveau…","o":["D'autonomie","De salaire","D'ancienneté"],"a":0,"e":"Cadre."},{"q":"Critère de choix de la personne ?","o":["Compétence, disponibilité, motivation","Âge","Amitié"],"a":0,"e":"Adéquation."},{"q":"Déléguer permet de libérer du temps pour…","o":["Les tâches à forte valeur","Plus de réunions inutiles","Les pauses"],"a":0,"e":"Priorités."},{"q":"Confier des responsabilités peut…","o":["Motiver","Démotiver toujours","N'avoir aucun effet"],"a":0,"e":"Reconnaissance."},{"q":"Les points de suivi sont convenus…","o":["À l'avance","Jamais","Seulement en cas d'échec"],"a":0,"e":"Cadre."}]},{"id":"mrh307-8","n":8,"t":"Feedback et reconnaissance","min":20,"html":"<h3>Pourquoi le feedback ?</h3>\n<p>Le feedback aide le collaborateur à savoir ce qu'il fait bien et ce qu'il peut améliorer. Il est plus efficace s'il est fréquent et proche de l'événement, plutôt que réservé à l'entretien annuel.</p>\n<h3>Le modèle SBI</h3>\n<ul><li><strong>Situation</strong> : où et quand.</li><li><strong>Behavior (comportement)</strong> : ce que la personne a fait, de façon observable.</li><li><strong>Impact</strong> : l'effet produit.</li></ul>\n<div class=\"callout\"><b>Exemple</b>« Lors de la réunion client de mardi (S), tu as présenté les chiffres avec un graphique clair (B) ; le client a validé la proposition sans demander de précision (I). »</div>\n<h3>Les règles du feedback correctif</h3>\n<ul><li>En privé, jamais en public.</li><li>Sur des faits, pas sur la personnalité (« tu as rendu le rapport avec 2 jours de retard » plutôt que « tu es désorganisé »).</li><li>Écouter le point de vue de la personne.</li><li>Se mettre d'accord sur une action d'amélioration.</li></ul>\n<h3>La reconnaissance</h3>\n<div class=\"tbl\"><table><thead><tr><th>Forme</th><th>Exemple</th></tr></thead><tbody>\n<tr><td>Reconnaissance du résultat</td><td>Féliciter pour un objectif atteint</td></tr>\n<tr><td>Reconnaissance de l'effort</td><td>Saluer l'investissement sur un dossier difficile</td></tr>\n<tr><td>Reconnaissance de la pratique</td><td>Valoriser une méthode de travail efficace</td></tr>\n<tr><td>Reconnaissance existentielle</td><td>Saluer, écouter, s'intéresser à la personne</td></tr></tbody></table></div>\n<p>La reconnaissance la plus efficace est sincère, précise et rapide. Elle ne coûte rien et agit fortement sur l'engagement.</p>","quiz":[{"q":"Le feedback est plus efficace s'il est…","o":["Fréquent et proche de l'événement","Annuel seulement","Anonyme"],"a":0,"e":"Réactivité."},{"q":"Le « S » de SBI signifie…","o":["Situation","Salaire","Sanction"],"a":0,"e":"Contexte."},{"q":"Le « B » de SBI signifie…","o":["Comportement (behavior)","Bilan","Bonus"],"a":0,"e":"Fait observable."},{"q":"Le « I » de SBI signifie…","o":["Impact","Idée","Incident"],"a":0,"e":"Effet."},{"q":"Un feedback correctif se donne…","o":["En privé","En public","Par affichage"],"a":0,"e":"Respect."},{"q":"« Tu es désorganisé » porte sur…","o":["La personnalité","Un fait","Un impact"],"a":0,"e":"À éviter."},{"q":"« Tu as rendu le rapport avec 2 jours de retard » porte sur…","o":["Un fait","La personnalité","Une émotion"],"a":0,"e":"Recommandé."},{"q":"Après un feedback correctif, on convient…","o":["D'une action d'amélioration","D'une sanction automatique","De rien"],"a":0,"e":"Progrès."},{"q":"Écouter le point de vue de la personne est…","o":["Une règle du feedback","Inutile","Interdit"],"a":0,"e":"Dialogue."},{"q":"Féliciter pour un objectif atteint est une reconnaissance…","o":["Du résultat","De l'effort","Existentielle"],"a":0,"e":"Type."},{"q":"Saluer l'investissement sur un dossier difficile : reconnaissance…","o":["De l'effort","Du résultat","De la pratique"],"a":0,"e":"Type."},{"q":"Valoriser une méthode de travail : reconnaissance…","o":["De la pratique","Existentielle","Du résultat"],"a":0,"e":"Type."},{"q":"Dire bonjour et s'intéresser à la personne : reconnaissance…","o":["Existentielle","Du résultat","De l'effort"],"a":0,"e":"Type."},{"q":"Une reconnaissance efficace est…","o":["Sincère, précise et rapide","Vague et tardive","Collective uniquement"],"a":0,"e":"Qualités."},{"q":"La reconnaissance agit fortement sur…","o":["L'engagement","Les impôts","Les stocks"],"a":0,"e":"Effet."},{"q":"La reconnaissance coûte…","o":["Peu ou rien","Très cher","Un salaire"],"a":0,"e":"Levier accessible."},{"q":"Dans l'exemple, « le client a validé la proposition » est…","o":["L'impact","La situation","Le comportement"],"a":0,"e":"Effet."},{"q":"Dans l'exemple, « lors de la réunion client de mardi » est…","o":["La situation","L'impact","Le comportement"],"a":0,"e":"Contexte."},{"q":"Réserver le feedback à l'entretien annuel est…","o":["Moins efficace","Recommandé","Obligatoire"],"a":0,"e":"Trop tardif."},{"q":"Le feedback positif sert à…","o":["Renforcer ce qui fonctionne","Rien","Critiquer"],"a":0,"e":"Renforcement."}]},{"id":"mrh307-9","n":9,"t":"Réunions efficaces et décision collective","min":20,"html":"<h3>Les types de réunion</h3>\n<div class=\"tbl\"><table><thead><tr><th>Type</th><th>Objectif</th></tr></thead><tbody>\n<tr><td>Information</td><td>Transmettre un message</td></tr>\n<tr><td>Résolution de problème</td><td>Analyser et trouver des solutions</td></tr>\n<tr><td>Décision</td><td>Choisir entre des options</td></tr>\n<tr><td>Créativité</td><td>Produire des idées (brainstorming)</td></tr>\n<tr><td>Suivi</td><td>Faire le point sur l'avancement</td></tr></tbody></table></div>\n<h3>Préparer</h3>\n<p>Définir l'objectif, inviter seulement les personnes utiles, envoyer l'ordre du jour avec la durée de chaque point, préparer les documents.</p>\n<h3>Animer</h3>\n<ul><li>Commencer et finir à l'heure.</li><li>Désigner un gardien du temps et un secrétaire.</li><li>Distribuer la parole, recadrer les digressions.</li><li>Reformuler et synthétiser régulièrement.</li></ul>\n<h3>Conclure</h3>\n<p>Un relevé de décisions : qui fait quoi, pour quand. Envoyé dans les 24 heures.</p>\n<h3>Les modes de décision</h3>\n<div class=\"tbl\"><table><thead><tr><th>Mode</th><th>Avantage</th><th>Limite</th></tr></thead><tbody>\n<tr><td>Décision du chef</td><td>Rapide</td><td>Faible adhésion</td></tr>\n<tr><td>Consultation puis décision</td><td>Rapide et éclairée</td><td>Frustration si l'avis n'est pas suivi</td></tr>\n<tr><td>Vote à la majorité</td><td>Simple</td><td>La minorité peut se désengager</td></tr>\n<tr><td>Consensus</td><td>Forte adhésion</td><td>Long</td></tr></tbody></table></div>\n<h3>Le brainstorming</h3>\n<p>Règles : quantité d'idées, pas de critique pendant la production, idées farfelues bienvenues, rebondir sur les idées des autres. L'évaluation vient après.</p>","quiz":[{"q":"Un brainstorming est une réunion de…","o":["Créativité","Information","Suivi"],"a":0,"e":"Production d'idées."},{"q":"Faire le point sur l'avancement : réunion de…","o":["Suivi","Créativité","Décision"],"a":0,"e":"Type."},{"q":"Qui inviter à une réunion ?","o":["Les personnes utiles","Tout le monde","Personne"],"a":0,"e":"Efficacité."},{"q":"L'ordre du jour indique…","o":["Les points et leur durée","Les salaires","Les absences"],"a":0,"e":"Préparation."},{"q":"Le gardien du temps veille…","o":["Au respect des horaires","Aux salaires","Aux congés"],"a":0,"e":"Rôle."},{"q":"Le secrétaire de séance…","o":["Note les décisions","Anime seul","Décide"],"a":0,"e":"Rôle."},{"q":"Recadrer une digression sert à…","o":["Rester sur l'objectif","Humilier","Allonger"],"a":0,"e":"Animation."},{"q":"Le relevé de décisions précise…","o":["Qui fait quoi, pour quand","Le menu","Les salaires"],"a":0,"e":"Conclusion."},{"q":"Délai d'envoi recommandé du relevé ?","o":["24 heures","Un mois","Jamais"],"a":0,"e":"Réactivité."},{"q":"Avantage de la décision du chef ?","o":["Rapidité","Forte adhésion","Consensus"],"a":0,"e":"Mode."},{"q":"Limite de la décision du chef ?","o":["Faible adhésion","Lenteur","Complexité"],"a":0,"e":"Mode."},{"q":"Avantage du consensus ?","o":["Forte adhésion","Rapidité","Simplicité"],"a":0,"e":"Mode."},{"q":"Limite du consensus ?","o":["Long","Faible adhésion","Autoritaire"],"a":0,"e":"Mode."},{"q":"Limite du vote à la majorité ?","o":["La minorité peut se désengager","Trop long","Impossible"],"a":0,"e":"Mode."},{"q":"Limite de la consultation puis décision ?","o":["Frustration si l'avis n'est pas suivi","Lenteur extrême","Pas de décision"],"a":0,"e":"Mode."},{"q":"Pendant un brainstorming, la critique est…","o":["Suspendue","Encouragée","Obligatoire"],"a":0,"e":"Règle."},{"q":"Dans un brainstorming, on vise…","o":["La quantité d'idées","Une seule idée parfaite","Le silence"],"a":0,"e":"Règle."},{"q":"Les idées farfelues sont…","o":["Bienvenues","Interdites","Sanctionnées"],"a":0,"e":"Créativité."},{"q":"L'évaluation des idées vient…","o":["Après la production","Pendant","Jamais"],"a":0,"e":"Séparation."},{"q":"Commencer et finir à l'heure montre…","o":["Le respect des participants","Une rigidité inutile","Rien"],"a":0,"e":"Discipline."}]},{"id":"mrh307-10","n":10,"t":"Intelligence collective et management à distance","min":20,"html":"<h3>L'intelligence collective</h3>\n<p>C'est la capacité d'un groupe à produire de meilleures solutions que ses membres pris isolément. Elle suppose la diversité des points de vue, la confiance, l'écoute et des méthodes d'animation.</p>\n<h3>La sécurité psychologique</h3>\n<p>Étudiée par Amy Edmondson, elle désigne la conviction partagée qu'on peut s'exprimer, poser une question ou reconnaître une erreur sans risque d'humiliation. Elle favorise l'apprentissage et la performance des équipes.</p>\n<h3>Quelques méthodes</h3>\n<ul><li><strong>Tour de table</strong> : chacun s'exprime à son tour.</li><li><strong>Méthode des six chapeaux</strong> (Edward de Bono) : on examine une question sous six angles (faits, émotions, risques, bénéfices, créativité, organisation).</li><li><strong>Retour d'expérience (RETEX)</strong> après un projet : ce qui a marché, ce qui n'a pas marché, ce qu'on refera.</li></ul>\n<h3>Manager à distance</h3>\n<div class=\"tbl\"><table><thead><tr><th>Défi</th><th>Réponse</th></tr></thead><tbody>\n<tr><td>Isolement</td><td>Points individuels réguliers, moments informels</td></tr>\n<tr><td>Communication</td><td>Règles d'usage des outils (messagerie, visio), temps de réponse</td></tr>\n<tr><td>Suivi du travail</td><td>Objectifs clairs, gestion par les résultats plutôt que par la présence</td></tr>\n<tr><td>Cohésion</td><td>Rituels d'équipe, rencontres physiques ponctuelles</td></tr>\n<tr><td>Équilibre de vie</td><td>Droit à la déconnexion, horaires respectés</td></tr></tbody></table></div>\n<h3>La confiance</h3>\n<p>À distance, le manager ne peut pas tout voir : il doit faire confiance et mesurer les résultats. Le contrôle permanent détruit la motivation.</p>","quiz":[{"q":"L'intelligence collective est…","o":["La capacité d'un groupe à produire de meilleures solutions","Le QI moyen","Un logiciel"],"a":0,"e":"Définition."},{"q":"Elle suppose…","o":["Diversité, confiance, écoute","Uniformité","Silence"],"a":0,"e":"Conditions."},{"q":"Qui a étudié la sécurité psychologique ?","o":["Amy Edmondson","Henri Fayol","Kurt Lewin"],"a":0,"e":"Recherche."},{"q":"La sécurité psychologique permet…","o":["De s'exprimer sans risque d'humiliation","De ne jamais travailler","D'éviter les objectifs"],"a":0,"e":"Définition."},{"q":"Elle favorise…","o":["L'apprentissage et la performance","Les erreurs cachées","La peur"],"a":0,"e":"Effet."},{"q":"Les six chapeaux sont une méthode de…","o":["Edward de Bono","Maslow","Belbin"],"a":0,"e":"Créativité."},{"q":"Les six chapeaux examinent une question…","o":["Sous six angles","Six fois de suite","Avec six personnes"],"a":0,"e":"Perspectives."},{"q":"Le RETEX intervient…","o":["Après un projet","Avant le recrutement","Pendant la paie"],"a":0,"e":"Retour d'expérience."},{"q":"Le RETEX analyse…","o":["Ce qui a marché et ce qui n'a pas marché","Les salaires","Les absences"],"a":0,"e":"Apprentissage."},{"q":"Réponse à l'isolement à distance ?","o":["Points individuels réguliers","Moins de contact","Contrôle permanent"],"a":0,"e":"Lien."},{"q":"À distance, on gère par…","o":["Les résultats","La présence","Le nombre de connexions"],"a":0,"e":"Principe."},{"q":"Le droit à la déconnexion répond à l'enjeu…","o":["D'équilibre de vie","De cohésion","De communication"],"a":0,"e":"Protection."},{"q":"Des rituels d'équipe répondent à l'enjeu…","o":["De cohésion","D'équilibre","De suivi"],"a":0,"e":"Lien collectif."},{"q":"Définir des règles d'usage des outils répond à l'enjeu…","o":["De communication","D'isolement","De rémunération"],"a":0,"e":"Organisation."},{"q":"Le contrôle permanent à distance…","o":["Détruit la motivation","Augmente la confiance","Est recommandé"],"a":0,"e":"Effet négatif."},{"q":"À distance, le manager doit…","o":["Faire confiance et mesurer les résultats","Tout surveiller","Ne rien suivre"],"a":0,"e":"Posture."},{"q":"Le tour de table permet…","o":["À chacun de s'exprimer","Au chef de parler seul","De voter"],"a":0,"e":"Équité de parole."},{"q":"Des rencontres physiques ponctuelles renforcent…","o":["La cohésion","L'isolement","Le turnover"],"a":0,"e":"Lien."},{"q":"Reconnaître une erreur sans crainte est possible grâce à…","o":["La sécurité psychologique","La sanction","Le contrôle"],"a":0,"e":"Climat."},{"q":"La diversité des points de vue…","o":["Enrichit les solutions","Nuit toujours","Est interdite"],"a":0,"e":"Intelligence collective."}]}]},{"id":"mrh308","code":"MRH 308","unit":"trad","title":"Initiation à la psychologie cognitive","summary":"Perception, attention, mémoire, apprentissage, raisonnement, décision, biais cognitifs, charge mentale et stress, appliqués aux pratiques RH.","lessons":[{"id":"mrh308-1","n":1,"t":"Qu'est-ce que la psychologie cognitive ?","min":20,"html":"<p>La psychologie cognitive étudie les processus mentaux qui nous permettent de connaître et d'agir : percevoir, faire attention, mémoriser, apprendre, raisonner, décider, parler.</p>\n<h3>Un peu d'histoire</h3>\n<ul><li><strong>Le béhaviorisme</strong> (Watson, Skinner), dominant dans la première moitié du XX<sup>e</sup> siècle, n'étudie que les comportements observables : stimulus → réponse.</li><li><strong>La révolution cognitive</strong> des années 1950-1960 s'intéresse à ce qui se passe « dans la tête ». Ulric Neisser publie <em>Cognitive Psychology</em> en 1967.</li></ul>\n<h3>Le modèle du traitement de l'information</h3>\n<p>L'esprit est comparé à un système qui reçoit des informations (entrée), les transforme et les stocke (traitement), puis produit une réponse (sortie). Nos capacités de traitement sont <strong>limitées</strong> : c'est une idée centrale.</p>\n<h3>Les méthodes</h3>\n<ul><li>Expériences en laboratoire (temps de réaction, taux d'erreurs).</li><li>Études de cas de patients atteints de lésions cérébrales.</li><li>Imagerie cérébrale (IRM fonctionnelle).</li><li>Modélisation informatique.</li></ul>\n<h3>Pourquoi l'étudier en RH ?</h3>\n<div class=\"tbl\"><table><thead><tr><th>Domaine RH</th><th>Apport</th></tr></thead><tbody>\n<tr><td>Formation</td><td>Concevoir des formations qui s'appuient sur le fonctionnement de la mémoire</td></tr>\n<tr><td>Recrutement</td><td>Réduire les biais de jugement</td></tr>\n<tr><td>Organisation du travail</td><td>Limiter la surcharge et les erreurs</td></tr>\n<tr><td>Communication</td><td>Rendre les messages compréhensibles</td></tr></tbody></table></div>","quiz":[{"q":"La psychologie cognitive étudie…","o":["Les processus mentaux","Uniquement les émotions","Les salaires"],"a":0,"e":"Définition."},{"q":"Le béhaviorisme étudie…","o":["Les comportements observables","Les pensées","Les rêves"],"a":0,"e":"Stimulus-réponse."},{"q":"Un représentant du béhaviorisme est…","o":["Skinner","Neisser","Kahneman"],"a":0,"e":"Béhaviorisme."},{"q":"La révolution cognitive date des années…","o":["1950-1960","1900","2000"],"a":0,"e":"Période."},{"q":"Qui a publié « Cognitive Psychology » en 1967 ?","o":["Ulric Neisser","Freud","Maslow"],"a":0,"e":"Ouvrage fondateur."},{"q":"Le modèle du traitement de l'information compare l'esprit à…","o":["Un système entrée-traitement-sortie","Une pompe","Un arbre"],"a":0,"e":"Analogie."},{"q":"Idée centrale : nos capacités de traitement sont…","o":["Limitées","Illimitées","Inexistantes"],"a":0,"e":"Principe."},{"q":"Le schéma béhavioriste est…","o":["Stimulus → réponse","Pensée → émotion","Mémoire → oubli"],"a":0,"e":"Modèle."},{"q":"Une méthode de la psychologie cognitive est…","o":["L'expérience en laboratoire","Le sondage politique","La comptabilité"],"a":0,"e":"Méthode."},{"q":"L'IRM fonctionnelle est une méthode…","o":["D'imagerie cérébrale","De paie","De recrutement"],"a":0,"e":"Neurosciences."},{"q":"Mesurer un temps de réaction sert à…","o":["Étudier le traitement de l'information","Calculer un salaire","Évaluer un stock"],"a":0,"e":"Méthode expérimentale."},{"q":"Apport en formation ?","o":["S'appuyer sur le fonctionnement de la mémoire","Supprimer les formations","Allonger les cours"],"a":0,"e":"Application."},{"q":"Apport en recrutement ?","o":["Réduire les biais de jugement","Recruter plus vite sans entretien","Augmenter les salaires"],"a":0,"e":"Application."},{"q":"Apport en organisation du travail ?","o":["Limiter la surcharge et les erreurs","Augmenter les heures","Supprimer les pauses"],"a":0,"e":"Application."},{"q":"Décider fait partie des processus…","o":["Cognitifs","Comptables","Juridiques"],"a":0,"e":"Définition."},{"q":"Les études de cas de patients cérébrolésés aident à…","o":["Comprendre le rôle des zones du cerveau","Calculer l'ITS","Recruter"],"a":0,"e":"Méthode."},{"q":"La modélisation informatique sert à…","o":["Simuler des processus mentaux","Payer les salaires","Archiver"],"a":0,"e":"Méthode."},{"q":"Le béhaviorisme a dominé…","o":["La première moitié du XXe siècle","Le XIXe siècle","Les années 2000"],"a":0,"e":"Période."},{"q":"Watson est associé au…","o":["Béhaviorisme","Cognitivisme","Management"],"a":0,"e":"Fondateur."},{"q":"Rendre un message compréhensible relève de l'apport en…","o":["Communication","Paie","Fiscalité"],"a":0,"e":"Application."}]},{"id":"mrh308-2","n":2,"t":"Perception et attention","min":20,"html":"<h3>La perception</h3>\n<p>Percevoir, ce n'est pas enregistrer passivement : le cerveau <strong>interprète</strong> les informations sensorielles à partir de ses connaissances et attentes. Deux personnes peuvent percevoir différemment la même situation.</p>\n<p>Les psychologues de la <strong>Gestalt</strong> ont décrit des lois d'organisation : on regroupe spontanément les éléments proches, semblables, ou formant une figure fermée.</p>\n<h3>Les formes d'attention</h3>\n<div class=\"tbl\"><table><thead><tr><th>Forme</th><th>Définition</th><th>Exemple</th></tr></thead><tbody>\n<tr><td>Sélective</td><td>Se concentrer sur une information en ignorant les autres</td><td>Suivre une conversation dans un open space bruyant</td></tr>\n<tr><td>Divisée</td><td>Traiter plusieurs informations en même temps</td><td>Répondre au téléphone en saisissant des données</td></tr>\n<tr><td>Soutenue</td><td>Maintenir la concentration dans la durée</td><td>Contrôler une paie de 300 bulletins</td></tr></tbody></table></div>\n<h3>L'effet cocktail party</h3>\n<p>Dans une salle bruyante, on entend son prénom prononcé dans une autre conversation : le cerveau surveille en arrière-plan les informations importantes pour nous.</p>\n<h3>La cécité attentionnelle</h3>\n<p>Concentrés sur une tâche, nous pouvons ne pas voir un élément pourtant visible (expérience du « gorille invisible » de Simons et Chabris, 1999).</p>\n<h3>Le mythe du multitâche</h3>\n<p>Pour des tâches complexes, le cerveau ne fait pas deux choses à la fois : il alterne. Chaque bascule a un coût (temps, erreurs). Les interruptions fréquentes réduisent la qualité du travail.</p>\n<div class=\"callout\"><b>Application RH</b>Prévoir des plages sans interruption pour les tâches de contrôle (paie, déclarations).</div>","quiz":[{"q":"Percevoir, c'est…","o":["Interpréter les informations sensorielles","Enregistrer passivement","Mémoriser définitivement"],"a":0,"e":"Construction."},{"q":"Deux personnes peuvent percevoir différemment la même situation car…","o":["Le cerveau interprète selon ses attentes","Leurs yeux sont différents","C'est impossible"],"a":0,"e":"Perception active."},{"q":"La Gestalt décrit…","o":["Des lois d'organisation perceptive","Des lois fiscales","Des styles de management"],"a":0,"e":"Psychologie de la forme."},{"q":"Une loi de la Gestalt : on regroupe les éléments…","o":["Proches","Éloignés","Invisibles"],"a":0,"e":"Proximité."},{"q":"L'attention sélective consiste à…","o":["Se concentrer sur une information en ignorant les autres","Tout traiter à la fois","Maintenir longtemps"],"a":0,"e":"Définition."},{"q":"L'attention divisée consiste à…","o":["Traiter plusieurs informations en même temps","Ignorer tout","Dormir"],"a":0,"e":"Définition."},{"q":"L'attention soutenue consiste à…","o":["Maintenir la concentration dans la durée","Changer de tâche souvent","Se distraire"],"a":0,"e":"Définition."},{"q":"Contrôler 300 bulletins demande l'attention…","o":["Soutenue","Divisée","Sélective uniquement"],"a":0,"e":"Durée."},{"q":"Téléphoner en saisissant des données mobilise l'attention…","o":["Divisée","Soutenue","Nulle"],"a":0,"e":"Simultanéité."},{"q":"Suivre une conversation dans le bruit mobilise l'attention…","o":["Sélective","Divisée","Soutenue"],"a":0,"e":"Filtrage."},{"q":"L'effet cocktail party, c'est…","o":["Entendre son prénom dans le bruit","Oublier une fête","Boire trop"],"a":0,"e":"Surveillance en arrière-plan."},{"q":"La cécité attentionnelle, c'est…","o":["Ne pas voir un élément visible car on est concentré ailleurs","Une maladie des yeux","Une vision parfaite"],"a":0,"e":"Définition."},{"q":"L'expérience du « gorille invisible » est de…","o":["Simons et Chabris","Maslow","Fayol"],"a":0,"e":"1999."},{"q":"Pour des tâches complexes, le cerveau…","o":["Alterne entre les tâches","Fait tout en parallèle parfaitement","S'arrête"],"a":0,"e":"Mythe du multitâche."},{"q":"Chaque bascule entre tâches a un coût en…","o":["Temps et erreurs","Argent seulement","Rien"],"a":0,"e":"Coût de bascule."},{"q":"Les interruptions fréquentes…","o":["Réduisent la qualité du travail","L'améliorent","N'ont pas d'effet"],"a":0,"e":"Effet."},{"q":"Application RH ?","o":["Plages sans interruption pour les contrôles","Plus de réunions","Plus de notifications"],"a":0,"e":"Organisation."},{"q":"Le multitâche sur tâches complexes est…","o":["Un mythe","Une compétence universelle","Toujours efficace"],"a":0,"e":"Idée reçue."},{"q":"La perception dépend des…","o":["Connaissances et attentes","Seuls organes","Salaires"],"a":0,"e":"Traitement descendant."},{"q":"L'expérience du gorille date de…","o":["1999","1950","2020"],"a":0,"e":"Date."}]},{"id":"mrh308-3","n":3,"t":"Les systèmes de mémoire","min":25,"html":"<h3>Le modèle d'Atkinson et Shiffrin (1968)</h3>\n<p>Il distingue trois registres successifs.</p>\n<div class=\"tbl\"><table><thead><tr><th>Registre</th><th>Durée</th><th>Capacité</th></tr></thead><tbody>\n<tr><td>Mémoire sensorielle</td><td>Moins d'une seconde (visuelle) à quelques secondes (auditive)</td><td>Très grande</td></tr>\n<tr><td>Mémoire à court terme</td><td>Environ 15 à 30 secondes sans répétition</td><td>Limitée : 7 ± 2 éléments (Miller, 1956)</td></tr>\n<tr><td>Mémoire à long terme</td><td>Durable, jusqu'à toute la vie</td><td>Pratiquement illimitée</td></tr></tbody></table></div>\n<p>Des recherches plus récentes estiment la capacité réelle de la mémoire de travail plutôt autour de <strong>4 éléments</strong> (Cowan).</p>\n<h3>La mémoire de travail (Baddeley et Hitch, 1974)</h3>\n<p>C'est la mémoire à court terme « active », qui manipule l'information. Elle comprend un <strong>administrateur central</strong> (contrôle), une <strong>boucle phonologique</strong> (sons, mots), un <strong>calepin visuo-spatial</strong> (images, positions) et un <strong>buffer épisodique</strong>.</p>\n<h3>La mémoire à long terme</h3>\n<ul><li><strong>Déclarative (explicite)</strong> : <em>épisodique</em> (souvenirs personnels datés) et <em>sémantique</em> (connaissances générales).</li><li><strong>Procédurale (implicite)</strong> : savoir-faire automatisés (taper au clavier, conduire).</li></ul>\n<h3>Le regroupement (chunking)</h3>\n<p>On retient mieux en regroupant : 0707123456 est plus facile à retenir sous la forme 07 07 12 34 56.</p>\n<div class=\"callout\"><b>Application RH</b>Une procédure de 15 étapes données oralement dépasse la mémoire de travail : fournissez un support écrit ou une check-list.</div>","quiz":[{"q":"Qui a proposé le modèle à trois registres ?","o":["Atkinson et Shiffrin","Baddeley et Hitch","Simons et Chabris"],"a":0,"e":"1968."},{"q":"Durée de la mémoire sensorielle visuelle ?","o":["Moins d'une seconde","Une heure","Toute la vie"],"a":0,"e":"Très brève."},{"q":"Durée de la mémoire à court terme sans répétition ?","o":["15 à 30 secondes","5 minutes","Une journée"],"a":0,"e":"Brève."},{"q":"Capacité de la mémoire à court terme selon Miller ?","o":["7 ± 2 éléments","100 éléments","1 élément"],"a":0,"e":"1956."},{"q":"Estimation plus récente de Cowan ?","o":["Environ 4 éléments","20 éléments","Illimitée"],"a":0,"e":"Révision."},{"q":"Capacité de la mémoire à long terme ?","o":["Pratiquement illimitée","7 éléments","Nulle"],"a":0,"e":"Vaste."},{"q":"Qui a proposé le modèle de la mémoire de travail ?","o":["Baddeley et Hitch","Atkinson et Shiffrin","Miller"],"a":0,"e":"1974."},{"q":"L'administrateur central assure…","o":["Le contrôle","Le stockage à vie","La vision"],"a":0,"e":"Composante."},{"q":"La boucle phonologique traite…","o":["Les sons et mots","Les images","Les émotions"],"a":0,"e":"Composante."},{"q":"Le calepin visuo-spatial traite…","o":["Images et positions","Sons","Odeurs"],"a":0,"e":"Composante."},{"q":"La mémoire épisodique concerne…","o":["Les souvenirs personnels datés","Les savoir-faire","Les réflexes"],"a":0,"e":"Déclarative."},{"q":"La mémoire sémantique concerne…","o":["Les connaissances générales","Les souvenirs datés","Les gestes"],"a":0,"e":"Déclarative."},{"q":"Taper au clavier relève de la mémoire…","o":["Procédurale","Épisodique","Sémantique"],"a":0,"e":"Implicite."},{"q":"La mémoire procédurale est…","o":["Implicite","Explicite","Sensorielle"],"a":0,"e":"Automatismes."},{"q":"Savoir que Yamoussoukro est la capitale politique de la Côte d'Ivoire relève de la mémoire…","o":["Sémantique","Épisodique","Procédurale"],"a":0,"e":"Connaissance générale."},{"q":"Se souvenir de son premier jour de travail relève de la mémoire…","o":["Épisodique","Sémantique","Procédurale"],"a":0,"e":"Souvenir daté."},{"q":"Le chunking consiste à…","o":["Regrouper les informations","Oublier","Répéter sans fin"],"a":0,"e":"Regroupement."},{"q":"Une procédure orale de 15 étapes…","o":["Dépasse la mémoire de travail","Est facile à retenir","Est idéale"],"a":0,"e":"Application."},{"q":"Solution pour une procédure longue ?","o":["Un support écrit ou check-list","La répéter une fois","Rien"],"a":0,"e":"Aide externe."},{"q":"La mémoire de travail…","o":["Manipule l'information","Stocke à vie","Ne fait rien"],"a":0,"e":"Mémoire active."}]},{"id":"mrh308-4","n":4,"t":"Apprendre et oublier","min":25,"html":"<h3>La courbe de l'oubli</h3>\n<p>Hermann Ebbinghaus (1885) a montré que l'on oublie très vite après un apprentissage : une grande partie de l'information est perdue dans les jours qui suivent, puis l'oubli ralentit.</p>\n<h3>Les stratégies qui marchent</h3>\n<div class=\"tbl\"><table><thead><tr><th>Stratégie</th><th>Principe</th></tr></thead><tbody>\n<tr><td>Répétition espacée</td><td>Revoir l'information à intervalles croissants (J+1, J+7, J+30)</td></tr>\n<tr><td>Effet de test (récupération active)</td><td>Se tester renforce davantage la mémoire que relire</td></tr>\n<tr><td>Élaboration</td><td>Relier la nouvelle information à ce que l'on sait déjà, l'expliquer avec ses mots</td></tr>\n<tr><td>Double codage</td><td>Associer texte et image</td></tr>\n<tr><td>Alternance (entrelacement)</td><td>Mélanger des exercices de types différents</td></tr></tbody></table></div>\n<h3>Les stratégies moins efficaces</h3>\n<p>Relire passivement, surligner abondamment, apprendre tout la veille (« bachotage ») : ces méthodes donnent une impression de maîtrise mais la mémorisation est fragile.</p>\n<h3>Le rôle du sommeil</h3>\n<p>Pendant le sommeil, le cerveau consolide les apprentissages de la journée. Le manque de sommeil nuit à la mémorisation.</p>\n<h3>Le transfert</h3>\n<p>Apprendre ne suffit pas : il faut pouvoir utiliser la connaissance dans une situation nouvelle. Le transfert est favorisé par des exemples variés et des mises en situation proches du travail réel.</p>\n<div class=\"callout\"><b>Application RH</b>Une formation efficace alterne apports courts, quiz, cas pratiques et rappels programmés après la session.</div>","quiz":[{"q":"Qui a établi la courbe de l'oubli ?","o":["Ebbinghaus","Miller","Baddeley"],"a":0,"e":"1885."},{"q":"Selon Ebbinghaus, l'oubli est…","o":["Rapide au début puis ralentit","Lent puis rapide","Inexistant"],"a":0,"e":"Forme de la courbe."},{"q":"La répétition espacée consiste à…","o":["Revoir à intervalles croissants","Tout relire le même jour","Ne jamais revoir"],"a":0,"e":"Principe."},{"q":"Intervalles typiques de répétition espacée ?","o":["J+1, J+7, J+30","Toutes les heures","Une fois par an"],"a":0,"e":"Exemple."},{"q":"L'effet de test montre que…","o":["Se tester renforce la mémoire","Relire est plus efficace","Les tests sont inutiles"],"a":0,"e":"Récupération active."},{"q":"L'élaboration consiste à…","o":["Relier à ce que l'on sait déjà","Surligner","Recopier"],"a":0,"e":"Profondeur."},{"q":"Le double codage associe…","o":["Texte et image","Deux langues","Deux cours"],"a":0,"e":"Principe."},{"q":"L'entrelacement consiste à…","o":["Mélanger des exercices de types différents","Faire un seul type","Arrêter"],"a":0,"e":"Alternance."},{"q":"Relire passivement est…","o":["Peu efficace","Très efficace","La meilleure méthode"],"a":0,"e":"Illusion de maîtrise."},{"q":"Le bachotage de la veille produit une mémorisation…","o":["Fragile","Durable","Parfaite"],"a":0,"e":"Oubli rapide."},{"q":"Pendant le sommeil, le cerveau…","o":["Consolide les apprentissages","Efface tout","Ne fait rien"],"a":0,"e":"Consolidation."},{"q":"Le manque de sommeil…","o":["Nuit à la mémorisation","L'améliore","N'a aucun effet"],"a":0,"e":"Effet."},{"q":"Le transfert, c'est…","o":["Utiliser la connaissance dans une situation nouvelle","Changer de poste","Envoyer un fichier"],"a":0,"e":"Définition."},{"q":"Le transfert est favorisé par…","o":["Des exemples variés","Un seul exemple","L'absence d'exemples"],"a":0,"e":"Généralisation."},{"q":"Une formation efficace alterne…","o":["Apports courts, quiz, cas pratiques","Un exposé de 8 heures","Uniquement des lectures"],"a":0,"e":"Application."},{"q":"Surligner abondamment donne…","o":["Une impression de maîtrise","Une maîtrise garantie","Un diplôme"],"a":0,"e":"Illusion."},{"q":"Programmer des rappels après la formation applique…","o":["La répétition espacée","Le bachotage","L'oubli"],"a":0,"e":"Application."},{"q":"Expliquer une notion avec ses mots relève de…","o":["L'élaboration","La relecture","Le surlignage"],"a":0,"e":"Stratégie."},{"q":"Ce quiz de fin de leçon utilise…","o":["L'effet de test","Le bachotage","Le double codage uniquement"],"a":0,"e":"Récupération active."},{"q":"Des mises en situation proches du travail favorisent…","o":["Le transfert","L'oubli","La fatigue"],"a":0,"e":"Application."}]},{"id":"mrh308-5","n":5,"t":"Langage et compréhension","min":20,"html":"<h3>Comprendre un message</h3>\n<p>Comprendre un texte ou un discours, c'est construire une représentation mentale de la situation décrite, en combinant les mots et ses connaissances préalables.</p>\n<h3>Ce qui facilite la compréhension</h3>\n<ul><li>Des phrases courtes, à la voix active.</li><li>Des mots courants plutôt que du jargon.</li><li>Une information principale par phrase.</li><li>Une structure annoncée (titre, plan, intertitres).</li><li>Des exemples concrets.</li></ul>\n<h3>Ce qui la complique</h3>\n<ul><li>Les doubles négations (« il n'est pas impossible que »).</li><li>Les sigles non expliqués.</li><li>Les phrases longues avec plusieurs subordonnées.</li><li>Les informations importantes noyées au milieu du texte.</li></ul>\n<h3>Le langage clair</h3>\n<p>Rédiger en langage clair permet au lecteur de trouver l'information, de la comprendre et de l'utiliser. C'est essentiel pour les documents RH : règlement intérieur, notes, procédures, bulletins.</p>\n<div class=\"tbl\"><table><thead><tr><th>Version complexe</th><th>Version claire</th></tr></thead><tbody>\n<tr><td>« Il est porté à la connaissance de l'ensemble du personnel que les demandes de congés devront impérativement être transmises dans un délai qui ne saurait être inférieur à quinze jours. »</td><td>« Envoyez vos demandes de congés au moins 15 jours à l'avance. »</td></tr></tbody></table></div>\n<h3>Le contexte multilingue</h3>\n<p>Dans un pays où l'on parle le français et de nombreuses langues nationales, certains salariés comprennent mieux un message oral, illustré ou traduit. Le RH adapte le canal et la forme au public.</p>","quiz":[{"q":"Comprendre un message, c'est…","o":["Construire une représentation mentale","Lire tous les mots","Mémoriser mot à mot"],"a":0,"e":"Définition."},{"q":"Les connaissances préalables…","o":["Aident à comprendre","Gênent toujours","N'interviennent pas"],"a":0,"e":"Combinaison."},{"q":"Ce qui facilite la compréhension ?","o":["Phrases courtes","Double négation","Sigles non expliqués"],"a":0,"e":"Clarté."},{"q":"La voix active est…","o":["Plus facile à comprendre","Plus difficile","Interdite"],"a":0,"e":"Clarté."},{"q":"Combien d'informations principales par phrase ?","o":["Une","Cinq","Autant que possible"],"a":0,"e":"Règle."},{"q":"« Il n'est pas impossible que » est…","o":["Une double négation","Une phrase claire","Un sigle"],"a":0,"e":"Complexité."},{"q":"Un sigle non expliqué…","o":["Complique la compréhension","La facilite","Est obligatoire"],"a":0,"e":"Obstacle."},{"q":"Annoncer la structure aide le lecteur à…","o":["S'orienter","Se perdre","Abandonner"],"a":0,"e":"Plan."},{"q":"Des exemples concrets…","o":["Facilitent la compréhension","La compliquent","Sont inutiles"],"a":0,"e":"Illustration."},{"q":"Le langage clair permet au lecteur de…","o":["Trouver, comprendre et utiliser l'information","Admirer le style","Deviner"],"a":0,"e":"Objectif."},{"q":"Version claire de la note sur les congés ?","o":["« Envoyez vos demandes au moins 15 jours à l'avance »","La version longue","Aucune"],"a":0,"e":"Simplification."},{"q":"Le langage clair est essentiel pour…","o":["Le règlement intérieur et les procédures","Les romans","La poésie"],"a":0,"e":"Documents RH."},{"q":"Placer l'information importante au milieu d'un long texte…","o":["La noie","La met en valeur","Est recommandé"],"a":0,"e":"Mise en évidence."},{"q":"Dans un contexte multilingue, le RH…","o":["Adapte le canal et la forme","Utilise uniquement l'écrit complexe","Ignore le problème"],"a":0,"e":"Accessibilité."},{"q":"Un message illustré peut aider…","o":["Ceux qui lisent moins facilement","Personne","Seulement les cadres"],"a":0,"e":"Accessibilité."},{"q":"Le jargon est à…","o":["Éviter avec un public large","Privilégier","Doubler"],"a":0,"e":"Clarté."},{"q":"Les phrases avec plusieurs subordonnées sont…","o":["Difficiles à comprendre","Faciles","Recommandées"],"a":0,"e":"Charge."},{"q":"Des intertitres servent à…","o":["Structurer le texte","Décorer seulement","Allonger"],"a":0,"e":"Navigation."},{"q":"La compréhension combine les mots et…","o":["Les connaissances préalables","Le salaire","La météo"],"a":0,"e":"Principe."},{"q":"Un bulletin de paie clair réduit…","o":["Les questions et réclamations","Les salaires","Les impôts"],"a":0,"e":"Application."}]},{"id":"mrh308-6","n":6,"t":"Raisonner et résoudre des problèmes","min":20,"html":"<h3>Deux formes de raisonnement</h3>\n<ul><li><strong>Déduction</strong> : du général au particulier. « Tous les salariés en CDI ont droit à des congés. Awa est en CDI. Donc Awa a droit à des congés. » Si les prémisses sont vraies, la conclusion est certaine.</li><li><strong>Induction</strong> : du particulier au général. « Les trois derniers stagiaires de cette école étaient excellents, donc les stagiaires de cette école sont excellents. » La conclusion est seulement probable.</li></ul>\n<h3>La résolution de problèmes</h3>\n<p>Selon Newell et Simon, résoudre un problème, c'est passer d'un état initial à un état but en appliquant des opérations. On utilise :</p>\n<div class=\"tbl\"><table><thead><tr><th>Méthode</th><th>Principe</th></tr></thead><tbody>\n<tr><td>Algorithme</td><td>Procédure systématique qui garantit la solution (mais peut être longue)</td></tr>\n<tr><td>Heuristique</td><td>Raccourci mental rapide, souvent efficace mais sans garantie</td></tr>\n<tr><td>Analyse moyens-fins</td><td>Découper le problème en sous-buts</td></tr>\n<tr><td>Analogie</td><td>Réutiliser la solution d'un problème semblable</td></tr></tbody></table></div>\n<h3>Les obstacles</h3>\n<ul><li><strong>Fixité fonctionnelle</strong> : ne voir un objet que dans son usage habituel.</li><li><strong>Effet d'attitude (Einstellung)</strong> : appliquer une méthode connue même quand une plus simple existe.</li><li>Mauvaise définition du problème.</li></ul>\n<h3>L'insight</h3>\n<p>Parfois la solution apparaît soudainement (« eurêka ») après une période d'incubation, quand on a cessé d'y penser activement.</p>","quiz":[{"q":"La déduction va…","o":["Du général au particulier","Du particulier au général","Nulle part"],"a":0,"e":"Définition."},{"q":"L'induction va…","o":["Du particulier au général","Du général au particulier","En cercle"],"a":0,"e":"Définition."},{"q":"Une conclusion déductive à prémisses vraies est…","o":["Certaine","Probable","Fausse"],"a":0,"e":"Validité."},{"q":"Une conclusion inductive est…","o":["Probable","Certaine","Impossible"],"a":0,"e":"Généralisation."},{"q":"« Trois stagiaires excellents donc tous excellents » est…","o":["Une induction","Une déduction","Un algorithme"],"a":0,"e":"Généralisation."},{"q":"« Tous les CDI ont des congés, Awa est en CDI, donc… » est…","o":["Une déduction","Une induction","Une heuristique"],"a":0,"e":"Syllogisme."},{"q":"Qui a modélisé la résolution de problèmes comme passage d'un état initial à un état but ?","o":["Newell et Simon","Fayol","Maslow"],"a":0,"e":"Modèle."},{"q":"Un algorithme…","o":["Garantit la solution","Est un raccourci risqué","Est toujours rapide"],"a":0,"e":"Définition."},{"q":"Une heuristique est…","o":["Un raccourci mental rapide","Une procédure garantie","Un logiciel"],"a":0,"e":"Définition."},{"q":"L'analyse moyens-fins consiste à…","o":["Découper en sous-buts","Abandonner","Deviner"],"a":0,"e":"Méthode."},{"q":"L'analogie consiste à…","o":["Réutiliser la solution d'un problème semblable","Inventer à partir de rien","Copier un collègue"],"a":0,"e":"Méthode."},{"q":"La fixité fonctionnelle, c'est…","o":["Ne voir un objet que dans son usage habituel","Être très créatif","Travailler vite"],"a":0,"e":"Obstacle."},{"q":"L'effet d'attitude, c'est…","o":["Appliquer une méthode connue quand une plus simple existe","Changer d'attitude","Être poli"],"a":0,"e":"Einstellung."},{"q":"Un obstacle fréquent est…","o":["Une mauvaise définition du problème","Trop d'informations claires","Un bon algorithme"],"a":0,"e":"Cadrage."},{"q":"L'insight est…","o":["Une solution qui apparaît soudainement","Un calcul lent","Une erreur"],"a":0,"e":"Eurêka."},{"q":"L'insight suit souvent une période…","o":["D'incubation","De panique","De réunion"],"a":0,"e":"Pause."},{"q":"Généraliser à partir de trois cas risque…","o":["L'erreur","La certitude","Rien"],"a":0,"e":"Limite de l'induction."},{"q":"Pour un problème complexe, découper en sous-buts aide à…","o":["Avancer étape par étape","Se perdre","Abandonner"],"a":0,"e":"Méthode."},{"q":"Les heuristiques sont souvent…","o":["Efficaces mais sans garantie","Toujours fausses","Toujours justes"],"a":0,"e":"Nuance."},{"q":"Prendre du recul peut favoriser…","o":["L'insight","L'oubli définitif","L'erreur"],"a":0,"e":"Incubation."}]},{"id":"mrh308-7","n":7,"t":"Décider : système 1 et système 2","min":25,"html":"<p>Daniel Kahneman, prix Nobel d'économie 2002, décrit dans <em>Système 1 / Système 2</em> (2011) deux modes de pensée.</p>\n<div class=\"tbl\"><table><thead><tr><th>Système 1</th><th>Système 2</th></tr></thead><tbody>\n<tr><td>Rapide, automatique, intuitif</td><td>Lent, réfléchi, analytique</td></tr>\n<tr><td>Peu d'effort</td><td>Demande de l'effort et de l'attention</td></tr>\n<tr><td>Reconnaître un visage, comprendre une phrase simple</td><td>Calculer 17 × 24, comparer deux offres d'emploi en détail</td></tr>\n<tr><td>Source de nombreux biais</td><td>Peut corriger le système 1, mais il est « paresseux »</td></tr></tbody></table></div>\n<h3>Les heuristiques de jugement</h3>\n<p>Tversky et Kahneman (1974) ont décrit trois raccourcis :</p>\n<ul><li><strong>Disponibilité</strong> : juger la fréquence d'un événement selon la facilité à en trouver des exemples (surestimer un risque récemment médiatisé).</li><li><strong>Représentativité</strong> : juger selon la ressemblance à un stéréotype, en oubliant les statistiques.</li><li><strong>Ancrage</strong> : être influencé par un premier chiffre, même arbitraire.</li></ul>\n<div class=\"callout\"><b>Ancrage en négociation salariale</b>Le premier montant annoncé sert de point de référence à toute la discussion.</div>\n<h3>L'aversion à la perte</h3>\n<p>Une perte pèse psychologiquement environ deux fois plus qu'un gain de même montant. C'est pourquoi retirer un avantage suscite plus de réactions que ne pas l'accorder.</p>\n<h3>L'effet de cadrage</h3>\n<p>La même information présentée différemment change la décision : « 90 % de réussite » est mieux accepté que « 10 % d'échec ».</p>","quiz":[{"q":"Qui a décrit le système 1 et le système 2 ?","o":["Daniel Kahneman","Abraham Maslow","Henri Fayol"],"a":0,"e":"2011."},{"q":"Kahneman a reçu le prix Nobel d'économie en…","o":["2002","1990","2015"],"a":0,"e":"Date."},{"q":"Le système 1 est…","o":["Rapide et intuitif","Lent et analytique","Inexistant"],"a":0,"e":"Caractéristique."},{"q":"Le système 2 est…","o":["Lent et réfléchi","Rapide et automatique","Émotionnel uniquement"],"a":0,"e":"Caractéristique."},{"q":"Calculer 17 × 24 mobilise le système…","o":["2","1","Aucun"],"a":0,"e":"Effort."},{"q":"Reconnaître un visage mobilise le système…","o":["1","2","Aucun"],"a":0,"e":"Automatique."},{"q":"Le système 2 est décrit comme…","o":["Paresseux","Toujours actif","Infaillible"],"a":0,"e":"Il s'active peu."},{"q":"La source principale de biais est…","o":["Le système 1","Le système 2","Le sommeil"],"a":0,"e":"Raccourcis."},{"q":"L'heuristique de disponibilité juge…","o":["Selon la facilité à trouver des exemples","Selon un premier chiffre","Selon un stéréotype"],"a":0,"e":"Définition."},{"q":"L'heuristique de représentativité juge…","o":["Selon la ressemblance à un stéréotype","Selon un premier chiffre","Selon la mémoire récente"],"a":0,"e":"Définition."},{"q":"L'ancrage, c'est…","o":["Être influencé par un premier chiffre","Rester au bureau","Refuser de négocier"],"a":0,"e":"Définition."},{"q":"Surestimer un risque récemment médiatisé relève de…","o":["La disponibilité","L'ancrage","La représentativité"],"a":0,"e":"Exemple."},{"q":"En négociation salariale, le premier montant annoncé…","o":["Sert de référence","N'a aucun effet","Est toujours refusé"],"a":0,"e":"Ancrage."},{"q":"Selon l'aversion à la perte, une perte pèse environ…","o":["Deux fois plus qu'un gain équivalent","Autant","Moitié moins"],"a":0,"e":"Asymétrie."},{"q":"Retirer un avantage suscite…","o":["Plus de réactions que ne pas l'accorder","Moins de réactions","Aucune réaction"],"a":0,"e":"Aversion à la perte."},{"q":"« 90 % de réussite » vs « 10 % d'échec » illustre…","o":["L'effet de cadrage","L'ancrage","La disponibilité"],"a":0,"e":"Présentation."},{"q":"Tversky et Kahneman ont publié sur les heuristiques en…","o":["1974","1943","2011"],"a":0,"e":"Date."},{"q":"Pour réduire les biais, on active le système…","o":["2","1","Aucun"],"a":0,"e":"Réflexion."},{"q":"Comparer deux offres d'emploi en détail mobilise le système…","o":["2","1","Aucun"],"a":0,"e":"Analyse."},{"q":"Le système 1 demande…","o":["Peu d'effort","Beaucoup d'effort","Un calcul"],"a":0,"e":"Automatisme."}]},{"id":"mrh308-8","n":8,"t":"Les biais cognitifs dans les décisions RH","min":25,"html":"<div class=\"tbl\"><table><thead><tr><th>Biais</th><th>Définition</th><th>Situation RH</th></tr></thead><tbody>\n<tr><td>Effet de halo</td><td>Une caractéristique saillante influence tout le jugement</td><td>Candidat très éloquent jugé compétent en tout</td></tr>\n<tr><td>Biais de confirmation</td><td>Chercher ce qui confirme sa première impression</td><td>Questions orientées après une bonne ou mauvaise première minute</td></tr>\n<tr><td>Biais de similarité</td><td>Préférer ceux qui nous ressemblent</td><td>Même école, même région, mêmes loisirs</td></tr>\n<tr><td>Effet de primauté</td><td>Les premières informations pèsent trop</td><td>Jugement fait dans les 5 premières minutes</td></tr>\n<tr><td>Effet de récence</td><td>Les dernières informations pèsent trop</td><td>Évaluation annuelle fondée sur le dernier mois</td></tr>\n<tr><td>Effet de contraste</td><td>Juger par comparaison avec le précédent</td><td>Candidat moyen jugé excellent après un très faible</td></tr>\n<tr><td>Stéréotypes</td><td>Croyances générales sur un groupe</td><td>« Les jeunes ne sont pas fiables »</td></tr>\n<tr><td>Biais d'attribution</td><td>Expliquer l'échec des autres par leur personnalité, le sien par les circonstances</td><td>« Il a raté parce qu'il est paresseux »</td></tr></tbody></table></div>\n<h3>Comment réduire les biais</h3>\n<ul><li><strong>Structurer</strong> : mêmes questions, même grille, critères définis à l'avance.</li><li><strong>Noter séparément</strong> chaque critère avant de former un avis global.</li><li><strong>Plusieurs évaluateurs</strong> qui notent indépendamment avant de discuter.</li><li><strong>S'appuyer sur des faits</strong> et des exemples précis.</li><li><strong>Anonymiser</strong> certaines informations (nom, photo) au stade du tri des CV.</li><li><strong>Former</strong> les recruteurs et managers aux biais.</li></ul>\n<div class=\"callout\"><b>À retenir</b>Connaître les biais ne suffit pas à les éviter : il faut des procédures qui les limitent.</div>","quiz":[{"q":"Un candidat très éloquent jugé compétent en tout illustre…","o":["L'effet de halo","L'effet de récence","Le stéréotype"],"a":0,"e":"Généralisation."},{"q":"Chercher ce qui confirme sa première impression est…","o":["Le biais de confirmation","L'effet de contraste","L'ancrage"],"a":0,"e":"Définition."},{"q":"Préférer un candidat de la même école que soi est…","o":["Le biais de similarité","L'effet de halo","L'effet de récence"],"a":0,"e":"Ressemblance."},{"q":"Juger dans les 5 premières minutes est…","o":["L'effet de primauté","L'effet de récence","L'effet de contraste"],"a":0,"e":"Premières informations."},{"q":"Évaluer sur le dernier mois seulement est…","o":["L'effet de récence","L'effet de primauté","Le halo"],"a":0,"e":"Dernières informations."},{"q":"Un candidat moyen paraît excellent après un très faible :","o":["Effet de contraste","Biais de similarité","Stéréotype"],"a":0,"e":"Comparaison."},{"q":"« Les jeunes ne sont pas fiables » est…","o":["Un stéréotype","Un fait","Une grille"],"a":0,"e":"Croyance générale."},{"q":"Expliquer l'échec d'un autre par sa paresse illustre…","o":["Le biais d'attribution","L'effet de halo","L'ancrage"],"a":0,"e":"Attribution."},{"q":"Structurer l'entretien, c'est…","o":["Mêmes questions, même grille","Improviser","Poser des questions personnelles"],"a":0,"e":"Réduction des biais."},{"q":"Noter chaque critère séparément avant l'avis global limite…","o":["L'effet de halo","La motivation","Le recrutement"],"a":0,"e":"Méthode."},{"q":"Plusieurs évaluateurs doivent noter…","o":["Indépendamment avant de discuter","Ensemble dès le début","Au hasard"],"a":0,"e":"Éviter l'influence."},{"q":"Anonymiser les CV limite…","o":["Les stéréotypes et biais de similarité","La compétence","Le nombre de candidats"],"a":0,"e":"Méthode."},{"q":"Connaître les biais suffit-il à les éviter ?","o":["Non, il faut des procédures","Oui","Toujours"],"a":0,"e":"Principe."},{"q":"Les critères d'évaluation sont définis…","o":["À l'avance","Après l'entretien","Jamais"],"a":0,"e":"Objectivité."},{"q":"S'appuyer sur des exemples précis limite…","o":["Les jugements subjectifs","La mémoire","La paie"],"a":0,"e":"Faits."},{"q":"Former les managers aux biais…","o":["Aide à les repérer","Est inutile","Est interdit"],"a":0,"e":"Sensibilisation."},{"q":"Questions orientées après une mauvaise première minute : biais…","o":["De confirmation","De contraste","D'attribution"],"a":0,"e":"Exemple."},{"q":"Même région, mêmes loisirs : biais…","o":["De similarité","De récence","De primauté"],"a":0,"e":"Exemple."},{"q":"Recevoir les candidats dans un ordre différent aide à limiter…","o":["L'effet de contraste","La motivation","Les salaires"],"a":0,"e":"Ordre de passage."},{"q":"Le halo peut être positif ou négatif ?","o":["Les deux","Seulement positif","Seulement négatif"],"a":0,"e":"Un défaut peut aussi tout colorer."}]},{"id":"mrh308-9","n":9,"t":"Charge cognitive et organisation du travail","min":20,"html":"<h3>La théorie de la charge cognitive</h3>\n<p>John Sweller (1988) distingue trois types de charge sur la mémoire de travail.</p>\n<div class=\"tbl\"><table><thead><tr><th>Charge</th><th>Origine</th><th>Que faire ?</th></tr></thead><tbody>\n<tr><td>Intrinsèque</td><td>Complexité propre du contenu</td><td>Découper, progresser du simple au complexe</td></tr>\n<tr><td>Extrinsèque</td><td>Mauvaise présentation (documents confus, informations dispersées)</td><td>La réduire au maximum</td></tr>\n<tr><td>Essentielle (germane)</td><td>Effort utile pour comprendre et construire des schémas</td><td>La favoriser</td></tr></tbody></table></div>\n<h3>L'effet d'attention partagée</h3>\n<p>Quand un texte et un schéma qui s'expliquent mutuellement sont séparés (texte page 3, schéma page 7), l'apprenant doit les intégrer mentalement : la charge extrinsèque augmente. Il vaut mieux les rapprocher.</p>\n<h3>La charge mentale au travail</h3>\n<p>Elle résulte de la quantité et de la complexité des informations à traiter, des interruptions, des délais et de l'incertitude. Une surcharge durable augmente les erreurs, la fatigue et le stress.</p>\n<h3>Les leviers d'organisation</h3>\n<ul><li>Check-lists pour les tâches répétitives et critiques (contrôle de paie).</li><li>Procédures écrites claires, modèles de documents.</li><li>Plages de travail sans interruption.</li><li>Limiter le nombre de priorités simultanées.</li><li>Automatiser les calculs répétitifs.</li><li>Pauses régulières.</li></ul>\n<div class=\"callout\"><b>La check-list</b>Utilisée dans l'aviation et la chirurgie, elle libère la mémoire de travail et réduit les oublis dans les tâches critiques.</div>","quiz":[{"q":"Qui a proposé la théorie de la charge cognitive ?","o":["John Sweller","Kahneman","Ebbinghaus"],"a":0,"e":"1988."},{"q":"Combien de types de charge cognitive ?","o":["Trois","Deux","Cinq"],"a":0,"e":"Intrinsèque, extrinsèque, essentielle."},{"q":"La charge intrinsèque vient…","o":["De la complexité du contenu","D'une mauvaise présentation","De l'effort utile"],"a":0,"e":"Définition."},{"q":"La charge extrinsèque vient…","o":["D'une mauvaise présentation","De la complexité","De la motivation"],"a":0,"e":"Définition."},{"q":"La charge essentielle correspond…","o":["À l'effort utile pour comprendre","Au bruit","À la fatigue"],"a":0,"e":"Définition."},{"q":"Que faire de la charge extrinsèque ?","o":["La réduire","L'augmenter","L'ignorer"],"a":0,"e":"Principe."},{"q":"Que faire de la charge essentielle ?","o":["La favoriser","La supprimer","L'ignorer"],"a":0,"e":"Principe."},{"q":"Pour la charge intrinsèque, on…","o":["Découpe et progresse du simple au complexe","Supprime le contenu","Accélère"],"a":0,"e":"Principe."},{"q":"Texte page 3 et schéma page 7 provoquent…","o":["L'effet d'attention partagée","Une meilleure compréhension","Rien"],"a":0,"e":"Dispersion."},{"q":"Solution à l'attention partagée ?","o":["Rapprocher texte et schéma","Supprimer le schéma","Ajouter des pages"],"a":0,"e":"Intégration."},{"q":"Une surcharge durable augmente…","o":["Les erreurs et le stress","La qualité","La motivation"],"a":0,"e":"Effets."},{"q":"Les interruptions augmentent…","o":["La charge mentale","La productivité","Le repos"],"a":0,"e":"Facteur."},{"q":"Une check-list sert à…","o":["Libérer la mémoire et réduire les oublis","Allonger les tâches","Décorer"],"a":0,"e":"Outil."},{"q":"Secteurs connus pour les check-lists ?","o":["Aviation et chirurgie","Mode et publicité","Tourisme"],"a":0,"e":"Exemples."},{"q":"Limiter les priorités simultanées réduit…","o":["La charge mentale","La compétence","Le salaire"],"a":0,"e":"Levier."},{"q":"Automatiser les calculs répétitifs…","o":["Réduit la charge et les erreurs","Augmente les erreurs","Est interdit"],"a":0,"e":"Levier."},{"q":"Des modèles de documents réduisent…","o":["La charge extrinsèque","Les salaires","La motivation"],"a":0,"e":"Standardisation."},{"q":"L'incertitude augmente…","o":["La charge mentale","Le repos","La clarté"],"a":0,"e":"Facteur."},{"q":"Des pauses régulières…","o":["Préviennent la fatigue","Réduisent la productivité toujours","Sont inutiles"],"a":0,"e":"Récupération."},{"q":"Des informations dispersées dans plusieurs fichiers augmentent la charge…","o":["Extrinsèque","Essentielle","Intrinsèque"],"a":0,"e":"Présentation."}]},{"id":"mrh308-10","n":10,"t":"Émotions, stress et performance","min":20,"html":"<h3>Émotions et cognition</h3>\n<p>Les émotions ne s'opposent pas à la raison : elles orientent l'attention, colorent la mémoire et participent à la décision. Antonio Damasio a montré que des patients privés de réactions émotionnelles avaient de grandes difficultés à prendre des décisions simples.</p>\n<h3>La loi de Yerkes-Dodson</h3>\n<p>La relation entre l'activation (stress, éveil) et la performance a la forme d'un <strong>U inversé</strong> : trop peu d'activation entraîne ennui et inattention ; un niveau modéré donne la meilleure performance ; trop d'activation désorganise. Pour une tâche complexe, le niveau optimal est plus bas que pour une tâche simple.</p>\n<h3>Le stress</h3>\n<p>Selon Lazarus, le stress naît d'une <strong>évaluation</strong> : la personne juge que les exigences de la situation dépassent ses ressources. Deux personnes face à la même situation peuvent donc réagir différemment.</p>\n<div class=\"tbl\"><table><thead><tr><th>Stress aigu</th><th>Stress chronique</th></tr></thead><tbody>\n<tr><td>Ponctuel, face à un défi</td><td>Durable, répété</td></tr>\n<tr><td>Mobilise l'énergie</td><td>Épuise, altère la mémoire et l'attention</td></tr>\n<tr><td>Disparaît après l'événement</td><td>Peut conduire à l'épuisement professionnel</td></tr></tbody></table></div>\n<h3>Le modèle de Karasek</h3>\n<p>Il croise la <strong>demande psychologique</strong> (charge) et la <strong>latitude décisionnelle</strong> (autonomie). La situation la plus à risque est « forte demande + faible latitude » (job strain). Le <strong>soutien social</strong> atténue ce risque.</p>\n<h3>Les leviers RH</h3>\n<p>Donner de l'autonomie, clarifier les rôles, ajuster la charge, développer le soutien entre collègues et des managers, former à la gestion du stress, repérer les signaux (irritabilité, erreurs, absences).</p>","quiz":[{"q":"Les émotions…","o":["Participent à la décision","S'opposent toujours à la raison","N'ont aucun rôle"],"a":0,"e":"Damasio."},{"q":"Qui a étudié des patients privés de réactions émotionnelles ?","o":["Antonio Damasio","Kahneman","Maslow"],"a":0,"e":"Neurosciences."},{"q":"La loi de Yerkes-Dodson a la forme…","o":["D'un U inversé","D'une droite","D'un cercle"],"a":0,"e":"Relation."},{"q":"Trop peu d'activation entraîne…","o":["Ennui et inattention","Performance maximale","Stress intense"],"a":0,"e":"Bas de la courbe."},{"q":"La meilleure performance correspond à une activation…","o":["Modérée","Nulle","Maximale"],"a":0,"e":"Sommet."},{"q":"Pour une tâche complexe, le niveau optimal d'activation est…","o":["Plus bas","Plus haut","Identique"],"a":0,"e":"Nuance."},{"q":"Selon Lazarus, le stress naît…","o":["D'une évaluation exigences / ressources","Uniquement de la charge","Du hasard"],"a":0,"e":"Modèle transactionnel."},{"q":"Deux personnes face à la même situation peuvent…","o":["Réagir différemment","Réagir toujours pareil","Ne jamais réagir"],"a":0,"e":"Évaluation personnelle."},{"q":"Le stress aigu…","o":["Mobilise l'énergie","Épuise durablement","Dure des années"],"a":0,"e":"Ponctuel."},{"q":"Le stress chronique…","o":["Altère mémoire et attention","Améliore la performance","Disparaît vite"],"a":0,"e":"Durable."},{"q":"Le stress chronique peut conduire à…","o":["L'épuisement professionnel","La promotion","La relaxation"],"a":0,"e":"Burn-out."},{"q":"Le modèle de Karasek croise…","o":["Demande psychologique et latitude décisionnelle","Salaire et âge","Service et ancienneté"],"a":0,"e":"Deux axes."},{"q":"La situation la plus à risque selon Karasek ?","o":["Forte demande et faible latitude","Faible demande et forte latitude","Forte latitude"],"a":0,"e":"Job strain."},{"q":"Qu'est-ce qui atténue le risque chez Karasek ?","o":["Le soutien social","L'isolement","Plus de contrôle"],"a":0,"e":"Troisième dimension."},{"q":"Un levier RH contre le stress est…","o":["Donner de l'autonomie","Réduire l'autonomie","Isoler"],"a":0,"e":"Latitude."},{"q":"Clarifier les rôles réduit…","o":["L'incertitude et le stress","La motivation","Les salaires"],"a":0,"e":"Levier."},{"q":"Un signal de stress à repérer est…","o":["L'irritabilité","La bonne humeur","La ponctualité"],"a":0,"e":"Signal."},{"q":"La latitude décisionnelle correspond à…","o":["L'autonomie","La charge","Le salaire"],"a":0,"e":"Définition."},{"q":"La demande psychologique correspond à…","o":["La charge de travail","L'autonomie","Le soutien"],"a":0,"e":"Définition."},{"q":"Trop d'activation…","o":["Désorganise la performance","L'améliore toujours","N'a pas d'effet"],"a":0,"e":"Haut de la courbe."}]}]},{"id":"mrh309","code":"MRH 309","unit":"trad","title":"Droit du numérique (RGPD) et autres","summary":"Protection des données personnelles en Côte d'Ivoire et dans l'Union européenne, données RH, surveillance des salariés, cybersécurité et transactions électroniques.","lessons":[{"id":"mrh309-1","n":1,"t":"Le cadre du droit du numérique","min":20,"html":"<p>Le droit du numérique encadre l'usage des technologies de l'information : données personnelles, transactions électroniques, cybersécurité, propriété intellectuelle sur les logiciels.</p>\n<h3>Les principaux textes ivoiriens</h3>\n<div class=\"tbl\"><table><thead><tr><th>Texte</th><th>Objet</th></tr></thead><tbody>\n<tr><td>Loi n° 2013-450 du 19 juin 2013</td><td>Protection des données à caractère personnel</td></tr>\n<tr><td>Loi n° 2013-451 du 19 juin 2013</td><td>Lutte contre la cybercriminalité</td></tr>\n<tr><td>Loi n° 2013-546 du 30 juillet 2013</td><td>Transactions électroniques</td></tr></tbody></table></div>\n<h3>L'autorité de contrôle</h3>\n<p>L'<strong>ARTCI</strong> (Autorité de régulation des télécommunications/TIC de Côte d'Ivoire) est chargée de la protection des données personnelles : elle reçoit les déclarations, délivre les autorisations, contrôle et peut sanctionner.</p>\n<h3>Le cadre régional et international</h3>\n<ul><li><strong>Convention de Malabo</strong> (Union africaine, 2014) sur la cybersécurité et la protection des données personnelles.</li><li><strong>Acte additionnel de la CEDEAO</strong> (2010) relatif à la protection des données personnelles.</li><li><strong>RGPD</strong> (Règlement général sur la protection des données, Union européenne), applicable depuis le 25 mai 2018, qui peut concerner des entreprises ivoiriennes.</li></ul>\n<h3>Pourquoi c'est un sujet RH ?</h3>\n<p>Le service RH est l'un des plus gros détenteurs de données personnelles de l'entreprise : candidats, salariés, ayants droit, anciens salariés. Il manipule aussi des données sensibles (santé, situation familiale).</p>","quiz":[{"q":"Quelle loi ivoirienne protège les données personnelles ?","o":["Loi n° 2013-450","Loi n° 2015-532","Loi n° 95-15"],"a":0,"e":"19 juin 2013."},{"q":"La loi n° 2013-451 porte sur…","o":["La cybercriminalité","Le Code du travail","Les impôts"],"a":0,"e":"Lutte contre la cybercriminalité."},{"q":"La loi n° 2013-546 porte sur…","o":["Les transactions électroniques","Les données de santé","Le droit de grève"],"a":0,"e":"30 juillet 2013."},{"q":"Quelle autorité contrôle la protection des données en Côte d'Ivoire ?","o":["L'ARTCI","La CNPS","La DGI"],"a":0,"e":"Autorité de régulation."},{"q":"L'ARTCI peut…","o":["Recevoir des déclarations et sanctionner","Fixer les salaires","Juger les licenciements"],"a":0,"e":"Missions."},{"q":"La Convention de Malabo a été adoptée par…","o":["L'Union africaine","L'Union européenne","L'OIT"],"a":0,"e":"2014."},{"q":"La Convention de Malabo date de…","o":["2014","2018","2000"],"a":0,"e":"Date."},{"q":"L'Acte additionnel de la CEDEAO sur les données date de…","o":["2010","2020","1995"],"a":0,"e":"Date."},{"q":"Le RGPD s'applique depuis le…","o":["25 mai 2018","1er janvier 2013","19 juin 2013"],"a":0,"e":"Date d'entrée en application."},{"q":"Le RGPD est un texte…","o":["De l'Union européenne","Ivoirien","De l'Union africaine"],"a":0,"e":"Origine."},{"q":"Le RGPD peut-il concerner une entreprise ivoirienne ?","o":["Oui, dans certains cas","Jamais","Toujours"],"a":0,"e":"Champ territorial."},{"q":"Pourquoi le RH est-il concerné ?","o":["Il détient de nombreuses données personnelles","Il vend des données","Il n'est pas concerné"],"a":0,"e":"Enjeu."},{"q":"Le RH manipule des données sensibles comme…","o":["La santé","Le prix des produits","Le stock"],"a":0,"e":"Exemple."},{"q":"Les candidats sont-ils concernés par la protection des données ?","o":["Oui","Non","Seulement s'ils sont recrutés"],"a":0,"e":"Personnes concernées."},{"q":"Les anciens salariés sont-ils concernés ?","o":["Oui","Non","Seulement les cadres"],"a":0,"e":"Personnes concernées."},{"q":"Le droit du numérique encadre notamment…","o":["Les données personnelles et la cybersécurité","Les salaires minimums","La TVA"],"a":0,"e":"Champ."},{"q":"Les deux lois de juin 2013 ont été adoptées le…","o":["19 juin 2013","20 juillet 2015","25 mai 2018"],"a":0,"e":"Date."},{"q":"Qui délivre les autorisations de traitement en Côte d'Ivoire ?","o":["L'ARTCI","Le ministère de la Santé","La mairie"],"a":0,"e":"Formalités."},{"q":"La propriété intellectuelle sur les logiciels relève…","o":["Du droit du numérique","Du droit fiscal seulement","Du droit du travail uniquement"],"a":0,"e":"Champ."},{"q":"Les ayants droit des salariés sont…","o":["Des personnes dont le RH détient des données","Sans rapport","Des fournisseurs"],"a":0,"e":"Personnes concernées."}]},{"id":"mrh309-2","n":2,"t":"Les notions clés","min":20,"html":"<h3>Donnée à caractère personnel</h3>\n<p>Toute information relative à une personne physique identifiée ou identifiable, directement (nom, photo) ou indirectement (matricule, numéro CNPS, adresse IP, voix, combinaison âge + service).</p>\n<h3>Traitement</h3>\n<p>Toute opération sur des données : collecte, enregistrement, organisation, conservation, modification, consultation, utilisation, communication, effacement. Un simple fichier Excel des salariés est un traitement.</p>\n<h3>Les acteurs</h3>\n<div class=\"tbl\"><table><thead><tr><th>Acteur</th><th>Définition</th><th>Exemple RH</th></tr></thead><tbody>\n<tr><td>Responsable du traitement</td><td>Détermine les finalités et les moyens</td><td>L'entreprise employeur</td></tr>\n<tr><td>Sous-traitant</td><td>Traite les données pour le compte du responsable</td><td>Éditeur du logiciel de paie en ligne, cabinet de recrutement mandaté</td></tr>\n<tr><td>Personne concernée</td><td>Personne dont les données sont traitées</td><td>Le salarié, le candidat</td></tr>\n<tr><td>Destinataire</td><td>Reçoit communication des données</td><td>CNPS, DGI, assureur</td></tr></tbody></table></div>\n<h3>Les données sensibles</h3>\n<p>Leur traitement est en principe interdit, sauf exceptions (consentement, obligation légale, santé au travail) : origine raciale ou ethnique, opinions politiques, convictions religieuses ou philosophiques, appartenance syndicale, santé, vie sexuelle, données génétiques et biométriques. Les données relatives aux infractions et condamnations sont également très encadrées.</p>\n<h3>Anonymisation et pseudonymisation</h3>\n<p>Une donnée <strong>anonymisée</strong> ne permet plus d'identifier la personne, de façon irréversible : elle sort du champ de la loi. Une donnée <strong>pseudonymisée</strong> (nom remplacé par un code) reste personnelle, car on peut retrouver la personne avec la table de correspondance.</p>","quiz":[{"q":"Une donnée personnelle concerne…","o":["Une personne physique identifiable","Une entreprise","Un produit"],"a":0,"e":"Définition."},{"q":"Le numéro CNPS est une donnée…","o":["Personnelle (identification indirecte)","Anonyme","Publique sans protection"],"a":0,"e":"Identifiant."},{"q":"Une adresse IP peut être…","o":["Une donnée personnelle","Jamais personnelle","Un logiciel"],"a":0,"e":"Identification indirecte."},{"q":"Un fichier Excel des salariés est…","o":["Un traitement","Hors champ de la loi","Un simple document sans règles"],"a":0,"e":"Toute opération."},{"q":"Consulter une donnée est-il un traitement ?","o":["Oui","Non","Seulement en ligne"],"a":0,"e":"Définition large."},{"q":"Le responsable du traitement…","o":["Détermine finalités et moyens","Traite pour le compte d'un autre","Est la personne concernée"],"a":0,"e":"Définition."},{"q":"Dans un contexte RH, le responsable du traitement est…","o":["L'entreprise employeur","Le salarié","La CNPS"],"a":0,"e":"Exemple."},{"q":"L'éditeur d'un logiciel de paie en ligne est…","o":["Un sous-traitant","Le responsable","La personne concernée"],"a":0,"e":"Pour le compte de l'employeur."},{"q":"Le salarié est…","o":["La personne concernée","Le sous-traitant","Le destinataire"],"a":0,"e":"Exemple."},{"q":"La CNPS, recevant des données salariales, est…","o":["Un destinataire","Un sous-traitant","Le responsable de l'employeur"],"a":0,"e":"Communication."},{"q":"Une donnée de santé est…","o":["Sensible","Ordinaire","Publique"],"a":0,"e":"Catégorie."},{"q":"L'appartenance syndicale est une donnée…","o":["Sensible","Ordinaire","Commerciale"],"a":0,"e":"Catégorie."},{"q":"Les empreintes digitales sont des données…","o":["Biométriques sensibles","Ordinaires","Comptables"],"a":0,"e":"Catégorie."},{"q":"Le traitement des données sensibles est en principe…","o":["Interdit sauf exceptions","Libre","Obligatoire"],"a":0,"e":"Principe."},{"q":"Une exception pour les données de santé au travail est…","o":["La médecine du travail","Le marketing","La curiosité du manager"],"a":0,"e":"Exception."},{"q":"Une donnée anonymisée…","o":["Ne permet plus d'identifier la personne","Reste personnelle","Est sensible"],"a":0,"e":"Définition."},{"q":"Une donnée anonymisée est-elle soumise à la loi ?","o":["Non","Oui","Seulement en Europe"],"a":0,"e":"Hors champ."},{"q":"Une donnée pseudonymisée…","o":["Reste personnelle","Est anonyme","Est publique"],"a":0,"e":"Réversible."},{"q":"Remplacer le nom par un code avec table de correspondance, c'est…","o":["Pseudonymiser","Anonymiser","Supprimer"],"a":0,"e":"Définition."},{"q":"Âge + service de 3 personnes peut constituer…","o":["Une identification indirecte","Une donnée anonyme","Rien"],"a":0,"e":"Combinaison."}]},{"id":"mrh309-3","n":3,"t":"Les principes de protection","min":25,"html":"<p>Tout traitement de données personnelles doit respecter des principes communs à la loi ivoirienne et au RGPD.</p>\n<div class=\"tbl\"><table><thead><tr><th>Principe</th><th>Signification</th><th>Exemple RH</th></tr></thead><tbody>\n<tr><td>Licéité, loyauté, transparence</td><td>Base légale, pas de collecte cachée, information des personnes</td><td>Informer les candidats de l'usage de leur CV</td></tr>\n<tr><td>Finalité</td><td>Objectif déterminé, explicite, légitime ; pas de réutilisation incompatible</td><td>Les données de badge servent à la sécurité, pas à noter les salariés</td></tr>\n<tr><td>Minimisation (proportionnalité)</td><td>Seulement les données nécessaires</td><td>Ne pas demander la religion dans un formulaire d'embauche</td></tr>\n<tr><td>Exactitude</td><td>Données exactes et mises à jour</td><td>Mettre à jour la situation familiale</td></tr>\n<tr><td>Limitation de la conservation</td><td>Durée définie selon la finalité</td><td>Supprimer les CV non retenus après un délai</td></tr>\n<tr><td>Sécurité et confidentialité</td><td>Mesures techniques et organisationnelles</td><td>Accès restreint au SIRH, mots de passe</td></tr></tbody></table></div>\n<h3>Les bases légales</h3>\n<p>Un traitement doit reposer sur une base : le <strong>consentement</strong>, l'exécution d'un <strong>contrat</strong> (paie), une <strong>obligation légale</strong> (déclarations CNPS), la sauvegarde d'un intérêt vital, une mission d'intérêt public ou l'<strong>intérêt légitime</strong> du responsable.</p>\n<div class=\"callout\"><b>Le consentement du salarié</b>Dans la relation de travail, le salarié est en position de subordination : son consentement est rarement considéré comme libre. On s'appuie plutôt sur le contrat ou l'obligation légale.</div>\n<h3>La responsabilité (accountability)</h3>\n<p>Le responsable du traitement doit être capable de démontrer qu'il respecte les principes : registre des traitements, politiques internes, formation, contrats avec les sous-traitants.</p>","quiz":[{"q":"Le principe de finalité exige un objectif…","o":["Déterminé, explicite, légitime","Vague","Secret"],"a":0,"e":"Définition."},{"q":"Utiliser les données de badge pour noter les salariés viole…","o":["La finalité","L'exactitude","La sécurité"],"a":0,"e":"Réutilisation incompatible."},{"q":"La minimisation signifie…","o":["Seulement les données nécessaires","Le maximum de données","Aucune donnée"],"a":0,"e":"Proportionnalité."},{"q":"Demander la religion dans un formulaire d'embauche viole…","o":["La minimisation","L'exactitude","La conservation"],"a":0,"e":"Donnée non nécessaire."},{"q":"Mettre à jour la situation familiale relève de…","o":["L'exactitude","La finalité","La sécurité"],"a":0,"e":"Principe."},{"q":"Supprimer les CV non retenus après un délai applique…","o":["La limitation de la conservation","La finalité","La transparence"],"a":0,"e":"Durée."},{"q":"Restreindre l'accès au SIRH relève de…","o":["La sécurité","La minimisation","L'exactitude"],"a":0,"e":"Principe."},{"q":"Informer les candidats de l'usage de leur CV relève de…","o":["La transparence","La conservation","La sécurité"],"a":0,"e":"Principe."},{"q":"Une base légale possible est…","o":["L'exécution d'un contrat","La curiosité","La convenance"],"a":0,"e":"Liste."},{"q":"La paie repose principalement sur…","o":["L'exécution du contrat et l'obligation légale","Le consentement","L'intérêt vital"],"a":0,"e":"Base légale."},{"q":"Les déclarations CNPS reposent sur…","o":["Une obligation légale","Le consentement","L'intérêt commercial"],"a":0,"e":"Base légale."},{"q":"Le consentement du salarié est rarement libre car…","o":["Il est en situation de subordination","Il est toujours d'accord","La loi l'interdit"],"a":0,"e":"Déséquilibre."},{"q":"L'accountability signifie…","o":["Pouvoir démontrer sa conformité","Comptabilité","Audit fiscal"],"a":0,"e":"Responsabilité."},{"q":"Un outil de démonstration de conformité est…","o":["Le registre des traitements","Le bilan","La facture"],"a":0,"e":"Documentation."},{"q":"Les contrats avec les sous-traitants servent à…","o":["Encadrer leurs obligations","Réduire les prix","Rien"],"a":0,"e":"Accountability."},{"q":"La loyauté interdit…","o":["La collecte cachée","L'information","Le consentement"],"a":0,"e":"Principe."},{"q":"Combien de principes sont listés dans le tableau ?","o":["Six","Trois","Dix"],"a":0,"e":"Liste."},{"q":"L'intérêt légitime est…","o":["Une base légale","Une donnée sensible","Un sous-traitant"],"a":0,"e":"Base."},{"q":"La sécurité comprend des mesures…","o":["Techniques et organisationnelles","Uniquement juridiques","Uniquement physiques"],"a":0,"e":"Double nature."},{"q":"Former le personnel à la protection des données relève de…","o":["L'accountability","La minimisation","L'exactitude"],"a":0,"e":"Démonstration."}]},{"id":"mrh309-4","n":4,"t":"Formalités et gouvernance des données","min":20,"html":"<h3>Les formalités auprès de l'ARTCI</h3>\n<p>La loi ivoirienne prévoit des formalités préalables à la mise en œuvre de certains traitements :</p>\n<ul><li><strong>La déclaration</strong> pour les traitements courants.</li><li><strong>L'autorisation préalable</strong> pour les traitements présentant des risques particuliers : données sensibles, données biométriques, interconnexion de fichiers, transfert vers un pays tiers, traitements à des fins de surveillance.</li></ul>\n<p>Le traitement ne peut commencer qu'après l'accomplissement de la formalité requise. Les modalités exactes (formulaires, délais, dispenses) sont précisées par l'ARTCI.</p>\n<h3>Le correspondant à la protection des données</h3>\n<p>L'entreprise peut désigner un correspondant (appelé DPO, <em>Data Protection Officer</em>, dans le RGPD). Il conseille, sensibilise, tient le registre et fait le lien avec l'autorité.</p>\n<h3>Le registre des traitements</h3>\n<div class=\"tbl\"><table><thead><tr><th>Rubrique</th><th>Exemple : traitement « paie »</th></tr></thead><tbody>\n<tr><td>Finalité</td><td>Calcul et versement des salaires, déclarations sociales et fiscales</td></tr>\n<tr><td>Catégories de personnes</td><td>Salariés</td></tr>\n<tr><td>Catégories de données</td><td>Identité, n° CNPS, salaire, situation familiale, RIB</td></tr>\n<tr><td>Destinataires</td><td>Service paie, CNPS, DGI, banque</td></tr>\n<tr><td>Durée de conservation</td><td>Selon les obligations légales</td></tr>\n<tr><td>Mesures de sécurité</td><td>Accès nominatif, sauvegardes, chiffrement</td></tr></tbody></table></div>\n<h3>L'analyse d'impact</h3>\n<p>Pour les traitements à risque élevé (surveillance systématique, données sensibles à grande échelle), le RGPD impose une analyse d'impact (AIPD) qui évalue les risques pour les personnes et les mesures pour les réduire.</p>","quiz":[{"q":"Quelles sont les deux formalités principales auprès de l'ARTCI ?","o":["Déclaration et autorisation préalable","Vente et achat","Plainte et appel"],"a":0,"e":"Régime."},{"q":"Un traitement de données biométriques nécessite…","o":["Une autorisation préalable","Rien","Une simple information orale"],"a":0,"e":"Risque particulier."},{"q":"Un transfert vers un pays tiers nécessite…","o":["Une autorisation préalable","Rien","Un visa"],"a":0,"e":"Risque particulier."},{"q":"Un traitement courant nécessite…","o":["Une déclaration","Une autorisation du juge","Rien"],"a":0,"e":"Régime simple."},{"q":"Quand peut commencer le traitement ?","o":["Après la formalité requise","Avant","N'importe quand"],"a":0,"e":"Préalable."},{"q":"Qui précise les modalités des formalités ?","o":["L'ARTCI","La CNPS","Le syndicat"],"a":0,"e":"Autorité."},{"q":"DPO signifie…","o":["Data Protection Officer","Directeur du personnel ouvrier","Déclaration préalable obligatoire"],"a":0,"e":"Délégué."},{"q":"Rôle du correspondant ?","o":["Conseiller, sensibiliser, tenir le registre","Calculer la paie","Recruter"],"a":0,"e":"Missions."},{"q":"Le registre des traitements recense…","o":["Les traitements de données de l'entreprise","Les ventes","Les accidents"],"a":0,"e":"Documentation."},{"q":"Une rubrique du registre est…","o":["La finalité","Le prix","La couleur"],"a":0,"e":"Contenu."},{"q":"Pour la paie, les destinataires incluent…","o":["CNPS, DGI, banque","Les clients","Les concurrents"],"a":0,"e":"Exemple."},{"q":"Le RIB est une donnée du traitement…","o":["Paie","Recrutement","Formation"],"a":0,"e":"Exemple."},{"q":"Une mesure de sécurité du traitement paie est…","o":["L'accès nominatif","L'accès public","Aucun mot de passe"],"a":0,"e":"Exemple."},{"q":"AIPD signifie…","o":["Analyse d'impact relative à la protection des données","Audit interne de paie","Autorisation individuelle"],"a":0,"e":"RGPD."},{"q":"L'AIPD est imposée pour les traitements…","o":["À risque élevé","Tous","Aucun"],"a":0,"e":"Seuil."},{"q":"La surveillance systématique relève…","o":["D'un risque élevé","D'un risque nul","Du marketing"],"a":0,"e":"Exemple."},{"q":"L'AIPD évalue…","o":["Les risques et les mesures pour les réduire","Les salaires","Les ventes"],"a":0,"e":"Contenu."},{"q":"L'interconnexion de fichiers nécessite…","o":["Une autorisation préalable","Rien","Une déclaration CNPS"],"a":0,"e":"Risque."},{"q":"Les catégories de personnes du traitement paie sont…","o":["Les salariés","Les clients","Les fournisseurs"],"a":0,"e":"Exemple."},{"q":"Le correspondant fait le lien avec…","o":["L'autorité de contrôle","Les clients","La presse"],"a":0,"e":"Rôle."}]},{"id":"mrh309-5","n":5,"t":"Les droits des personnes","min":20,"html":"<h3>Le droit à l'information</h3>\n<p>Lors de la collecte, la personne doit être informée : identité du responsable, finalité, caractère obligatoire ou facultatif des réponses, destinataires, durée de conservation, droits et moyens de les exercer, transferts éventuels.</p>\n<h3>Les autres droits</h3>\n<div class=\"tbl\"><table><thead><tr><th>Droit</th><th>Contenu</th><th>Exemple</th></tr></thead><tbody>\n<tr><td>Accès</td><td>Savoir si des données sont traitées et en obtenir copie</td><td>Un salarié demande la copie de son dossier</td></tr>\n<tr><td>Rectification</td><td>Faire corriger des données inexactes</td><td>Changement d'adresse, erreur de date de naissance</td></tr>\n<tr><td>Opposition</td><td>S'opposer à un traitement pour motif légitime</td><td>Refuser l'utilisation de sa photo dans le journal interne</td></tr>\n<tr><td>Effacement</td><td>Obtenir la suppression dans certains cas</td><td>Candidat qui retire sa candidature</td></tr>\n<tr><td>Limitation (RGPD)</td><td>Geler temporairement un traitement contesté</td><td>Pendant la vérification d'une contestation</td></tr>\n<tr><td>Portabilité (RGPD)</td><td>Récupérer ses données dans un format réutilisable</td><td>Export de ses données de formation</td></tr></tbody></table></div>\n<h3>Exercer ses droits</h3>\n<p>La demande est adressée au responsable du traitement. Il vérifie l'identité du demandeur et répond dans un délai raisonnable (un mois selon le RGPD). En cas de refus ou d'absence de réponse, la personne peut saisir l'autorité de contrôle.</p>\n<h3>Les limites</h3>\n<p>Le droit d'opposition ou d'effacement ne s'applique pas lorsque le traitement répond à une obligation légale : un salarié ne peut pas exiger la suppression de ses données de paie que l'employeur doit conserver.</p>","quiz":[{"q":"Lors de la collecte, la personne doit être informée de…","o":["La finalité","Le salaire du DG","Le chiffre d'affaires"],"a":0,"e":"Information."},{"q":"Le droit d'accès permet…","o":["D'obtenir copie de ses données","De modifier celles des autres","De supprimer toutes les données"],"a":0,"e":"Définition."},{"q":"Le droit de rectification permet…","o":["De corriger des données inexactes","De supprimer tout","D'accéder aux données des autres"],"a":0,"e":"Définition."},{"q":"Un changement d'adresse relève du droit de…","o":["Rectification","Portabilité","Opposition"],"a":0,"e":"Exemple."},{"q":"Refuser sa photo dans le journal interne relève du droit…","o":["D'opposition","D'accès","De rectification"],"a":0,"e":"Exemple."},{"q":"Un candidat qui retire sa candidature peut demander…","o":["L'effacement","La portabilité","La promotion"],"a":0,"e":"Exemple."},{"q":"La portabilité permet…","o":["De récupérer ses données dans un format réutilisable","De vendre ses données","D'effacer"],"a":0,"e":"RGPD."},{"q":"La limitation permet…","o":["De geler temporairement un traitement contesté","De tout supprimer","D'accéder"],"a":0,"e":"RGPD."},{"q":"À qui adresser une demande d'exercice des droits ?","o":["Au responsable du traitement","Au sous-traitant seulement","À la presse"],"a":0,"e":"Destinataire."},{"q":"Avant de répondre, le responsable vérifie…","o":["L'identité du demandeur","Le salaire","L'âge"],"a":0,"e":"Sécurité."},{"q":"Délai de réponse selon le RGPD ?","o":["Un mois","Un an","Une heure"],"a":0,"e":"Délai."},{"q":"En cas de refus, la personne peut saisir…","o":["L'autorité de contrôle","La CNPS","Le fournisseur"],"a":0,"e":"Recours."},{"q":"Un salarié peut-il exiger l'effacement de ses données de paie légalement conservées ?","o":["Non","Oui","Toujours"],"a":0,"e":"Obligation légale."},{"q":"Le droit d'opposition exige…","o":["Un motif légitime","Aucun motif","Un avocat"],"a":0,"e":"Condition."},{"q":"L'information porte aussi sur…","o":["La durée de conservation","Les goûts du responsable","Le prix"],"a":0,"e":"Contenu."},{"q":"L'information précise si les réponses sont…","o":["Obligatoires ou facultatives","Payantes","Publiques"],"a":0,"e":"Contenu."},{"q":"Un salarié demande la copie de son dossier : droit…","o":["D'accès","D'opposition","De portabilité"],"a":0,"e":"Exemple."},{"q":"Les droits de limitation et de portabilité sont prévus notamment par…","o":["Le RGPD","Le Code du travail","La convention collective"],"a":0,"e":"Origine."},{"q":"Les transferts éventuels vers l'étranger doivent être…","o":["Mentionnés dans l'information","Cachés","Interdits"],"a":0,"e":"Transparence."},{"q":"Le droit d'effacement est…","o":["Limité par les obligations légales","Absolu","Inexistant"],"a":0,"e":"Limite."}]},{"id":"mrh309-6","n":6,"t":"Le RGPD européen","min":25,"html":"<h3>Le champ d'application</h3>\n<p>Le RGPD s'applique :</p>\n<ul><li>aux responsables et sous-traitants <strong>établis dans l'Union européenne</strong> ;</li><li>aux organismes <strong>hors UE</strong> qui proposent des biens ou services à des personnes situées dans l'UE, ou qui suivent leur comportement.</li></ul>\n<p>Exemple : une entreprise ivoirienne qui recrute en ligne des candidats résidant en France, ou une filiale d'un groupe européen, peut être concernée.</p>\n<h3>Les apports du RGPD</h3>\n<div class=\"tbl\"><table><thead><tr><th>Mesure</th><th>Contenu</th></tr></thead><tbody>\n<tr><td>Responsabilité</td><td>Démontrer sa conformité (registre, politiques)</td></tr>\n<tr><td>Protection dès la conception</td><td>Intégrer la protection des données dès la création d'un outil (privacy by design)</td></tr>\n<tr><td>Protection par défaut</td><td>Réglages les plus protecteurs par défaut</td></tr>\n<tr><td>DPO</td><td>Obligatoire dans certains cas (autorités publiques, suivi à grande échelle)</td></tr>\n<tr><td>Violation de données</td><td>Notification à l'autorité dans les 72 heures ; information des personnes si risque élevé</td></tr></tbody></table></div>\n<h3>Les sanctions</h3>\n<p>Les amendes administratives peuvent atteindre <strong>20 millions d'euros</strong> ou <strong>4 % du chiffre d'affaires annuel mondial</strong>, le montant le plus élevé étant retenu.</p>\n<h3>Les transferts hors UE</h3>\n<p>Les données ne peuvent sortir de l'UE que vers un pays reconnu comme offrant une protection adéquate, ou avec des garanties appropriées (clauses contractuelles types, règles d'entreprise contraignantes).</p>\n<h3>Les autorités</h3>\n<p>Chaque État membre a une autorité de contrôle (en France : la CNIL). Elles coopèrent au sein du Comité européen de la protection des données.</p>","quiz":[{"q":"Le RGPD s'applique aux organismes établis…","o":["Dans l'Union européenne","En Asie uniquement","Nulle part"],"a":0,"e":"Critère d'établissement."},{"q":"Un organisme hors UE est concerné s'il…","o":["Cible des personnes situées dans l'UE","A un site web","Utilise un ordinateur"],"a":0,"e":"Critère de ciblage."},{"q":"Une entreprise ivoirienne recrutant des candidats en France peut être…","o":["Concernée par le RGPD","Jamais concernée","Exonérée"],"a":0,"e":"Exemple."},{"q":"Privacy by design signifie…","o":["Protection dès la conception","Protection après un incident","Design graphique"],"a":0,"e":"Principe."},{"q":"Protection par défaut signifie…","o":["Réglages les plus protecteurs par défaut","Aucune protection","Protection payante"],"a":0,"e":"Principe."},{"q":"Délai de notification d'une violation de données à l'autorité ?","o":["72 heures","30 jours","1 an"],"a":0,"e":"Obligation."},{"q":"Les personnes sont informées d'une violation si…","o":["Le risque est élevé","Toujours, même sans risque","Jamais"],"a":0,"e":"Seuil."},{"q":"Amende maximale en montant fixe ?","o":["20 millions d'euros","1 million d'euros","100 000 euros"],"a":0,"e":"Plafond."},{"q":"Amende maximale en pourcentage ?","o":["4 % du CA annuel mondial","1 % du CA local","10 % du bénéfice"],"a":0,"e":"Plafond."},{"q":"Entre les deux plafonds, on retient…","o":["Le plus élevé","Le plus faible","La moyenne"],"a":0,"e":"Règle."},{"q":"Le DPO est obligatoire notamment pour…","o":["Les autorités publiques","Toutes les petites entreprises","Aucun organisme"],"a":0,"e":"Cas."},{"q":"Un transfert hors UE est possible vers un pays…","o":["À protection adéquate","Quelconque","Sans loi"],"a":0,"e":"Condition."},{"q":"Les clauses contractuelles types sont…","o":["Une garantie pour les transferts","Un contrat de travail","Une amende"],"a":0,"e":"Outil."},{"q":"L'autorité de contrôle française est…","o":["La CNIL","L'ARTCI","La CNPS"],"a":0,"e":"Exemple."},{"q":"Les autorités européennes coopèrent au sein…","o":["Du Comité européen de la protection des données","De l'OIT","De l'ONU"],"a":0,"e":"Coordination."},{"q":"Une filiale d'un groupe européen en Côte d'Ivoire peut…","o":["Être concernée par le RGPD","Être toujours exclue","Ignorer toute règle"],"a":0,"e":"Groupe."},{"q":"Le RGPD renforce le principe de…","o":["Responsabilité","Gratuité","Secret"],"a":0,"e":"Accountability."},{"q":"Suivre le comportement de personnes dans l'UE fait entrer dans…","o":["Le champ du RGPD","Le droit fiscal","Le droit du travail ivoirien seul"],"a":0,"e":"Critère."},{"q":"Les règles d'entreprise contraignantes servent aux…","o":["Transferts intra-groupe","Paies","Recrutements"],"a":0,"e":"BCR."},{"q":"Une violation de données est par exemple…","o":["Une fuite du fichier du personnel","Une augmentation","Un congé"],"a":0,"e":"Exemple."}]},{"id":"mrh309-7","n":7,"t":"Les données dans le cycle RH","min":25,"html":"<h3>Le recrutement</h3>\n<ul><li>Ne collecter que des informations en lien avec le poste et les compétences.</li><li>Informer les candidats (finalité, durée de conservation, droits).</li><li>Conserver les CV non retenus pour une durée limitée, et seulement si le candidat en est informé (ou y consent) pour de futurs postes.</li><li>Les informations recueillies sur les réseaux sociaux doivent rester professionnelles et pertinentes.</li></ul>\n<h3>La gestion du personnel</h3>\n<div class=\"tbl\"><table><thead><tr><th>Donnée</th><th>Légitime ?</th></tr></thead><tbody>\n<tr><td>Identité, coordonnées, n° CNPS</td><td>Oui</td></tr>\n<tr><td>Situation familiale (enfants à charge)</td><td>Oui, pour la paie et les prestations</td></tr>\n<tr><td>Diplômes, formations, évaluations</td><td>Oui</td></tr>\n<tr><td>Aptitude médicale</td><td>Oui (avis d'aptitude), mais pas le dossier médical</td></tr>\n<tr><td>Opinions politiques, religion</td><td>Non</td></tr>\n<tr><td>Vie privée hors travail</td><td>Non, sauf lien direct avec l'emploi</td></tr></tbody></table></div>\n<h3>Le secret médical</h3>\n<p>L'employeur reçoit l'avis d'aptitude ou d'inaptitude du médecin du travail, pas le diagnostic. Le dossier médical reste chez le médecin.</p>\n<h3>Les durées de conservation</h3>\n<p>Elles dépendent de la finalité et des obligations légales : documents de paie et déclarations conservés pendant les délais légaux ; dossier du salarié conservé pendant le contrat puis archivé pour la durée des prescriptions ; CV non retenus supprimés après un délai court.</p>\n<h3>Les accès</h3>\n<p>Le principe du « besoin d'en connaître » : un manager accède aux évaluations de son équipe, pas à leurs salaires détaillés ni à leur situation familiale, sauf nécessité.</p>","quiz":[{"q":"En recrutement, on collecte seulement…","o":["Des informations liées au poste","Toute information disponible","Les opinions politiques"],"a":0,"e":"Minimisation."},{"q":"Les CV non retenus sont conservés…","o":["Pour une durée limitée avec information du candidat","Pour toujours","Jamais, même un jour"],"a":0,"e":"Conservation."},{"q":"Les informations des réseaux sociaux doivent rester…","o":["Professionnelles et pertinentes","Personnelles","Illimitées"],"a":0,"e":"Minimisation."},{"q":"La situation familiale est légitime pour…","o":["La paie et les prestations","La promotion","La sanction"],"a":0,"e":"Finalité."},{"q":"L'employeur peut-il détenir l'avis d'aptitude ?","o":["Oui","Non","Seulement le diagnostic"],"a":0,"e":"Avis seulement."},{"q":"L'employeur peut-il détenir le dossier médical ?","o":["Non","Oui","Oui s'il le demande"],"a":0,"e":"Secret médical."},{"q":"Les opinions politiques dans le dossier RH sont…","o":["Illégitimes","Légitimes","Obligatoires"],"a":0,"e":"Donnée sensible sans lien."},{"q":"La vie privée hors travail est collectée…","o":["Non, sauf lien direct avec l'emploi","Toujours","Pour les cadres"],"a":0,"e":"Principe."},{"q":"Le médecin du travail transmet à l'employeur…","o":["L'avis d'aptitude","Le diagnostic","Le traitement"],"a":0,"e":"Secret."},{"q":"Les diplômes et évaluations sont…","o":["Légitimes","Interdits","Sensibles"],"a":0,"e":"Données professionnelles."},{"q":"Durée de conservation des CV non retenus ?","o":["Courte","Illimitée","Aucune"],"a":0,"e":"Principe."},{"q":"Le dossier du salarié après son départ est…","o":["Archivé pour la durée des prescriptions","Publié","Vendu"],"a":0,"e":"Conservation."},{"q":"Le principe d'accès aux données est…","o":["Le besoin d'en connaître","Tout le monde voit tout","Le hasard"],"a":0,"e":"Principe."},{"q":"Un manager accède en principe…","o":["Aux évaluations de son équipe","Aux salaires détaillés de tous","Aux dossiers médicaux"],"a":0,"e":"Besoin."},{"q":"Le numéro CNPS du salarié est…","o":["Légitime","Illégitime","Sensible interdit"],"a":0,"e":"Nécessaire."},{"q":"Informer les candidats est une obligation de…","o":["Transparence","Paie","Formation"],"a":0,"e":"Principe."},{"q":"Les documents de paie sont conservés…","o":["Pendant les délais légaux","Une semaine","Jamais"],"a":0,"e":"Obligation."},{"q":"La religion du salarié dans le SIRH est…","o":["À exclure","Obligatoire","Utile"],"a":0,"e":"Donnée sensible."},{"q":"Le secret médical protège…","o":["Le diagnostic du salarié","Le salaire","Les évaluations"],"a":0,"e":"Objet."},{"q":"Garder un CV pour de futurs postes suppose…","o":["D'en informer le candidat","Rien","De le publier"],"a":0,"e":"Transparence."}]},{"id":"mrh309-8","n":8,"t":"La surveillance des salariés","min":25,"html":"<p>L'employeur peut contrôler l'activité de ses salariés, mais ce contrôle doit être <strong>justifié</strong> par un intérêt légitime, <strong>proportionné</strong> au but recherché et <strong>transparent</strong>.</p>\n<h3>Les conditions générales</h3>\n<ol><li>Un objectif légitime (sécurité, protection des biens, respect du temps de travail).</li><li>Une information préalable des salariés et des représentants du personnel.</li><li>L'accomplissement des formalités auprès de l'ARTCI.</li><li>Une durée de conservation limitée.</li><li>Un accès restreint aux données collectées.</li></ol>\n<p>Un dispositif caché ou disproportionné ne peut pas, en principe, servir de preuve contre le salarié.</p>\n<h3>Les dispositifs courants</h3>\n<div class=\"tbl\"><table><thead><tr><th>Dispositif</th><th>Admis si…</th><th>Interdit</th></tr></thead><tbody>\n<tr><td>Vidéosurveillance</td><td>Sécurité des entrées, caisses, entrepôts</td><td>Filmer en permanence un poste de travail, les toilettes, les zones de pause</td></tr>\n<tr><td>Géolocalisation des véhicules</td><td>Sécurité, organisation des tournées</td><td>Suivre en dehors du temps de travail</td></tr>\n<tr><td>Contrôle de la messagerie</td><td>Messages professionnels, avec information</td><td>Ouvrir les messages identifiés « personnel » hors procédure</td></tr>\n<tr><td>Biométrie (empreintes)</td><td>Accès à des zones très sensibles, avec autorisation</td><td>Simple contrôle des horaires quand d'autres moyens suffisent</td></tr>\n<tr><td>Logiciels de contrôle d'activité</td><td>Sécurité du système</td><td>Enregistrement permanent des frappes clavier (keylogger)</td></tr></tbody></table></div>\n<h3>La charte informatique</h3>\n<p>Annexée au règlement intérieur, elle fixe les règles d'usage des outils numériques et les contrôles possibles. Elle doit être portée à la connaissance des salariés.</p>","quiz":[{"q":"Le contrôle des salariés doit être…","o":["Justifié, proportionné, transparent","Secret","Illimité"],"a":0,"e":"Conditions."},{"q":"Un objectif légitime de surveillance est…","o":["La sécurité","La curiosité","Le classement des salariés par sympathie"],"a":0,"e":"Exemple."},{"q":"Qui informer avant la mise en place d'un dispositif ?","o":["Les salariés et leurs représentants","Personne","Les clients seulement"],"a":0,"e":"Transparence."},{"q":"Un dispositif caché peut-il servir de preuve ?","o":["En principe non","Oui toujours","Oui s'il est efficace"],"a":0,"e":"Loyauté de la preuve."},{"q":"Filmer en permanence un poste de travail est…","o":["En principe interdit","Recommandé","Obligatoire"],"a":0,"e":"Disproportion."},{"q":"Filmer les toilettes est…","o":["Interdit","Admis","Recommandé"],"a":0,"e":"Atteinte à l'intimité."},{"q":"Filmer les entrées pour la sécurité est…","o":["Admis sous conditions","Interdit","Obligatoire"],"a":0,"e":"But légitime."},{"q":"La géolocalisation hors temps de travail est…","o":["Interdite","Admise","Obligatoire"],"a":0,"e":"Vie privée."},{"q":"Un message identifié « personnel » peut-il être ouvert librement ?","o":["Non","Oui","Toujours"],"a":0,"e":"Secret des correspondances."},{"q":"La biométrie pour contrôler de simples horaires est…","o":["Disproportionnée si d'autres moyens suffisent","Toujours admise","Obligatoire"],"a":0,"e":"Proportionnalité."},{"q":"Un keylogger permanent est…","o":["Interdit","Recommandé","Neutre"],"a":0,"e":"Surveillance excessive."},{"q":"La charte informatique est annexée…","o":["Au règlement intérieur","Au bilan","Au contrat de vente"],"a":0,"e":"Support."},{"q":"La charte informatique fixe…","o":["Les règles d'usage des outils et les contrôles","Les salaires","Les prix"],"a":0,"e":"Contenu."},{"q":"Les images de vidéosurveillance sont conservées…","o":["Pour une durée limitée","Pour toujours","Jamais"],"a":0,"e":"Principe."},{"q":"L'accès aux images doit être…","o":["Restreint","Public","Libre"],"a":0,"e":"Sécurité."},{"q":"Les zones de pause peuvent-elles être filmées en permanence ?","o":["Non","Oui","Seulement le week-end"],"a":0,"e":"Vie privée."},{"q":"La géolocalisation pour organiser des tournées est…","o":["Admise sous conditions","Interdite","Obligatoire"],"a":0,"e":"But légitime."},{"q":"La biométrie nécessite en Côte d'Ivoire…","o":["Une autorisation de l'ARTCI","Rien","Un accord du client"],"a":0,"e":"Donnée sensible."},{"q":"La proportionnalité compare…","o":["Le dispositif au but recherché","Le salaire à l'âge","Le prix au coût"],"a":0,"e":"Principe."},{"q":"La charte doit être…","o":["Portée à la connaissance des salariés","Secrète","Réservée à la direction"],"a":0,"e":"Opposabilité."}]},{"id":"mrh309-9","n":9,"t":"Sous-traitance, cloud et transferts","min":20,"html":"<h3>Recourir à un sous-traitant</h3>\n<p>Beaucoup d'entreprises confient des traitements RH à des prestataires : logiciel de paie en ligne, SIRH en mode SaaS, cabinet de recrutement, plateforme de formation. Le responsable du traitement reste responsable : il doit choisir un sous-traitant qui présente des <strong>garanties suffisantes</strong>.</p>\n<h3>Le contrat de sous-traitance</h3>\n<ul><li>Objet, durée, nature et finalité du traitement.</li><li>Le sous-traitant n'agit que sur instruction documentée du responsable.</li><li>Confidentialité des personnes autorisées.</li><li>Mesures de sécurité.</li><li>Conditions de recours à un autre sous-traitant.</li><li>Aide au responsable pour l'exercice des droits et les violations de données.</li><li>Sort des données en fin de contrat (restitution ou suppression).</li><li>Droit d'audit.</li></ul>\n<h3>Le cloud</h3>\n<p>Stocker des données RH dans le cloud implique de savoir <strong>où</strong> les données sont hébergées (pays, centre de données), <strong>qui</strong> peut y accéder et <strong>comment</strong> elles sont protégées (chiffrement, sauvegardes).</p>\n<h3>Les transferts hors de Côte d'Ivoire</h3>\n<p>La loi ivoirienne encadre le transfert de données vers un pays tiers : il n'est en principe possible que si ce pays assure un niveau de protection suffisant, et il est soumis à l'autorisation préalable de l'ARTCI.</p>\n<div class=\"callout\"><b>Exemple</b>Un groupe dont le SIRH est hébergé en Europe transfère les données des salariés ivoiriens : il doit vérifier les conditions de la loi ivoirienne et obtenir l'autorisation requise.</div>","quiz":[{"q":"Un SIRH en mode SaaS est fourni par…","o":["Un sous-traitant","Le salarié","La CNPS"],"a":0,"e":"Prestataire."},{"q":"Qui reste responsable en cas de sous-traitance ?","o":["Le responsable du traitement","Uniquement le sous-traitant","Personne"],"a":0,"e":"Principe."},{"q":"Le sous-traitant doit présenter…","o":["Des garanties suffisantes","Le prix le plus bas uniquement","Aucune garantie"],"a":0,"e":"Choix."},{"q":"Le sous-traitant agit…","o":["Sur instruction documentée du responsable","Librement","Selon ses intérêts commerciaux"],"a":0,"e":"Principe."},{"q":"Le contrat précise le sort des données…","o":["En fin de contrat","Jamais","Seulement en cas de faillite"],"a":0,"e":"Restitution ou suppression."},{"q":"Le responsable dispose d'un droit…","o":["D'audit","De vente des données","D'effacement du contrat"],"a":0,"e":"Contrôle."},{"q":"Le recours à un autre sous-traitant est…","o":["Encadré par le contrat","Libre","Interdit dans tous les cas"],"a":0,"e":"Sous-traitance ultérieure."},{"q":"Dans le cloud, il faut savoir…","o":["Où sont hébergées les données","Seulement le prix","Rien"],"a":0,"e":"Localisation."},{"q":"Une mesure de protection dans le cloud est…","o":["Le chiffrement","L'accès public","L'absence de sauvegarde"],"a":0,"e":"Sécurité."},{"q":"Un transfert vers un pays tiers exige en Côte d'Ivoire…","o":["L'autorisation préalable de l'ARTCI","Rien","Une simple déclaration fiscale"],"a":0,"e":"Formalité."},{"q":"Le pays destinataire doit assurer…","o":["Un niveau de protection suffisant","Aucune protection","Des impôts bas"],"a":0,"e":"Condition."},{"q":"Un cabinet de recrutement mandaté est…","o":["Un sous-traitant","Le responsable","La personne concernée"],"a":0,"e":"Qualification."},{"q":"Le sous-traitant aide le responsable…","o":["En cas de violation de données","À fixer les salaires","À vendre"],"a":0,"e":"Coopération."},{"q":"La confidentialité des personnes autorisées chez le sous-traitant est…","o":["Prévue au contrat","Facultative","Interdite"],"a":0,"e":"Clause."},{"q":"Qui peut accéder aux données dans le cloud est une question…","o":["Essentielle","Sans importance","Réservée au fournisseur"],"a":0,"e":"Contrôle."},{"q":"Un SIRH hébergé en Europe pour des salariés ivoiriens implique…","o":["Un transfert soumis à la loi ivoirienne","Aucune formalité","L'application exclusive du droit fiscal"],"a":0,"e":"Exemple."},{"q":"La plateforme de formation en ligne est souvent…","o":["Un sous-traitant","Le responsable","Un destinataire public"],"a":0,"e":"Qualification."},{"q":"Les sauvegardes protègent contre…","o":["La perte de données","Les augmentations","Les grèves"],"a":0,"e":"Sécurité."},{"q":"Le contrat de sous-traitance précise la finalité…","o":["Du traitement","De l'entreprise","Du salarié"],"a":0,"e":"Clause."},{"q":"Choisir un prestataire uniquement sur le prix est…","o":["Risqué","Recommandé","Obligatoire"],"a":0,"e":"Garanties insuffisantes."}]},{"id":"mrh309-10","n":10,"t":"Cybersécurité, cybercriminalité et transactions électroniques","min":25,"html":"<h3>La cybercriminalité</h3>\n<p>La loi n° 2013-451 réprime notamment l'accès frauduleux à un système informatique, l'atteinte à l'intégrité des données, l'usurpation d'identité numérique, la fraude informatique et certaines atteintes aux personnes commises en ligne. En Côte d'Ivoire, la <strong>PLCC</strong> (Plateforme de lutte contre la cybercriminalité) reçoit les signalements.</p>\n<h3>Les menaces courantes pour les RH</h3>\n<div class=\"tbl\"><table><thead><tr><th>Menace</th><th>Exemple</th><th>Parade</th></tr></thead><tbody>\n<tr><td>Hameçonnage (phishing)</td><td>Faux e-mail demandant les identifiants du SIRH</td><td>Formation, vérification de l'expéditeur</td></tr>\n<tr><td>Fraude au changement de RIB</td><td>Un « salarié » demande par e-mail de modifier son compte bancaire</td><td>Vérification par un autre canal, procédure écrite</td></tr>\n<tr><td>Rançongiciel</td><td>Fichiers chiffrés, rançon exigée</td><td>Sauvegardes hors ligne, mises à jour</td></tr>\n<tr><td>Fuite interne</td><td>Fichier des salaires envoyé par erreur</td><td>Droits d'accès, vérification des destinataires</td></tr></tbody></table></div>\n<h3>Les bonnes pratiques</h3>\n<ul><li>Mots de passe robustes et uniques, double authentification.</li><li>Mises à jour régulières.</li><li>Sauvegardes testées.</li><li>Droits d'accès revus à chaque mouvement de personnel (fermeture des comptes au départ).</li><li>Sensibilisation régulière des salariés.</li></ul>\n<h3>Les transactions électroniques</h3>\n<p>La loi n° 2013-546 reconnaît la valeur juridique de l'écrit électronique et de la <strong>signature électronique</strong>, sous réserve de garanties sur l'identification du signataire et l'intégrité du document. Cela permet, par exemple, de signer des contrats ou avenants à distance et de dématérialiser des documents RH.</p>\n<div class=\"callout\"><b>Réflexe</b>Toute demande de modification de coordonnées bancaires reçue par e-mail doit être confirmée par un autre canal avant d'être saisie en paie.</div>","quiz":[{"q":"La loi n° 2013-451 réprime…","o":["La cybercriminalité","Le travail au noir","La fraude fiscale"],"a":0,"e":"Objet."},{"q":"L'accès frauduleux à un système informatique est…","o":["Réprimé","Autorisé","Encouragé"],"a":0,"e":"Infraction."},{"q":"La PLCC est…","o":["La Plateforme de lutte contre la cybercriminalité","Un logiciel de paie","Un syndicat"],"a":0,"e":"Signalement."},{"q":"Un faux e-mail demandant les identifiants est…","o":["De l'hameçonnage","Un rançongiciel","Une fuite interne"],"a":0,"e":"Phishing."},{"q":"Parade contre l'hameçonnage ?","o":["Formation et vérification de l'expéditeur","Cliquer rapidement","Partager ses identifiants"],"a":0,"e":"Prévention."},{"q":"Un « salarié » demande par e-mail un changement de RIB :","o":["Vérifier par un autre canal","Modifier immédiatement","Ignorer toute demande à vie"],"a":0,"e":"Fraude au RIB."},{"q":"Un rançongiciel…","o":["Chiffre les fichiers et exige une rançon","Améliore la sécurité","Est un antivirus"],"a":0,"e":"Définition."},{"q":"Parade contre le rançongiciel ?","o":["Sauvegardes hors ligne","Payer la rançon","Supprimer l'antivirus"],"a":0,"e":"Prévention."},{"q":"Envoyer par erreur le fichier des salaires est…","o":["Une fuite interne","Du phishing","Un rançongiciel"],"a":0,"e":"Menace."},{"q":"La double authentification…","o":["Renforce la sécurité des comptes","Affaiblit la sécurité","Est inutile"],"a":0,"e":"Bonne pratique."},{"q":"Au départ d'un salarié, ses comptes doivent être…","o":["Fermés","Conservés actifs","Partagés"],"a":0,"e":"Droits d'accès."},{"q":"Les sauvegardes doivent être…","o":["Testées","Jamais vérifiées","Supprimées"],"a":0,"e":"Fiabilité."},{"q":"La loi n° 2013-546 reconnaît…","o":["La signature électronique","Le travail des enfants","La grève illimitée"],"a":0,"e":"Transactions électroniques."},{"q":"Conditions de validité de la signature électronique ?","o":["Identification du signataire et intégrité","Aucune","Une photo"],"a":0,"e":"Garanties."},{"q":"La signature électronique permet de…","o":["Signer des avenants à distance","Éviter le contrat","Payer moins d'impôts"],"a":0,"e":"Application RH."},{"q":"L'écrit électronique a-t-il une valeur juridique ?","o":["Oui, sous conditions","Non","Seulement en Europe"],"a":0,"e":"Reconnaissance."},{"q":"Les mises à jour régulières…","o":["Corrigent des failles de sécurité","Sont inutiles","Créent des failles"],"a":0,"e":"Bonne pratique."},{"q":"La sensibilisation des salariés doit être…","o":["Régulière","Unique","Inexistante"],"a":0,"e":"Bonne pratique."},{"q":"Un mot de passe doit être…","o":["Robuste et unique","Court et partagé","Le même partout"],"a":0,"e":"Bonne pratique."},{"q":"L'usurpation d'identité numérique est…","o":["Une infraction","Un droit","Une pratique RH"],"a":0,"e":"Cybercriminalité."}]}]},{"id":"mrh310","code":"MRH 310","unit":"lang","title":"Approfondissement des techniques d'expression orales et écrites","summary":"Communiquer avec clarté à l'écrit (courrier, e-mail, notes, comptes rendus, synthèse) et à l'oral (prise de parole, voix, supports, écoute, assertivité).","lessons":[{"id":"mrh310-1","n":1,"t":"Les fondements de la communication","min":20,"html":"<h3>Le schéma de la communication</h3>\n<p>Claude Shannon et Warren Weaver (1949) décrivent la communication comme la transmission d'un message d'un <strong>émetteur</strong> à un <strong>récepteur</strong> par un <strong>canal</strong>, avec un risque de <strong>bruit</strong> (perturbations). On y ajoute le <strong>code</strong> (la langue), le <strong>contexte</strong> et le <strong>feedback</strong> (retour du récepteur).</p>\n<h3>Les fonctions du langage selon Jakobson</h3>\n<div class=\"tbl\"><table><thead><tr><th>Fonction</th><th>Centrée sur</th><th>Exemple</th></tr></thead><tbody>\n<tr><td>Référentielle</td><td>Le contexte, l'information</td><td>« La réunion aura lieu à 10 h. »</td></tr>\n<tr><td>Expressive</td><td>L'émetteur, ses sentiments</td><td>« Je suis ravi de vous accueillir. »</td></tr>\n<tr><td>Conative</td><td>Le récepteur, l'action demandée</td><td>« Merci de confirmer votre présence. »</td></tr>\n<tr><td>Phatique</td><td>Le contact</td><td>« Allô, vous m'entendez ? »</td></tr>\n<tr><td>Métalinguistique</td><td>Le code</td><td>« Par ITS, j'entends l'impôt sur les traitements et salaires. »</td></tr>\n<tr><td>Poétique</td><td>La forme du message</td><td>Un slogan rythmé</td></tr></tbody></table></div>\n<h3>Verbal, paraverbal, non-verbal</h3>\n<p>Le <strong>verbal</strong> est le choix des mots ; le <strong>paraverbal</strong>, la voix (ton, débit, volume) ; le <strong>non-verbal</strong>, le corps (regard, posture, gestes). Les études d'Albert Mehrabian sont souvent citées pour dire que « 93 % de la communication est non verbale » : c'est une généralisation abusive d'expériences limitées à l'expression de sentiments. Retenez que le ton et le corps doivent être cohérents avec les mots.</p>\n<h3>Les obstacles</h3>\n<p>Bruit, jargon, différences culturelles, émotions, préjugés, surcharge d'informations, absence de feedback.</p>","quiz":[{"q":"Qui a proposé le modèle émetteur-canal-récepteur ?","o":["Shannon et Weaver","Jakobson","Mehrabian"],"a":0,"e":"1949."},{"q":"Le bruit dans la communication est…","o":["Une perturbation","Le message","Le récepteur"],"a":0,"e":"Définition."},{"q":"Le feedback est…","o":["Le retour du récepteur","Le canal","Le code"],"a":0,"e":"Définition."},{"q":"Le code est…","o":["La langue utilisée","Le bruit","L'émetteur"],"a":0,"e":"Définition."},{"q":"Combien de fonctions du langage chez Jakobson ?","o":["Six","Trois","Dix"],"a":0,"e":"Modèle."},{"q":"« La réunion aura lieu à 10 h » : fonction…","o":["Référentielle","Expressive","Phatique"],"a":0,"e":"Information."},{"q":"« Je suis ravi de vous accueillir » : fonction…","o":["Expressive","Conative","Référentielle"],"a":0,"e":"Émetteur."},{"q":"« Merci de confirmer votre présence » : fonction…","o":["Conative","Phatique","Poétique"],"a":0,"e":"Action demandée."},{"q":"« Allô, vous m'entendez ? » : fonction…","o":["Phatique","Référentielle","Expressive"],"a":0,"e":"Contact."},{"q":"Expliquer un sigle relève de la fonction…","o":["Métalinguistique","Poétique","Conative"],"a":0,"e":"Code."},{"q":"Un slogan rythmé relève de la fonction…","o":["Poétique","Phatique","Référentielle"],"a":0,"e":"Forme."},{"q":"Le paraverbal concerne…","o":["La voix","Les mots","Les gestes"],"a":0,"e":"Ton, débit, volume."},{"q":"Le non-verbal concerne…","o":["Le corps","Les mots","L'orthographe"],"a":0,"e":"Regard, posture."},{"q":"Le verbal concerne…","o":["Le choix des mots","La voix","Les gestes"],"a":0,"e":"Définition."},{"q":"La règle des « 93 % non verbal » est…","o":["Une généralisation abusive","Une loi scientifique universelle","Un article du Code du travail"],"a":0,"e":"Mehrabian."},{"q":"Les expériences de Mehrabian portaient sur…","o":["L'expression de sentiments","Les négociations commerciales","Les discours politiques"],"a":0,"e":"Limites."},{"q":"À retenir de Mehrabian ?","o":["Ton et corps doivent être cohérents avec les mots","Les mots ne comptent pas","Seule la voix compte"],"a":0,"e":"Cohérence."},{"q":"Le jargon est…","o":["Un obstacle","Un facilitateur universel","Obligatoire"],"a":0,"e":"Obstacle."},{"q":"L'absence de feedback…","o":["Empêche de vérifier la compréhension","Améliore la communication","N'a aucun effet"],"a":0,"e":"Obstacle."},{"q":"Le contexte influence…","o":["L'interprétation du message","Rien","Seulement le canal"],"a":0,"e":"Élément du schéma."}]},{"id":"mrh310-2","n":2,"t":"Écrire pour être lu","min":20,"html":"<h3>Avant d'écrire</h3>\n<p>Répondez à trois questions : <strong>Qui</strong> va lire ? <strong>Pourquoi</strong> j'écris (informer, demander, convaincre) ? <strong>Que</strong> doit faire ou retenir le lecteur ?</p>\n<h3>La méthode QQOQCCP</h3>\n<p>Pour ne rien oublier : Qui ? Quoi ? Où ? Quand ? Comment ? Combien ? Pourquoi ?</p>\n<h3>Structurer</h3>\n<ul><li>Commencez par l'essentiel (principe de la <strong>pyramide inversée</strong> : l'information la plus importante d'abord).</li><li>Un paragraphe = une idée.</li><li>Des intertitres et des listes pour les documents longs.</li></ul>\n<h3>Rédiger clairement</h3>\n<div class=\"tbl\"><table><thead><tr><th>À éviter</th><th>À préférer</th></tr></thead><tbody>\n<tr><td>Phrases de plus de 25 mots</td><td>Phrases de 15 à 20 mots en moyenne</td></tr>\n<tr><td>Voix passive (« La demande a été traitée par le service »)</td><td>Voix active (« Le service a traité la demande »)</td></tr>\n<tr><td>Nominalisations (« procéder à la vérification »)</td><td>Verbes (« vérifier »)</td></tr>\n<tr><td>Jargon, sigles non expliqués</td><td>Mots courants, sigle développé à la première occurrence</td></tr>\n<tr><td>Formules creuses (« il convient de noter que »)</td><td>Aller droit au fait</td></tr></tbody></table></div>\n<h3>Relire</h3>\n<p>Relisez au moins deux fois : une fois pour le fond (tout y est ? c'est juste ?), une fois pour la forme (orthographe, accords, ponctuation). Lire à voix haute aide à repérer les phrases trop longues.</p>","quiz":[{"q":"Trois questions avant d'écrire ?","o":["Qui lit, pourquoi j'écris, que doit faire le lecteur","Combien de pages, quelle police, quelle couleur","Aucune"],"a":0,"e":"Préparation."},{"q":"QQOQCCP sert à…","o":["Ne rien oublier","Compter les mots","Choisir la police"],"a":0,"e":"Check-list."},{"q":"Le premier « Q » de QQOQCCP ?","o":["Qui","Quel","Quand"],"a":0,"e":"Ordre."},{"q":"La pyramide inversée place…","o":["L'essentiel d'abord","L'essentiel à la fin","Les détails d'abord"],"a":0,"e":"Principe."},{"q":"Un paragraphe contient…","o":["Une idée","Toutes les idées","Aucune idée"],"a":0,"e":"Règle."},{"q":"Longueur moyenne recommandée d'une phrase ?","o":["15 à 20 mots","50 mots","5 mots"],"a":0,"e":"Lisibilité."},{"q":"« La demande a été traitée par le service » est à la voix…","o":["Passive","Active","Pronominale"],"a":0,"e":"Forme."},{"q":"Version active ?","o":["« Le service a traité la demande »","« La demande est traitée »","« Traitement de la demande »"],"a":0,"e":"Réécriture."},{"q":"« Procéder à la vérification » est…","o":["Une nominalisation","Un verbe simple","Un sigle"],"a":0,"e":"Lourdeur."},{"q":"Remplacer « procéder à la vérification » par…","o":["« Vérifier »","« Faire la procédure de vérification »","« Vérification procédée »"],"a":0,"e":"Simplification."},{"q":"Un sigle doit être développé…","o":["À la première occurrence","Jamais","À la fin"],"a":0,"e":"Clarté."},{"q":"« Il convient de noter que » est…","o":["Une formule creuse","Indispensable","Un titre"],"a":0,"e":"À éviter."},{"q":"Combien de relectures au minimum ?","o":["Deux","Aucune","Dix"],"a":0,"e":"Fond et forme."},{"q":"La première relecture porte sur…","o":["Le fond","L'orthographe seulement","La police"],"a":0,"e":"Contenu."},{"q":"La seconde relecture porte sur…","o":["La forme","Le fond","Le destinataire"],"a":0,"e":"Orthographe, ponctuation."},{"q":"Lire à voix haute aide à repérer…","o":["Les phrases trop longues","Les couleurs","Les pièces jointes"],"a":0,"e":"Rythme."},{"q":"Des intertitres conviennent aux…","o":["Documents longs","SMS","Signatures"],"a":0,"e":"Structure."},{"q":"Pourquoi j'écris peut être…","o":["Informer, demander, convaincre","Remplir une page","Occuper le temps"],"a":0,"e":"Objectifs."},{"q":"Le dernier « P » de QQOQCCP ?","o":["Pourquoi","Prix","Plan"],"a":0,"e":"Ordre."},{"q":"Un écrit clair fait gagner du temps…","o":["Au lecteur","À personne","Seulement à l'auteur"],"a":0,"e":"Efficacité."}]},{"id":"mrh310-3","n":3,"t":"Le courrier professionnel","min":25,"html":"<h3>La présentation d'une lettre</h3>\n<div class=\"tbl\"><table><thead><tr><th>Élément</th><th>Position habituelle</th></tr></thead><tbody>\n<tr><td>Expéditeur (en-tête)</td><td>En haut à gauche</td></tr>\n<tr><td>Destinataire</td><td>À droite, sous l'expéditeur</td></tr>\n<tr><td>Lieu et date</td><td>À droite (« Abidjan, le 25 septembre 2026 »)</td></tr>\n<tr><td>Références (V/Réf., N/Réf.)</td><td>À gauche</td></tr>\n<tr><td>Objet</td><td>À gauche, avant la formule d'appel</td></tr>\n<tr><td>Pièces jointes (P.J.)</td><td>À gauche, en fin de lettre</td></tr>\n<tr><td>Formule d'appel</td><td>« Madame, », « Monsieur, », « Madame la Directrice, »</td></tr>\n<tr><td>Corps de la lettre</td><td>Introduction, développement, conclusion</td></tr>\n<tr><td>Formule de politesse</td><td>Fin de lettre</td></tr>\n<tr><td>Signature</td><td>Nom, fonction, signature</td></tr></tbody></table></div>\n<h3>Le corps de la lettre</h3>\n<ol><li><strong>Introduction</strong> : le rappel du contexte (« Suite à votre demande du 12 septembre… »).</li><li><strong>Développement</strong> : l'information, la réponse ou la demande.</li><li><strong>Conclusion</strong> : l'action attendue ou la suite (« Je vous remercie de bien vouloir… »).</li></ol>\n<h3>La formule de politesse</h3>\n<p>Elle reprend exactement la formule d'appel : « Veuillez agréer, <strong>Madame</strong>, l'expression de mes salutations distinguées. » On évite de mêler « sentiments » et « salutations ». Une femme qui écrit évite traditionnellement d'exprimer des « sentiments » à un homme et préfère « salutations ».</p>\n<h3>Les courriers RH fréquents</h3>\n<p>Lettre d'embauche, attestation de travail, convocation à un entretien préalable, notification de sanction, réponse à un candidat, lettre de félicitations.</p>\n<div class=\"callout\"><b>Envoi recommandé</b>Les courriers ayant des effets juridiques (sanction, licenciement) sont remis en main propre contre décharge ou envoyés en recommandé avec accusé de réception, pour prouver la date de notification.</div>","quiz":[{"q":"Où place-t-on l'expéditeur ?","o":["En haut à gauche","En bas à droite","Au centre"],"a":0,"e":"En-tête."},{"q":"Où place-t-on le destinataire ?","o":["À droite","À gauche en bas","Nulle part"],"a":0,"e":"Présentation."},{"q":"Formule correcte de lieu et date ?","o":["« Abidjan, le 25 septembre 2026 »","« 25/09 Abidjan »","« Le Abidjan 2026 »"],"a":0,"e":"Usage."},{"q":"L'objet se place…","o":["Avant la formule d'appel","Après la signature","Dans la formule de politesse"],"a":0,"e":"Ordre."},{"q":"P.J. signifie…","o":["Pièces jointes","Personne juridique","Procès judiciaire"],"a":0,"e":"Abréviation."},{"q":"Une formule d'appel correcte ?","o":["« Madame, »","« Salut, »","« Cher ami, » pour un inconnu"],"a":0,"e":"Registre."},{"q":"L'introduction du corps rappelle…","o":["Le contexte","La signature","Les pièces jointes"],"a":0,"e":"Structure."},{"q":"La conclusion indique…","o":["L'action attendue ou la suite","Le lieu","Les références"],"a":0,"e":"Structure."},{"q":"La formule de politesse reprend…","o":["La formule d'appel","L'objet","La date"],"a":0,"e":"Cohérence."},{"q":"Si l'appel est « Monsieur, », la politesse dit…","o":["« Veuillez agréer, Monsieur, … »","« Veuillez agréer, Madame, … »","« Bisous »"],"a":0,"e":"Reprise exacte."},{"q":"Faut-il mêler « sentiments » et « salutations » ?","o":["Non","Oui","Toujours"],"a":0,"e":"Maladresse."},{"q":"La signature comprend…","o":["Nom, fonction, signature","Seulement un prénom","Rien"],"a":0,"e":"Éléments."},{"q":"V/Réf. désigne…","o":["La référence du destinataire","Le vendeur","La version"],"a":0,"e":"Votre référence."},{"q":"N/Réf. désigne…","o":["Notre référence","Nouvelle référence","Numéro de facture"],"a":0,"e":"Référence de l'expéditeur."},{"q":"Un courrier RH fréquent est…","o":["La convocation à un entretien préalable","Une facture","Un bon de commande"],"a":0,"e":"Exemple."},{"q":"Une notification de sanction est envoyée…","o":["En recommandé ou remise contre décharge","Par SMS uniquement","Oralement"],"a":0,"e":"Preuve."},{"q":"Pourquoi le recommandé avec accusé de réception ?","o":["Prouver la date de notification","Aller plus vite","Réduire le coût"],"a":0,"e":"Preuve."},{"q":"« Suite à votre demande du 12 septembre » est…","o":["Une introduction","Une conclusion","Une signature"],"a":0,"e":"Contexte."},{"q":"« Je vous remercie de bien vouloir… » est…","o":["Une conclusion","Un objet","Une référence"],"a":0,"e":"Action attendue."},{"q":"Combien de parties dans le corps de la lettre ?","o":["Trois","Une","Cinq"],"a":0,"e":"Introduction, développement, conclusion."}]},{"id":"mrh310-4","n":4,"t":"L'e-mail professionnel","min":20,"html":"<h3>L'objet</h3>\n<p>Précis et informatif : « Validation des heures supplémentaires de septembre – réponse avant le 20 » plutôt que « Question » ou « Urgent ».</p>\n<h3>Les destinataires</h3>\n<div class=\"tbl\"><table><thead><tr><th>Champ</th><th>Usage</th></tr></thead><tbody>\n<tr><td>À</td><td>Les personnes qui doivent agir ou répondre</td></tr>\n<tr><td>Cc (copie carbone)</td><td>Les personnes informées, sans action attendue</td></tr>\n<tr><td>Cci (copie cachée)</td><td>Destinataires invisibles des autres ; utile pour un envoi groupé à des personnes extérieures qui ne se connaissent pas</td></tr></tbody></table></div>\n<p>« Répondre à tous » ne s'utilise que si tous les destinataires ont besoin de la réponse.</p>\n<h3>Le corps</h3>\n<ul><li>Une formule d'appel adaptée (« Bonjour Madame Koné, »).</li><li>L'essentiel dans les deux premières lignes.</li><li>Un e-mail = un sujet.</li><li>Des paragraphes courts, une demande claire avec une échéance.</li><li>Une formule de clôture (« Cordialement, ») et une signature complète.</li></ul>\n<h3>Les pièges</h3>\n<ul><li>Écrire sous le coup de l'émotion : attendez avant d'envoyer.</li><li>Les majuscules, perçues comme des cris.</li><li>Les données sensibles (salaires, santé) envoyées sans protection ou au mauvais destinataire.</li><li>L'oubli de la pièce jointe annoncée.</li></ul>\n<div class=\"callout\"><b>Règle</b>N'écrivez jamais dans un e-mail ce que vous ne voudriez pas voir transféré à toute l'entreprise.</div>","quiz":[{"q":"Un bon objet d'e-mail est…","o":["Précis et informatif","« Question »","« Urgent » seul"],"a":0,"e":"Clarté."},{"q":"Le champ « À » est pour…","o":["Ceux qui doivent agir ou répondre","Les personnes simplement informées","Les destinataires cachés"],"a":0,"e":"Usage."},{"q":"Le champ « Cc » est pour…","o":["Les personnes informées","Ceux qui doivent agir","Les destinataires cachés"],"a":0,"e":"Usage."},{"q":"Le champ « Cci » rend les destinataires…","o":["Invisibles des autres","Prioritaires","Responsables"],"a":0,"e":"Copie cachée."},{"q":"Envoi groupé à des externes qui ne se connaissent pas : champ…","o":["Cci","À","Cc"],"a":0,"e":"Confidentialité des adresses."},{"q":"« Répondre à tous » s'utilise…","o":["Si tous ont besoin de la réponse","Toujours","Jamais"],"a":0,"e":"Usage."},{"q":"Où placer l'essentiel ?","o":["Dans les deux premières lignes","À la fin","En pièce jointe"],"a":0,"e":"Efficacité."},{"q":"Combien de sujets par e-mail ?","o":["Un","Cinq","Autant que possible"],"a":0,"e":"Règle."},{"q":"Une demande claire comprend…","o":["Une échéance","Un smiley","Un proverbe"],"a":0,"e":"Action."},{"q":"Une formule de clôture courante est…","o":["« Cordialement, »","« Salut »","« Ciao »"],"a":0,"e":"Usage."},{"q":"Écrire sous le coup de l'émotion…","o":["Est à éviter","Est recommandé","Est obligatoire"],"a":0,"e":"Piège."},{"q":"Les majuscules sont perçues comme…","o":["Des cris","De la politesse","De l'élégance"],"a":0,"e":"Piège."},{"q":"Envoyer des salaires sans protection est…","o":["Un risque","Une bonne pratique","Neutre"],"a":0,"e":"Donnée sensible."},{"q":"Oublier la pièce jointe annoncée est…","o":["Un piège fréquent","Recommandé","Impossible"],"a":0,"e":"Vérifier."},{"q":"Règle d'or de l'e-mail ?","o":["Ne rien écrire qu'on ne voudrait pas voir transféré","Tout écrire","Écrire en majuscules"],"a":0,"e":"Prudence."},{"q":"La signature d'un e-mail doit être…","o":["Complète","Absente","Un surnom"],"a":0,"e":"Nom, fonction, contacts."},{"q":"« Bonjour Madame Koné, » est…","o":["Une formule d'appel adaptée","Trop familière","Interdite"],"a":0,"e":"Usage."},{"q":"Des paragraphes courts facilitent…","o":["La lecture","L'oubli","Le spam"],"a":0,"e":"Lisibilité."},{"q":"Un objet « Urgent » seul est…","o":["Insuffisant","Parfait","Obligatoire"],"a":0,"e":"Imprécis."},{"q":"Avant d'envoyer un e-mail tendu, il faut…","o":["Attendre et relire","Envoyer vite","Mettre tout le monde en copie"],"a":0,"e":"Recul."}]},{"id":"mrh310-5","n":5,"t":"La note de service et la note d'information","min":20,"html":"<h3>La note de service</h3>\n<p>Elle transmet une <strong>instruction</strong> ou une <strong>décision</strong> de la hiérarchie vers le personnel. Elle a un caractère obligatoire.</p>\n<h3>La note d'information</h3>\n<p>Elle <strong>informe</strong> sans donner d'ordre : un événement, un changement, un rappel.</p>\n<h3>La structure</h3>\n<ol><li>En-tête : nom de l'entreprise, service émetteur, numéro de la note, lieu et date.</li><li>Destinataires (« À l'ensemble du personnel », « Aux chefs de service »).</li><li>Objet.</li><li>Corps : le contexte (une phrase), la décision ou l'information, les modalités pratiques (qui, quand, comment), la date d'effet.</li><li>Signature de l'autorité compétente, avec sa fonction.</li></ol>\n<p>Pas de formule d'appel ni de formule de politesse développée.</p>\n<h3>Le style</h3>\n<ul><li>Neutre, impersonnel, concis.</li><li>Le présent ou le futur de l'indicatif.</li><li>Des formules comme « Il est demandé à… », « À compter du… ».</li></ul>\n<h3>Exemple</h3>\n<div class=\"callout\"><b>Note de service n° 2026-014</b>Destinataires : ensemble du personnel. Objet : horaires pendant les travaux. En raison des travaux de rénovation du bâtiment B, les bureaux du service RH seront transférés au rez-de-chaussée du bâtiment A du 5 au 30 octobre 2026. Les horaires d'accueil restent inchangés (8 h – 12 h, 14 h – 17 h). Signé : la Directrice des ressources humaines.</div>\n<h3>La diffusion</h3>\n<p>Affichage, messagerie, intranet, remise en main propre contre émargement pour les décisions importantes.</p>","quiz":[{"q":"La note de service transmet…","o":["Une instruction ou une décision","Une simple information sans portée","Une facture"],"a":0,"e":"Définition."},{"q":"La note d'information…","o":["Informe sans ordonner","Ordonne","Sanctionne"],"a":0,"e":"Définition."},{"q":"La note de service a un caractère…","o":["Obligatoire","Facultatif","Commercial"],"a":0,"e":"Portée."},{"q":"L'en-tête comprend…","o":["Le numéro de la note","La formule de politesse","Un proverbe"],"a":0,"e":"Structure."},{"q":"« À l'ensemble du personnel » indique…","o":["Les destinataires","L'objet","La signature"],"a":0,"e":"Structure."},{"q":"La note contient-elle une formule d'appel ?","o":["Non","Oui","Seulement le lundi"],"a":0,"e":"Particularité."},{"q":"Le style de la note est…","o":["Neutre et concis","Familier","Poétique"],"a":0,"e":"Registre."},{"q":"Temps recommandés ?","o":["Présent ou futur de l'indicatif","Passé simple","Subjonctif imparfait"],"a":0,"e":"Usage."},{"q":"« À compter du… » indique…","o":["La date d'effet","La signature","Le destinataire"],"a":0,"e":"Formule."},{"q":"Qui signe la note ?","o":["L'autorité compétente","N'importe quel salarié","Le client"],"a":0,"e":"Légitimité."},{"q":"Dans l'exemple, le transfert des bureaux dure…","o":["Du 5 au 30 octobre 2026","Un an","Une journée"],"a":0,"e":"Lecture."},{"q":"Dans l'exemple, les horaires d'accueil…","o":["Restent inchangés","Sont supprimés","Sont doublés"],"a":0,"e":"Lecture."},{"q":"Le corps commence par…","o":["Le contexte en une phrase","La signature","Les remerciements"],"a":0,"e":"Structure."},{"q":"Les modalités pratiques précisent…","o":["Qui, quand, comment","Le salaire du DG","Le bilan"],"a":0,"e":"Structure."},{"q":"Pour une décision importante, la remise se fait…","o":["Contre émargement","Par rumeur","Jamais"],"a":0,"e":"Preuve."},{"q":"« Il est demandé à… » est une formule…","o":["Impersonnelle","Familière","Poétique"],"a":0,"e":"Style."},{"q":"Un moyen de diffusion est…","o":["L'affichage","La publicité télévisée","Le courrier du client"],"a":0,"e":"Canal."},{"q":"Un rappel des règles de sécurité peut faire l'objet…","o":["D'une note d'information ou de service","D'un contrat de vente","D'un bilan"],"a":0,"e":"Usage."},{"q":"L'objet d'une note doit être…","o":["Précis","Absent","Long d'une page"],"a":0,"e":"Clarté."},{"q":"La formule de politesse développée est…","o":["Absente de la note","Obligatoire","Placée en en-tête"],"a":0,"e":"Particularité."}]},{"id":"mrh310-6","n":6,"t":"Le compte rendu et le procès-verbal","min":25,"html":"<h3>Le compte rendu</h3>\n<p>Il restitue de façon <strong>fidèle, objective et synthétique</strong> ce qui s'est dit ou passé lors d'une réunion, d'une visite, d'un événement. Il sélectionne l'essentiel et le réorganise par thème.</p>\n<h3>Le procès-verbal</h3>\n<p>Il a une <strong>valeur juridique</strong> : il fait foi de ce qui a été dit et décidé. Il est plus exhaustif, suit l'ordre chronologique des débats, attribue les propos à leurs auteurs et est souvent signé ou approuvé par les participants (réunions des délégués, assemblées générales, conseils de discipline).</p>\n<div class=\"tbl\"><table><thead><tr><th></th><th>Compte rendu</th><th>Procès-verbal</th></tr></thead><tbody>\n<tr><td>Valeur</td><td>Informative</td><td>Juridique, fait foi</td></tr>\n<tr><td>Contenu</td><td>Sélection de l'essentiel</td><td>Plus exhaustif</td></tr>\n<tr><td>Ordre</td><td>Thématique possible</td><td>Chronologique</td></tr>\n<tr><td>Signature</td><td>Pas toujours</td><td>Souvent signé ou approuvé</td></tr></tbody></table></div>\n<h3>La structure d'un compte rendu de réunion</h3>\n<ol><li>Titre, date, lieu, heure.</li><li>Présents, absents excusés, rédacteur.</li><li>Ordre du jour.</li><li>Pour chaque point : échanges essentiels, décisions.</li><li>Tableau des actions : quoi, qui, quand.</li><li>Date de la prochaine réunion.</li></ol>\n<h3>Le style</h3>\n<p>Neutre, au présent ou au passé composé, au discours indirect (« Le DRH indique que… »). Pas de jugement personnel du rédacteur. Les verbes introducteurs nuancent : <em>affirmer, proposer, rappeler, souligner, s'interroger, contester</em>.</p>\n<h3>La prise de notes</h3>\n<p>Notez les mots-clés, les chiffres, les décisions ; utilisez des abréviations ; rédigez le compte rendu dans les 24 heures, tant que la mémoire est fraîche.</p>","quiz":[{"q":"Le compte rendu doit être…","o":["Fidèle, objectif, synthétique","Personnel et subjectif","Exhaustif mot à mot"],"a":0,"e":"Qualités."},{"q":"Le procès-verbal a une valeur…","o":["Juridique","Décorative","Commerciale"],"a":0,"e":"Fait foi."},{"q":"Quel document est plus exhaustif ?","o":["Le procès-verbal","Le compte rendu","La note de service"],"a":0,"e":"Comparaison."},{"q":"Le procès-verbal suit l'ordre…","o":["Chronologique","Alphabétique","Thématique obligatoirement"],"a":0,"e":"Débats."},{"q":"Le compte rendu peut suivre un ordre…","o":["Thématique","Aléatoire","Inversé obligatoire"],"a":0,"e":"Réorganisation."},{"q":"Le procès-verbal est souvent…","o":["Signé ou approuvé","Anonyme","Secret"],"a":0,"e":"Validation."},{"q":"Une réunion des délégués donne souvent lieu à…","o":["Un procès-verbal","Une facture","Un bilan"],"a":0,"e":"Exemple."},{"q":"Le compte rendu mentionne…","o":["Présents et absents excusés","Les salaires des présents","Les opinions du rédacteur"],"a":0,"e":"Structure."},{"q":"Le tableau des actions indique…","o":["Quoi, qui, quand","Le menu","La météo"],"a":0,"e":"Suivi."},{"q":"Le style du compte rendu est…","o":["Neutre","Humoristique","Polémique"],"a":0,"e":"Objectivité."},{"q":"« Le DRH indique que… » est au discours…","o":["Indirect","Direct","Poétique"],"a":0,"e":"Style."},{"q":"Le rédacteur donne-t-il son avis ?","o":["Non","Oui","Toujours"],"a":0,"e":"Neutralité."},{"q":"« Contester » est un verbe…","o":["Introducteur qui nuance","Interdit","Sans sens"],"a":0,"e":"Nuance."},{"q":"En prise de notes, on note…","o":["Mots-clés, chiffres, décisions","Chaque mot","Rien"],"a":0,"e":"Méthode."},{"q":"Délai recommandé de rédaction ?","o":["24 heures","Un mois","Un an"],"a":0,"e":"Mémoire fraîche."},{"q":"Le compte rendu se termine par…","o":["La date de la prochaine réunion","La formule de politesse","Une blague"],"a":0,"e":"Structure."},{"q":"Le PV attribue les propos…","o":["À leurs auteurs","À personne","Au rédacteur"],"a":0,"e":"Précision."},{"q":"Le compte rendu sélectionne…","o":["L'essentiel","Tout","Rien"],"a":0,"e":"Synthèse."},{"q":"Un conseil de discipline donne lieu à…","o":["Un procès-verbal","Un e-mail informel","Rien"],"a":0,"e":"Enjeu juridique."},{"q":"Les abréviations en prise de notes…","o":["Font gagner du temps","Sont interdites","Doivent être publiées"],"a":0,"e":"Méthode."}]},{"id":"mrh310-7","n":7,"t":"La note de synthèse","min":25,"html":"<p>La note de synthèse présente de façon <strong>objective, ordonnée et concise</strong> l'essentiel d'un ensemble de documents, pour permettre à un décideur de comprendre rapidement une question.</p>\n<h3>La méthode</h3>\n<ol><li><strong>Lire la consigne</strong> : sujet, destinataire, longueur.</li><li><strong>Survoler le dossier</strong> : titres, sources, dates.</li><li><strong>Lire en profondeur</strong> et relever les idées essentielles de chaque document.</li><li><strong>Construire un tableau</strong> de confrontation : idées en lignes, documents en colonnes.</li><li><strong>Bâtir un plan</strong> en deux ou trois parties, avec des sous-parties.</li><li><strong>Rédiger</strong> l'introduction, le développement et, si demandé, une conclusion.</li></ol>\n<h3>L'introduction</h3>\n<p>Une phrase d'accroche liée à l'actualité ou au contexte, la problématique (la question centrale), l'annonce du plan.</p>\n<h3>Les règles</h3>\n<ul><li>N'utiliser que les informations du dossier ; pas de connaissances personnelles ni d'opinion (sauf consigne contraire).</li><li>Citer les documents entre parenthèses (Doc. 2).</li><li>Traiter tous les documents.</li><li>Respecter la longueur demandée (par exemple 2 pages).</li><li>Des titres apparents pour les parties.</li></ul>\n<h3>Types de plans</h3>\n<div class=\"tbl\"><table><thead><tr><th>Plan</th><th>Structure</th></tr></thead><tbody>\n<tr><td>Constat / causes / solutions</td><td>Utile pour un problème</td></tr>\n<tr><td>Avantages / inconvénients</td><td>Utile pour évaluer une mesure</td></tr>\n<tr><td>Enjeux / moyens</td><td>Utile pour un projet</td></tr></tbody></table></div>","quiz":[{"q":"La note de synthèse est…","o":["Objective, ordonnée, concise","Personnelle et engagée","Exhaustive et longue"],"a":0,"e":"Qualités."},{"q":"Son objectif est d'aider…","o":["Un décideur à comprendre rapidement","Un client à acheter","Un salarié à se détendre"],"a":0,"e":"Finalité."},{"q":"Première étape de la méthode ?","o":["Lire la consigne","Rédiger","Faire le plan"],"a":0,"e":"Ordre."},{"q":"Le tableau de confrontation croise…","o":["Idées et documents","Salaires et âges","Dates et lieux"],"a":0,"e":"Outil."},{"q":"Nombre de parties recommandé ?","o":["Deux ou trois","Dix","Une seule"],"a":0,"e":"Plan."},{"q":"L'introduction comprend…","o":["Accroche, problématique, annonce du plan","Seulement la conclusion","La signature"],"a":0,"e":"Structure."},{"q":"La problématique est…","o":["La question centrale","Une liste de documents","Le titre du dossier"],"a":0,"e":"Définition."},{"q":"Peut-on ajouter ses connaissances personnelles ?","o":["Non, sauf consigne","Oui toujours","Oui, c'est obligatoire"],"a":0,"e":"Règle."},{"q":"Peut-on donner son opinion ?","o":["Non, sauf consigne","Oui toujours","Oui en conclusion obligatoire"],"a":0,"e":"Objectivité."},{"q":"Comment citer un document ?","o":["(Doc. 2)","En note de bas de page de 3 lignes","Pas besoin"],"a":0,"e":"Usage."},{"q":"Faut-il traiter tous les documents ?","o":["Oui","Non","Seulement le premier"],"a":0,"e":"Règle."},{"q":"La longueur demandée doit être…","o":["Respectée","Dépassée","Ignorée"],"a":0,"e":"Règle."},{"q":"Les titres des parties doivent être…","o":["Apparents","Cachés","Absents"],"a":0,"e":"Lisibilité."},{"q":"Plan adapté à un problème ?","o":["Constat / causes / solutions","Chronologie de l'univers","Ordre alphabétique"],"a":0,"e":"Type."},{"q":"Plan adapté pour évaluer une mesure ?","o":["Avantages / inconvénients","Constat / causes","Introduction seule"],"a":0,"e":"Type."},{"q":"Plan adapté à un projet ?","o":["Enjeux / moyens","Avantages / avantages","Aucun"],"a":0,"e":"Type."},{"q":"Survoler le dossier consiste à regarder…","o":["Titres, sources, dates","Seulement les images","Rien"],"a":0,"e":"Repérage."},{"q":"L'accroche est liée…","o":["Au contexte ou à l'actualité","À une blague","Au rédacteur"],"a":0,"e":"Introduction."},{"q":"La lecture en profondeur sert à…","o":["Relever les idées essentielles","Compter les mots","Colorier"],"a":0,"e":"Méthode."},{"q":"La conclusion est rédigée…","o":["Si elle est demandée","Jamais","Avant l'introduction"],"a":0,"e":"Selon la consigne."}]},{"id":"mrh310-8","n":8,"t":"Préparer une prise de parole","min":20,"html":"<h3>Analyser la situation</h3>\n<ul><li><strong>Le public</strong> : qui, combien, que savent-ils, qu'attendent-ils ?</li><li><strong>L'objectif</strong> : informer, convaincre, former, fédérer ?</li><li><strong>Le cadre</strong> : durée, lieu, matériel, moment de la journée.</li></ul>\n<h3>Définir le message clé</h3>\n<p>Si le public ne devait retenir qu'une phrase, laquelle ? Tout le reste sert ce message.</p>\n<h3>Structurer</h3>\n<div class=\"tbl\"><table><thead><tr><th>Partie</th><th>Contenu</th><th>Part du temps</th></tr></thead><tbody>\n<tr><td>Introduction</td><td>Accroche, objectif, plan</td><td>Environ 10 %</td></tr>\n<tr><td>Développement</td><td>2 ou 3 idées, chacune illustrée</td><td>Environ 80 %</td></tr>\n<tr><td>Conclusion</td><td>Résumé, message clé, appel à l'action</td><td>Environ 10 %</td></tr></tbody></table></div>\n<h3>Les accroches</h3>\n<p>Une question au public, un chiffre marquant, une anecdote, une citation, une image.</p>\n<h3>Répéter</h3>\n<p>Répétez à voix haute, debout, chronomètre en main, au moins trois fois. Préparez des fiches avec des mots-clés, pas un texte à lire.</p>\n<h3>Gérer le trac</h3>\n<p>Le trac est normal : c'est une réaction de stress qui mobilise l'énergie. Pour le maîtriser : bien préparer l'introduction, respirer lentement par le ventre avant de commencer, arriver en avance pour découvrir la salle, regarder des visages bienveillants au début.</p>\n<div class=\"callout\"><b>Règle du temps</b>Comptez environ 130 à 150 mots par minute à l'oral : un exposé de 10 minutes représente environ 1 300 à 1 500 mots.</div>","quiz":[{"q":"Première chose à analyser avant de parler ?","o":["Le public","La couleur des diapositives","Le menu"],"a":0,"e":"Analyse."},{"q":"Un objectif de prise de parole peut être…","o":["Convaincre","Remplir le temps","Endormir"],"a":0,"e":"Finalité."},{"q":"Le message clé est…","o":["La phrase que le public doit retenir","La première diapositive","Le titre du fichier"],"a":0,"e":"Définition."},{"q":"Part du temps de l'introduction ?","o":["Environ 10 %","50 %","80 %"],"a":0,"e":"Répartition."},{"q":"Part du temps du développement ?","o":["Environ 80 %","10 %","30 %"],"a":0,"e":"Répartition."},{"q":"Combien d'idées dans le développement ?","o":["2 ou 3","10","Une vingtaine"],"a":0,"e":"Mémorisation."},{"q":"La conclusion contient…","o":["Résumé, message clé, appel à l'action","De nouvelles idées","Rien"],"a":0,"e":"Structure."},{"q":"Une accroche possible est…","o":["Un chiffre marquant","La lecture du sommaire","Un silence de 5 minutes"],"a":0,"e":"Exemple."},{"q":"Combien de répétitions au minimum ?","o":["Trois","Aucune","Une"],"a":0,"e":"Préparation."},{"q":"On répète…","o":["À voix haute, debout, chronométré","Dans sa tête seulement","Jamais"],"a":0,"e":"Conditions réelles."},{"q":"Les fiches contiennent…","o":["Des mots-clés","Le texte intégral à lire","Rien"],"a":0,"e":"Support."},{"q":"Le trac est…","o":["Normal","Une maladie","Un signe d'incompétence"],"a":0,"e":"Réaction de stress."},{"q":"Pour maîtriser le trac, on prépare surtout…","o":["L'introduction","La conclusion seulement","Les questions du public"],"a":0,"e":"Démarrage."},{"q":"Respirer lentement par le ventre aide à…","o":["Se calmer","S'essouffler","Oublier"],"a":0,"e":"Technique."},{"q":"Arriver en avance permet de…","o":["Découvrir la salle","Partir plus tôt","Éviter le public"],"a":0,"e":"Préparation."},{"q":"Au début, regarder…","o":["Des visages bienveillants","Le plafond","Ses chaussures"],"a":0,"e":"Confiance."},{"q":"Débit oral moyen ?","o":["130 à 150 mots par minute","20 mots par minute","500 mots par minute"],"a":0,"e":"Repère."},{"q":"Un exposé de 10 minutes représente environ…","o":["1 300 à 1 500 mots","300 mots","5 000 mots"],"a":0,"e":"Calcul."},{"q":"Le cadre inclut…","o":["Durée, lieu, matériel","Le salaire","Le contrat"],"a":0,"e":"Analyse."},{"q":"Chaque idée du développement doit être…","o":["Illustrée","Cachée","Répétée dix fois"],"a":0,"e":"Exemple."}]},{"id":"mrh310-9","n":9,"t":"Voix, gestuelle et supports visuels","min":20,"html":"<h3>La voix</h3>\n<div class=\"tbl\"><table><thead><tr><th>Élément</th><th>Conseil</th></tr></thead><tbody>\n<tr><td>Volume</td><td>Parler pour la dernière rangée</td></tr>\n<tr><td>Débit</td><td>Ralentir sur les idées importantes</td></tr>\n<tr><td>Articulation</td><td>Prononcer chaque syllabe, surtout les chiffres</td></tr>\n<tr><td>Intonation</td><td>Varier pour éviter la monotonie</td></tr>\n<tr><td>Silences</td><td>Marquer une pause après une idée forte</td></tr></tbody></table></div>\n<p>Évitez les tics verbaux (« euh », « donc », « voilà ») : remplacez-les par un silence.</p>\n<h3>Le corps</h3>\n<ul><li><strong>Posture</strong> : debout, stable, les deux pieds ancrés au sol.</li><li><strong>Regard</strong> : balayer toute la salle, s'adresser à chacun quelques secondes.</li><li><strong>Gestes</strong> : ouverts, au-dessus de la taille, qui accompagnent le propos ; éviter bras croisés, mains dans les poches, jeux avec un stylo.</li><li><strong>Sourire</strong> : il crée un climat de confiance.</li></ul>\n<h3>Les supports visuels</h3>\n<ul><li>Une idée par diapositive, un titre qui dit le message.</li><li>Peu de texte : quelques mots-clés, jamais des paragraphes à lire.</li><li>Une taille de police lisible depuis le fond de la salle.</li><li>Des graphiques simples plutôt que des tableaux denses.</li><li>Le support aide l'orateur, il ne le remplace pas : on ne lit pas ses diapositives dos au public.</li></ul>\n<h3>Répondre aux questions</h3>\n<p>Écouter jusqu'au bout, remercier, reformuler, répondre brièvement ; si l'on ne sait pas, le dire et proposer de revenir vers la personne.</p>","quiz":[{"q":"Pour le volume, on parle pour…","o":["La dernière rangée","Le premier rang seulement","Soi-même"],"a":0,"e":"Audibilité."},{"q":"Sur une idée importante, on…","o":["Ralentit","Accélère","Chuchote"],"a":0,"e":"Mise en valeur."},{"q":"Une pause après une idée forte…","o":["Renforce l'impact","Montre de l'oubli","Est interdite"],"a":0,"e":"Silence."},{"q":"Varier l'intonation évite…","o":["La monotonie","La clarté","Le sens"],"a":0,"e":"Voix."},{"q":"Remplacer « euh » par…","o":["Un silence","Un autre « euh »","Une toux"],"a":0,"e":"Tic verbal."},{"q":"La posture recommandée est…","o":["Debout, stable, pieds ancrés","Assise affalée","En mouvement permanent"],"a":0,"e":"Corps."},{"q":"Le regard doit…","o":["Balayer toute la salle","Fixer une seule personne","Viser le plafond"],"a":0,"e":"Contact."},{"q":"Les gestes recommandés sont…","o":["Ouverts, au-dessus de la taille","Bras croisés","Mains dans les poches"],"a":0,"e":"Corps."},{"q":"Jouer avec un stylo est…","o":["À éviter","Recommandé","Neutre"],"a":0,"e":"Parasite."},{"q":"Le sourire crée…","o":["Un climat de confiance","De la méfiance","De l'ennui"],"a":0,"e":"Effet."},{"q":"Combien d'idées par diapositive ?","o":["Une","Cinq","Dix"],"a":0,"e":"Clarté."},{"q":"Le titre d'une diapositive doit…","o":["Dire le message","Être « Diapositive 3 »","Être absent"],"a":0,"e":"Titre-message."},{"q":"Le texte sur une diapositive doit être…","o":["Réduit à quelques mots-clés","Un paragraphe complet","Le discours intégral"],"a":0,"e":"Support."},{"q":"La police doit être lisible depuis…","o":["Le fond de la salle","L'ordinateur seulement","Le premier rang"],"a":0,"e":"Lisibilité."},{"q":"On préfère…","o":["Des graphiques simples","Des tableaux denses","Des captures illisibles"],"a":0,"e":"Visuel."},{"q":"Lire ses diapositives dos au public est…","o":["À éviter","Recommandé","Obligatoire"],"a":0,"e":"Erreur."},{"q":"Le support visuel…","o":["Aide l'orateur sans le remplacer","Remplace l'orateur","Est inutile"],"a":0,"e":"Rôle."},{"q":"Face à une question, on commence par…","o":["Écouter jusqu'au bout","Interrompre","Ignorer"],"a":0,"e":"Écoute."},{"q":"Si l'on ne connaît pas la réponse, on…","o":["Le dit et propose de revenir vers la personne","Invente","Change de sujet"],"a":0,"e":"Honnêteté."},{"q":"Articuler est particulièrement important pour…","o":["Les chiffres","Les pauses","Les gestes"],"a":0,"e":"Clarté."}]},{"id":"mrh310-10","n":10,"t":"Écoute active et assertivité","min":20,"html":"<h3>L'écoute active</h3>\n<p>Développée par Carl Rogers, elle consiste à écouter pour comprendre, pas pour répondre. Ses techniques :</p>\n<ul><li><strong>Les relances</strong> : « Oui… », « Et ensuite ? », hochements de tête.</li><li><strong>La reformulation</strong> : redire avec ses mots ce que l'on a compris (« Si je comprends bien, vous… »).</li><li><strong>Les questions ouvertes</strong> pour explorer (« Comment ? », « Qu'est-ce qui… ? »).</li><li><strong>Les questions fermées</strong> pour vérifier un point précis (« C'était lundi ? »).</li><li><strong>Le silence</strong> qui laisse l'autre compléter.</li><li><strong>La synthèse</strong> en fin d'échange.</li></ul>\n<h3>Les quatre attitudes</h3>\n<div class=\"tbl\"><table><thead><tr><th>Attitude</th><th>Définition</th></tr></thead><tbody>\n<tr><td>Passive (fuite)</td><td>Éviter le conflit, ne pas exprimer ses besoins</td></tr>\n<tr><td>Agressive</td><td>Imposer, dominer, attaquer la personne</td></tr>\n<tr><td>Manipulatrice</td><td>Obtenir de façon détournée (culpabilisation, flatterie)</td></tr>\n<tr><td>Assertive</td><td>Exprimer ses opinions et besoins clairement, en respectant l'autre</td></tr></tbody></table></div>\n<h3>Les techniques d'assertivité</h3>\n<ul><li><strong>Parler en « je »</strong> : « Je suis inquiet du retard » plutôt que « Tu es toujours en retard ».</li><li><strong>Le disque rayé</strong> : répéter calmement sa position face à l'insistance.</li><li><strong>Dire non</strong> clairement, avec une raison brève, et proposer une alternative si possible.</li><li><strong>L'édredon</strong> : face à une critique, reconnaître la part de vérité sans se justifier à l'excès (« C'est possible, j'y serai attentif »).</li></ul>\n<div class=\"callout\"><b>Pour le RH</b>L'écoute active est l'outil de base de l'entretien de recrutement, de l'entretien annuel, de la médiation et de l'accueil des réclamations.</div>","quiz":[{"q":"Qui a développé l'écoute active ?","o":["Carl Rogers","Kahneman","Fayol"],"a":0,"e":"Psychologie humaniste."},{"q":"L'écoute active consiste à écouter pour…","o":["Comprendre","Répondre au plus vite","Juger"],"a":0,"e":"Principe."},{"q":"« Si je comprends bien, vous… » est…","o":["Une reformulation","Une relance","Une question fermée"],"a":0,"e":"Technique."},{"q":"« Et ensuite ? » est…","o":["Une relance","Une reformulation","Une synthèse"],"a":0,"e":"Technique."},{"q":"« Comment cela s'est-il passé ? » est une question…","o":["Ouverte","Fermée","Rhétorique"],"a":0,"e":"Exploration."},{"q":"« C'était lundi ? » est une question…","o":["Fermée","Ouverte","Suggestive"],"a":0,"e":"Vérification."},{"q":"Le silence permet à l'autre de…","o":["Compléter sa pensée","Partir","S'ennuyer"],"a":0,"e":"Technique."},{"q":"Éviter le conflit sans exprimer ses besoins est une attitude…","o":["Passive","Assertive","Agressive"],"a":0,"e":"Fuite."},{"q":"Imposer et attaquer la personne est une attitude…","o":["Agressive","Passive","Assertive"],"a":0,"e":"Domination."},{"q":"Obtenir par culpabilisation est une attitude…","o":["Manipulatrice","Assertive","Passive"],"a":0,"e":"Détour."},{"q":"Exprimer clairement en respectant l'autre est une attitude…","o":["Assertive","Agressive","Passive"],"a":0,"e":"Définition."},{"q":"« Je suis inquiet du retard » est un message en…","o":["« Je »","« Tu »","« On »"],"a":0,"e":"Assertivité."},{"q":"« Tu es toujours en retard » est…","o":["Un reproche en « tu »","Assertif","Une reformulation"],"a":0,"e":"À éviter."},{"q":"La technique du disque rayé consiste à…","o":["Répéter calmement sa position","Crier","Changer d'avis"],"a":0,"e":"Technique."},{"q":"Dire non de façon assertive, c'est…","o":["Clairement, avec une raison brève","En s'excusant longuement","Par e-mail anonyme"],"a":0,"e":"Technique."},{"q":"La technique de l'édredon face à une critique consiste à…","o":["Reconnaître la part de vérité sans trop se justifier","Contre-attaquer","Pleurer"],"a":0,"e":"Technique."},{"q":"Combien d'attitudes dans le tableau ?","o":["Quatre","Deux","Six"],"a":0,"e":"Modèle."},{"q":"La synthèse intervient…","o":["En fin d'échange","Au début","Jamais"],"a":0,"e":"Technique."},{"q":"L'écoute active sert au RH notamment pour…","o":["La médiation","Le calcul de l'ITS","La TVA"],"a":0,"e":"Application."},{"q":"La flatterie pour obtenir quelque chose relève de…","o":["La manipulation","L'assertivité","L'écoute"],"a":0,"e":"Attitude."}]}]},{"id":"mrh311","code":"MRH 311","unit":"prat","title":"Initiation au métier de gestionnaire RH et paie","summary":"Le quotidien du gestionnaire RH et paie : missions, interlocuteurs, outils, dossiers d'entrée, cycle mensuel, variables, demandes des salariés, procédures et déontologie.","lessons":[{"id":"mrh311-1","n":1,"t":"Le métier de gestionnaire RH et paie","min":20,"html":"<p>Le gestionnaire RH et paie assure la gestion administrative du personnel et la production de la paie, dans le respect de la loi, de la convention collective et des procédures internes.</p>\n<h3>Les missions principales</h3>\n<div class=\"tbl\"><table><thead><tr><th>Domaine</th><th>Activités</th></tr></thead><tbody>\n<tr><td>Administration du personnel</td><td>Contrats, avenants, dossiers, registre, attestations, entrées et sorties</td></tr>\n<tr><td>Paie</td><td>Collecte des variables, calcul, contrôle, bulletins, virements</td></tr>\n<tr><td>Déclarations</td><td>CNPS, DGI, FDFP, déclarations annuelles</td></tr>\n<tr><td>Temps et absences</td><td>Congés, maladies, heures supplémentaires</td></tr>\n<tr><td>Information des salariés</td><td>Réponses aux questions sur la paie et les droits</td></tr>\n<tr><td>Reporting</td><td>Masse salariale, effectifs, tableaux de bord</td></tr></tbody></table></div>\n<h3>La place dans l'organisation</h3>\n<p>Il est rattaché au responsable RH ou au DRH, parfois au directeur administratif et financier dans les petites structures. Dans une PME, une seule personne peut couvrir toutes ces missions ; dans un grand groupe, les tâches sont réparties (gestionnaire paie, chargé d'administration du personnel).</p>\n<h3>Les formes d'exercice</h3>\n<ul><li>En entreprise (service RH interne).</li><li>En cabinet comptable ou d'externalisation de la paie, pour le compte de plusieurs clients.</li></ul>\n<h3>Les évolutions possibles</h3>\n<p>Responsable paie, responsable administration du personnel, contrôleur de gestion sociale, responsable RH, consultant SIRH.</p>","quiz":[{"q":"Le gestionnaire RH et paie assure…","o":["La gestion administrative et la paie","La vente","La production industrielle"],"a":0,"e":"Définition."},{"q":"Rédiger un avenant relève de…","o":["L'administration du personnel","La paie","Le reporting"],"a":0,"e":"Domaine."},{"q":"Collecter les variables relève de…","o":["La paie","Le recrutement","Le marketing"],"a":0,"e":"Domaine."},{"q":"Les déclarations CNPS relèvent de…","o":["Déclarations","Formation","Recrutement"],"a":0,"e":"Domaine."},{"q":"Suivre la masse salariale relève du…","o":["Reporting","Recrutement","Contentieux"],"a":0,"e":"Domaine."},{"q":"Gérer les congés relève de…","o":["Temps et absences","Paie uniquement","Stratégie"],"a":0,"e":"Domaine."},{"q":"Dans une petite structure, il peut être rattaché…","o":["Au directeur administratif et financier","Au service commercial","Au client"],"a":0,"e":"Organisation."},{"q":"Dans une PME, une seule personne peut…","o":["Couvrir toutes les missions","Ne rien faire","Remplacer le DG"],"a":0,"e":"Organisation."},{"q":"Dans un grand groupe, les tâches sont…","o":["Réparties","Toutes faites par une personne","Supprimées"],"a":0,"e":"Spécialisation."},{"q":"Un gestionnaire paie en cabinet travaille…","o":["Pour plusieurs clients","Pour un seul salarié","Sans client"],"a":0,"e":"Externalisation."},{"q":"Une évolution possible est…","o":["Responsable paie","Directeur commercial obligatoirement","Stagiaire"],"a":0,"e":"Carrière."},{"q":"Le contrôle de gestion sociale est…","o":["Une évolution possible","Hors RH","Une sanction"],"a":0,"e":"Carrière."},{"q":"Le gestionnaire respecte la loi, la convention collective et…","o":["Les procédures internes","Ses préférences","Les rumeurs"],"a":0,"e":"Cadre."},{"q":"Répondre aux questions des salariés sur leur paie relève de…","o":["L'information des salariés","La stratégie","La vente"],"a":0,"e":"Domaine."},{"q":"Délivrer une attestation de travail relève de…","o":["L'administration du personnel","Le reporting","La formation"],"a":0,"e":"Domaine."},{"q":"Les virements des salaires relèvent de…","o":["La paie","Le recrutement","La communication"],"a":0,"e":"Domaine."},{"q":"Le registre du personnel relève de…","o":["L'administration du personnel","La paie seulement","Le marketing"],"a":0,"e":"Domaine."},{"q":"Consultant SIRH est…","o":["Une évolution possible","Sans rapport","Un organisme"],"a":0,"e":"Carrière."},{"q":"La déclaration FDFP relève de…","o":["Déclarations","Temps","Recrutement"],"a":0,"e":"Domaine."},{"q":"Le gestionnaire est souvent rattaché au…","o":["Responsable RH ou DRH","Service commercial","Client"],"a":0,"e":"Organisation."}]},{"id":"mrh311-2","n":2,"t":"Compétences, qualités et éthique","min":20,"html":"<h3>Les compétences techniques</h3>\n<ul><li>Droit du travail et convention collective.</li><li>Techniques de paie : du brut au net, cotisations, ITS.</li><li>Obligations déclaratives (CNPS, DGI, FDFP).</li><li>Maîtrise d'un logiciel de paie, d'un SIRH et d'Excel.</li><li>Bases de comptabilité (écritures de paie, provisions).</li></ul>\n<h3>Les qualités personnelles</h3>\n<div class=\"tbl\"><table><thead><tr><th>Qualité</th><th>Pourquoi</th></tr></thead><tbody>\n<tr><td>Rigueur</td><td>Une erreur de paie touche directement le salarié</td></tr>\n<tr><td>Confidentialité</td><td>Accès aux salaires, à la situation familiale, aux sanctions</td></tr>\n<tr><td>Organisation</td><td>Échéances mensuelles impératives</td></tr>\n<tr><td>Sens du service</td><td>Les salariés viennent avec des questions sensibles</td></tr>\n<tr><td>Pédagogie</td><td>Expliquer un bulletin simplement</td></tr>\n<tr><td>Curiosité</td><td>Les textes et taux changent chaque année</td></tr></tbody></table></div>\n<h3>La confidentialité</h3>\n<p>Le gestionnaire ne divulgue aucune information personnelle, même à un collègue ou un manager qui n'en a pas besoin. Il ne laisse pas de documents visibles sur son bureau, verrouille son ordinateur et ne discute pas des salaires en dehors du cadre professionnel.</p>\n<h3>L'éthique</h3>\n<ul><li>Appliquer les mêmes règles à tous, sans favoritisme.</li><li>Refuser toute demande illégale (payer « au noir », antidater un contrat).</li><li>Signaler une anomalie à sa hiérarchie plutôt que la dissimuler.</li><li>Ne jamais modifier sa propre paie ou celle d'un proche sans validation.</li></ul>\n<div class=\"callout\"><b>Situation</b>Un manager demande le salaire d'un collègue d'une autre équipe « pour comparer ». Réponse : refuser poliment, rappeler la règle de confidentialité.</div>","quiz":[{"q":"Une compétence technique du gestionnaire paie est…","o":["Le calcul du brut au net","La vente","La conduite d'engins"],"a":0,"e":"Technique."},{"q":"Pourquoi la rigueur est-elle essentielle ?","o":["Une erreur touche directement le salarié","Pour aller plus vite","Pour plaire"],"a":0,"e":"Enjeu."},{"q":"Pourquoi la confidentialité ?","o":["Accès à des données personnelles sensibles","Par habitude","Pour cacher des erreurs"],"a":0,"e":"Enjeu."},{"q":"Pourquoi l'organisation ?","o":["Échéances mensuelles impératives","Pour décorer le bureau","Pour réduire les salaires"],"a":0,"e":"Enjeu."},{"q":"Pourquoi la curiosité ?","o":["Les textes et taux changent","Pour espionner","Pour les réseaux sociaux"],"a":0,"e":"Veille."},{"q":"La pédagogie sert à…","o":["Expliquer un bulletin simplement","Compliquer","Recruter"],"a":0,"e":"Enjeu."},{"q":"Un manager demande le salaire d'un collègue d'une autre équipe :","o":["Refuser poliment","Donner l'information","Envoyer tout le fichier"],"a":0,"e":"Confidentialité."},{"q":"Quitter son poste sans verrouiller l'ordinateur est…","o":["Une faute de confidentialité","Normal","Recommandé"],"a":0,"e":"Sécurité."},{"q":"Payer « au noir » à la demande d'un manager :","o":["Refuser","Accepter","Accepter en secret"],"a":0,"e":"Illégal."},{"q":"Antidater un contrat est…","o":["À refuser","Une pratique normale","Obligatoire"],"a":0,"e":"Éthique."},{"q":"Face à une anomalie, le gestionnaire…","o":["La signale à sa hiérarchie","La dissimule","L'ignore"],"a":0,"e":"Transparence."},{"q":"Modifier sa propre paie sans validation est…","o":["Interdit","Autorisé","Encouragé"],"a":0,"e":"Conflit d'intérêts."},{"q":"Appliquer les mêmes règles à tous évite…","o":["Le favoritisme","La paie","Les congés"],"a":0,"e":"Équité."},{"q":"Les bases de comptabilité servent pour…","o":["Les écritures de paie","La publicité","Le recrutement"],"a":0,"e":"Compétence."},{"q":"Le sens du service est utile car…","o":["Les salariés viennent avec des questions sensibles","Il n'y a pas de questions","Le client achète"],"a":0,"e":"Relation."},{"q":"Laisser des bulletins visibles sur le bureau est…","o":["À éviter","Recommandé","Obligatoire"],"a":0,"e":"Confidentialité."},{"q":"Discuter des salaires à la cafétéria est…","o":["Contraire à la confidentialité","Normal","Recommandé"],"a":0,"e":"Discrétion."},{"q":"La maîtrise d'Excel est…","o":["Une compétence technique","Inutile","Interdite"],"a":0,"e":"Outil."},{"q":"Connaître la convention collective sert à…","o":["Appliquer les minima et primes","Vendre","Rien"],"a":0,"e":"Technique."},{"q":"La confidentialité s'applique aussi…","o":["Aux collègues sans besoin d'en connaître","Seulement aux clients","À personne"],"a":0,"e":"Portée."}]},{"id":"mrh311-3","n":3,"t":"Les interlocuteurs du gestionnaire","min":20,"html":"<h3>En interne</h3>\n<div class=\"tbl\"><table><thead><tr><th>Interlocuteur</th><th>Échanges</th></tr></thead><tbody>\n<tr><td>Salariés</td><td>Questions sur la paie, attestations, congés</td></tr>\n<tr><td>Managers</td><td>Variables (heures, absences, primes), entrées et sorties</td></tr>\n<tr><td>Direction RH</td><td>Validation, politique salariale, dossiers sensibles</td></tr>\n<tr><td>Comptabilité / trésorerie</td><td>Écritures de paie, virements, provisions</td></tr>\n<tr><td>Représentants du personnel</td><td>Réclamations sur la paie et les droits</td></tr>\n<tr><td>Service informatique</td><td>Logiciel de paie, accès, sauvegardes</td></tr></tbody></table></div>\n<h3>En externe</h3>\n<div class=\"tbl\"><table><thead><tr><th>Organisme</th><th>Rôle</th></tr></thead><tbody>\n<tr><td>CNPS</td><td>Immatriculation, cotisations, prestations (retraite, accidents du travail, allocations familiales)</td></tr>\n<tr><td>DGI</td><td>ITS, contribution employeur, déclarations fiscales</td></tr>\n<tr><td>FDFP</td><td>Taxes de formation et financement des plans</td></tr>\n<tr><td>Inspection du travail</td><td>Contrôle, conciliation, visas de certains contrats</td></tr>\n<tr><td>Médecine du travail</td><td>Visites médicales, aptitude</td></tr>\n<tr><td>Banque</td><td>Virements des salaires</td></tr>\n<tr><td>Assureurs</td><td>Couverture santé complémentaire, prévoyance</td></tr>\n<tr><td>Agence emploi jeunes</td><td>Programmes d'insertion et de stages</td></tr></tbody></table></div>\n<h3>La qualité de la relation</h3>\n<p>Tenir un annuaire à jour des contacts, archiver les échanges écrits avec les organismes, respecter les délais de réponse, et formaliser les demandes importantes par écrit.</p>","quiz":[{"q":"Qui transmet les variables de paie ?","o":["Les managers","La DGI","La banque"],"a":0,"e":"Interne."},{"q":"Qui valide les dossiers sensibles ?","o":["La direction RH","Le fournisseur","La banque"],"a":0,"e":"Interne."},{"q":"Les écritures de paie sont échangées avec…","o":["La comptabilité","L'inspection","Le médecin"],"a":0,"e":"Interne."},{"q":"Le logiciel de paie relève aussi du…","o":["Service informatique","Service commercial","Client"],"a":0,"e":"Interne."},{"q":"Les réclamations collectives sur la paie viennent souvent…","o":["Des représentants du personnel","De la banque","De la DGI"],"a":0,"e":"Interne."},{"q":"L'immatriculation des salariés se fait auprès de…","o":["La CNPS","La DGI","Le FDFP"],"a":0,"e":"Externe."},{"q":"L'ITS est déclaré à…","o":["La DGI","La CNPS","L'inspection"],"a":0,"e":"Externe."},{"q":"Les taxes de formation concernent…","o":["Le FDFP","La banque","Le médecin"],"a":0,"e":"Externe."},{"q":"La conciliation d'un litige est menée par…","o":["L'inspection du travail","La banque","L'assureur"],"a":0,"e":"Externe."},{"q":"Les visites d'aptitude relèvent de…","o":["La médecine du travail","La DGI","Le FDFP"],"a":0,"e":"Externe."},{"q":"Les virements de salaires passent par…","o":["La banque","La CNPS","L'inspection"],"a":0,"e":"Externe."},{"q":"La couverture santé complémentaire relève…","o":["Des assureurs","De la DGI","Du FDFP"],"a":0,"e":"Externe."},{"q":"Les allocations familiales sont versées par…","o":["La CNPS","La DGI","La banque"],"a":0,"e":"Prestation."},{"q":"Les programmes d'insertion des jeunes relèvent…","o":["De l'agence emploi jeunes","De la DGI","De la CNPS"],"a":0,"e":"Externe."},{"q":"Tenir un annuaire à jour des contacts…","o":["Facilite la relation","Est inutile","Est interdit"],"a":0,"e":"Organisation."},{"q":"Les échanges avec les organismes doivent être…","o":["Archivés","Supprimés","Oubliés"],"a":0,"e":"Traçabilité."},{"q":"Les demandes importantes se formalisent…","o":["Par écrit","Oralement seulement","Jamais"],"a":0,"e":"Preuve."},{"q":"La trésorerie intervient pour…","o":["Les virements","Le recrutement","Les visites médicales"],"a":0,"e":"Paiement."},{"q":"Les accidents du travail sont pris en charge par…","o":["La CNPS","La DGI","Le FDFP"],"a":0,"e":"Branche risques professionnels."},{"q":"Les salariés s'adressent au gestionnaire pour…","o":["Des attestations et questions de paie","Leurs achats","Leurs impôts personnels hors salaire"],"a":0,"e":"Interne."}]},{"id":"mrh311-4","n":4,"t":"Les outils du gestionnaire","min":20,"html":"<h3>Le logiciel de paie</h3>\n<p>Il calcule les bulletins à partir de <strong>paramètres</strong> (rubriques, taux, plafonds, barèmes) et de <strong>données</strong> (fiche salarié, variables du mois). Il produit le bulletin, le journal de paie, les états de cotisations, le fichier de virement et les écritures comptables.</p>\n<h3>Le SIRH</h3>\n<p>Il centralise les données du personnel et souvent d'autres modules : temps et absences, formation, recrutement, entretiens, portail salarié. Il alimente la paie par interface.</p>\n<h3>Le tableur</h3>\n<p>Excel sert aux contrôles (comparaison mois par mois), aux tableaux de bord, aux simulations (coût d'une augmentation), au suivi des CDD ou des visites médicales.</p>\n<h3>Les portails en ligne</h3>\n<ul><li><strong>e-CNPS</strong> : déclarations et paiements des cotisations sociales.</li><li><strong>e-impôts</strong> : déclarations et paiements fiscaux auprès de la DGI.</li></ul>\n<h3>Le rôle des paramètres</h3>\n<div class=\"tbl\"><table><thead><tr><th>Paramètre</th><th>Exemple</th><th>Mise à jour</th></tr></thead><tbody>\n<tr><td>Rubrique de paie</td><td>Prime d'ancienneté, heures sup. à 15 %</td><td>Lors d'un nouvel élément de rémunération</td></tr>\n<tr><td>Taux</td><td>Retraite 6,3 % / 7,7 %</td><td>Lors d'un changement réglementaire</td></tr>\n<tr><td>Plafond</td><td>Plafond des prestations familiales</td><td>Lors d'une revalorisation</td></tr>\n<tr><td>Barème</td><td>Barème de l'ITS</td><td>Loi de finances</td></tr></tbody></table></div>\n<div class=\"callout\"><b>Règle</b>Toute modification de paramètre est testée sur quelques bulletins avant le calcul général, et tracée (date, auteur, motif).</div>","quiz":[{"q":"Le logiciel de paie calcule à partir de…","o":["Paramètres et données","Rumeurs","Ventes"],"a":0,"e":"Fonctionnement."},{"q":"Une rubrique de paie est…","o":["Un paramètre","Une donnée du salarié","Un salarié"],"a":0,"e":"Paramétrage."},{"q":"Les variables du mois sont…","o":["Des données","Des paramètres","Des taux"],"a":0,"e":"Données."},{"q":"Le logiciel de paie produit…","o":["Bulletins, journal, fichier de virement","Des factures clients","Des bons de commande"],"a":0,"e":"Sorties."},{"q":"Le SIRH…","o":["Centralise les données du personnel","Remplace la banque","Calcule la TVA"],"a":0,"e":"Rôle."},{"q":"Le SIRH alimente la paie par…","o":["Interface","Courrier","Téléphone"],"a":0,"e":"Intégration."},{"q":"Excel sert notamment aux…","o":["Contrôles et simulations","Virements bancaires","Déclarations CNPS officielles uniquement"],"a":0,"e":"Usage."},{"q":"Simuler le coût d'une augmentation se fait souvent dans…","o":["Excel","Le registre","La note de service"],"a":0,"e":"Outil."},{"q":"e-CNPS sert aux…","o":["Déclarations et paiements des cotisations","Déclarations fiscales","Recrutements"],"a":0,"e":"Portail."},{"q":"e-impôts sert aux…","o":["Déclarations fiscales","Cotisations CNPS","Congés"],"a":0,"e":"Portail."},{"q":"Un taux de cotisation se met à jour lors…","o":["D'un changement réglementaire","D'un anniversaire","D'une réunion"],"a":0,"e":"Paramètre."},{"q":"Le barème de l'ITS se met à jour avec…","o":["La loi de finances","La convention collective","Le contrat"],"a":0,"e":"Source."},{"q":"Une nouvelle prime nécessite…","o":["Une nouvelle rubrique","Rien","Un nouveau logiciel"],"a":0,"e":"Paramétrage."},{"q":"Toute modification de paramètre doit être…","o":["Testée et tracée","Faite en urgence sans test","Secrète"],"a":0,"e":"Règle."},{"q":"La traçabilité d'une modification indique…","o":["Date, auteur, motif","La couleur","Le prix"],"a":0,"e":"Contenu."},{"q":"On teste une modification sur…","o":["Quelques bulletins","Tous les bulletins directement","Aucun bulletin"],"a":0,"e":"Prudence."},{"q":"Le journal de paie sert…","o":["Aux contrôles et à la comptabilité","Au recrutement","À la publicité"],"a":0,"e":"Usage."},{"q":"Le portail salarié est souvent un module…","o":["Du SIRH","De la banque","De la DGI"],"a":0,"e":"Module."},{"q":"Le suivi des visites médicales peut se faire…","o":["Dans un tableau Excel ou le SIRH","Nulle part","Dans le bilan"],"a":0,"e":"Outil."},{"q":"Un plafond de cotisation est…","o":["Un paramètre","Une variable du mois","Un salarié"],"a":0,"e":"Paramétrage."}]},{"id":"mrh311-5","n":5,"t":"Gérer l'entrée d'un salarié","min":20,"html":"<h3>La check-list d'embauche</h3>\n<div class=\"tbl\"><table><thead><tr><th>Étape</th><th>Document ou action</th></tr></thead><tbody>\n<tr><td>1. Recevoir la validation</td><td>Demande d'embauche signée, conditions (poste, catégorie, salaire, date)</td></tr>\n<tr><td>2. Collecter les pièces</td><td>Pièce d'identité, extrait d'acte de naissance, photos, diplômes, certificats de travail, RIB, actes d'état civil des ayants droit</td></tr>\n<tr><td>3. Visite médicale</td><td>Avis d'aptitude</td></tr>\n<tr><td>4. Contrat</td><td>Rédaction, signature en deux exemplaires ; visa pour un travailleur étranger</td></tr>\n<tr><td>5. Déclarations</td><td>Déclaration d'embauche et immatriculation CNPS si nécessaire</td></tr>\n<tr><td>6. Registres</td><td>Inscription au registre d'employeur</td></tr>\n<tr><td>7. SIRH et paie</td><td>Création de la fiche, matricule, rubriques, situation familiale</td></tr>\n<tr><td>8. Accueil</td><td>Livret d'accueil, règlement intérieur, badge, accès</td></tr>\n<tr><td>9. Suivi</td><td>Alerte de fin de période d'essai</td></tr></tbody></table></div>\n<h3>Le premier bulletin</h3>\n<p>Une embauche en cours de mois entraîne un salaire <strong>proratisé</strong>. Méthode courante : salaire mensuel × jours ouvrés (ou calendaires) de présence / jours du mois selon la règle de l'entreprise.</p>\n<div class=\"callout\"><b>Exemple</b>Salaire 260 000 FCFA, embauche le 14, 26 jours ouvrables dans le mois dont 13 travaillés : 260 000 × 13 / 26 = <strong>130 000 FCFA</strong>.</div>\n<h3>Les erreurs fréquentes</h3>\n<ul><li>Oublier la déclaration CNPS.</li><li>Situation familiale non renseignée : ITS mal calculé.</li><li>RIB erroné : virement rejeté.</li><li>Date de fin d'essai non programmée.</li></ul>","quiz":[{"q":"Première étape de la check-list d'embauche ?","o":["Recevoir la validation","Créer le badge","Programmer la fin d'essai"],"a":0,"e":"Ordre."},{"q":"Le RIB sert…","o":["Au virement du salaire","À la visite médicale","Au recrutement"],"a":0,"e":"Pièce."},{"q":"Les actes d'état civil des ayants droit servent…","o":["À la situation familiale et aux prestations","À la décoration","Au recrutement"],"a":0,"e":"Pièce."},{"q":"La visite médicale donne…","o":["Un avis d'aptitude","Un contrat","Un salaire"],"a":0,"e":"Résultat."},{"q":"Le contrat est signé en…","o":["Deux exemplaires","Un seul","Dix"],"a":0,"e":"Usage."},{"q":"Le contrat d'un travailleur étranger nécessite…","o":["Un visa","Rien","Une photo supplémentaire uniquement"],"a":0,"e":"Formalité."},{"q":"Le nouveau salarié est inscrit sur…","o":["Le registre d'employeur","Le bilan","Le livre de caisse"],"a":0,"e":"Registre."},{"q":"Le matricule est créé…","o":["Dans le SIRH et la paie","Au registre du commerce","À la CNPS uniquement"],"a":0,"e":"Création."},{"q":"Le livret d'accueil est remis…","o":["À l'accueil","À la sortie","Jamais"],"a":0,"e":"Intégration."},{"q":"Il faut programmer une alerte pour…","o":["La fin de la période d'essai","Le 1er mai","L'anniversaire du DG"],"a":0,"e":"Suivi."},{"q":"Une embauche en cours de mois entraîne…","o":["Un salaire proratisé","Un mois complet","Aucun salaire"],"a":0,"e":"Prorata."},{"q":"Salaire 260 000, 13 jours sur 26 : premier salaire ?","o":["130 000","260 000","200 000"],"a":0,"e":"260 000 × 13 / 26."},{"q":"Salaire 300 000, 20 jours sur 25 : premier salaire ?","o":["240 000","300 000","200 000"],"a":0,"e":"300 000 × 20 / 25."},{"q":"Situation familiale non renseignée entraîne…","o":["Un ITS mal calculé","Rien","Une prime"],"a":0,"e":"Erreur."},{"q":"Un RIB erroné entraîne…","o":["Un virement rejeté","Un salaire doublé","Une promotion"],"a":0,"e":"Erreur."},{"q":"Oublier la déclaration CNPS est…","o":["Une erreur fréquente et grave","Sans conséquence","Recommandé"],"a":0,"e":"Erreur."},{"q":"Les certificats de travail antérieurs servent à…","o":["Vérifier l'expérience","Calculer la TVA","Rien"],"a":0,"e":"Pièce."},{"q":"La demande d'embauche signée précise…","o":["Poste, catégorie, salaire, date","Le menu de la cantine","Les vacances"],"a":0,"e":"Validation."},{"q":"Le règlement intérieur est remis…","o":["À l'accueil","Au départ","Jamais"],"a":0,"e":"Information."},{"q":"Les accès informatiques sont créés…","o":["À l'arrivée","Un an après","Jamais"],"a":0,"e":"Accueil."}]},{"id":"mrh311-6","n":6,"t":"Le cycle mensuel de paie","min":25,"html":"<p>La paie suit un cycle mensuel rythmé par des échéances. Un calendrier partagé avec les managers est indispensable.</p>\n<div class=\"tbl\"><table><thead><tr><th>Période</th><th>Tâches</th></tr></thead><tbody>\n<tr><td>Début de mois (J1 – J10)</td><td>Déclarations du mois précédent, archivage, mise à jour des paramètres</td></tr>\n<tr><td>J10 – J18</td><td>Mise à jour des mouvements (entrées, sorties, promotions, changements de situation)</td></tr>\n<tr><td>J15 – J20</td><td>Collecte des variables auprès des managers (date limite annoncée)</td></tr>\n<tr><td>J20 – J23</td><td>Saisie ou import des variables, calcul de la paie</td></tr>\n<tr><td>J23 – J25</td><td>Contrôles, corrections, validation par le responsable</td></tr>\n<tr><td>J25 – J28</td><td>Fichier de virement, ordre à la banque</td></tr>\n<tr><td>Fin de mois</td><td>Diffusion des bulletins, écritures comptables</td></tr></tbody></table></div>\n<h3>La date limite des variables</h3>\n<p>Les éléments reçus après la date limite sont traités le mois suivant, en régularisation. Cette règle, connue de tous, protège la qualité des contrôles.</p>\n<h3>La clôture de la paie</h3>\n<p>Une fois la paie validée et les virements envoyés, la période est « clôturée » dans le logiciel : on ne peut plus la modifier. Toute erreur découverte ensuite est corrigée sur le mois suivant.</p>\n<h3>Les périodes chargées</h3>\n<p>Décembre (primes de fin d'année, clôture annuelle), janvier (nouveaux taux et barèmes, déclarations annuelles), périodes d'augmentations générales.</p>\n<div class=\"callout\"><b>Astuce</b>Tenez un journal de paie mensuel : ce qui a changé ce mois-ci, les cas particuliers, les points à régulariser le mois suivant.</div>","quiz":[{"q":"En début de mois, on traite…","o":["Les déclarations du mois précédent","Les virements du mois","Les bulletins du mois"],"a":0,"e":"Calendrier."},{"q":"Période indicative de collecte des variables ?","o":["J15 – J20","J1 – J5","J28 – J30"],"a":0,"e":"Calendrier."},{"q":"Après le calcul vient…","o":["Le contrôle et la validation","La collecte","Le recrutement"],"a":0,"e":"Ordre."},{"q":"Le fichier de virement est envoyé…","o":["Après validation","Avant le calcul","Jamais"],"a":0,"e":"Ordre."},{"q":"Les bulletins sont diffusés…","o":["En fin de mois","En début de mois suivant obligatoirement","Une fois par an"],"a":0,"e":"Calendrier."},{"q":"Une variable reçue après la date limite est…","o":["Traitée le mois suivant","Refusée définitivement","Payée deux fois"],"a":0,"e":"Régularisation."},{"q":"Pourquoi une date limite ?","o":["Protéger la qualité des contrôles","Punir les managers","Retarder la paie"],"a":0,"e":"Objectif."},{"q":"La clôture de la paie signifie…","o":["On ne peut plus modifier la période","On supprime la paie","On recommence"],"a":0,"e":"Définition."},{"q":"Une erreur découverte après clôture est corrigée…","o":["Le mois suivant","En rouvrant toujours la période","Jamais"],"a":0,"e":"Régularisation."},{"q":"Mois chargé à cause des primes de fin d'année ?","o":["Décembre","Juin","Avril"],"a":0,"e":"Période."},{"q":"Janvier est chargé à cause…","o":["Des nouveaux taux et déclarations annuelles","Des vacances","De rien"],"a":0,"e":"Période."},{"q":"Les mouvements (entrées, sorties) sont mis à jour…","o":["Avant le calcul","Après les virements","Jamais"],"a":0,"e":"Ordre."},{"q":"Qui valide la paie ?","o":["Le responsable","Le salarié","La banque"],"a":0,"e":"Contrôle."},{"q":"Le calendrier de paie doit être…","o":["Partagé avec les managers","Secret","Changé chaque mois sans prévenir"],"a":0,"e":"Coordination."},{"q":"Les écritures comptables de paie sont passées…","o":["En fin de mois","À l'embauche","Jamais"],"a":0,"e":"Comptabilité."},{"q":"Le journal de paie mensuel du gestionnaire note…","o":["Les changements et points à régulariser","Les résultats sportifs","Rien"],"a":0,"e":"Astuce."},{"q":"Mise à jour des paramètres en début de mois : exemple ?","o":["Nouveau taux de cotisation","Nouvelle couleur","Nouveau client"],"a":0,"e":"Paramètre."},{"q":"Période indicative des contrôles ?","o":["J23 – J25","J1 – J3","J10 – J12"],"a":0,"e":"Calendrier."},{"q":"Les augmentations générales créent…","o":["Une période chargée","Aucun travail","Une fermeture"],"a":0,"e":"Période."},{"q":"L'archivage du mois précédent intervient…","o":["En début de mois","En fin d'année seulement","Jamais"],"a":0,"e":"Calendrier."}]},{"id":"mrh311-7","n":7,"t":"Collecter et contrôler les variables","min":25,"html":"<h3>Les variables de paie</h3>\n<p>Ce sont les éléments qui changent d'un mois à l'autre : heures supplémentaires, absences, congés pris, primes ponctuelles, commissions, acomptes, avances, retenues diverses, indemnités de fin de contrat.</p>\n<h3>Organiser la collecte</h3>\n<ul><li>Un <strong>modèle unique</strong> de fichier ou un module SIRH pour tous les managers.</li><li>Des justificatifs systématiques (relevé d'heures signé, certificat médical, décision de prime).</li><li>Une <strong>date limite</strong> connue.</li><li>Un circuit de <strong>validation</strong> : manager, puis RH.</li></ul>\n<h3>Les contrôles avant calcul</h3>\n<div class=\"tbl\"><table><thead><tr><th>Contrôle</th><th>Exemple d'anomalie</th></tr></thead><tbody>\n<tr><td>Cohérence</td><td>Heures supplémentaires saisies pour un salarié en congé</td></tr>\n<tr><td>Plafonds</td><td>Volume d'heures supplémentaires au-delà de la limite autorisée</td></tr>\n<tr><td>Justificatif</td><td>Prime exceptionnelle sans décision signée</td></tr>\n<tr><td>Doublon</td><td>Même absence saisie deux fois</td></tr></tbody></table></div>\n<h3>Les contrôles après calcul</h3>\n<ul><li>Comparer la masse salariale au mois précédent ; expliquer tout écart supérieur à un seuil (par exemple 2 %).</li><li>Examiner les salariés dont le net varie fortement.</li><li>Vérifier les entrées et sorties du mois.</li><li>Contrôler qu'aucun net n'est négatif.</li><li>Rapprocher le total des virements du total des nets.</li></ul>\n<div class=\"callout\"><b>Exemple</b>Masse salariale : 48 000 000 en août, 50 400 000 en septembre, soit +5 %. Explication attendue : 3 embauches et rappel d'augmentation. Sans explication, on recherche l'erreur avant de valider.</div>","quiz":[{"q":"Une variable de paie est…","o":["Un élément qui change d'un mois à l'autre","Le salaire de base","Le taux de cotisation"],"a":0,"e":"Définition."},{"q":"Exemple de variable ?","o":["Heures supplémentaires","Numéro CNPS","Date de naissance"],"a":0,"e":"Exemple."},{"q":"Pourquoi un modèle unique de collecte ?","o":["Homogénéité et fiabilité","Compliquer","Décorer"],"a":0,"e":"Organisation."},{"q":"Un relevé d'heures doit être…","o":["Signé","Anonyme","Oral"],"a":0,"e":"Justificatif."},{"q":"Circuit de validation des variables ?","o":["Manager puis RH","Salarié seul","Banque"],"a":0,"e":"Validation."},{"q":"Heures sup. saisies pour un salarié en congé : anomalie de…","o":["Cohérence","Doublon","Plafond"],"a":0,"e":"Contrôle."},{"q":"Prime exceptionnelle sans décision signée : anomalie de…","o":["Justificatif","Cohérence","Plafond"],"a":0,"e":"Contrôle."},{"q":"Même absence saisie deux fois : anomalie de…","o":["Doublon","Plafond","Justificatif"],"a":0,"e":"Contrôle."},{"q":"Heures sup. au-delà de la limite autorisée : anomalie de…","o":["Plafond","Doublon","Cohérence"],"a":0,"e":"Contrôle."},{"q":"Après calcul, on compare la masse salariale…","o":["Au mois précédent","Au chiffre d'affaires","Aux impôts"],"a":0,"e":"Contrôle."},{"q":"48 M en août, 50,4 M en septembre : variation ?","o":["+5 %","+2,4 %","+10 %"],"a":0,"e":"2,4 / 48."},{"q":"Un écart inexpliqué conduit à…","o":["Rechercher l'erreur avant validation","Valider quand même","Supprimer la paie"],"a":0,"e":"Règle."},{"q":"Un net négatif est…","o":["Une anomalie à contrôler","Normal","Impossible à détecter"],"a":0,"e":"Contrôle."},{"q":"Le total des virements doit être égal…","o":["Au total des nets","Au brut","Au coût employeur"],"a":0,"e":"Rapprochement."},{"q":"Une explication valable d'une hausse de masse salariale ?","o":["Des embauches","Une erreur","Un doublon"],"a":0,"e":"Exemple."},{"q":"Seuil d'écart indicatif déclenchant une analyse ?","o":["2 %","50 %","0,0001 %"],"a":0,"e":"Exemple."},{"q":"Un acompte est…","o":["Une variable","Un paramètre","Un taux"],"a":0,"e":"Exemple."},{"q":"Les salariés dont le net varie fortement doivent être…","o":["Examinés","Ignorés","Payés deux fois"],"a":0,"e":"Contrôle."},{"q":"Le certificat médical justifie…","o":["Une absence maladie","Une prime","Une heure sup."],"a":0,"e":"Justificatif."},{"q":"Vérifier les entrées et sorties du mois évite…","o":["Les salariés fantômes ou oubliés","Les augmentations","Les congés"],"a":0,"e":"Contrôle."}]},{"id":"mrh311-8","n":8,"t":"Répondre aux demandes des salariés","min":20,"html":"<h3>Les demandes fréquentes</h3>\n<div class=\"tbl\"><table><thead><tr><th>Demande</th><th>Réponse type</th></tr></thead><tbody>\n<tr><td>Attestation de travail</td><td>Délivrée sous quelques jours, signée par une personne habilitée</td></tr>\n<tr><td>Attestation de salaire (banque, crédit)</td><td>Salaire brut et net, ancienneté, type de contrat</td></tr>\n<tr><td>Explication du bulletin</td><td>Rubrique par rubrique, avec un langage simple</td></tr>\n<tr><td>Écart de salaire</td><td>Vérifier les variables et les justificatifs du mois</td></tr>\n<tr><td>Solde de congés</td><td>Jours acquis, pris, restants</td></tr>\n<tr><td>Acompte</td><td>Selon la procédure interne et les plafonds</td></tr>\n<tr><td>Situation CNPS</td><td>Orientation vers l'espace assuré ou l'agence CNPS</td></tr></tbody></table></div>\n<h3>La méthode de traitement</h3>\n<ol><li>Accueillir et écouter la demande jusqu'au bout.</li><li>Vérifier l'identité du demandeur avant de communiquer une information personnelle.</li><li>Rechercher l'information (bulletin, variables, dossier).</li><li>Répondre clairement ; si une erreur est constatée, la reconnaître et indiquer la date de régularisation.</li><li>Tracer la demande (registre ou outil de tickets) et le délai de réponse.</li></ol>\n<h3>Acompte et avance</h3>\n<p>L'<strong>acompte</strong> est le paiement anticipé d'un salaire correspondant à un travail <strong>déjà effectué</strong> dans le mois ; il est déduit du salaire du même mois. L'<strong>avance</strong> est un prêt sur un travail <strong>non encore effectué</strong> ; elle est remboursée par retenues échelonnées, dans les limites légales de la quotité saisissable.</p>\n<div class=\"callout\"><b>Ton</b>Une question sur la paie touche au revenu du salarié : répondez avec patience, sans jargon, et sans renvoyer d'un service à l'autre.</div>","quiz":[{"q":"Une attestation de travail est signée par…","o":["Une personne habilitée","N'importe quel collègue","Le salarié lui-même"],"a":0,"e":"Validité."},{"q":"Une attestation de salaire indique…","o":["Brut, net, ancienneté, contrat","Les salaires des collègues","Le chiffre d'affaires"],"a":0,"e":"Contenu."},{"q":"Pour un écart de salaire, on vérifie…","o":["Les variables et justificatifs","L'horoscope","Rien"],"a":0,"e":"Méthode."},{"q":"Le solde de congés indique…","o":["Jours acquis, pris, restants","Le salaire","Les primes"],"a":0,"e":"Contenu."},{"q":"Pour la situation CNPS, on oriente vers…","o":["L'espace assuré ou l'agence CNPS","La DGI","La banque"],"a":0,"e":"Orientation."},{"q":"Première étape du traitement d'une demande ?","o":["Accueillir et écouter","Répondre sans écouter","Transférer"],"a":0,"e":"Méthode."},{"q":"Avant de communiquer une information personnelle, on…","o":["Vérifie l'identité du demandeur","Publie","Demande au collègue"],"a":0,"e":"Confidentialité."},{"q":"Si une erreur est constatée, on…","o":["La reconnaît et indique la date de régularisation","La nie","L'ignore"],"a":0,"e":"Transparence."},{"q":"Tracer les demandes permet de…","o":["Suivre les délais","Oublier","Punir"],"a":0,"e":"Organisation."},{"q":"L'acompte correspond à un travail…","o":["Déjà effectué","Non effectué","Futur lointain"],"a":0,"e":"Définition."},{"q":"L'avance correspond à un travail…","o":["Non encore effectué","Déjà effectué","Annulé"],"a":0,"e":"Définition."},{"q":"L'acompte est déduit…","o":["Du salaire du même mois","Sur 12 mois","Jamais"],"a":0,"e":"Traitement."},{"q":"L'avance est remboursée…","o":["Par retenues échelonnées","Jamais","En une fois obligatoirement le jour même"],"a":0,"e":"Traitement."},{"q":"Les retenues d'avance respectent…","o":["La quotité saisissable","Aucune limite","Le bon vouloir du manager"],"a":0,"e":"Limite légale."},{"q":"Expliquer un bulletin se fait…","o":["Rubrique par rubrique, simplement","En jargon","Par écrit illisible"],"a":0,"e":"Pédagogie."},{"q":"Renvoyer le salarié d'un service à l'autre est…","o":["À éviter","Recommandé","Obligatoire"],"a":0,"e":"Qualité de service."},{"q":"Une question sur la paie touche…","o":["Au revenu du salarié","À rien d'important","Au client"],"a":0,"e":"Sensibilité."},{"q":"Un outil de tickets sert à…","o":["Tracer les demandes","Payer","Recruter"],"a":0,"e":"Traçabilité."},{"q":"Un prêt accordé au salarié sur son salaire futur est…","o":["Une avance","Un acompte","Une prime"],"a":0,"e":"Définition."},{"q":"Le ton recommandé face à une réclamation est…","o":["Patient et clair","Sec","Moqueur"],"a":0,"e":"Relation."}]},{"id":"mrh311-9","n":9,"t":"Organisation et procédures","min":20,"html":"<h3>S'organiser</h3>\n<ul><li>Un <strong>calendrier annuel</strong> des échéances (paie, déclarations mensuelles et annuelles, revues salariales, visites médicales).</li><li>Une <strong>liste de tâches</strong> quotidienne, priorisée selon l'urgence et l'importance.</li><li>Des <strong>plages protégées</strong> pour les tâches de contrôle.</li><li>Un classement des dossiers papier et numériques cohérent (par matricule, par année).</li></ul>\n<h3>Le manuel de procédures</h3>\n<p>Il décrit chaque procédure : objectif, déclencheur, étapes, responsable, documents, contrôles, délais. Il permet la continuité en cas d'absence et facilite l'intégration d'un nouveau gestionnaire.</p>\n<div class=\"tbl\"><table><thead><tr><th>Procédure</th><th>Déclencheur</th></tr></thead><tbody>\n<tr><td>Embauche</td><td>Demande d'embauche validée</td></tr>\n<tr><td>Départ</td><td>Démission reçue, fin de CDD, licenciement notifié</td></tr>\n<tr><td>Changement de RIB</td><td>Demande écrite du salarié</td></tr>\n<tr><td>Acompte</td><td>Demande écrite, avant une date du mois</td></tr>\n<tr><td>Clôture mensuelle</td><td>Calendrier</td></tr></tbody></table></div>\n<h3>La procédure de changement de RIB</h3>\n<ol><li>Demande écrite et signée du salarié, avec un justificatif bancaire.</li><li>Vérification de l'identité par un autre canal (appel au numéro connu, présentation au service).</li><li>Saisie par un gestionnaire, contrôle par un second.</li><li>Information du salarié du mois d'effet.</li></ol>\n<h3>La continuité de service</h3>\n<p>Chaque tâche critique a un suppléant formé. Les mots de passe ne sont pas partagés, mais les accès du suppléant sont prévus.</p>","quiz":[{"q":"Le calendrier annuel recense…","o":["Les échéances","Les anniversaires","Les ventes"],"a":0,"e":"Organisation."},{"q":"Les tâches quotidiennes sont priorisées selon…","o":["Urgence et importance","L'ordre alphabétique","L'humeur"],"a":0,"e":"Priorisation."},{"q":"Les plages protégées servent aux…","o":["Tâches de contrôle","Pauses longues","Réunions"],"a":0,"e":"Concentration."},{"q":"Les dossiers sont classés par…","o":["Matricule et année","Couleur","Taille"],"a":0,"e":"Cohérence."},{"q":"Le manuel de procédures décrit…","o":["Étapes, responsables, contrôles, délais","Les salaires","Les clients"],"a":0,"e":"Contenu."},{"q":"Le manuel permet…","o":["La continuité en cas d'absence","De supprimer les contrôles","D'éviter la paie"],"a":0,"e":"Utilité."},{"q":"Déclencheur de la procédure d'embauche ?","o":["Demande d'embauche validée","Un appel du client","La fin du mois"],"a":0,"e":"Déclencheur."},{"q":"Déclencheur de la procédure de départ ?","o":["Démission reçue","Une promotion","Une visite"],"a":0,"e":"Déclencheur."},{"q":"Déclencheur de la clôture mensuelle ?","o":["Le calendrier","Un e-mail aléatoire","La météo"],"a":0,"e":"Déclencheur."},{"q":"Un changement de RIB exige…","o":["Une demande écrite et signée","Un appel anonyme","Rien"],"a":0,"e":"Procédure."},{"q":"Pourquoi vérifier par un autre canal ?","o":["Prévenir la fraude","Perdre du temps","Par politesse"],"a":0,"e":"Sécurité."},{"q":"La saisie du RIB est contrôlée par…","o":["Un second gestionnaire","Personne","Le salarié seul"],"a":0,"e":"Double contrôle."},{"q":"Le salarié est informé…","o":["Du mois d'effet","De rien","Du salaire des autres"],"a":0,"e":"Information."},{"q":"Chaque tâche critique a…","o":["Un suppléant formé","Aucun suppléant","Dix responsables"],"a":0,"e":"Continuité."},{"q":"Les mots de passe…","o":["Ne sont pas partagés","Sont affichés","Sont communs à tous"],"a":0,"e":"Sécurité."},{"q":"Les accès du suppléant sont…","o":["Prévus à l'avance","Improvisés","Interdits"],"a":0,"e":"Continuité."},{"q":"Le manuel facilite…","o":["L'intégration d'un nouveau gestionnaire","Les erreurs","Les retards"],"a":0,"e":"Utilité."},{"q":"Une demande d'acompte doit être faite…","o":["Par écrit, avant une date du mois","Oralement le jour de la paie","Jamais"],"a":0,"e":"Procédure."},{"q":"Un justificatif bancaire accompagne…","o":["La demande de changement de RIB","La demande de congé","L'attestation de travail"],"a":0,"e":"Pièce."},{"q":"Le double contrôle réduit…","o":["Les erreurs et fraudes","La qualité","La confidentialité"],"a":0,"e":"Contrôle interne."}]},{"id":"mrh311-10","n":10,"t":"Erreurs de paie et régularisations","min":20,"html":"<h3>Les erreurs fréquentes</h3>\n<ul><li>Variable oubliée ou saisie deux fois.</li><li>Mauvais taux ou plafond (paramètre non mis à jour).</li><li>Mauvaise situation familiale (ITS erroné).</li><li>Prorata mal calculé à l'entrée ou à la sortie.</li><li>Prime versée à tort.</li></ul>\n<h3>Le moins-perçu</h3>\n<p>Le salarié a reçu moins que ce qui lui était dû. On régularise au plus vite, en général sur la paie suivante, ou par un virement complémentaire si le montant est important. Le salarié est informé.</p>\n<h3>Le trop-perçu</h3>\n<p>Le salarié a reçu plus que ce qui lui était dû. L'employeur peut en demander le remboursement, mais :</p>\n<ul><li>il informe le salarié par écrit, avec le détail du calcul ;</li><li>il propose un échéancier raisonnable ;</li><li>les retenues respectent les limites légales de la quotité saisissable ;</li><li>l'action en répétition est soumise à un délai de prescription.</li></ul>\n<div class=\"callout\"><b>Exemple</b>Une prime de 60 000 FCFA a été versée deux fois. On informe le salarié et on convient d'une retenue de 20 000 FCFA sur trois mois.</div>\n<h3>Analyser la cause</h3>\n<p>Chaque erreur est une occasion d'améliorer : pourquoi est-elle arrivée (saisie, paramètre, information tardive) ? Quel contrôle l'aurait détectée ? On met à jour la procédure ou la check-list.</p>\n<h3>La déontologie</h3>\n<p>Ne jamais dissimuler une erreur ni la corriger discrètement sans en informer le salarié et la hiérarchie : la transparence préserve la confiance dans le service paie.</p>","quiz":[{"q":"Un paramètre non mis à jour peut causer…","o":["Un mauvais taux ou plafond","Une meilleure paie","Rien"],"a":0,"e":"Erreur."},{"q":"Une mauvaise situation familiale fausse…","o":["L'ITS","Le salaire de base","La date d'embauche"],"a":0,"e":"Erreur."},{"q":"Le moins-perçu signifie que le salarié a reçu…","o":["Moins que dû","Plus que dû","Exactement le dû"],"a":0,"e":"Définition."},{"q":"Le trop-perçu signifie que le salarié a reçu…","o":["Plus que dû","Moins que dû","Rien"],"a":0,"e":"Définition."},{"q":"Un moins-perçu est régularisé…","o":["Au plus vite","Dans 5 ans","Jamais"],"a":0,"e":"Traitement."},{"q":"Un moins-perçu important peut donner lieu à…","o":["Un virement complémentaire","Une sanction du salarié","Rien"],"a":0,"e":"Traitement."},{"q":"Pour un trop-perçu, on informe le salarié…","o":["Par écrit avec le détail","Jamais","Par rumeur"],"a":0,"e":"Procédure."},{"q":"On propose pour un trop-perçu…","o":["Un échéancier raisonnable","Une retenue totale immédiate quel que soit le montant","Une amende"],"a":0,"e":"Procédure."},{"q":"Les retenues respectent…","o":["La quotité saisissable","Aucune limite","L'avis du manager"],"a":0,"e":"Limite légale."},{"q":"L'action en remboursement d'un trop-perçu est soumise…","o":["À un délai de prescription","À aucun délai","À l'accord du syndicat"],"a":0,"e":"Limite."},{"q":"Prime de 60 000 versée deux fois, retenue sur 3 mois : montant mensuel ?","o":["20 000","60 000","30 000"],"a":0,"e":"60 000 / 3."},{"q":"Trop-perçu de 90 000 sur 3 mois : retenue mensuelle ?","o":["30 000","90 000","45 000"],"a":0,"e":"90 000 / 3."},{"q":"Après une erreur, on analyse…","o":["Sa cause","Le coupable à sanctionner","Rien"],"a":0,"e":"Amélioration."},{"q":"Une question à se poser après une erreur ?","o":["Quel contrôle l'aurait détectée ?","Qui blâmer ?","Comment la cacher ?"],"a":0,"e":"Amélioration."},{"q":"Après analyse, on met à jour…","o":["La procédure ou la check-list","Le logo","Le salaire du gestionnaire"],"a":0,"e":"Correction."},{"q":"Corriger une erreur discrètement sans informer est…","o":["Contraire à la déontologie","Recommandé","Obligatoire"],"a":0,"e":"Transparence."},{"q":"La transparence préserve…","o":["La confiance dans le service paie","Les erreurs","Les conflits"],"a":0,"e":"Effet."},{"q":"Un prorata mal calculé touche souvent…","o":["Les entrées et sorties","Les congés annuels uniquement","Les impôts de l'entreprise"],"a":0,"e":"Erreur."},{"q":"Une variable saisie deux fois est…","o":["Un doublon","Un paramètre","Une régularisation"],"a":0,"e":"Erreur."},{"q":"Qui informer d'une erreur ?","o":["Le salarié et la hiérarchie","Personne","Les concurrents"],"a":0,"e":"Transparence."}]}]},{"id":"mrh312","code":"MRH 312","unit":"prat","title":"Consultant fonctionnel ERP (SIRH)","summary":"Conduire un projet SIRH côté métier : cadrage, recueil des besoins, spécifications, choix de solution, paramétrage, reprise de données, recette et conduite du changement.","lessons":[{"id":"mrh312-1","n":1,"t":"ERP et SIRH : définitions et marché","min":20,"html":"<h3>L'ERP</h3>\n<p>Un ERP (<em>Enterprise Resource Planning</em>, ou PGI : progiciel de gestion intégré) couvre plusieurs fonctions de l'entreprise (finance, achats, ventes, stocks, RH) avec une <strong>base de données unique</strong>. Une information saisie une fois est disponible pour tous les modules.</p>\n<h3>Le SIRH</h3>\n<p>Le système d'information RH regroupe les outils de gestion des ressources humaines. Il peut être un module d'ERP ou une solution spécialisée.</p>\n<div class=\"tbl\"><table><thead><tr><th>Module SIRH</th><th>Fonctions</th></tr></thead><tbody>\n<tr><td>Administration du personnel</td><td>Dossier salarié, contrats, organisation</td></tr>\n<tr><td>Paie</td><td>Calcul, bulletins, déclarations</td></tr>\n<tr><td>Temps et activités</td><td>Absences, congés, plannings, pointage</td></tr>\n<tr><td>Recrutement</td><td>Offres, candidatures, suivi</td></tr>\n<tr><td>Formation</td><td>Catalogue, inscriptions, plan, e-learning</td></tr>\n<tr><td>Talents</td><td>Entretiens, objectifs, compétences, succession</td></tr>\n<tr><td>Libre-service (portail)</td><td>Accès des salariés et managers à leurs données et demandes</td></tr>\n<tr><td>Reporting</td><td>Tableaux de bord, bilan social</td></tr></tbody></table></div>\n<h3>Le marché</h3>\n<p>On trouve des éditeurs internationaux (SAP SuccessFactors, Oracle HCM Cloud, Workday), des solutions de gestion pour PME (Sage), et des éditeurs régionaux adaptés à la législation sociale et fiscale ivoirienne.</p>\n<h3>Sur site ou SaaS ?</h3>\n<p><strong>Sur site (on-premise)</strong> : logiciel installé sur les serveurs de l'entreprise, licence achetée. <strong>SaaS</strong> : logiciel accessible en ligne, hébergé par l'éditeur, payé par abonnement, mis à jour automatiquement.</p>","quiz":[{"q":"ERP signifie…","o":["Enterprise Resource Planning","Employee Record Program","Electronic Payroll Report"],"a":0,"e":"Définition."},{"q":"En français, ERP se dit…","o":["PGI","SIRH","GPEC"],"a":0,"e":"Progiciel de gestion intégré."},{"q":"Caractéristique clé d'un ERP ?","o":["Une base de données unique","Un logiciel par service sans lien","Pas de données"],"a":0,"e":"Intégration."},{"q":"Le SIRH peut être…","o":["Un module d'ERP ou une solution spécialisée","Uniquement papier","Un tableur"],"a":0,"e":"Formes."},{"q":"Les congés relèvent du module…","o":["Temps et activités","Recrutement","Formation"],"a":0,"e":"Module."},{"q":"Les entretiens annuels relèvent du module…","o":["Talents","Paie","Temps"],"a":0,"e":"Module."},{"q":"Le portail libre-service permet…","o":["Aux salariés d'accéder à leurs données et demandes","Au client de commander","Au fisc de contrôler"],"a":0,"e":"Module."},{"q":"Le bilan social relève du module…","o":["Reporting","Recrutement","Paie seulement"],"a":0,"e":"Module."},{"q":"Un éditeur international de SIRH est…","o":["Workday","La CNPS","L'ARTCI"],"a":0,"e":"Marché."},{"q":"SAP propose le SIRH…","o":["SuccessFactors","e-CNPS","Excel"],"a":0,"e":"Marché."},{"q":"Sage cible plutôt…","o":["Les PME","Uniquement les États","Les particuliers"],"a":0,"e":"Marché."},{"q":"Pourquoi des éditeurs régionaux ?","o":["Adaptation à la législation locale","Prix toujours nul","Aucune raison"],"a":0,"e":"Marché."},{"q":"Un logiciel sur site est installé…","o":["Sur les serveurs de l'entreprise","Chez l'éditeur","Nulle part"],"a":0,"e":"Définition."},{"q":"Un logiciel SaaS est…","o":["Accessible en ligne et hébergé par l'éditeur","Installé sur chaque poste","Gratuit"],"a":0,"e":"Définition."},{"q":"Le SaaS est payé…","o":["Par abonnement","Une seule fois pour toujours","Jamais"],"a":0,"e":"Modèle."},{"q":"Les mises à jour d'un SaaS sont…","o":["Automatiques","Impossibles","Manuelles sur chaque poste"],"a":0,"e":"Avantage."},{"q":"Une information saisie une fois dans un ERP est…","o":["Disponible pour tous les modules","Perdue","Recopiée à la main"],"a":0,"e":"Intégration."},{"q":"Le catalogue de formation relève du module…","o":["Formation","Paie","Temps"],"a":0,"e":"Module."},{"q":"Oracle propose…","o":["HCM Cloud","e-impôts","SuccessFactors"],"a":0,"e":"Marché."},{"q":"Le dossier salarié relève du module…","o":["Administration du personnel","Recrutement","Reporting"],"a":0,"e":"Module."}]},{"id":"mrh312-2","n":2,"t":"Le métier de consultant fonctionnel","min":20,"html":"<p>Le consultant fonctionnel SIRH fait le lien entre le <strong>métier RH</strong> et l'<strong>outil</strong>. Il comprend les processus RH et paie, et sait les traduire en paramétrage.</p>\n<h3>Les acteurs d'un projet SIRH</h3>\n<div class=\"tbl\"><table><thead><tr><th>Acteur</th><th>Rôle</th></tr></thead><tbody>\n<tr><td>Sponsor</td><td>Membre de la direction qui porte le projet et arbitre</td></tr>\n<tr><td>Chef de projet</td><td>Pilote planning, budget, risques, équipe</td></tr>\n<tr><td>Consultant fonctionnel</td><td>Recueille les besoins, conçoit la solution, paramètre, forme</td></tr>\n<tr><td>Consultant technique</td><td>Interfaces, développements spécifiques, reprise de données, infrastructure</td></tr>\n<tr><td>Utilisateurs clés (key users)</td><td>Experts métier du client qui participent aux ateliers, testent et forment leurs collègues</td></tr>\n<tr><td>Utilisateurs finaux</td><td>Gestionnaires, managers, salariés</td></tr></tbody></table></div>\n<h3>Les compétences du consultant fonctionnel</h3>\n<ul><li>Connaissance des processus RH, du droit du travail et de la paie.</li><li>Maîtrise d'un ou plusieurs progiciels.</li><li>Capacité d'analyse et de modélisation des processus.</li><li>Rédaction (spécifications, procédures, supports de formation).</li><li>Animation d'ateliers, écoute, pédagogie.</li><li>Gestion des priorités et des délais.</li></ul>\n<h3>Côté éditeur, intégrateur ou client</h3>\n<p>Le consultant peut travailler chez un <strong>éditeur</strong> (qui conçoit le logiciel), chez un <strong>intégrateur</strong> ou cabinet de conseil (qui met en place le logiciel chez des clients), ou <strong>en interne</strong> chez un client (équipe SIRH).</p>\n<div class=\"callout\"><b>Profil type</b>Beaucoup de consultants fonctionnels SIRH sont d'anciens gestionnaires de paie ou d'administration du personnel : leur expérience métier est un atout.</div>","quiz":[{"q":"Le consultant fonctionnel fait le lien entre…","o":["Le métier RH et l'outil","La banque et le fisc","Le client et le fournisseur de matières"],"a":0,"e":"Définition."},{"q":"Le sponsor est…","o":["Un membre de la direction qui porte le projet","Un utilisateur final","Un fournisseur"],"a":0,"e":"Rôle."},{"q":"Le chef de projet pilote…","o":["Planning, budget, risques","La paie mensuelle","Les ventes"],"a":0,"e":"Rôle."},{"q":"Qui paramètre la solution côté métier ?","o":["Le consultant fonctionnel","Le sponsor","Le salarié"],"a":0,"e":"Rôle."},{"q":"Les interfaces et développements spécifiques relèvent…","o":["Du consultant technique","Du consultant fonctionnel seul","Du sponsor"],"a":0,"e":"Rôle."},{"q":"Les key users sont…","o":["Des experts métier du client","Des développeurs de l'éditeur","Des clients externes"],"a":0,"e":"Rôle."},{"q":"Les key users…","o":["Participent aux ateliers et testent","Ne font rien","Signent le budget"],"a":0,"e":"Rôle."},{"q":"Qui arbitre les décisions importantes ?","o":["Le sponsor","L'utilisateur final","Le stagiaire"],"a":0,"e":"Gouvernance."},{"q":"Une compétence du consultant fonctionnel est…","o":["L'animation d'ateliers","La soudure","La conduite de camions"],"a":0,"e":"Compétence."},{"q":"La modélisation des processus est…","o":["Une compétence du consultant","Inutile","Réservée au sponsor"],"a":0,"e":"Compétence."},{"q":"Un éditeur…","o":["Conçoit le logiciel","Utilise seulement le logiciel","Contrôle la CNPS"],"a":0,"e":"Acteur du marché."},{"q":"Un intégrateur…","o":["Met en place le logiciel chez des clients","Conçoit toujours le logiciel","Est un salarié du client"],"a":0,"e":"Acteur du marché."},{"q":"Un consultant interne travaille…","o":["Dans l'équipe SIRH d'un client","Chez l'éditeur","Nulle part"],"a":0,"e":"Mode d'exercice."},{"q":"La reprise de données relève surtout…","o":["Du consultant technique","Du sponsor","Des salariés"],"a":0,"e":"Rôle."},{"q":"Les utilisateurs finaux sont…","o":["Gestionnaires, managers, salariés","Les développeurs","Les actionnaires"],"a":0,"e":"Rôle."},{"q":"Un atout d'un ancien gestionnaire de paie devenu consultant ?","o":["Son expérience métier","Aucun","Sa méconnaissance"],"a":0,"e":"Profil."},{"q":"La rédaction de spécifications relève du…","o":["Consultant fonctionnel","Consultant technique uniquement","Sponsor"],"a":0,"e":"Rôle."},{"q":"Former les utilisateurs est une mission du…","o":["Consultant fonctionnel (et des key users)","Sponsor seul","Fisc"],"a":0,"e":"Rôle."},{"q":"Connaître le droit du travail est utile au consultant…","o":["Fonctionnel","Technique réseau","Commercial uniquement"],"a":0,"e":"Compétence."},{"q":"Les key users forment ensuite…","o":["Leurs collègues","Les éditeurs","Le sponsor"],"a":0,"e":"Démultiplication."}]},{"id":"mrh312-3","n":3,"t":"Cadrer le projet","min":20,"html":"<h3>La note de cadrage</h3>\n<p>Elle définit ce que le projet doit produire et dans quelles conditions :</p>\n<ul><li><strong>Contexte et objectifs</strong> : pourquoi changer (outil obsolète, erreurs de paie, croissance, obligations légales) ?</li><li><strong>Périmètre</strong> : quels modules, quelles entités, quelles populations (tous les salariés, les expatriés ?). Ce qui est hors périmètre est aussi écrit.</li><li><strong>Livrables</strong> : solution paramétrée, données reprises, utilisateurs formés.</li><li><strong>Planning</strong> et jalons clés.</li><li><strong>Budget</strong> : licences ou abonnements, prestations, formation, temps interne.</li><li><strong>Organisation</strong> et gouvernance.</li><li><strong>Risques</strong> identifiés.</li></ul>\n<h3>La gouvernance</h3>\n<div class=\"tbl\"><table><thead><tr><th>Instance</th><th>Membres</th><th>Rôle</th><th>Fréquence</th></tr></thead><tbody>\n<tr><td>Comité de pilotage (COPIL)</td><td>Sponsor, direction, chefs de projet</td><td>Décisions stratégiques, arbitrages, budget</td><td>Mensuelle</td></tr>\n<tr><td>Comité de projet (COPROJ)</td><td>Chefs de projet, consultants, key users</td><td>Suivi opérationnel, avancement, problèmes</td><td>Hebdomadaire</td></tr></tbody></table></div>\n<h3>Le triangle du projet</h3>\n<p><strong>Périmètre, délai, coût</strong> sont liés : élargir le périmètre sans changer le délai ni le budget fait baisser la qualité. Toute demande nouvelle passe par une procédure de gestion des changements.</p>\n<h3>Le planning d'un projet paie</h3>\n<p>On évite de démarrer une nouvelle paie en décembre ou en janvier (clôture annuelle, nouveaux taux) ; un démarrage en début de trimestre ou d'année, préparé à l'avance, est souvent privilégié.</p>","quiz":[{"q":"La note de cadrage définit…","o":["Ce que le projet doit produire et comment","Les salaires","Les ventes"],"a":0,"e":"Définition."},{"q":"Le périmètre précise…","o":["Modules, entités, populations","La couleur de l'outil","Le nom des salariés"],"a":0,"e":"Contenu."},{"q":"Faut-il écrire ce qui est hors périmètre ?","o":["Oui","Non","Seulement à la fin"],"a":0,"e":"Clarté."},{"q":"Un livrable du projet est…","o":["Des utilisateurs formés","Un bilan comptable","Un contrat de vente"],"a":0,"e":"Exemple."},{"q":"Le budget comprend aussi…","o":["Le temps interne","Uniquement la licence","Rien d'autre"],"a":0,"e":"Coûts."},{"q":"COPIL signifie…","o":["Comité de pilotage","Comité de pilotes aériens","Contrôle de paie"],"a":0,"e":"Gouvernance."},{"q":"Le COPIL prend…","o":["Les décisions stratégiques","Les décisions de saisie quotidienne","Aucune décision"],"a":0,"e":"Rôle."},{"q":"Fréquence indicative du COPIL ?","o":["Mensuelle","Quotidienne","Annuelle"],"a":0,"e":"Rythme."},{"q":"Le COPROJ assure…","o":["Le suivi opérationnel","Les arbitrages budgétaires majeurs","La paie"],"a":0,"e":"Rôle."},{"q":"Fréquence indicative du COPROJ ?","o":["Hebdomadaire","Annuelle","Jamais"],"a":0,"e":"Rythme."},{"q":"Les trois sommets du triangle du projet ?","o":["Périmètre, délai, coût","Nom, prénom, âge","Rouge, vert, bleu"],"a":0,"e":"Modèle."},{"q":"Élargir le périmètre sans changer délai ni budget fait baisser…","o":["La qualité","Les coûts","Les risques"],"a":0,"e":"Triangle."},{"q":"Une demande nouvelle passe par…","o":["La gestion des changements","Un accord oral","Rien"],"a":0,"e":"Procédure."},{"q":"Période à éviter pour démarrer une nouvelle paie ?","o":["Décembre-janvier","Mars","Juin"],"a":0,"e":"Planning."},{"q":"Pourquoi éviter décembre-janvier ?","o":["Clôture annuelle et nouveaux taux","Congés des consultants seulement","Aucune raison"],"a":0,"e":"Contraintes."},{"q":"Un objectif de projet SIRH peut être…","o":["Réduire les erreurs de paie","Augmenter les erreurs","Supprimer les RH"],"a":0,"e":"Exemple."},{"q":"Les risques sont…","o":["Identifiés dès le cadrage","Ignorés","Découverts à la fin seulement"],"a":0,"e":"Anticipation."},{"q":"Les key users participent au…","o":["COPROJ","COPIL obligatoirement seul","Conseil d'administration"],"a":0,"e":"Instance."},{"q":"Le sponsor participe au…","o":["COPIL","COPROJ uniquement","Rien"],"a":0,"e":"Instance."},{"q":"Les jalons clés figurent dans…","o":["Le planning","Le bulletin","Le contrat de travail"],"a":0,"e":"Contenu."}]},{"id":"mrh312-4","n":4,"t":"Recueillir les besoins","min":25,"html":"<h3>Les techniques</h3>\n<div class=\"tbl\"><table><thead><tr><th>Technique</th><th>Usage</th></tr></thead><tbody>\n<tr><td>Entretiens individuels</td><td>Comprendre les attentes d'un décideur ou d'un expert</td></tr>\n<tr><td>Ateliers</td><td>Décrire un processus avec plusieurs acteurs</td></tr>\n<tr><td>Observation</td><td>Voir comment le travail se fait réellement</td></tr>\n<tr><td>Analyse documentaire</td><td>Contrats, convention collective, bulletins, procédures, rapports</td></tr>\n<tr><td>Questionnaire</td><td>Recueillir l'avis de nombreux utilisateurs</td></tr></tbody></table></div>\n<h3>AS-IS et TO-BE</h3>\n<p>On décrit d'abord le processus <strong>actuel</strong> (AS-IS) : étapes, acteurs, outils, irritants. Puis le processus <strong>cible</strong> (TO-BE) : ce qu'il sera avec le nouvel outil. L'écart entre les deux montre ce qu'il faut paramétrer et changer.</p>\n<h3>Animer un atelier</h3>\n<ol><li>Envoyer l'objectif et la liste des documents à apporter.</li><li>Rappeler le périmètre en ouverture.</li><li>Faire décrire le processus pas à pas, avec des cas réels.</li><li>Distinguer les <strong>besoins</strong> (ce qu'il faut obtenir) des <strong>solutions</strong> imaginées.</li><li>Noter les règles de gestion (« la prime d'ancienneté démarre à 2 ans »).</li><li>Faire un compte rendu validé par les participants.</li></ol>\n<h3>Prioriser : la méthode MoSCoW</h3>\n<ul><li><strong>Must have</strong> : indispensable (paie conforme).</li><li><strong>Should have</strong> : important mais contournable.</li><li><strong>Could have</strong> : souhaitable si le temps le permet.</li><li><strong>Won't have (this time)</strong> : pas dans cette version.</li></ul>\n<div class=\"callout\"><b>Piège</b>Reproduire à l'identique dans le nouvel outil toutes les habitudes de l'ancien : c'est l'occasion de simplifier.</div>","quiz":[{"q":"Pour décrire un processus avec plusieurs acteurs, on organise…","o":["Un atelier","Un questionnaire","Une facture"],"a":0,"e":"Technique."},{"q":"Pour voir comment le travail se fait réellement, on utilise…","o":["L'observation","Le questionnaire","Le devis"],"a":0,"e":"Technique."},{"q":"La convention collective fait partie de…","o":["L'analyse documentaire","L'observation","Le questionnaire"],"a":0,"e":"Technique."},{"q":"Pour recueillir l'avis de nombreux utilisateurs :","o":["Questionnaire","Entretien individuel","Observation"],"a":0,"e":"Technique."},{"q":"AS-IS désigne…","o":["Le processus actuel","Le processus cible","Le budget"],"a":0,"e":"Définition."},{"q":"TO-BE désigne…","o":["Le processus cible","Le processus actuel","Le planning"],"a":0,"e":"Définition."},{"q":"L'écart AS-IS / TO-BE montre…","o":["Ce qu'il faut paramétrer et changer","Le salaire","Les ventes"],"a":0,"e":"Analyse."},{"q":"Un irritant est…","o":["Une difficulté du processus actuel","Un bonus","Une règle légale"],"a":0,"e":"AS-IS."},{"q":"En atelier, on distingue besoins et…","o":["Solutions imaginées","Salaires","Congés"],"a":0,"e":"Méthode."},{"q":"« La prime d'ancienneté démarre à 2 ans » est…","o":["Une règle de gestion","Un besoin vague","Une solution technique"],"a":0,"e":"Exemple."},{"q":"Le compte rendu d'atelier est…","o":["Validé par les participants","Secret","Facultatif"],"a":0,"e":"Validation."},{"q":"Le « M » de MoSCoW signifie…","o":["Must have","Maybe","Money"],"a":0,"e":"Priorisation."},{"q":"Une paie conforme est un besoin…","o":["Must have","Could have","Won't have"],"a":0,"e":"Indispensable."},{"q":"« Should have » désigne…","o":["Important mais contournable","Indispensable","Exclu"],"a":0,"e":"Priorisation."},{"q":"« Could have » désigne…","o":["Souhaitable si le temps le permet","Indispensable","Interdit"],"a":0,"e":"Priorisation."},{"q":"« Won't have this time » désigne…","o":["Pas dans cette version","Indispensable","Urgent"],"a":0,"e":"Priorisation."},{"q":"Piège fréquent ?","o":["Reproduire toutes les habitudes de l'ancien outil","Simplifier","Prioriser"],"a":0,"e":"Opportunité perdue."},{"q":"En ouverture d'atelier, on rappelle…","o":["Le périmètre","Les salaires","Les impôts"],"a":0,"e":"Cadrage."},{"q":"Décrire le processus avec des cas réels aide à…","o":["Ne rien oublier","Aller plus vite sans réfléchir","Compliquer"],"a":0,"e":"Concret."},{"q":"Pour comprendre les attentes d'un décideur :","o":["Entretien individuel","Questionnaire de masse","Observation"],"a":0,"e":"Technique."}]},{"id":"mrh312-5","n":5,"t":"Rédiger les spécifications","min":20,"html":"<h3>Le cahier des charges</h3>\n<p>Rédigé par le client (avec l'aide d'un consultant) avant de choisir un éditeur, il décrit le contexte, les besoins fonctionnels et techniques, les contraintes (légales, budget, délais) et les critères de sélection.</p>\n<h3>Les spécifications fonctionnelles</h3>\n<p>Après le choix de la solution, elles décrivent précisément comment l'outil doit fonctionner pour chaque processus : écrans, données, règles de gestion, calculs, workflows, éditions, droits d'accès.</p>\n<div class=\"tbl\"><table><thead><tr><th>Rubrique</th><th>Exemple</th></tr></thead><tbody>\n<tr><td>Règle de gestion</td><td>La prime d'ancienneté est égale à 2 % du salaire de base après 2 ans, puis +1 % par an, plafonnée à 25 %</td></tr>\n<tr><td>Donnée d'entrée</td><td>Date d'ancienneté, salaire de base</td></tr>\n<tr><td>Calcul</td><td>Taux = min(25 %, 2 % + (ancienneté − 2) × 1 %) si ancienneté ≥ 2</td></tr>\n<tr><td>Cas particuliers</td><td>Salarié réembauché : reprise d'ancienneté selon décision</td></tr>\n<tr><td>Test attendu</td><td>6 ans d'ancienneté, base 200 000 → prime 12 000</td></tr></tbody></table></div>\n<h3>Les récits utilisateurs (user stories)</h3>\n<p>Dans les projets agiles, un besoin s'écrit : « En tant que <em>[rôle]</em>, je veux <em>[action]</em> afin de <em>[bénéfice]</em>. » Exemple : « En tant que manager, je veux valider les demandes de congés depuis mon téléphone afin de répondre sous 24 heures. »</p>\n<h3>Les qualités d'une bonne spécification</h3>\n<p>Claire, complète, testable (on peut vérifier qu'elle est respectée), validée par le métier, versionnée (numéro et date de version).</p>","quiz":[{"q":"Le cahier des charges est rédigé…","o":["Avant le choix de l'éditeur","Après la mise en production","Jamais"],"a":0,"e":"Chronologie."},{"q":"Le cahier des charges contient…","o":["Besoins et critères de sélection","Les bulletins","Le code source"],"a":0,"e":"Contenu."},{"q":"Les spécifications fonctionnelles décrivent…","o":["Comment l'outil doit fonctionner","Le prix","Les salaires"],"a":0,"e":"Définition."},{"q":"Elles sont rédigées…","o":["Après le choix de la solution","Avant tout projet","Par le salarié"],"a":0,"e":"Chronologie."},{"q":"Une règle de gestion est par exemple…","o":["Le mode de calcul de la prime d'ancienneté","Le logo","Le nom de l'éditeur"],"a":0,"e":"Exemple."},{"q":"Ancienneté 6 ans, base 200 000 : prime attendue ?","o":["12 000","8 000","20 000"],"a":0,"e":"6 %."},{"q":"Ancienneté 1 an : prime selon la règle ?","o":["0","2 %","1 %"],"a":0,"e":"Avant 2 ans."},{"q":"Ancienneté 30 ans : taux selon la règle ?","o":["25 %","30 %","2 %"],"a":0,"e":"Plafond."},{"q":"Un salarié réembauché est…","o":["Un cas particulier","Hors sujet","Un paramètre de taux"],"a":0,"e":"Exemple."},{"q":"Format d'une user story ?","o":["En tant que…, je veux…, afin de…","Titre, prix, délai","Nom, âge, salaire"],"a":0,"e":"Agile."},{"q":"Dans « En tant que manager… », le manager est…","o":["Le rôle","Le bénéfice","L'action"],"a":0,"e":"Structure."},{"q":"« Afin de répondre sous 24 h » est…","o":["Le bénéfice","Le rôle","L'action"],"a":0,"e":"Structure."},{"q":"Une bonne spécification est…","o":["Testable","Vague","Secrète"],"a":0,"e":"Qualité."},{"q":"Une spécification doit être validée par…","o":["Le métier","Le fournisseur de café","Personne"],"a":0,"e":"Qualité."},{"q":"Versionner une spécification, c'est…","o":["Lui donner un numéro et une date","La traduire","La supprimer"],"a":0,"e":"Qualité."},{"q":"Les droits d'accès font partie…","o":["Des spécifications fonctionnelles","Du bilan","Du contrat de travail"],"a":0,"e":"Contenu."},{"q":"Un test attendu dans la spécification sert…","o":["À la recette","À la paie du consultant","À rien"],"a":0,"e":"Lien avec les tests."},{"q":"Les user stories sont typiques des projets…","o":["Agiles","Sans méthode","Juridiques"],"a":0,"e":"Méthode."},{"q":"Les contraintes légales figurent dans…","o":["Le cahier des charges","Le bulletin","L'annonce de recrutement"],"a":0,"e":"Contenu."},{"q":"Un workflow décrit…","o":["Un circuit de validation","Un salaire","Une facture"],"a":0,"e":"Contenu."}]},{"id":"mrh312-6","n":6,"t":"Choisir une solution","min":20,"html":"<h3>La démarche de sélection</h3>\n<ol><li>Rédiger le cahier des charges.</li><li>Identifier les éditeurs et intégrateurs possibles (veille, références).</li><li>Lancer un appel d'offres ou une consultation.</li><li>Analyser les réponses écrites.</li><li>Organiser des <strong>démonstrations sur scénarios</strong> : l'éditeur montre comment son outil traite vos cas réels.</li><li>Contacter des <strong>références</strong> clientes.</li><li>Noter avec une grille et décider.</li><li>Négocier le contrat.</li></ol>\n<h3>La grille de sélection</h3>\n<div class=\"tbl\"><table><thead><tr><th>Critère</th><th>Poids</th></tr></thead><tbody>\n<tr><td>Couverture fonctionnelle (dont conformité paie ivoirienne)</td><td>35 %</td></tr>\n<tr><td>Ergonomie et facilité d'usage</td><td>15 %</td></tr>\n<tr><td>Coût total sur 5 ans</td><td>20 %</td></tr>\n<tr><td>Solidité de l'éditeur et support local</td><td>15 %</td></tr>\n<tr><td>Technique (sécurité, hébergement, interfaces)</td><td>15 %</td></tr></tbody></table></div>\n<p>Chaque solution reçoit une note sur 5 par critère ; la note pondérée = somme (note × poids).</p>\n<div class=\"callout\"><b>Exemple</b>Solution A : 4 × 35 % + 3 × 15 % + 3 × 20 % + 4 × 15 % + 4 × 15 % = 1,4 + 0,45 + 0,6 + 0,6 + 0,6 = <strong>3,65 / 5</strong>.</div>\n<h3>Le coût total de possession (TCO)</h3>\n<p>Il inclut licences ou abonnements, mise en œuvre, reprise de données, formation, maintenance, évolutions réglementaires, hébergement et temps interne, sur plusieurs années.</p>\n<h3>Le contrat</h3>\n<p>Il précise le périmètre, les niveaux de service (disponibilité, délais de correction), la mise à jour réglementaire, la réversibilité (récupération des données en fin de contrat) et la protection des données.</p>","quiz":[{"q":"Première étape de la sélection ?","o":["Rédiger le cahier des charges","Signer le contrat","Former les utilisateurs"],"a":0,"e":"Ordre."},{"q":"Une démonstration sur scénarios montre…","o":["Le traitement de vos cas réels","Une vidéo publicitaire","Les salaires de l'éditeur"],"a":0,"e":"Méthode."},{"q":"Contacter des références clientes sert à…","o":["Vérifier l'expérience d'autres clients","Recruter","Payer"],"a":0,"e":"Méthode."},{"q":"Critère le plus pondéré dans l'exemple ?","o":["Couverture fonctionnelle","Ergonomie","Technique"],"a":0,"e":"35 %."},{"q":"Poids du coût total dans l'exemple ?","o":["20 %","35 %","5 %"],"a":0,"e":"Grille."},{"q":"Note pondérée =","o":["Somme des notes × poids","Moyenne simple toujours","Note la plus haute"],"a":0,"e":"Calcul."},{"q":"Note pondérée de la solution A ?","o":["3,65","4","3,2"],"a":0,"e":"Calcul."},{"q":"Notes toutes à 5 : note pondérée ?","o":["5","25","1"],"a":0,"e":"Somme des poids = 100 %."},{"q":"Notes toutes à 3 : note pondérée ?","o":["3","15","0,6"],"a":0,"e":"Somme des poids = 100 %."},{"q":"Le TCO signifie…","o":["Coût total de possession","Taux de cotisation obligatoire","Tableau de contrôle"],"a":0,"e":"Définition."},{"q":"Le TCO inclut…","o":["Formation et maintenance","Seulement la licence","Seulement le matériel"],"a":0,"e":"Contenu."},{"q":"Le TCO se calcule sur…","o":["Plusieurs années","Un mois","Un jour"],"a":0,"e":"Horizon."},{"q":"La réversibilité permet…","o":["De récupérer ses données en fin de contrat","D'annuler le projet sans frais","De revenir au papier"],"a":0,"e":"Clause."},{"q":"Les niveaux de service précisent…","o":["Disponibilité et délais de correction","Les salaires","Les congés"],"a":0,"e":"Clause."},{"q":"La mise à jour réglementaire est importante car…","o":["Les taux et barèmes changent","Rien ne change","Pour décorer"],"a":0,"e":"Clause."},{"q":"La conformité paie ivoirienne relève du critère…","o":["Couverture fonctionnelle","Ergonomie","Technique"],"a":0,"e":"Grille."},{"q":"Un support local est un critère lié à…","o":["La solidité de l'éditeur","L'ergonomie","Le coût uniquement"],"a":0,"e":"Grille."},{"q":"La sécurité et l'hébergement relèvent du critère…","o":["Technique","Ergonomie","Couverture"],"a":0,"e":"Grille."},{"q":"Après la décision, on…","o":["Négocie le contrat","Lance l'appel d'offres","Rédige le cahier des charges"],"a":0,"e":"Ordre."},{"q":"La protection des données doit figurer…","o":["Dans le contrat","Nulle part","Dans l'annonce"],"a":0,"e":"Clause."}]},{"id":"mrh312-7","n":7,"t":"Paramétrer la solution","min":25,"html":"<h3>Paramétrage ou développement ?</h3>\n<p>Le <strong>paramétrage</strong> utilise les options prévues par le logiciel (tables, règles, écrans). Le <strong>développement spécifique</strong> modifie ou complète le code : il coûte plus cher, complique les mises à jour et doit rester exceptionnel.</p>\n<h3>Les grands blocs de paramétrage</h3>\n<div class=\"tbl\"><table><thead><tr><th>Bloc</th><th>Contenu</th></tr></thead><tbody>\n<tr><td>Structures</td><td>Sociétés, établissements, services, centres de coûts, postes</td></tr>\n<tr><td>Référentiels</td><td>Catégories, emplois, grilles de salaires, motifs d'entrée et de sortie, types d'absence</td></tr>\n<tr><td>Paie</td><td>Rubriques (gains, retenues, cotisations), formules, taux, plafonds, barème ITS, bulletin</td></tr>\n<tr><td>Temps</td><td>Calendriers, horaires, règles d'acquisition des congés</td></tr>\n<tr><td>Workflows</td><td>Circuits de validation (congés, embauche, modification de salaire)</td></tr>\n<tr><td>Habilitations</td><td>Profils et droits d'accès (qui voit et modifie quoi)</td></tr>\n<tr><td>Éditions</td><td>Attestations, états de contrôle, déclarations</td></tr></tbody></table></div>\n<h3>La rubrique de paie</h3>\n<p>Chaque rubrique a un code, un libellé, un type (gain, retenue, cotisation, information), une formule ou un mode de saisie, et des propriétés : soumise ou non à cotisations, imposable ou non, prise en compte dans la base de congés.</p>\n<h3>Les habilitations</h3>\n<p>Principe du <strong>moindre privilège</strong> : chaque utilisateur n'a que les droits nécessaires à sa fonction. Un manager voit son équipe, pas toute l'entreprise ; un gestionnaire paie ne valide pas sa propre saisie.</p>\n<h3>Documenter</h3>\n<p>Chaque paramétrage est documenté (dossier de paramétrage) pour permettre la maintenance, les audits et la formation.</p>","quiz":[{"q":"Le paramétrage utilise…","o":["Les options prévues par le logiciel","Du nouveau code","Des feuilles papier"],"a":0,"e":"Définition."},{"q":"Le développement spécifique…","o":["Modifie ou complète le code","Utilise les options standard","Est gratuit"],"a":0,"e":"Définition."},{"q":"Pourquoi limiter les développements spécifiques ?","o":["Coût et complexité des mises à jour","Ils sont interdits","Ils sont trop simples"],"a":0,"e":"Risque."},{"q":"Les établissements font partie du bloc…","o":["Structures","Paie","Éditions"],"a":0,"e":"Bloc."},{"q":"Les types d'absence font partie des…","o":["Référentiels","Workflows","Habilitations"],"a":0,"e":"Bloc."},{"q":"Le barème ITS fait partie du bloc…","o":["Paie","Temps","Structures"],"a":0,"e":"Bloc."},{"q":"Les règles d'acquisition des congés relèvent du bloc…","o":["Temps","Paie","Éditions"],"a":0,"e":"Bloc."},{"q":"Un circuit de validation des congés est un…","o":["Workflow","Référentiel","Barème"],"a":0,"e":"Bloc."},{"q":"Qui voit et modifie quoi relève des…","o":["Habilitations","Structures","Éditions"],"a":0,"e":"Bloc."},{"q":"Une attestation de travail relève des…","o":["Éditions","Workflows","Référentiels"],"a":0,"e":"Bloc."},{"q":"Un type de rubrique est…","o":["Gain, retenue, cotisation ou information","Rouge ou vert","Petit ou grand"],"a":0,"e":"Propriété."},{"q":"Une propriété de rubrique est…","o":["Imposable ou non","Sa couleur","Son auteur"],"a":0,"e":"Propriété."},{"q":"Le principe du moindre privilège signifie…","o":["Seulement les droits nécessaires","Tous les droits pour tous","Aucun droit"],"a":0,"e":"Sécurité."},{"q":"Un manager voit…","o":["Son équipe","Toute l'entreprise","Rien"],"a":0,"e":"Habilitation."},{"q":"Un gestionnaire paie valide-t-il sa propre saisie ?","o":["Non","Oui","Toujours"],"a":0,"e":"Séparation des tâches."},{"q":"Le dossier de paramétrage sert à…","o":["Maintenance, audits, formation","Rien","Payer l'éditeur"],"a":0,"e":"Documentation."},{"q":"Les centres de coûts relèvent du bloc…","o":["Structures","Temps","Éditions"],"a":0,"e":"Bloc."},{"q":"Une grille de salaires relève des…","o":["Référentiels","Workflows","Habilitations"],"a":0,"e":"Bloc."},{"q":"Une rubrique « prise en compte dans la base de congés » influence…","o":["L'allocation de congé","Le logo","Le recrutement"],"a":0,"e":"Propriété."},{"q":"Les motifs de sortie font partie des…","o":["Référentiels","Éditions","Structures"],"a":0,"e":"Bloc."}]},{"id":"mrh312-8","n":8,"t":"Reprendre les données","min":20,"html":"<p>La reprise (ou migration) de données transfère les informations de l'ancien système vers le nouveau. C'est souvent l'étape la plus sous-estimée d'un projet SIRH.</p>\n<h3>Les étapes</h3>\n<ol><li><strong>Inventaire</strong> : quelles données reprendre (salariés actifs, historiques de paie, soldes de congés, cumuls annuels) ?</li><li><strong>Extraction</strong> depuis l'ancien système.</li><li><strong>Nettoyage</strong> : doublons, champs vides, formats, salariés partis encore actifs.</li><li><strong>Correspondance (mapping)</strong> : chaque champ et code de l'ancien système est associé à son équivalent dans le nouveau.</li><li><strong>Chargement</strong> dans un environnement de test.</li><li><strong>Contrôle</strong> : comptages, sommes, échantillons.</li><li><strong>Chargement définitif</strong> avant la bascule.</li></ol>\n<h3>Le mapping</h3>\n<div class=\"tbl\"><table><thead><tr><th>Ancien code</th><th>Ancien libellé</th><th>Nouveau code</th></tr></thead><tbody>\n<tr><td>AB01</td><td>Absence maladie</td><td>MAL</td></tr>\n<tr><td>AB02</td><td>Absence injustifiée</td><td>ABI</td></tr>\n<tr><td>CP</td><td>Congé payé</td><td>CPA</td></tr></tbody></table></div>\n<h3>Les contrôles de reprise</h3>\n<ul><li>Nombre de salariés : identique entre ancien et nouveau système.</li><li>Somme des salaires de base : identique.</li><li>Soldes de congés et cumuls annuels (brut, cotisations, ITS) : identiques.</li><li>Échantillon de dossiers vérifiés un par un.</li></ul>\n<h3>Les cumuls annuels</h3>\n<p>Si l'on démarre en cours d'année, il faut reprendre les cumuls des mois déjà payés, sinon les déclarations annuelles (DISA, état 301) seront fausses. D'où l'intérêt de démarrer en début d'année quand c'est possible.</p>","quiz":[{"q":"La reprise de données transfère…","o":["Les informations de l'ancien vers le nouveau système","Les salariés vers un autre employeur","Les impôts"],"a":0,"e":"Définition."},{"q":"Étape souvent sous-estimée ?","o":["La reprise de données","Le choix du logo","La réunion de lancement"],"a":0,"e":"Risque."},{"q":"Première étape de la reprise ?","o":["L'inventaire","Le chargement définitif","Le contrôle"],"a":0,"e":"Ordre."},{"q":"Supprimer les doublons relève du…","o":["Nettoyage","Mapping","Chargement"],"a":0,"e":"Étape."},{"q":"Le mapping associe…","o":["Chaque code ancien à un code nouveau","Deux salariés","Deux banques"],"a":0,"e":"Définition."},{"q":"Dans l'exemple, AB01 devient…","o":["MAL","ABI","CPA"],"a":0,"e":"Lecture."},{"q":"Dans l'exemple, CP devient…","o":["CPA","MAL","ABI"],"a":0,"e":"Lecture."},{"q":"Le premier chargement se fait…","o":["Dans un environnement de test","Directement en production","Sur papier"],"a":0,"e":"Prudence."},{"q":"Un contrôle de reprise simple est…","o":["Comparer le nombre de salariés","Compter les pages","Regarder les couleurs"],"a":0,"e":"Comptage."},{"q":"La somme des salaires de base doit être…","o":["Identique","Différente","Ignorée"],"a":0,"e":"Contrôle."},{"q":"Les cumuls annuels comprennent…","o":["Brut, cotisations, ITS","Les ventes","Les stocks"],"a":0,"e":"Contenu."},{"q":"Sans reprise des cumuls en cours d'année…","o":["Les déclarations annuelles seront fausses","Tout va bien","La paie est plus simple"],"a":0,"e":"Risque."},{"q":"Déclarations annuelles concernées ?","o":["DISA et état 301","TVA et douane","Aucune"],"a":0,"e":"Lien."},{"q":"Pourquoi démarrer en début d'année ?","o":["Éviter la reprise de cumuls","Pour les congés","Aucune raison"],"a":0,"e":"Simplification."},{"q":"Un salarié parti encore « actif » dans l'ancien système doit être…","o":["Nettoyé","Repris tel quel","Payé"],"a":0,"e":"Qualité."},{"q":"Vérifier un échantillon de dossiers un par un est…","o":["Un contrôle de reprise","Inutile","Interdit"],"a":0,"e":"Contrôle."},{"q":"Le chargement définitif intervient…","o":["Avant la bascule","Après un an","Jamais"],"a":0,"e":"Ordre."},{"q":"Les soldes de congés doivent être…","o":["Repris et contrôlés","Remis à zéro","Doublés"],"a":0,"e":"Droits des salariés."},{"q":"L'extraction se fait depuis…","o":["L'ancien système","Le nouveau système","La banque"],"a":0,"e":"Étape."},{"q":"Les formats incohérents sont traités lors…","o":["Du nettoyage","Du COPIL","De la paie"],"a":0,"e":"Étape."}]},{"id":"mrh312-9","n":9,"t":"La recette","min":25,"html":"<p>La recette vérifie que la solution paramétrée répond aux besoins spécifiés avant sa mise en production.</p>\n<h3>Les niveaux de tests</h3>\n<div class=\"tbl\"><table><thead><tr><th>Test</th><th>Objet</th><th>Qui</th></tr></thead><tbody>\n<tr><td>Tests unitaires</td><td>Une règle ou rubrique isolée</td><td>Consultant</td></tr>\n<tr><td>Tests d'intégration</td><td>Enchaînement de processus et interfaces (SIRH → paie → comptabilité)</td><td>Consultants</td></tr>\n<tr><td>Recette utilisateur</td><td>Scénarios métier réels</td><td>Key users</td></tr>\n<tr><td>Paie en parallèle</td><td>Même mois calculé dans l'ancien et le nouveau système, comparaison salarié par salarié</td><td>Équipe paie</td></tr></tbody></table></div>\n<h3>Le cahier de recette</h3>\n<p>Chaque cas de test précise : identifiant, objectif, données de départ, étapes, résultat attendu, résultat obtenu, statut (conforme / non conforme), preuve (capture d'écran).</p>\n<h3>La gravité des anomalies</h3>\n<ul><li><strong>Bloquante</strong> : empêche un processus essentiel (la paie ne se calcule pas). Mise en production impossible.</li><li><strong>Majeure</strong> : résultat faux sans contournement simple (cotisation mal calculée).</li><li><strong>Mineure</strong> : gêne sans impact sur le résultat (libellé mal orthographié).</li></ul>\n<h3>La paie en parallèle</h3>\n<p>On compare les nets et les principales rubriques pour chaque salarié. Chaque écart est expliqué (anomalie, correction de l'ancien système, différence d'arrondi). On réalise en général deux paies parallèles concluantes avant de basculer.</p>\n<h3>Le procès-verbal de recette</h3>\n<p>Signé par le client, il atteste que la solution est conforme, éventuellement avec des réserves (anomalies mineures à corriger), et autorise la mise en production.</p>","quiz":[{"q":"La recette vérifie…","o":["Que la solution répond aux besoins","Le salaire du consultant","Les ventes"],"a":0,"e":"Définition."},{"q":"Un test unitaire porte sur…","o":["Une règle isolée","Toute l'entreprise","Le planning"],"a":0,"e":"Niveau."},{"q":"Un test d'intégration porte sur…","o":["L'enchaînement des processus et interfaces","Une seule rubrique","La couleur des écrans"],"a":0,"e":"Niveau."},{"q":"La recette utilisateur est réalisée par…","o":["Les key users","Le sponsor seul","Les clients externes"],"a":0,"e":"Acteur."},{"q":"La paie en parallèle consiste à…","o":["Calculer le même mois dans les deux systèmes et comparer","Payer deux fois","Payer la moitié"],"a":0,"e":"Définition."},{"q":"Le cahier de recette précise…","o":["Résultat attendu et obtenu","Le menu","Les congés"],"a":0,"e":"Contenu."},{"q":"Une preuve de test peut être…","o":["Une capture d'écran","Un souvenir","Une rumeur"],"a":0,"e":"Traçabilité."},{"q":"La paie ne se calcule pas : anomalie…","o":["Bloquante","Mineure","Majeure"],"a":0,"e":"Gravité."},{"q":"Cotisation mal calculée : anomalie…","o":["Majeure","Mineure","Inexistante"],"a":0,"e":"Gravité."},{"q":"Libellé mal orthographié : anomalie…","o":["Mineure","Bloquante","Majeure"],"a":0,"e":"Gravité."},{"q":"Avec une anomalie bloquante, la mise en production est…","o":["Impossible","Possible","Recommandée"],"a":0,"e":"Règle."},{"q":"En paie parallèle, on compare…","o":["Salarié par salarié","Seulement le total","Rien"],"a":0,"e":"Méthode."},{"q":"Chaque écart en paie parallèle doit être…","o":["Expliqué","Ignoré","Arrondi"],"a":0,"e":"Rigueur."},{"q":"Une cause d'écart acceptable peut être…","o":["Une différence d'arrondi","Un oubli de salarié","Un salaire doublé"],"a":0,"e":"Explication."},{"q":"Combien de paies parallèles concluantes en général ?","o":["Deux","Aucune","Dix"],"a":0,"e":"Pratique."},{"q":"Le PV de recette est signé par…","o":["Le client","L'éditeur seul","Un salarié tiré au sort"],"a":0,"e":"Validation."},{"q":"Le PV peut contenir…","o":["Des réserves","Des salaires","Des publicités"],"a":0,"e":"Contenu."},{"q":"Le PV de recette autorise…","o":["La mise en production","Le licenciement","Le recrutement"],"a":0,"e":"Effet."},{"q":"SIRH → paie → comptabilité est un test…","o":["D'intégration","Unitaire","Utilisateur uniquement"],"a":0,"e":"Niveau."},{"q":"Le statut d'un cas de test est…","o":["Conforme ou non conforme","Beau ou laid","Cher ou pas cher"],"a":0,"e":"Résultat."}]},{"id":"mrh312-10","n":10,"t":"Déployer et conduire le changement","min":25,"html":"<h3>La bascule</h3>\n<p>C'est le passage de l'ancien au nouveau système. Elle suit un plan détaillé : gel des modifications dans l'ancien outil, chargement définitif, contrôles, ouverture aux utilisateurs, plan de retour arrière en cas de problème majeur.</p>\n<h3>L'accompagnement après démarrage (hypercare)</h3>\n<p>Pendant les premières semaines, une équipe renforcée répond rapidement aux questions et corrige les anomalies. La première paie produite dans le nouvel outil fait l'objet de contrôles renforcés.</p>\n<h3>La conduite du changement</h3>\n<p>Un outil n'est utile que s'il est utilisé. La conduite du changement vise l'adhésion des utilisateurs.</p>\n<div class=\"tbl\"><table><thead><tr><th>Levier</th><th>Actions</th></tr></thead><tbody>\n<tr><td>Communication</td><td>Expliquer pourquoi, quoi, quand, et ce que chacun y gagne</td></tr>\n<tr><td>Formation</td><td>Par profil (gestionnaire, manager, salarié), sur des cas réels, juste avant l'usage</td></tr>\n<tr><td>Accompagnement</td><td>Key users relais, guides pas à pas, FAQ, assistance</td></tr>\n<tr><td>Implication</td><td>Associer les utilisateurs dès les ateliers et la recette</td></tr></tbody></table></div>\n<h3>La courbe du deuil</h3>\n<p>Inspirée des travaux d'Elisabeth Kübler-Ross, elle décrit les réactions face au changement : choc, déni, colère, marchandage, tristesse, acceptation, engagement. Le consultant anticipe ces phases et adapte son discours.</p>\n<h3>Les méthodes de projet</h3>\n<p>Le <strong>cycle en V</strong> enchaîne les étapes (besoins, conception, réalisation, tests) de façon séquentielle, chaque phase de conception ayant sa phase de test correspondante. Les méthodes <strong>agiles</strong> (comme Scrum) livrent par itérations courtes (sprints) et ajustent en continu avec les utilisateurs. Les projets de paie combinent souvent les deux.</p>","quiz":[{"q":"La bascule est…","o":["Le passage de l'ancien au nouveau système","Une réunion","Un congé"],"a":0,"e":"Définition."},{"q":"Avant la bascule, on gèle…","o":["Les modifications dans l'ancien outil","Les salaires","Les recrutements"],"a":0,"e":"Plan."},{"q":"Le plan de retour arrière sert…","o":["En cas de problème majeur","À annuler le projet d'office","Jamais"],"a":0,"e":"Sécurité."},{"q":"L'hypercare désigne…","o":["L'accompagnement renforcé après démarrage","Une assurance santé","Un logiciel"],"a":0,"e":"Définition."},{"q":"La première paie dans le nouvel outil fait l'objet…","o":["De contrôles renforcés","D'aucun contrôle","D'une fête seulement"],"a":0,"e":"Prudence."},{"q":"La conduite du changement vise…","o":["L'adhésion des utilisateurs","La vente","Les impôts"],"a":0,"e":"Objectif."},{"q":"La communication explique notamment…","o":["Ce que chacun y gagne","Le salaire du consultant","Rien"],"a":0,"e":"Levier."},{"q":"La formation se fait de préférence…","o":["Par profil et juste avant l'usage","Un an avant","Pour tous en même temps sans distinction"],"a":0,"e":"Levier."},{"q":"Les key users servent de…","o":["Relais","Sponsors","Éditeurs"],"a":0,"e":"Accompagnement."},{"q":"Une FAQ est un outil…","o":["D'accompagnement","De paie","De recrutement"],"a":0,"e":"Levier."},{"q":"Associer les utilisateurs dès les ateliers favorise…","o":["L'implication","Le rejet","Le retard"],"a":0,"e":"Levier."},{"q":"La courbe du deuil s'inspire de…","o":["Elisabeth Kübler-Ross","Henri Fayol","Kurt Lewin"],"a":0,"e":"Origine."},{"q":"Première réaction de la courbe du deuil ?","o":["Le choc","L'engagement","L'acceptation"],"a":0,"e":"Phase."},{"q":"Dernière étape de la courbe ?","o":["L'engagement","Le déni","La colère"],"a":0,"e":"Phase."},{"q":"Le cycle en V est…","o":["Séquentiel","Itératif par sprints","Sans étapes"],"a":0,"e":"Méthode."},{"q":"Dans le cycle en V, chaque phase de conception a…","o":["Une phase de test correspondante","Aucune suite","Un budget séparé"],"a":0,"e":"Principe."},{"q":"Les méthodes agiles livrent…","o":["Par itérations courtes","En une fois à la fin","Jamais"],"a":0,"e":"Principe."},{"q":"Scrum est une méthode…","o":["Agile","En V","Comptable"],"a":0,"e":"Exemple."},{"q":"Une itération agile s'appelle…","o":["Un sprint","Un COPIL","Un mapping"],"a":0,"e":"Vocabulaire."},{"q":"Un outil n'est utile que…","o":["S'il est utilisé","S'il est cher","S'il est nouveau"],"a":0,"e":"Principe."}]}]},{"id":"mrh313","code":"MRH 313","unit":"prat","title":"Excel appliqué à la fonction RH","summary":"Fichier du personnel, formules, fonctions conditionnelles, de recherche et de dates, nettoyage, tableaux croisés dynamiques, graphiques et tableau de bord RH.","lessons":[{"id":"mrh313-1","n":1,"t":"Structurer un fichier du personnel","min":20,"html":"<h3>Les règles d'un bon fichier</h3>\n<ul><li>Une ligne = un salarié ; une colonne = une information.</li><li>Une seule ligne d'en-tête, sans cellules fusionnées, sans lignes vides.</li><li>Un identifiant unique : le <strong>matricule</strong>.</li><li>Des dates saisies comme des dates (jj/mm/aaaa), jamais comme du texte.</li><li>Des montants sans texte (« 250000 », pas « 250 000 FCFA »).</li><li>Des listes de valeurs homogènes (même libellé de service partout).</li></ul>\n<h3>Exemple de colonnes</h3>\n<div class=\"tbl\"><table><thead><tr><th>Colonne</th><th>Type</th></tr></thead><tbody>\n<tr><td>Matricule</td><td>Texte ou nombre unique</td></tr>\n<tr><td>Nom, Prénoms</td><td>Texte</td></tr>\n<tr><td>Sexe</td><td>Liste (F / M)</td></tr>\n<tr><td>Date de naissance, Date d'embauche</td><td>Date</td></tr>\n<tr><td>Service, Catégorie, Contrat</td><td>Liste</td></tr>\n<tr><td>Salaire de base</td><td>Nombre</td></tr></tbody></table></div>\n<h3>Mettre sous forme de Tableau</h3>\n<p>Sélectionnez les données puis <strong>Ctrl + L</strong> (ou Accueil &gt; Mettre sous forme de tableau). Avantages : les formules et mises en forme s'étendent automatiquement aux nouvelles lignes, les filtres sont activés, on peut utiliser des références structurées comme <span class=\"phrase\">[@Salaire]</span>.</p>\n<h3>Figer les volets</h3>\n<p>Affichage &gt; Figer les volets permet de garder l'en-tête et la colonne Matricule visibles en faisant défiler.</p>\n<div class=\"callout\"><b>Sécurité</b>Le fichier du personnel contient des données personnelles : protégez-le par un mot de passe et limitez sa diffusion.</div>","quiz":[{"q":"Dans un bon fichier, une ligne correspond à…","o":["Un salarié","Une information","Un service"],"a":0,"e":"Règle."},{"q":"Une colonne correspond à…","o":["Une information","Un salarié","Un mois"],"a":0,"e":"Règle."},{"q":"Combien de lignes d'en-tête ?","o":["Une seule","Deux","Trois"],"a":0,"e":"Règle."},{"q":"Les cellules fusionnées sont…","o":["À éviter","Recommandées","Obligatoires"],"a":0,"e":"Règle."},{"q":"L'identifiant unique recommandé est…","o":["Le matricule","Le prénom","Le service"],"a":0,"e":"Règle."},{"q":"Les dates doivent être saisies comme…","o":["Des dates","Du texte","Des images"],"a":0,"e":"Règle."},{"q":"« 250 000 FCFA » dans une cellule de montant est…","o":["À éviter (texte)","Recommandé","Obligatoire"],"a":0,"e":"Règle."},{"q":"Le sexe se saisit de préférence via…","o":["Une liste","Du texte libre","Une image"],"a":0,"e":"Homogénéité."},{"q":"Raccourci pour mettre sous forme de Tableau ?","o":["Ctrl + L","Ctrl + P","Ctrl + Z"],"a":0,"e":"Raccourci."},{"q":"Avantage du Tableau Excel ?","o":["Les formules s'étendent aux nouvelles lignes","Il supprime les données","Il imprime automatiquement"],"a":0,"e":"Avantage."},{"q":"[@Salaire] est une…","o":["Référence structurée","Erreur","Fonction de date"],"a":0,"e":"Tableau."},{"q":"Figer les volets permet…","o":["De garder l'en-tête visible","De protéger le fichier","D'imprimer"],"a":0,"e":"Affichage."},{"q":"Figer les volets se trouve dans l'onglet…","o":["Affichage","Formules","Données"],"a":0,"e":"Menu."},{"q":"Les lignes vides dans les données sont…","o":["À éviter","Recommandées","Obligatoires"],"a":0,"e":"Règle."},{"q":"Un libellé de service doit être…","o":["Identique partout","Varié","Abrégé au hasard"],"a":0,"e":"Homogénéité."},{"q":"Le fichier du personnel doit être…","o":["Protégé par mot de passe","Partagé à tous","Publié"],"a":0,"e":"Sécurité."},{"q":"Le salaire de base est de type…","o":["Nombre","Texte","Date"],"a":0,"e":"Type."},{"q":"La date d'embauche est de type…","o":["Date","Texte","Liste"],"a":0,"e":"Type."},{"q":"Le format de date recommandé est…","o":["jj/mm/aaaa","« 12 mars »","mm-aaaa texte"],"a":0,"e":"Format."},{"q":"Les filtres sont activés automatiquement…","o":["Dans un Tableau","Jamais","Seulement sur Mac"],"a":0,"e":"Avantage."}]},{"id":"mrh313-2","n":2,"t":"Formules de base et références","min":20,"html":"<h3>Écrire une formule</h3>\n<p>Une formule commence par <strong>=</strong>. En version française d'Excel, les arguments sont séparés par des <strong>points-virgules</strong> : <span class=\"phrase\">=SOMME(F2:F50)</span>.</p>\n<h3>Les fonctions de base</h3>\n<div class=\"tbl\"><table><thead><tr><th>Fonction</th><th>Usage RH</th></tr></thead><tbody>\n<tr><td>SOMME</td><td>Masse salariale</td></tr>\n<tr><td>MOYENNE</td><td>Salaire moyen</td></tr>\n<tr><td>MIN / MAX</td><td>Salaire le plus bas / le plus élevé</td></tr>\n<tr><td>MEDIANE</td><td>Salaire médian</td></tr>\n<tr><td>NB</td><td>Nombre de cellules contenant des nombres</td></tr>\n<tr><td>NBVAL</td><td>Nombre de cellules non vides (effectif à partir des matricules)</td></tr>\n<tr><td>ARRONDI</td><td>Arrondir un montant : <span class=\"phrase\">=ARRONDI(F2*6,3%;0)</span></td></tr></tbody></table></div>\n<h3>Références relatives et absolues</h3>\n<ul><li><strong>Relative</strong> (<span class=\"phrase\">B2</span>) : s'adapte quand on recopie la formule.</li><li><strong>Absolue</strong> (<span class=\"phrase\">$B$2</span>) : reste fixe ; on l'obtient avec la touche <strong>F4</strong>.</li><li><strong>Mixte</strong> (<span class=\"phrase\">$B2</span> ou <span class=\"phrase\">B$2</span>) : seule la colonne ou la ligne est bloquée.</li></ul>\n<div class=\"callout\"><b>Exemple</b>Le taux de retraite salarial (6,3 %) est en H1. Cotisation du salarié en ligne 2 : <span class=\"phrase\">=F2*$H$1</span>. En recopiant vers le bas, F2 devient F3, F4… mais $H$1 reste fixe.</div>\n<h3>Les opérateurs</h3>\n<p>+ − * / pour les calculs, ^ pour la puissance, & pour assembler du texte, = &lt; &gt; &lt;= &gt;= &lt;&gt; pour comparer.</p>\n<h3>Les erreurs courantes</h3>\n<p>#DIV/0! (division par zéro), #N/A (valeur non trouvée), #VALEUR! (type incorrect, par exemple du texte dans un calcul), #NOM? (fonction mal orthographiée), #REF! (référence supprimée).</p>","quiz":[{"q":"Une formule commence par…","o":["=","+","#"],"a":0,"e":"Syntaxe."},{"q":"Séparateur d'arguments en Excel français ?","o":["Point-virgule","Virgule","Deux-points"],"a":0,"e":"Syntaxe."},{"q":"Fonction pour la masse salariale ?","o":["SOMME","MOYENNE","NB"],"a":0,"e":"Usage."},{"q":"Fonction pour le salaire moyen ?","o":["MOYENNE","SOMME","MAX"],"a":0,"e":"Usage."},{"q":"Fonction pour compter les cellules non vides ?","o":["NBVAL","NB","SOMME"],"a":0,"e":"Usage."},{"q":"NB compte…","o":["Les cellules contenant des nombres","Les cellules de texte","Les cellules vides"],"a":0,"e":"Définition."},{"q":"Une référence absolue s'écrit…","o":["$B$2","B2","B$"],"a":0,"e":"Syntaxe."},{"q":"Touche pour rendre une référence absolue ?","o":["F4","F1","F12"],"a":0,"e":"Raccourci."},{"q":"Une référence relative…","o":["S'adapte en recopiant","Reste fixe","Est interdite"],"a":0,"e":"Définition."},{"q":"$B2 bloque…","o":["La colonne","La ligne","Rien"],"a":0,"e":"Référence mixte."},{"q":"B$2 bloque…","o":["La ligne","La colonne","Tout"],"a":0,"e":"Référence mixte."},{"q":"Dans =F2*$H$1 recopié en ligne 3, on obtient…","o":["=F3*$H$1","=F3*$H$2","=F2*$H$1"],"a":0,"e":"Recopie."},{"q":"L'opérateur pour assembler du texte ?","o":["&","+","^"],"a":0,"e":"Concaténation."},{"q":"« Différent de » s'écrit…","o":["<>","!=","=/="],"a":0,"e":"Opérateur."},{"q":"#DIV/0! signifie…","o":["Division par zéro","Valeur non trouvée","Fonction inconnue"],"a":0,"e":"Erreur."},{"q":"#N/A signifie…","o":["Valeur non trouvée","Division par zéro","Référence supprimée"],"a":0,"e":"Erreur."},{"q":"#NOM? signifie…","o":["Fonction mal orthographiée","Division par zéro","Texte dans un calcul"],"a":0,"e":"Erreur."},{"q":"#REF! signifie…","o":["Référence supprimée","Valeur non trouvée","Nombre trop grand"],"a":0,"e":"Erreur."},{"q":"#VALEUR! signifie…","o":["Type incorrect dans un calcul","Référence supprimée","Division par zéro"],"a":0,"e":"Erreur."},{"q":"=ARRONDI(125,6;0) donne…","o":["126","125","125,6"],"a":0,"e":"Arrondi à l'unité."}]},{"id":"mrh313-3","n":3,"t":"Les fonctions conditionnelles","min":25,"html":"<h3>La fonction SI</h3>\n<p>Syntaxe : <span class=\"phrase\">=SI(test; valeur_si_vrai; valeur_si_faux)</span>.</p>\n<div class=\"callout\"><b>Exemple</b>Prime de 10 000 FCFA si l'ancienneté (colonne G) est d'au moins 5 ans : <span class=\"phrase\">=SI(G2>=5;10000;0)</span>.</div>\n<h3>ET et OU</h3>\n<ul><li><span class=\"phrase\">ET(cond1;cond2)</span> est vrai si <strong>toutes</strong> les conditions sont vraies.</li><li><span class=\"phrase\">OU(cond1;cond2)</span> est vrai si <strong>au moins une</strong> condition est vraie.</li></ul>\n<p>Exemple : prime pour les CDI ayant au moins 2 ans d'ancienneté : <span class=\"phrase\">=SI(ET(D2=\"CDI\";G2>=2);15000;0)</span>.</p>\n<h3>Les SI imbriqués</h3>\n<p>Pour plusieurs cas : <span class=\"phrase\">=SI(G2>=10;\"Senior\";SI(G2>=3;\"Confirmé\";\"Junior\"))</span>. Excel teste les conditions dans l'ordre et s'arrête à la première vraie.</p>\n<h3>SI.CONDITIONS</h3>\n<p>Plus lisible pour plusieurs cas (Excel récent) : <span class=\"phrase\">=SI.CONDITIONS(G2>=10;\"Senior\";G2>=3;\"Confirmé\";VRAI;\"Junior\")</span>. Le dernier test VRAI sert de « sinon ».</p>\n<h3>Application : prime d'ancienneté indicative</h3>\n<p>Taux = 0 avant 2 ans, puis 2 % + 1 % par année supplémentaire, plafonné à 25 % : <span class=\"phrase\">=SI(G2<2;0;MIN(25%;2%+(G2-2)*1%))</span>.</p>\n<div class=\"tbl\"><table><thead><tr><th>Ancienneté</th><th>Taux</th></tr></thead><tbody>\n<tr><td>1 an</td><td>0 %</td></tr><tr><td>2 ans</td><td>2 %</td></tr><tr><td>6 ans</td><td>6 %</td></tr><tr><td>30 ans</td><td>25 %</td></tr></tbody></table></div>","quiz":[{"q":"Syntaxe de SI ?","o":["=SI(test;si_vrai;si_faux)","=SI(si_vrai;test)","=SI(test)"],"a":0,"e":"Syntaxe."},{"q":"=SI(G2>=5;10000;0) avec G2 = 7 donne…","o":["10000","0","7"],"a":0,"e":"Test vrai."},{"q":"=SI(G2>=5;10000;0) avec G2 = 4 donne…","o":["0","10000","4"],"a":0,"e":"Test faux."},{"q":"ET est vrai si…","o":["Toutes les conditions sont vraies","Une seule est vraie","Aucune n'est vraie"],"a":0,"e":"Définition."},{"q":"OU est vrai si…","o":["Au moins une condition est vraie","Toutes sont vraies obligatoirement","Aucune"],"a":0,"e":"Définition."},{"q":"CDI avec 1 an : =SI(ET(D2=\"CDI\";G2>=2);15000;0) ?","o":["0","15000","1"],"a":0,"e":"Une condition fausse."},{"q":"CDD avec 5 ans, même formule ?","o":["0","15000","5"],"a":0,"e":"Une condition fausse."},{"q":"CDI avec 3 ans, même formule ?","o":["15000","0","3"],"a":0,"e":"Deux conditions vraies."},{"q":"SI imbriqués avec G2 = 12 : résultat ?","o":["Senior","Confirmé","Junior"],"a":0,"e":"Premier test vrai."},{"q":"SI imbriqués avec G2 = 5 : résultat ?","o":["Confirmé","Senior","Junior"],"a":0,"e":"Deuxième test."},{"q":"SI imbriqués avec G2 = 1 : résultat ?","o":["Junior","Confirmé","Senior"],"a":0,"e":"Sinon."},{"q":"Excel teste les conditions imbriquées…","o":["Dans l'ordre et s'arrête à la première vraie","Toutes en même temps","Au hasard"],"a":0,"e":"Fonctionnement."},{"q":"Dans SI.CONDITIONS, le test VRAI final sert de…","o":["Sinon","Erreur","Titre"],"a":0,"e":"Astuce."},{"q":"Taux de prime pour 1 an d'ancienneté ?","o":["0 %","1 %","2 %"],"a":0,"e":"Avant 2 ans."},{"q":"Taux de prime pour 6 ans ?","o":["6 %","8 %","4 %"],"a":0,"e":"2 % + 4 %."},{"q":"Taux de prime pour 30 ans ?","o":["25 %","30 %","2 %"],"a":0,"e":"Plafond."},{"q":"Taux pour 10 ans ?","o":["10 %","8 %","12 %"],"a":0,"e":"2 % + 8 %."},{"q":"La fonction MIN dans la formule de prime sert à…","o":["Plafonner à 25 %","Arrondir","Compter"],"a":0,"e":"Plafond."},{"q":"Un texte dans un test s'écrit…","o":["Entre guillemets","Sans guillemets","Entre parenthèses"],"a":0,"e":"Syntaxe."},{"q":"=SI(OU(E2=\"Cadre\";F2>500000);\"Oui\";\"Non\") avec E2 = « Employé » et F2 = 600 000 ?","o":["Oui","Non","Erreur"],"a":0,"e":"Une condition vraie suffit."}]},{"id":"mrh313-4","n":4,"t":"Compter et additionner selon des critères","min":25,"html":"<h3>Les fonctions</h3>\n<div class=\"tbl\"><table><thead><tr><th>Fonction</th><th>Rôle</th></tr></thead><tbody>\n<tr><td>NB.SI(plage; critère)</td><td>Compte les cellules qui respectent un critère</td></tr>\n<tr><td>NB.SI.ENS(plage1; critère1; plage2; critère2…)</td><td>Compte selon plusieurs critères</td></tr>\n<tr><td>SOMME.SI.ENS(plage_somme; plage1; critère1…)</td><td>Additionne selon un ou plusieurs critères</td></tr>\n<tr><td>MOYENNE.SI.ENS(plage_moyenne; plage1; critère1…)</td><td>Moyenne selon un ou plusieurs critères</td></tr></tbody></table></div>\n<p>Attention : dans SOMME.SI.ENS, la plage à additionner vient <strong>en premier</strong>.</p>\n<h3>Exemples</h3>\n<ul><li>Nombre de femmes : <span class=\"phrase\">=NB.SI(C:C;\"F\")</span></li><li>Nombre de femmes cadres : <span class=\"phrase\">=NB.SI.ENS(C:C;\"F\";E:E;\"Cadre\")</span></li><li>Masse salariale du service Finance : <span class=\"phrase\">=SOMME.SI.ENS(F:F;D:D;\"Finance\")</span></li><li>Salaire moyen des femmes cadres : <span class=\"phrase\">=MOYENNE.SI.ENS(F:F;C:C;\"F\";E:E;\"Cadre\")</span></li><li>Salariés gagnant plus de 500 000 : <span class=\"phrase\">=NB.SI(F:F;\"&gt;500000\")</span></li></ul>\n<h3>Critère dans une cellule</h3>\n<p>Plutôt que d'écrire « Finance » dans la formule, on fait référence à une cellule : <span class=\"phrase\">=SOMME.SI.ENS(F:F;D:D;H2)</span>. Pour un critère de comparaison : <span class=\"phrase\">\"&gt;\"&amp;H3</span>.</p>\n<h3>Application : taux de féminisation par service</h3>\n<p><span class=\"phrase\">=NB.SI.ENS(D:D;H2;C:C;\"F\")/NB.SI(D:D;H2)</span>, au format pourcentage.</p>","quiz":[{"q":"NB.SI compte…","o":["Les cellules respectant un critère","Toutes les cellules","Les cellules vides"],"a":0,"e":"Définition."},{"q":"Pour compter selon plusieurs critères :","o":["NB.SI.ENS","NB.SI","SOMME"],"a":0,"e":"Fonction."},{"q":"Pour additionner selon des critères :","o":["SOMME.SI.ENS","NB.SI","MOYENNE"],"a":0,"e":"Fonction."},{"q":"Dans SOMME.SI.ENS, la plage à additionner vient…","o":["En premier","En dernier","Au milieu"],"a":0,"e":"Syntaxe."},{"q":"Nombre de femmes : =NB.SI(C:C;…) avec quel critère ?","o":["\"F\"","F sans guillemets","\"Femme cadre\""],"a":0,"e":"Texte entre guillemets."},{"q":"Masse salariale du service Finance ?","o":["=SOMME.SI.ENS(F:F;D:D;\"Finance\")","=NB.SI(D:D;\"Finance\")","=SOMME(F:F)"],"a":0,"e":"Formule."},{"q":"Salaire moyen des femmes cadres ?","o":["MOYENNE.SI.ENS","NB.SI.ENS","SOMME"],"a":0,"e":"Fonction."},{"q":"Salariés gagnant plus de 500 000 : critère ?","o":["\">500000\"","500000","<500000"],"a":0,"e":"Critère de comparaison."},{"q":"Pourquoi mettre le critère dans une cellule ?","o":["Pour changer facilement de critère","Pour compliquer","C'est interdit"],"a":0,"e":"Souplesse."},{"q":"Critère de comparaison avec cellule H3 ?","o":["\">\"&H3","\">H3\"",">H3"],"a":0,"e":"Concaténation."},{"q":"Taux de féminisation d'un service =","o":["Femmes du service / effectif du service","Femmes / hommes","Effectif / femmes"],"a":0,"e":"Formule."},{"q":"Si 12 femmes sur 40 dans le service : taux ?","o":["30 %","12 %","40 %"],"a":0,"e":"12 / 40."},{"q":"NB.SI.ENS(C:C;\"F\";E:E;\"Cadre\") compte…","o":["Les femmes cadres","Toutes les femmes","Tous les cadres"],"a":0,"e":"Deux critères."},{"q":"Le résultat du taux s'affiche en format…","o":["Pourcentage","Date","Texte"],"a":0,"e":"Format."},{"q":"MOYENNE.SI.ENS commence par…","o":["La plage à moyenner","Le premier critère","Le titre"],"a":0,"e":"Syntaxe."},{"q":"Compter les CDD : =NB.SI(Contrat;…) ?","o":["\"CDD\"","CDD sans guillemets","=CDD"],"a":0,"e":"Critère."},{"q":"Additionner les salaires des cadres : =SOMME.SI.ENS(F:F;E:E;…) ?","o":["\"Cadre\"","F:F","E2"],"a":0,"e":"Critère."},{"q":"Si le service contient « finance » en minuscules, NB.SI…","o":["Ne distingue pas les majuscules","Renvoie une erreur","Ne compte rien"],"a":0,"e":"Insensible à la casse."},{"q":"Une plage C:C désigne…","o":["Toute la colonne C","La cellule C1","La ligne C"],"a":0,"e":"Référence."},{"q":"Pour compter les salariés de plus de 50 ans, on utilise…","o":["NB.SI avec \">50\" sur la colonne âge","SOMME","MOYENNE"],"a":0,"e":"Application."}]},{"id":"mrh313-5","n":5,"t":"Les fonctions de recherche","min":25,"html":"<h3>RECHERCHEV</h3>\n<p><span class=\"phrase\">=RECHERCHEV(valeur_cherchée; table; n°_colonne; FAUX)</span> cherche une valeur dans la <strong>première colonne</strong> d'une table et renvoie la valeur de la colonne indiquée, sur la même ligne. Le dernier argument <strong>FAUX</strong> impose une correspondance exacte.</p>\n<div class=\"callout\"><b>Exemple</b>Table A2:F200 avec le matricule en colonne A et le salaire en colonne F (6<sup>e</sup> colonne) : <span class=\"phrase\">=RECHERCHEV(H2;$A$2:$F$200;6;FAUX)</span> renvoie le salaire du matricule saisi en H2.</div>\n<p>Limites : la valeur cherchée doit être dans la première colonne ; si on insère une colonne, le numéro de colonne devient faux.</p>\n<h3>RECHERCHEX (Excel récent)</h3>\n<p><span class=\"phrase\">=RECHERCHEX(valeur; plage_recherche; plage_résultat; \"Non trouvé\")</span>. Plus souple : la plage de recherche peut être à droite ou à gauche, le résultat par défaut est intégré, et l'insertion de colonnes ne casse pas la formule.</p>\n<h3>INDEX et EQUIV</h3>\n<p><span class=\"phrase\">=INDEX(F2:F200;EQUIV(H2;A2:A200;0))</span> : EQUIV trouve la position du matricule, INDEX renvoie la valeur à cette position. Alternative robuste dans les anciennes versions.</p>\n<h3>SIERREUR</h3>\n<p><span class=\"phrase\">=SIERREUR(RECHERCHEV(…);\"Matricule inconnu\")</span> remplace l'erreur #N/A par un message clair.</p>\n<h3>Applications RH</h3>\n<ul><li>Rapatrier le salaire du fichier du personnel dans un fichier de variables.</li><li>Retrouver le service d'un salarié à partir de son matricule.</li><li>Comparer deux listes (les salariés présents en paie mais absents du fichier du personnel).</li></ul>","quiz":[{"q":"RECHERCHEV cherche dans…","o":["La première colonne de la table","N'importe quelle colonne","La dernière colonne"],"a":0,"e":"Principe."},{"q":"Le dernier argument FAUX signifie…","o":["Correspondance exacte","Correspondance approximative","Erreur"],"a":0,"e":"Syntaxe."},{"q":"Table A2:F200, salaire en colonne F : numéro de colonne ?","o":["6","5","7"],"a":0,"e":"A=1, F=6."},{"q":"Service en colonne D de la table A:F : numéro ?","o":["4","3","5"],"a":0,"e":"A=1, D=4."},{"q":"Limite de RECHERCHEV ?","o":["La valeur cherchée doit être en première colonne","Elle ne marche jamais","Elle est trop rapide"],"a":0,"e":"Limite."},{"q":"Insérer une colonne dans la table peut…","o":["Fausser le numéro de colonne de RECHERCHEV","N'avoir aucun effet","Supprimer la table"],"a":0,"e":"Limite."},{"q":"RECHERCHEX permet un résultat par défaut…","o":["Intégré","Impossible","Uniquement avec SIERREUR"],"a":0,"e":"Avantage."},{"q":"Avec RECHERCHEX, la plage de recherche peut être…","o":["À gauche ou à droite du résultat","Seulement à gauche","Seulement la première colonne"],"a":0,"e":"Souplesse."},{"q":"EQUIV renvoie…","o":["La position d'une valeur","La valeur elle-même","Une somme"],"a":0,"e":"Définition."},{"q":"INDEX renvoie…","o":["La valeur à une position","La position","Un nombre de cellules"],"a":0,"e":"Définition."},{"q":"INDEX + EQUIV est…","o":["Une alternative robuste","Une erreur","Une fonction de date"],"a":0,"e":"Usage."},{"q":"Le 0 dans EQUIV(…;0) signifie…","o":["Correspondance exacte","Zéro résultat","Tri décroissant"],"a":0,"e":"Syntaxe."},{"q":"SIERREUR sert à…","o":["Remplacer une erreur par un message","Créer une erreur","Supprimer la formule"],"a":0,"e":"Usage."},{"q":"Un matricule introuvable dans RECHERCHEV renvoie…","o":["#N/A","0","#DIV/0!"],"a":0,"e":"Erreur."},{"q":"Pourquoi $A$2:$F$200 est-il en référence absolue ?","o":["Pour que la table reste fixe en recopiant","Par décoration","C'est obligatoire pour toutes les cellules"],"a":0,"e":"Recopie."},{"q":"Comparer deux listes de matricules peut se faire avec…","o":["RECHERCHEV ou RECHERCHEX","SOMME","MAX"],"a":0,"e":"Application."},{"q":"Rapatrier le salaire dans un fichier de variables utilise…","o":["Une fonction de recherche","Un graphique","Une impression"],"a":0,"e":"Application."},{"q":"Un salarié présent en paie mais absent du fichier du personnel peut révéler…","o":["Une anomalie à vérifier","Une situation normale toujours","Une promotion"],"a":0,"e":"Contrôle."},{"q":"Syntaxe de RECHERCHEX ?","o":["valeur; plage_recherche; plage_résultat","table; colonne; valeur","plage; somme"],"a":0,"e":"Syntaxe."},{"q":"Le message « Matricule inconnu » s'obtient avec…","o":["SIERREUR","SI.CONDITIONS uniquement","NB.SI"],"a":0,"e":"Usage."}]},{"id":"mrh313-6","n":6,"t":"Calculer avec les dates","min":20,"html":"<h3>Comment Excel stocke les dates</h3>\n<p>Une date est un nombre : le nombre de jours depuis le 1<sup>er</sup> janvier 1900. On peut donc soustraire deux dates pour obtenir un nombre de jours.</p>\n<h3>Les fonctions utiles</h3>\n<div class=\"tbl\"><table><thead><tr><th>Fonction</th><th>Usage RH</th></tr></thead><tbody>\n<tr><td>AUJOURDHUI()</td><td>Date du jour, mise à jour automatiquement</td></tr>\n<tr><td>DATEDIF(début; fin; \"Y\")</td><td>Âge ou ancienneté en années complètes (\"M\" pour les mois, \"D\" pour les jours)</td></tr>\n<tr><td>ANNEE(date), MOIS(date)</td><td>Extraire l'année ou le mois (analyse des embauches par année)</td></tr>\n<tr><td>MOIS.DECALER(date; n)</td><td>Date de fin de période d'essai : <span class=\"phrase\">=MOIS.DECALER(G2;3)</span> pour 3 mois</td></tr>\n<tr><td>FIN.MOIS(date; 0)</td><td>Dernier jour du mois</td></tr>\n<tr><td>NB.JOURS.OUVRES(début; fin; fériés)</td><td>Jours ouvrés entre deux dates, en excluant les week-ends et une liste de jours fériés</td></tr>\n<tr><td>DATE(année; mois; jour)</td><td>Construire une date</td></tr></tbody></table></div>\n<h3>Exemples</h3>\n<ul><li>Âge : <span class=\"phrase\">=DATEDIF(E2;AUJOURDHUI();\"Y\")</span></li><li>Ancienneté au 31 décembre 2026 : <span class=\"phrase\">=DATEDIF(G2;DATE(2026;12;31);\"Y\")</span></li><li>Date de départ à la retraite à 60 ans : <span class=\"phrase\">=MOIS.DECALER(E2;60*12)</span></li><li>Alerte fin de CDD dans moins de 30 jours : <span class=\"phrase\">=SI(H2-AUJOURDHUI()&lt;=30;\"Alerte\";\"\")</span></li></ul>\n<div class=\"callout\"><b>Piège</b>Une date saisie comme du texte (alignée à gauche par défaut) ne permet aucun calcul : convertissez-la d'abord.</div>","quiz":[{"q":"Excel stocke une date comme…","o":["Un nombre de jours","Un texte","Une image"],"a":0,"e":"Principe."},{"q":"Soustraire deux dates donne…","o":["Un nombre de jours","Une erreur","Un texte"],"a":0,"e":"Calcul."},{"q":"AUJOURDHUI() renvoie…","o":["La date du jour","L'heure seulement","Le 1er janvier"],"a":0,"e":"Fonction."},{"q":"DATEDIF(début;fin;\"Y\") calcule…","o":["Les années complètes","Les jours","Les mois"],"a":0,"e":"Unité."},{"q":"Pour des mois complets avec DATEDIF, on utilise…","o":["\"M\"","\"Y\"","\"D\""],"a":0,"e":"Unité."},{"q":"Âge : =DATEDIF(E2;…;\"Y\") avec…","o":["AUJOURDHUI()","SOMME()","ANNEE()"],"a":0,"e":"Formule."},{"q":"Fin d'essai de 3 mois à partir de G2 ?","o":["=MOIS.DECALER(G2;3)","=G2+3","=FIN.MOIS(G2;3) toujours"],"a":0,"e":"Fonction."},{"q":"Dernier jour du mois ?","o":["FIN.MOIS(date;0)","DEBUT.MOIS","ANNEE"],"a":0,"e":"Fonction."},{"q":"NB.JOURS.OUVRES exclut…","o":["Week-ends et jours fériés listés","Uniquement les lundis","Rien"],"a":0,"e":"Fonction."},{"q":"Extraire l'année d'une date ?","o":["ANNEE","MOIS","JOUR.SEMAINE"],"a":0,"e":"Fonction."},{"q":"Construire la date du 31/12/2026 ?","o":["=DATE(2026;12;31)","=31/12/2026 en texte","=AUJOURDHUI(2026)"],"a":0,"e":"Fonction."},{"q":"Départ à la retraite à 60 ans depuis la date de naissance ?","o":["=MOIS.DECALER(E2;720)","=E2+60","=ANNEE(E2)+60 comme date"],"a":0,"e":"60 × 12 = 720 mois."},{"q":"Alerte si fin de CDD dans 30 jours ou moins :","o":["=SI(H2-AUJOURDHUI()<=30;\"Alerte\";\"\")","=SOMME(H2)","=NB(H2)"],"a":0,"e":"Formule."},{"q":"Une date alignée à gauche par défaut est souvent…","o":["Du texte","Un nombre","Une formule"],"a":0,"e":"Piège."},{"q":"Une date en texte permet-elle des calculs ?","o":["Non","Oui","Seulement des sommes"],"a":0,"e":"Piège."},{"q":"Né le 15/03/1990, âge au 15/03/2026 ?","o":["36","35","37"],"a":0,"e":"2026 − 1990."},{"q":"Embauché le 01/07/2020, ancienneté au 31/12/2026 en années complètes ?","o":["6","7","5"],"a":0,"e":"6 ans et 6 mois."},{"q":"Référence de départ du calendrier Excel ?","o":["1er janvier 1900","1er janvier 2000","1er janvier 1970"],"a":0,"e":"Système de dates."},{"q":"MOIS.DECALER(date;-1) donne…","o":["Un mois avant","Un mois après","Une erreur"],"a":0,"e":"Décalage négatif."},{"q":"Pour analyser les embauches par année, on extrait…","o":["L'année de la date d'embauche","Le jour de la semaine","L'heure"],"a":0,"e":"Application."}]},{"id":"mrh313-7","n":7,"t":"Nettoyer et préparer les données","min":20,"html":"<h3>Les fonctions de texte</h3>\n<div class=\"tbl\"><table><thead><tr><th>Fonction</th><th>Usage</th></tr></thead><tbody>\n<tr><td>SUPPRESPACE(texte)</td><td>Supprime les espaces en trop (début, fin, doubles)</td></tr>\n<tr><td>MAJUSCULE(texte)</td><td>Tout en majuscules (noms de famille)</td></tr>\n<tr><td>NOMPROPRE(texte)</td><td>Première lettre en majuscule (prénoms)</td></tr>\n<tr><td>MINUSCULE(texte)</td><td>Tout en minuscules (adresses e-mail)</td></tr>\n<tr><td>GAUCHE / DROITE / STXT</td><td>Extraire une partie d'un texte (code service dans un matricule)</td></tr>\n<tr><td>NBCAR(texte)</td><td>Nombre de caractères (vérifier la longueur d'un numéro)</td></tr>\n<tr><td>CONCAT ou &</td><td>Assembler : <span class=\"phrase\">=B2&\" \"&C2</span> pour « Nom Prénoms »</td></tr>\n<tr><td>CNUM(texte)</td><td>Convertir un nombre stocké en texte</td></tr></tbody></table></div>\n<h3>Les outils du ruban</h3>\n<ul><li><strong>Données &gt; Supprimer les doublons</strong> : sur la colonne Matricule.</li><li><strong>Données &gt; Convertir</strong> : séparer une colonne « Nom Prénom » en deux, ou convertir des dates texte.</li><li><strong>Rechercher et remplacer</strong> (Ctrl + H) : harmoniser « Ress. Humaines » en « RH ».</li><li><strong>Remplissage instantané</strong> (Ctrl + E) : Excel devine un motif à partir d'un exemple.</li></ul>\n<h3>Coller des valeurs</h3>\n<p>Après un nettoyage par formules, faites Copier puis <strong>Collage spécial &gt; Valeurs</strong> pour remplacer les formules par leurs résultats, avant de supprimer les colonnes d'origine.</p>\n<div class=\"callout\"><b>Méthode</b>Conservez toujours une copie du fichier brut et travaillez sur une copie.</div>","quiz":[{"q":"SUPPRESPACE sert à…","o":["Supprimer les espaces en trop","Supprimer le texte","Ajouter des espaces"],"a":0,"e":"Fonction."},{"q":"Pour mettre les noms de famille en capitales :","o":["MAJUSCULE","NOMPROPRE","MINUSCULE"],"a":0,"e":"Fonction."},{"q":"Pour « kouassi » → « Kouassi » :","o":["NOMPROPRE","MAJUSCULE","SUPPRESPACE"],"a":0,"e":"Fonction."},{"q":"Pour les adresses e-mail, on utilise souvent…","o":["MINUSCULE","MAJUSCULE","NOMPROPRE"],"a":0,"e":"Usage."},{"q":"GAUCHE(\"FIN0452\";3) donne…","o":["FIN","0452","F"],"a":0,"e":"Extraction."},{"q":"DROITE(\"FIN0452\";4) donne…","o":["0452","FIN0","2"],"a":0,"e":"Extraction."},{"q":"NBCAR(\"CI2026\") donne…","o":["6","5","4"],"a":0,"e":"Nombre de caractères."},{"q":"=B2&\" \"&C2 sert à…","o":["Assembler nom et prénoms","Additionner","Comparer"],"a":0,"e":"Concaténation."},{"q":"CNUM convertit…","o":["Un nombre stocké en texte en nombre","Un nombre en date","Une date en texte"],"a":0,"e":"Fonction."},{"q":"Supprimer les doublons se trouve dans l'onglet…","o":["Données","Accueil","Affichage"],"a":0,"e":"Ruban."},{"q":"Sur quelle colonne supprimer les doublons de salariés ?","o":["Matricule","Service","Sexe"],"a":0,"e":"Identifiant."},{"q":"Séparer « Nom Prénom » en deux colonnes :","o":["Données > Convertir","Supprimer les doublons","Figer les volets"],"a":0,"e":"Outil."},{"q":"Raccourci Rechercher et remplacer ?","o":["Ctrl + H","Ctrl + L","Ctrl + E"],"a":0,"e":"Raccourci."},{"q":"Raccourci du remplissage instantané ?","o":["Ctrl + E","Ctrl + H","Ctrl + P"],"a":0,"e":"Raccourci."},{"q":"Le remplissage instantané…","o":["Devine un motif à partir d'un exemple","Supprime les données","Crée un graphique"],"a":0,"e":"Outil."},{"q":"Collage spécial > Valeurs remplace…","o":["Les formules par leurs résultats","Les valeurs par des formules","Tout par du vide"],"a":0,"e":"Outil."},{"q":"Pourquoi coller des valeurs avant de supprimer les colonnes d'origine ?","o":["Sinon les formules renvoient #REF!","Pour décorer","Ce n'est pas utile"],"a":0,"e":"Méthode."},{"q":"Harmoniser « Ress. Humaines » en « RH » se fait avec…","o":["Rechercher et remplacer","NB.SI","DATEDIF"],"a":0,"e":"Outil."},{"q":"Avant de nettoyer, on…","o":["Garde une copie du fichier brut","Supprime l'original","Envoie le fichier à tous"],"a":0,"e":"Méthode."},{"q":"STXT sert à…","o":["Extraire une partie au milieu d'un texte","Compter","Additionner"],"a":0,"e":"Fonction."}]},{"id":"mrh313-8","n":8,"t":"Trier, filtrer, valider et mettre en forme","min":20,"html":"<h3>Trier</h3>\n<p>Données &gt; Trier permet des tris sur plusieurs niveaux : par service, puis par nom. Sélectionnez toujours tout le tableau (ou utilisez un Tableau Excel) pour ne pas désaligner les lignes.</p>\n<h3>Filtrer</h3>\n<p>Les filtres (Ctrl + Maj + L) affichent seulement les lignes voulues : les CDD, les salariés d'un service, les embauches de 2026. La fonction <span class=\"phrase\">SOUS.TOTAL(109;F2:F200)</span> additionne uniquement les lignes visibles.</p>\n<h3>La validation des données</h3>\n<p>Données &gt; Validation des données limite ce qu'on peut saisir :</p>\n<ul><li>une <strong>liste déroulante</strong> (CDI, CDD, Stage) ;</li><li>un <strong>nombre entier</strong> entre deux bornes (salaire ≥ 75 000) ;</li><li>une <strong>date</strong> dans une période ;</li><li>une <strong>longueur de texte</strong> (matricule de 6 caractères).</li></ul>\n<p>Un message d'erreur personnalisé explique la règle à l'utilisateur.</p>\n<h3>La mise en forme conditionnelle</h3>\n<p>Accueil &gt; Mise en forme conditionnelle colore automatiquement les cellules selon des règles :</p>\n<ul><li>salaire inférieur au SMIG en rouge ;</li><li>CDD arrivant à échéance dans 30 jours en orange ;</li><li>doublons de matricules en surbrillance ;</li><li>barres de données pour comparer les effectifs.</li></ul>\n<p>Avec une formule : <span class=\"phrase\">=$H2-AUJOURDHUI()&lt;=30</span> appliquée à toute la ligne.</p>","quiz":[{"q":"Un tri sur plusieurs niveaux permet de trier…","o":["Par service puis par nom","Uniquement une colonne","Au hasard"],"a":0,"e":"Tri."},{"q":"Pourquoi sélectionner tout le tableau avant de trier ?","o":["Pour ne pas désaligner les lignes","Pour aller vite","Pour imprimer"],"a":0,"e":"Piège."},{"q":"Raccourci pour activer les filtres ?","o":["Ctrl + Maj + L","Ctrl + E","Ctrl + H"],"a":0,"e":"Raccourci."},{"q":"SOUS.TOTAL(109;…) additionne…","o":["Les lignes visibles seulement","Toutes les lignes","Les lignes masquées seulement"],"a":0,"e":"Fonction."},{"q":"La validation des données sert à…","o":["Limiter les saisies","Colorer","Trier"],"a":0,"e":"Définition."},{"q":"Une liste déroulante de contrats est…","o":["Une validation des données","Un tri","Un graphique"],"a":0,"e":"Outil."},{"q":"Imposer un salaire ≥ 75 000 relève de…","o":["La validation des données","La mise en forme conditionnelle","Le tri"],"a":0,"e":"Outil."},{"q":"Imposer un matricule de 6 caractères :","o":["Validation par longueur de texte","Filtre","Graphique"],"a":0,"e":"Outil."},{"q":"Le message d'erreur personnalisé…","o":["Explique la règle","Supprime la cellule","Est interdit"],"a":0,"e":"Validation."},{"q":"La mise en forme conditionnelle…","o":["Colore selon des règles","Trie","Supprime"],"a":0,"e":"Définition."},{"q":"Salaire inférieur au SMIG en rouge relève de…","o":["La mise en forme conditionnelle","La validation","Le tri"],"a":0,"e":"Exemple."},{"q":"Mettre en surbrillance les doublons de matricules :","o":["Mise en forme conditionnelle","Tri","Collage spécial"],"a":0,"e":"Exemple."},{"q":"Les barres de données servent à…","o":["Comparer visuellement des valeurs","Valider","Trier"],"a":0,"e":"Exemple."},{"q":"=$H2-AUJOURDHUI()<=30 dans une règle signale…","o":["Une échéance dans 30 jours ou moins","Un salaire élevé","Un doublon"],"a":0,"e":"Formule."},{"q":"Pourquoi $H2 et non H2 dans la règle appliquée à la ligne ?","o":["Pour que chaque cellule de la ligne teste la colonne H","Par habitude","C'est une erreur"],"a":0,"e":"Référence mixte."},{"q":"Afficher seulement les CDD se fait avec…","o":["Un filtre","Un tri","Une somme"],"a":0,"e":"Outil."},{"q":"La validation des données se trouve dans l'onglet…","o":["Données","Affichage","Révision"],"a":0,"e":"Ruban."},{"q":"La mise en forme conditionnelle se trouve dans l'onglet…","o":["Accueil","Données","Formules"],"a":0,"e":"Ruban."},{"q":"Filtrer les embauches de 2026 affiche…","o":["Les lignes correspondantes","Toutes les lignes","Aucune ligne"],"a":0,"e":"Filtre."},{"q":"Une validation par date limite…","o":["Les dates hors période","Les couleurs","Les doublons"],"a":0,"e":"Outil."}]},{"id":"mrh313-9","n":9,"t":"Les tableaux croisés dynamiques","min":25,"html":"<p>Le tableau croisé dynamique (TCD) résume en quelques clics un grand tableau : effectifs par service, masse salariale par catégorie, âge moyen par sexe.</p>\n<h3>Créer un TCD</h3>\n<ol><li>Cliquez dans le tableau de données (idéalement un Tableau Excel).</li><li>Insertion &gt; Tableau croisé dynamique &gt; Nouvelle feuille.</li><li>Glissez les champs dans les quatre zones.</li></ol>\n<div class=\"tbl\"><table><thead><tr><th>Zone</th><th>Rôle</th><th>Exemple</th></tr></thead><tbody>\n<tr><td>Lignes</td><td>Catégories en lignes</td><td>Service</td></tr>\n<tr><td>Colonnes</td><td>Catégories en colonnes</td><td>Sexe</td></tr>\n<tr><td>Valeurs</td><td>Calcul (somme, nombre, moyenne)</td><td>Nombre de Matricule, Somme de Salaire</td></tr>\n<tr><td>Filtres</td><td>Filtre global</td><td>Type de contrat</td></tr></tbody></table></div>\n<h3>Paramétrer les valeurs</h3>\n<p>Clic droit sur une valeur &gt; Paramètres des champs de valeurs : choisir Somme, Nombre, Moyenne, Max… ou « Afficher les valeurs » en <strong>% du total général</strong>, <strong>% du total de la ligne</strong>.</p>\n<h3>Regrouper</h3>\n<p>Clic droit sur des âges &gt; Grouper par tranches de 10 ans pour construire une pyramide des âges ; sur des dates d'embauche &gt; Grouper par années.</p>\n<h3>Actualiser</h3>\n<p>Un TCD ne se met pas à jour tout seul : après modification des données, clic droit &gt; <strong>Actualiser</strong> (ou Données &gt; Actualiser tout). Si la source est un Tableau Excel, les nouvelles lignes sont incluses automatiquement.</p>\n<h3>Les segments</h3>\n<p>Insertion &gt; Segment ajoute des boutons de filtre visuels (par service, par année), pratiques pour un tableau de bord.</p>","quiz":[{"q":"Un TCD sert à…","o":["Résumer un grand tableau","Saisir des données","Imprimer"],"a":0,"e":"Définition."},{"q":"On crée un TCD via l'onglet…","o":["Insertion","Affichage","Révision"],"a":0,"e":"Ruban."},{"q":"Combien de zones dans un TCD ?","o":["Quatre","Deux","Six"],"a":0,"e":"Lignes, colonnes, valeurs, filtres."},{"q":"Effectif par service : Service va en…","o":["Lignes","Valeurs","Filtres"],"a":0,"e":"Zone."},{"q":"Pour compter les salariés, on met en Valeurs…","o":["Nombre de Matricule","Somme de Matricule","Moyenne de Service"],"a":0,"e":"Calcul."},{"q":"Pour la masse salariale, on utilise…","o":["Somme de Salaire","Nombre de Salaire","Max de Service"],"a":0,"e":"Calcul."},{"q":"Un filtre global par type de contrat va en…","o":["Filtres","Lignes","Valeurs"],"a":0,"e":"Zone."},{"q":"Sexe en colonnes permet de…","o":["Comparer hommes et femmes","Trier les noms","Calculer l'âge"],"a":0,"e":"Zone."},{"q":"Pour changer Somme en Moyenne :","o":["Paramètres des champs de valeurs","Supprimer le TCD","Trier"],"a":0,"e":"Paramétrage."},{"q":"« % du total général » affiche…","o":["La part de chaque valeur dans le total","Le nombre brut","Une erreur"],"a":0,"e":"Affichage."},{"q":"Pour une pyramide des âges, on groupe les âges…","o":["Par tranches","Par ordre alphabétique","Par service"],"a":0,"e":"Regroupement."},{"q":"Les dates d'embauche peuvent être groupées par…","o":["Années","Services","Salaires"],"a":0,"e":"Regroupement."},{"q":"Un TCD se met-il à jour tout seul ?","o":["Non, il faut actualiser","Oui toujours","Seulement le lundi"],"a":0,"e":"Actualisation."},{"q":"Comment actualiser ?","o":["Clic droit > Actualiser","Supprimer et recréer toujours","Fermer Excel"],"a":0,"e":"Actualisation."},{"q":"Avec un Tableau Excel comme source, les nouvelles lignes…","o":["Sont incluses automatiquement (après actualisation)","Sont ignorées","Créent une erreur"],"a":0,"e":"Avantage."},{"q":"Un segment est…","o":["Un bouton de filtre visuel","Une formule","Une erreur"],"a":0,"e":"Outil."},{"q":"Les segments sont pratiques pour…","o":["Un tableau de bord","La saisie","L'impression uniquement"],"a":0,"e":"Usage."},{"q":"Salaire moyen par catégorie : Catégorie en Lignes et…","o":["Moyenne de Salaire en Valeurs","Somme de Catégorie","Nombre de Sexe en Filtres"],"a":0,"e":"Construction."},{"q":"« % du total de la ligne » sert à voir…","o":["La répartition au sein de chaque ligne","Le total général","Rien"],"a":0,"e":"Affichage."},{"q":"Il est préférable de créer le TCD sur…","o":["Une nouvelle feuille","La feuille des données au milieu","Une image"],"a":0,"e":"Organisation."}]},{"id":"mrh313-10","n":10,"t":"Graphiques et tableau de bord RH","min":25,"html":"<h3>Choisir le graphique</h3>\n<div class=\"tbl\"><table><thead><tr><th>Question</th><th>Graphique</th></tr></thead><tbody>\n<tr><td>Évolution de l'effectif sur 12 mois</td><td>Courbe</td></tr>\n<tr><td>Effectif par service</td><td>Barres (histogramme)</td></tr>\n<tr><td>Pyramide des âges</td><td>Barres horizontales opposées (hommes en négatif)</td></tr>\n<tr><td>Répartition CDI / CDD / stages</td><td>Barres empilées à 100 % (secteurs si 2 ou 3 parts seulement)</td></tr>\n<tr><td>Salaire selon l'ancienneté</td><td>Nuage de points</td></tr></tbody></table></div>\n<p>Un <strong>graphique croisé dynamique</strong> se crée directement depuis un TCD et suit ses filtres et segments.</p>\n<h3>Soigner le graphique</h3>\n<ul><li>Un titre qui dit le message.</li><li>Supprimer le superflu (quadrillage lourd, 3D, légende inutile).</li><li>Étiquettes de données si peu de valeurs.</li><li>Couleur d'accent pour la donnée à retenir.</li></ul>\n<h3>Construire un tableau de bord RH</h3>\n<ol><li>Une feuille <strong>Données</strong> (Tableau Excel).</li><li>Une feuille <strong>Calculs</strong> (TCD ou formules NB.SI.ENS, SOMME.SI.ENS).</li><li>Une feuille <strong>Tableau de bord</strong> : indicateurs clés en haut (effectif, masse salariale, turnover, absentéisme), graphiques en dessous, segments pour filtrer.</li></ol>\n<h3>Protéger</h3>\n<ul><li>Révision &gt; Protéger la feuille : empêche de modifier les formules (déverrouillez d'abord les cellules de saisie).</li><li>Fichier &gt; Informations &gt; Protéger le classeur &gt; Chiffrer avec mot de passe : protège l'ouverture du fichier, indispensable pour des données de salaires.</li></ul>\n<div class=\"callout\"><b>Mise à jour mensuelle</b>Coller les nouvelles données dans la feuille Données, puis Données &gt; Actualiser tout : le tableau de bord se met à jour.</div>","quiz":[{"q":"Évolution de l'effectif sur 12 mois :","o":["Courbe","Secteurs","Nuage de points"],"a":0,"e":"Temps."},{"q":"Effectif par service :","o":["Barres","Courbe","Nuage"],"a":0,"e":"Comparaison."},{"q":"Pyramide des âges :","o":["Barres horizontales opposées","Secteurs","Courbe"],"a":0,"e":"Convention."},{"q":"Dans la pyramide, les hommes sont souvent saisis en…","o":["Valeurs négatives","Texte","Pourcentage"],"a":0,"e":"Astuce."},{"q":"Salaire selon l'ancienneté :","o":["Nuage de points","Secteurs","Barres empilées"],"a":0,"e":"Relation."},{"q":"Les secteurs conviennent si…","o":["2 ou 3 parts seulement","20 parts","Jamais"],"a":0,"e":"Lisibilité."},{"q":"Un graphique croisé dynamique suit…","o":["Les filtres et segments du TCD","Rien","Seulement l'impression"],"a":0,"e":"Lien."},{"q":"Le titre d'un graphique doit…","o":["Dire le message","Être « Graphique 1 »","Être absent"],"a":0,"e":"Bonne pratique."},{"q":"Les effets 3D sont…","o":["À supprimer","Recommandés","Obligatoires"],"a":0,"e":"Superflu."},{"q":"Les étiquettes de données sont utiles si…","o":["Peu de valeurs","Des milliers de valeurs","Jamais"],"a":0,"e":"Lisibilité."},{"q":"Combien de feuilles dans le modèle de tableau de bord ?","o":["Trois","Une","Dix"],"a":0,"e":"Données, Calculs, Tableau de bord."},{"q":"La feuille Données contient…","o":["Un Tableau Excel","Les graphiques","Les commentaires"],"a":0,"e":"Structure."},{"q":"Les indicateurs clés sont placés…","o":["En haut du tableau de bord","En bas","Dans une autre fichier"],"a":0,"e":"Hiérarchie."},{"q":"Protéger la feuille empêche…","o":["De modifier les formules","D'ouvrir le fichier","D'imprimer"],"a":0,"e":"Protection."},{"q":"Avant de protéger la feuille, on…","o":["Déverrouille les cellules de saisie","Supprime les formules","Ferme le fichier"],"a":0,"e":"Méthode."},{"q":"Pour protéger l'ouverture du fichier :","o":["Chiffrer avec mot de passe","Protéger la feuille","Figer les volets"],"a":0,"e":"Protection."},{"q":"Le chiffrement est indispensable pour…","o":["Des données de salaires","Un menu de cantine","Une liste de courses"],"a":0,"e":"Confidentialité."},{"q":"Mise à jour mensuelle : après avoir collé les données…","o":["Actualiser tout","Recréer tous les graphiques","Rien"],"a":0,"e":"Méthode."},{"q":"Protéger la feuille se trouve dans l'onglet…","o":["Révision","Insertion","Accueil"],"a":0,"e":"Ruban."},{"q":"Une couleur d'accent sert à…","o":["Mettre en valeur la donnée à retenir","Décorer toutes les barres","Cacher"],"a":0,"e":"Bonne pratique."}]}]}]
